    def test_the_app_band_asks_for_the_restart_of_a_background_install_and_does_not_say_it_runs(self):
        # installed in the background, no restart queued (`ask_restart`): the band waits for the person, it does not say
        # "Restarting for X…" for hours; its button is the page's restart (POST /api/restart), the same as the Updates screen
        self.ev("update.checked", None, result="restarting", app=True, layer=True, version="1.9.6", have_version="1.9.5",
                ask_restart=True)
        spy = ("(() => { window.__p = []; window.fetch = (u, o) => { window.__p.push([String(u), (o && o.body) || '']);"
               " return Promise.resolve(new Response('{}', {status: 200, headers: {'Content-Type': 'application/json'}})); };"
               " document.querySelector('.setupbar button').click(); return 1; })()")
        shots = os.environ.get("HUB_TEST_SHOTS")   # a folder: the band as pictures, Classic and Clean, light and dark
        for look in ((False, True) if shots else ()):
            for theme in ("light", "dark"):
                self.app_band({"shot": os.path.join(shots, f"restart-ask-{'clean' if look else 'classic'}-{theme}.png"),
                               "theme": theme, "width": 1000, "height": 240}, look=look)
        got = self.app_band({"eval": spy}, {"until": "window.__p.some((x) => x[0] === '/api/restart')", "ms": 5000},
                            {"eval": "window.__p.filter((x) => x[0] === '/api/restart')"},
                            {"until": "document.querySelector('.setupbar').dataset.kind === 'restart'", "ms": 5000},
                            {"eval": "document.querySelector('.setupbar-line').textContent"})
        band = got[0]
        self.assertEqual((band["kind"], band["level"], band["buttons"]), ("restart_ask", "hold", ["Restart"]), band)
        self.assertIn("1.9.6", band["text"])
        self.assertNotIn("Restarting", band["text"])
        self.assertTrue(got[2]["until"], got)
        self.assertEqual(got[3]["eval"], [["/api/restart", '{"parts":[]}']])
        self.assertTrue(got[4]["until"], got)   # pressed: now the restart is asked for, and the band says it runs
        self.assertEqual(got[5]["eval"], "Restarting for 1.9.6…")

