    def test_phone_list_connection_status_retries_now_and_keeps_draft_and_reassurance(self):
        import socket as so
        self.seed()
        cls = self.server.RequestHandlerClass
        original, live, calls, refused = cls.stream, [], [], []
        unavailable = [False]
        def controlled(h):
            calls.append(time.monotonic())
            if unavailable[0]:
                refused.append(time.monotonic())
                return h.send(502, b'{"error":"synthetic restart"}')
            live.append(h)
            return original(h)
        with mock.patch.object(cls, "stream", controlled):
            self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"},
                {"until": "!!document.querySelector('#msg')"},
                {"eval": "document.querySelector('#msg').value='kept connection draft';document.querySelector('#msg').dispatchEvent(new Event('input',{bubbles:true}));location.hash='#/sessions';1"},
                {"until": "document.querySelector('#app').dataset.view==='list'"},
                {"shot": os.path.join(self.state, "connected-list.png"), "width": 390, "height": 844})
            header = self.page({"eval": "document.querySelector('.search-row').getBoundingClientRect().height"})[-1]["eval"]
            unavailable[0] = True
            live[-1].connection.shutdown(so.SHUT_RDWR)
            # Wait for the existing CLOSED-stream backoff to reach a pending retry of several seconds.
            until = time.monotonic() + 14
            while len(refused) < 3 and time.monotonic() < until:
                time.sleep(.1)
            self.assertGreaterEqual(len(refused), 3)
            folder = self.state
            for width in (390, 1280):
                got = self.page({"shot": os.path.join(folder, f"disconnected-{width}.png"), "width": width, "height": 844},
                    {"eval": "(()=>{const n=document.querySelector('#connection-side');return {exists:!!n,visible:!!n?.getClientRects().length,text:n?.textContent,role:n?.getAttribute('role'),overflow:document.documentElement.scrollWidth>innerWidth,header:document.querySelector('.search-row').getBoundingClientRect().height,"
                             "a11y:[n,document.querySelector('#banner')].map((x)=>[x.getAttribute('aria-label'),x.querySelector('[data-conn-at]')?.getAttribute('aria-hidden'),x.querySelector('.sr')?.textContent])};})()"})[-1]["eval"]
                self.assertTrue(got["exists"])
                self.assertEqual(got["visible"], width == 390)
                self.assertIn("Connecting to the hub", got["text"])
                self.assertIn(" in ", got["text"])   # the next attempt is announced with a countdown
                self.assertNotIn("queue", got["text"])   # the web page has no outbox, so no promise about one
                self.assertEqual(got["role"], "button")
                # the countdown is for the eye: a screen reader hears the words once, the control is named "Retry"
                self.assertEqual(got["a11y"], [["Retry", "true", "Connecting to the hub…"]] * 2)
                self.assertFalse(got["overflow"])
                if width == 390:
                    self.assertEqual(got["header"], header)
            self.page({"shot": os.path.join(self.state, "retry-phone.png"), "width": 390, "height": 844})
            unavailable[0] = False
            before, clicked = len(calls), time.monotonic()
            self.page({"eval": "document.querySelector('#connection-side').click();1"},
                {"until": "document.querySelector('#conn .dot').dataset.s==='ok'"})
            self.assertEqual(len(calls), before + 1)
            self.assertLess(calls[-1] - clicked, .8, "click must not wait for the pending backoff")
            got = self.page({"eval": "({side:document.querySelector('#connection-side').textContent,visible:!!document.querySelector('#connection-side').getClientRects().length,main:document.querySelector('#banner').textContent})"})[-1]["eval"]
            self.assertEqual(got, {"side": "", "visible": False, "main": ""})
            # Keyboard users get the same connect-now action; opening the socket retains current behavior.
            for key in ("Enter", " "):
                live[-1].connection.shutdown(so.SHUT_RDWR)
                self.page({"until": "document.querySelector('#connection-side').classList.contains('on')"},
                    {"eval": "document.querySelector('#connection-side').focus();1"})
                before = len(calls)
                self.page({"key": key}, {"until": "document.querySelector('#conn .dot').dataset.s==='ok'"})
                self.assertEqual(len(calls), before + 1)
            self.page({"hash": "#/s/a"}, {"until": "!!document.querySelector('#msg')"})
            self.assertEqual(self.page({"eval": "document.querySelector('#msg').value"})[-1]["eval"], "kept connection draft")
            before = len(calls)
            self.page({"eval": "import('/static/js/api.js').then(m=>m.banner('Action refused',true));1"},
                {"until": "document.querySelector('#banner').textContent==='Action refused'"})
            got = self.page({"eval": "(()=>{const b=document.querySelector('#banner');const role=b.getAttribute('role'),label=b.getAttribute('aria-label');b.click();return {role,label,text:b.textContent};})()"})[-1]["eval"]
            self.assertEqual(got, {"role": "status", "label": None, "text": ""})
            self.assertEqual(len(calls), before, "ordinary action banner still dismisses rather than reconnecting")

    def test_online_and_focus_retry_the_stream_at_once_and_restart_the_pauses(self):
        import socket as so
        self.seed()
        cls = self.server.RequestHandlerClass
        original, live, calls = cls.stream, [], []
        unavailable = [False]
        def controlled(h):
            calls.append(time.monotonic())
            if unavailable[0]:
                return h.send(502, b'{"error":"synthetic restart"}')
            live.append(h)
            return original(h)
        with mock.patch.object(cls, "stream", controlled):
            self.page({"go": f"http://127.0.0.1:{self.port}/#/sessions"},
                {"until": "document.querySelector('#conn .dot').dataset.s==='ok'"})
            unavailable[0] = True
            live[-1].connection.shutdown(so.SHUT_RDWR)
            until = time.monotonic() + 14
            while len(calls) < 5 and time.monotonic() < until:   # pauses 1, 1, 2, 3 s: the next one is already several seconds
                time.sleep(.1)
            self.assertGreaterEqual(len(calls), 5)
            for event in ("online", "focus"):
                self.page({"until": self.PAUSE_PENDING, "ms": 8000})   # a pause is pending, not an attempt under way
                unavailable[0] = False
                before, fired = len(calls), time.monotonic()
                self.page({"eval": f"window.dispatchEvent(new Event('{event}'));1"},
                    {"until": "document.querySelector('#conn .dot').dataset.s==='ok'"})
                self.assertEqual(len(calls), before + 1, event)
                self.assertLess(calls[-1] - fired, .8, f"{event} must not wait for the pending pause")
                unavailable[0] = True
                live[-1].connection.shutdown(so.SHUT_RDWR)
                until = time.monotonic() + 6
                while len(calls) < before + 3 and time.monotonic() < until:   # the pauses start over from one second
                    time.sleep(.1)
                self.assertGreaterEqual(len(calls), before + 3, event)

    # the stream status counts down to the next attempt: more than half a second of pause is left
    COUNTDOWN = "+(document.querySelector('#banner [data-conn-at]')?.dataset.connAt||0)-Date.now()"
    PAUSE_PENDING = COUNTDOWN + ">500"

    def test_focus_and_visibility_together_try_the_stream_once_and_keep_the_pause(self):
        # review of PR #425: a return to the tab fires focus and visibilitychange together — that is one attempt, not two
        # streams, and it does not start the pauses over (only the network coming back or a stream that opened do)
        import socket as so
        self.seed()
        cls = self.server.RequestHandlerClass
        original, live, calls = cls.stream, [], []
        unavailable = [False]
        def controlled(h):
            calls.append(time.monotonic())
            if unavailable[0]:
                return h.send(502, b'{"error":"synthetic restart"}')
            live.append(h)
            return original(h)
        with mock.patch.object(cls, "stream", controlled):
            self.page({"go": f"http://127.0.0.1:{self.port}/#/sessions"},
                {"until": "document.querySelector('#conn .dot').dataset.s==='ok'"})
            unavailable[0] = True
            live[-1].connection.shutdown(so.SHUT_RDWR)
            until = time.monotonic() + 10
            while len(calls) < 4 and time.monotonic() < until:   # pauses 1, 1, 2 s: the next one is 3 s
                time.sleep(.1)
            self.assertGreaterEqual(len(calls), 4)
            self.assertTrue(self.page({"until": self.PAUSE_PENDING, "ms": 8000})[-1]["until"])
            before = len(calls)
            self.page({"eval": "window.dispatchEvent(new Event('focus'));document.dispatchEvent(new Event('visibilitychange',{bubbles:true}));1"},
                      {"sleep": 1500})
            self.assertEqual(len(calls), before + 1)   # one attempt at once, and the pause after it is not 1 s again
            got = self.page({"eval": self.COUNTDOWN})[-1]["eval"]
            self.assertGreater(got, 1000)   # the count went on (5 s), it did not start over from 1 s

    def test_a_hung_attempt_is_replaced_and_the_status_outlives_another_banner(self):
        # review of PR #425: the network came back while an attempt hangs on the dead route (no timer is pending) — online
        # and a later return to the tab replace it; a banner of another kind over the status gives the status back when it
        # goes, not with the next attempt (up to 60 s); the words for a screen reader are put once, not on every attempt
        import socket as so
        import threading
        self.seed()
        cls = self.server.RequestHandlerClass
        original, live, calls = cls.stream, [], []
        mode, release = ["ok"], threading.Event()
        self.addCleanup(release.set)
        def controlled(h):
            calls.append(time.monotonic())
            if mode[0] == "hang":
                release.wait(30)
            if mode[0] != "ok":
                return h.send(502, b'{"error":"synthetic restart"}')
            live.append(h)
            return original(h)
        with mock.patch.object(cls, "stream", controlled):
            self.page({"go": f"http://127.0.0.1:{self.port}/#/sessions"},
                {"until": "document.querySelector('#conn .dot').dataset.s==='ok'"})
            mode[0] = "down"
            live[-1].connection.shutdown(so.SHUT_RDWR)
            got = self.page({"until": self.PAUSE_PENDING, "ms": 5000},
                            {"eval": "(window.__ear = document.querySelector('#banner .sr'), 1)"},
                            {"until": "(+document.querySelector('#banner [data-conn-at]').dataset.connAt||0) - Date.now() > 1500", "ms": 8000},
                            {"eval": "window.__ear === document.querySelector('#banner .sr') && window.__ear.isConnected"})
            self.assertTrue(got[-1]["eval"], "the words for a screen reader stay the same node across attempts")
            # another banner over the status: when it is closed, the status is back at once
            got = self.page({"eval": "import('/static/js/api.js').then(m=>m.banner('Action refused'));1"},
                            {"until": "document.querySelector('#banner').textContent==='Action refused'"},
                            {"eval": "document.querySelector('#banner').click();1"},
                            {"eval": "[!!document.querySelector('#banner [data-conn-at]'), document.querySelector('#banner').getAttribute('aria-label')]"})
            self.assertEqual(got[-1]["eval"], [True, "Retry"])
            # an attempt hangs: no pause is pending, the status has no countdown
            mode[0] = "hang"
            before = len(calls)
            self.page({"eval": "document.querySelector('#banner').click();1"}, {"sleep": 300})
            self.assertGreaterEqual(len(calls), before + 1)   # + the pending pause's attempt, if it came just before the click
            for event, wait_ms in (("online", 0), ("focus", 2500)):
                before = len(calls)
                self.page({"sleep": wait_ms}, {"eval": f"window.dispatchEvent(new Event('{event}'));1"}, {"sleep": 500})
                self.assertEqual(len(calls), before + 1, f"{event} replaces the attempt that hangs")
            mode[0] = "ok"
            release.set()
            before = len(calls)
            got = self.page({"eval": "window.dispatchEvent(new Event('online'));1"},
                            {"until": "document.querySelector('#conn .dot').dataset.s==='ok'", "ms": 5000})
            self.assertTrue(got[-1]["until"])

    def test_stream_back_after_server_refused_it(self):
        # the stream broke (the core page restarts), the browser reconnected and got 502: the EventSource was closed for good,
        # and the page stayed red until a manual reload. Now it reconnects by itself, with a pause
        import socket as so
        from unittest import mock
        cls = self.server.RequestHandlerClass
        orig, live, refuse, refused = cls.stream, [], [0], []

        def stream(h):
            if refuse[0]:
                refuse[0] -= 1
                refused.append(time.monotonic())
                return h.send(502, b'{"error":"down"}')
            live.append(h)
            return orig(h)
        patch = mock.patch.object(cls, "stream", stream)
        patch.start()
        self.addCleanup(patch.stop)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None)
        self.tool("a", "t1", "pytest-alpha")
        self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "pytest-alpha"})
        refuse[0] = 3
        live[-1].connection.shutdown(so.SHUT_RDWR)   # the break: after that the browser gets 502 three times
        got = self.page({"until": "document.querySelector('#conn .dot')?.dataset.s === 'off'", "ms": 15000})
        self.assertTrue(got[-1]["until"])
        self.tool("a", "t2", "after-refused")
        got = self.page({"wait": "after-refused", "ms": 30000},
                        {"until": "document.querySelector('#conn .dot')?.dataset.s !== 'off'"})
        self.assertTrue(got[0]["ok"])
        self.assertTrue(got[1]["until"])
        self.assertEqual(refuse[0], 0)
        self.assertEqual(len(live), 2)   # one new stream, no duplicates
        # after a failure there is a pause that grows (1 s, 2 s), so the server is not hammered back to back
        gaps = [b - a for a, b in zip(refused, refused[1:])]
        self.assertGreater(gaps[0], 0.7)
        self.assertGreater(gaps[1], gaps[0] + 0.5)

    # page setup: intercept fetch (what went out as POST) and inject into the snapshot the fields the core does not
    # provide in this run
    PREP = ("import('/static/js/state.js').then((m) => { window.__m = m; window.__calls = []; const of = window.fetch; "
            "window.fetch = (u, o) => { if (o && o.method === 'POST') window.__calls.push([u, JSON.parse(o.body)]); "
            "return of(u, o); }; })")

    def test_queue_rows_in_the_strip_and_delayed_cancel(self):
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None)
        for i in (1, 2, 3):
            self.ev("message.received", None, to="a", text=f"in queue {i}", channel="web", owner=True)
        patch = ("(() => { const {S, render} = window.__m; const ids = S.snap.timelines.a.filter((i) => i.kind === 'in').map((i) => i.id); "
                 "ids.forEach((id) => { S.snap.messages[id] = {...S.snap.messages[id], state: 'queued', injectable: true, urgency: 0.7}; }); "
                 "S.snap.sessions.find((x) => x.name === 'a').state = 'busy'; render(); window.__ids = ids; return ids.length; })()")
        rows = ("JSON.stringify([...document.querySelectorAll('.strip-row')].map((r) => [...r.querySelectorAll('button')].map((b) => b.textContent).join(',')))")
        click = lambda label: ("(() => { [...document.querySelectorAll('.strip-row button')].find((b) => b.textContent === '%s').click(); return 1; })()" % label)
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "in queue 3"}, {"eval": self.PREP}, {"sleep": 400},
                        {"eval": patch}, {"sleep": 300}, {"eval": rows}, {"eval": "document.querySelectorAll('.strip-urg').length"},
                        {"eval": click("Remove")}, {"sleep": 300}, {"wait": "Removed from the queue"},
                        {"eval": "window.__calls.length"}, {"sleep": 6500}, {"eval": "JSON.stringify(window.__calls)"},
                        {"eval": click("Remove")}, {"sleep": 300}, {"eval": click("Undo")}, {"sleep": 7000},
                        {"eval": "window.__calls.length"}, {"eval": rows},
                        {"eval": "document.querySelector('.strip').textContent.includes('evaluating')"})
        self.assertFalse(got[20]["eval"])                                                # "evaluating…" does not hang forever
        self.assertEqual(json.loads(got[6]["eval"]), ["Send now,Remove"] * 3)   # each message has its own buttons
        self.assertEqual(got[7]["eval"], 3)                                              # and its own urgency estimate
        self.assertEqual(got[11]["eval"], 0)                                             # "Remove" sends nothing right away
        sent = json.loads(got[13]["eval"])
        self.assertEqual([x[0] for x in sent], ["/api/queue/cancel"])                    # after 6 s: exactly one cancel
        self.assertEqual(got[18]["eval"], 1)                                             # "Remove" + "Undo": no more after that
        self.assertEqual(len(json.loads(got[19]["eval"])), 2)                            # the remaining two are back in the queue

    def test_queue_remove_only_where_the_core_takes_it_and_a_refusal_comes_back(self):
        # "Remove" was also shown for what the core does not remove (a task), and the refusal came silently: the row hid until
        # switching to another session, then came back, so Remove looked as if it did not work
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None)
        for i in (1, 2):
            self.ev("message.received", None, to="a", text=f"in queue {i}", channel="web", owner=True)
        patch = ("(() => { const {S, render} = window.__m; const ids = S.snap.timelines.a.filter((i) => i.kind === 'in').map((i) => i.id); "
                 "ids.forEach((id, k) => { S.snap.messages[id] = {...S.snap.messages[id], state: 'queued', removable: k === 1, injectable: k === 1}; }); "
                 "S.snap.sessions.find((x) => x.name === 'a').state = 'busy'; render(); return ids.length; })()")
        rows = ("JSON.stringify([...document.querySelectorAll('.strip-row')].map((r) => r.querySelector('.t')?.textContent + '|' + "
                "[...r.querySelectorAll('button')].map((b) => b.textContent).join(',')))")
        click = "(() => { [...document.querySelectorAll('.strip-row button')].find((b) => b.textContent === 'Remove').click(); return 1; })()"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "in queue 2"}, {"eval": self.PREP}, {"sleep": 400},
                        {"eval": patch}, {"sleep": 300}, {"eval": rows}, {"eval": click}, {"sleep": 6500},
                        {"eval": "window.__calls.length"}, {"sleep": 10500}, {"eval": rows},
                        {"eval": "[...document.querySelectorAll('.strip-row')].filter((r) => r.textContent.includes('Failed - try again')).map((r) => r.dataset.k)"})
        first = json.loads(got[6]["eval"])
        self.assertEqual([r.split("|")[1] for r in first], ["", "Send now,Remove"])   # we do not offer to remove a task
        self.assertEqual(got[9]["eval"], 1)                                          # the cancel went out
        self.assertIn("Failed - try again", got[11]["eval"])                          # the message stayed, and the page says so
        self.assertEqual(got[12]["eval"], ["fail"])                                  # a hook for themes: the row of a failed removal

