    def test_fyi_row_has_no_remove_and_opens_to_the_full_text(self):
        # an informational item ("for information") leaves by itself with the session's next message, but "Remove" read as an
        # obligation to remove it by hand; the text was cut with "…" at 90 characters, and before delivery it could not be
        # read in full anywhere
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        tail = "end-of-the-note-in-full"
        self.ev("message.received", None, to="a", text="Note for information: " + "update details " * 12 + tail,
                channel="session", owner=False, sender="maps", fyi=True)
        row = ("(() => { const r = [...document.querySelectorAll('.strip-row')].find((x) => x.textContent.includes('Note')), "
               "t = r.querySelector('.t'); return [[...r.querySelectorAll('button')].filter((b) => b !== t).length, "
               "t.textContent.endsWith('%s'), t.getAttribute('aria-expanded'), t.scrollWidth > t.clientWidth + 1, "
               "Math.round(t.getBoundingClientRect().height), document.activeElement === t]; })()" % tail)
        # a mouse click (detail 1) is delayed; a double click (1, then 2) selects a word and the row does not change
        mouse = lambda *ds: ("(() => { const t = document.querySelector('.strip-row .t'); "
                             + "".join("t.dispatchEvent(new MouseEvent('click', {detail: %d, bubbles: true})); " % d for d in ds)
                             + "return 1; })()")
        rerender = "(() => { const {S, render} = window.__m; S.snap = {...S.snap}; document.querySelector('.strip-host').dataset.sig = ''; render(); return 1; })()"
        focus = "(() => { document.querySelector('.strip-row .t').focus(); return 1; })()"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Note for information"},
                        {"eval": self.PREP + ".then(() => import('/static/js/voice.js')).then((v) => { window.__v = v; })"},
                        {"sleep": 400}, {"eval": row}, {"eval": mouse(1, 2)}, {"sleep": 500}, {"eval": row},
                        {"eval": mouse(1)}, {"sleep": 500}, {"eval": row},
                        {"eval": rerender}, {"sleep": 200}, {"eval": row},
                        {"eval": focus}, {"key": "Enter"}, {"sleep": 200}, {"eval": row},
                        {"key": " "}, {"sleep": 200}, {"eval": row}, {"eval": "window.__v.voiceMode()"})
        closed, dbl, opened, again, keyed, spaced = (got[k]["eval"] for k in (4, 7, 10, 13, 17, 20))
        self.assertEqual(closed[:4], [0, True, "false", True])        # no buttons; the full text, in view: a single line with "…"
        self.assertEqual(dbl[2], "false")                             # a double click on a word does not expand it
        self.assertEqual(opened[:4], [0, True, "true", False])        # a click expands it fully, with line breaks
        self.assertGreater(opened[4], closed[4] * 2)
        self.assertEqual(again[2], "true")                            # a redraw from a snapshot does not collapse it
        self.assertEqual((keyed[2], keyed[5]), ("false", True))      # Enter does the same as a click; focus stays on the row
        self.assertEqual((spaced[2], spaced[5]), ("true", True))     # Space too
        self.assertEqual(got[21]["eval"], "")                         # and voice input did not take the Space key

