    def test_owner_reply_shows_what_it_answers(self):
        # a reply via "Reply": in "Brief" above the words is one line "↩ “start of the quote”", the full one as a tooltip;
        # in "Detailed" the whole quote; with no quote there is no line (without it the reply looked like a plain message
        # from the owner)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        long = "The agent watches the tag once a minute. " * 8
        for text, extra in (("why?", {"quote": long}), ("just because", {})):
            e = self.j.append("message.received", None, {"to": "a", "text": text, "channel": "web", "owner": True, **extra})
            self.ev("turn.started", "a", marker=f"m{e['seq']}", prompt_head=text)
            self.ev("turn.result", "a", text="ok")
            self.ev("turn.stopped", "a")
        probe = ("(() => { const rows = [...document.querySelectorAll('.feed .row.mine')]; return rows.map((r) => { "
                 "const q = r.querySelector('.in-reply'); if (!q) return null; const s = getComputedStyle(q); "
                 "return [q.textContent, q.title, s.whiteSpace === 'nowrap' && s.textOverflow === 'ellipsis' && q.scrollWidth > q.clientWidth, "
                 "!!r.querySelector('.quote')]; }); })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "compact"}, {"wait": "just because"}, {"eval": probe},
                        {"eval": "(() => { document.querySelector('.in-reply').click(); return getComputedStyle(document.querySelector('.in-reply')).whiteSpace; })()"},
                        {"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "just because"},
                        {"eval": "[...document.querySelectorAll('.feed .row.mine')].map((r) => (r.querySelector('.quote') || {}).textContent || null)"})
        compact = got[2]["eval"]
        self.assertEqual(len(compact), 2)
        text, title, one_line, full_quote = compact[0]
        self.assertTrue(text.startswith("“The agent watches the tag"), text)
        self.assertIn(long.strip(), title)                     # the full quote as a tooltip
        self.assertTrue(one_line)
        self.assertFalse(full_quote)                           # in "Brief" not the whole quote
        self.assertIsNone(compact[1])                          # no quote, no line
        self.assertEqual(got[3]["eval"], "pre-wrap")           # a tap expands it (a phone has no tooltips)
        self.assertEqual(got[7]["eval"], [f"“{long}”", None])  # "Detailed": the whole quote

    # a tap on the "In reply to" quote goes to the row that was replied to: it lands mid-window and is highlighted.
    # The position is judged by the visible row, not by scrollTop
    JUMPED = ("(() => { const f = document.querySelector('main .feed').getBoundingClientRect(), r = document.querySelector('.feed .row.flash'); "
              "if (!r) return null; const b = r.getBoundingClientRect(); "
              "return [r.innerText, b.top >= f.top - 1 && b.bottom <= f.bottom + 1, getComputedStyle(r).backgroundColor]; })()")

    SHOWN = "[...document.querySelectorAll('.feed .row.out')].some((r) => r.innerText.includes('%s'))"   # a session row, not a quote
    IN_VIEW = ("(() => { const f = document.querySelector('main .feed').getBoundingClientRect(); "
               "return [...document.querySelectorAll('.feed .row.out')].some((r) => { const b = r.getBoundingClientRect(); "
               "return r.innerText.includes('%s') && b.bottom > f.top && b.top < f.bottom; }); })()")

