    def test_the_wait_strip_leads_to_the_permission_card_and_decides_nothing(self):
        # permission request: the "Waiting for you" strip has a single "To the request" button; the decision is made only in
        # the feed card
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        self.ev("permission.requested", "a", request_id="r1", tool="Bash", input={"command": "rm -rf build/"})
        buttons = "JSON.stringify([...document.querySelectorAll('.strip .strip-row button')].map((b) => b.textContent))"
        words = ("JSON.stringify(['Allow', 'Deny'].map((w) => [...document.querySelectorAll('.strip button')]"
                 ".some((b) => b.textContent.includes(w))))")
        click = "(() => { [...document.querySelectorAll('.strip button')].find((b) => b.textContent === 'To the request').click(); return 1; })()"
        focused = ("(() => { const a = document.activeElement; const c = a && a.closest('.feed .card'); "
                   "return [!!c, !!document.querySelector('.feed .card button, .feed .card input')]; })()")
        deny = ("(() => { const b = [...document.querySelectorAll('.feed .card button')].find((x) => x.textContent === 'Deny'); "
                "return b ? b.className : null; })()")
        status = "document.querySelector('.status .stat-main').title"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Asks permission"}, {"eval": buttons},
                        {"eval": words}, {"eval": deny}, {"eval": status}, {"eval": click}, {"sleep": 400}, {"eval": focused})
        self.assertEqual(json.loads(got[2]["eval"]), ["To the request"])          # one button in the strip
        self.assertEqual(json.loads(got[3]["eval"]), [False, False])         # neither "Allow" nor "Deny"
        self.assertIsNotNone(got[4]["eval"])                                 # "Deny" is in the card...
        self.assertNotIn("danger", got[4]["eval"])                           # ...and is not red: red is only for "waiting for you"
        self.assertIn("/w", got[5]["eval"])                                  # the session folder is in the status row tooltip
        self.assertEqual(got[-1]["eval"], [True, True])                      # the click put focus on a card element
        self.assertFalse([e for e in self.spooled() if e["type"] == "permission.answered"])   # and decided nothing by itself

    def test_a_short_permission_command_is_never_broken_mid_line_in_the_strip(self):
        # an open strip row wraps anywhere; a command of up to 18 chars (the native clients' threshold) sits in its own nowrap span (the row text is unchanged),
        # a longer one is plain text as before
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        self.ev("permission.requested", "a", request_id="r1", tool="Bash", input={"command": "rm / -rf build"})
        probe = ("(() => { const t = document.querySelector('.strip-row .t'); const n = t.querySelectorAll('.nowrap'); "
                 "return [t.textContent, n.length, n.length ? n[0].textContent : null, n.length ? getComputedStyle(n[0]).whiteSpace : null]; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Asks permission"}, {"eval": probe})
        self.assertEqual(got[2]["eval"], ["Asks permission: Bash, rm / -rf build", 1, "rm / -rf build", "nowrap"])
        # the boundary: 18 chars is whole, 19 is plain text
        for n, want in ((18, 1), (19, 0)):
            cmd = "x" * n
            self.ev("permission.requested", "a", request_id=f"b{n}", tool="Bash", input={"command": cmd})
            mine = ("(() => { const t = [...document.querySelectorAll('.strip-row .t')].find((x) => x.textContent.endsWith('%s')); "
                    "return t ? t.querySelectorAll('.nowrap').length : -1; })()" % cmd)
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": cmd}, {"eval": mine})
            self.assertEqual(got[2]["eval"], want, n)

