    def test_the_tab_shows_the_waiting_count_in_its_title_and_icon_and_the_app_badge(self):
        # a question waits while the tab is in the background: the owner sees it on the tab itself. The same list as the
        # "Waiting for you" pill gives "(N) <hub name>" and a red dot on the icon; the icon <link> is replaced only when the
        # count changes (not on every snapshot), and the app badge follows where the browser has one
        for n in "ab":
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True)
            self.ev("session.started", n, session_id=f"s-{n}")
            self.ev("turn.started", n, marker=None, prompt_head="x")
        TAB_ICONS = " ".join(f"/static/favicon/tab-{px}.png" for px in (16, 32, 48))
        TAB_ICONS_ALERT = " ".join(f"/static/favicon/tab-{px}-alert.png" for px in (16, 32, 48))
        look = ("JSON.stringify([document.title, [...document.querySelectorAll('link[rel=\"icon\"]')].map((l) => l.getAttribute('href')).join(' '), "
                "window.__badge.join(',')])")
        stub = ("(() => { window.__badge = []; navigator.setAppBadge = (n) => { window.__badge.push(n); return Promise.resolve(); }; "
                "navigator.clearAppBadge = () => { window.__badge.push(0); return Promise.resolve(); }; "
                "window.__icon = document.querySelector('link[rel=\"icon\"]'); return 1; })()")
        same = "window.__icon === document.querySelector('link[rel=\"icon\"]')"

        def ask(n, rid):
            self.ev("permission.requested", n, request_id=rid, tool="Bash", input={"command": "ls"})

        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": "document.title === 'Hub'", "ms": 15000}, {"eval": stub},
                        {"eval": look})
        self.assertEqual(json.loads(got[-1]["eval"]), ["Hub", TAB_ICONS, ""])             # nobody waits: as before
        ask("a", "r1")
        got = self.page({"until": "document.title === '(1) Hub'", "ms": 15000}, {"eval": look}, {"eval": f"({same})"})
        self.assertEqual(json.loads(got[1]["eval"]), ["(1) Hub", TAB_ICONS_ALERT, "1"])
        self.assertFalse(got[2]["eval"])                                 # the <link> itself is replaced: Chrome rereads it
        got = self.page({"eval": "(() => { window.__icon = document.querySelector('link[rel=\"icon\"]'); return 1; })()"})
        self.ev("turn.started", "b", marker=None, prompt_head="y")      # a snapshot with the same count
        got = self.page({"sleep": 1500}, {"eval": f"({same})"}, {"eval": look})
        self.assertTrue(got[1]["eval"])                                  # the count did not change: the icon is not touched
        self.assertEqual(json.loads(got[2]["eval"])[2], "1")             # and the badge is not set again
        ask("b", "r2")
        got = self.page({"until": "document.title === '(2) Hub'", "ms": 15000}, {"eval": look})
        self.assertEqual(json.loads(got[1]["eval"]), ["(2) Hub", TAB_ICONS_ALERT, "1,2"])
        for n, rid in (("a", "r1"), ("b", "r2")):
            self.ev("permission.answered", n, request_id=rid, channel="web", owner=True)
        got = self.page({"until": "document.title === 'Hub'", "ms": 15000}, {"eval": look})
        self.assertEqual(json.loads(got[1]["eval"]), ["Hub", TAB_ICONS, "1,2,0"])         # the plain icon and a cleared badge

    def test_the_tab_counts_the_open_questions_not_the_sessions_that_wait(self):
        # owner report: one session has two open questions, the tab said (1). The pill counts sessions, the tab counts
        # what waits for an answer
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        for rid, q in (("r1", "First?"), ("r2", "Second?")):
            self.ev("permission.requested", "a", request_id=rid, tool="AskUserQuestion", interactive=True, input={
                "questions": [{"question": q, "options": [{"label": "Yes"}, {"label": "No"}]}]})
        got =self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": "document.title === '(2) Hub'", "ms": 15000},
                        {"eval": "[document.title, document.querySelector('.wpill .wn')?.textContent]"})
        self.assertEqual(got[-1]["eval"], ["(2) Hub", "1"])   # one session waits: the pill is about sessions
        self.ev("permission.answered", "a", request_id="r1", channel="web", owner=True)
        got = self.page({"until": "document.title === '(1) Hub'", "ms": 15000}, {"eval": "document.title"})
        self.assertEqual(got[-1]["eval"], "(1) Hub")
        self.ev("permission.answered", "a", request_id="r2", channel="web", owner=True)
        got = self.page({"until": "document.title === 'Hub'", "ms": 15000}, {"eval": "document.title"})
        self.assertEqual(got[-1]["eval"], "Hub")

    def preview_card(self, previews):
        """An open question with options carrying `preview`: ASCII, a picture on disk, a missing picture, no preview."""
        import struct
        import zlib
        shot = os.path.join(os.path.realpath(self.state), "shots", "after.png")
        os.makedirs(os.path.dirname(shot), exist_ok=True)
        rows = b"".join(b"\0" + b"\x40\x80\xf0" * 300 for _ in range(150))
        chunk = lambda t, d: struct.pack(">I", len(d)) + t + d + struct.pack(">I", zlib.crc32(t + d))  # noqa: E731
        with open(shot, "wb") as f:
            f.write(b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", 300, 150, 8, 2, 0, 0, 0))
                    + chunk(b"IDAT", zlib.compress(rows)) + chunk(b"IEND", b""))
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        q = {"questions": [{"question": "Which button is better?", "options": [
            {"label": "Left", "description": "at the edge", "preview": previews[0]},
            {"label": "Right", "preview": previews[1].replace("SHOT", shot)},
            {"label": "No file", "preview": "/nope/gone.png"},
            {"label": "No preview", "preview": ""}]}]}
        self.ev("turn.tool", "a", id="t1", name="AskUserQuestion", input=q)   # what the session showed: the picture is served
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input=q)
        return shot

    PREVIEW = ("(() => { const c = document.querySelector('.ask-card'); const r = c.getBoundingClientRect();"
               "const pre = c.querySelector('pre.opt-preview'); const img = c.querySelector('img.opt-img');"
               "const miss = c.querySelector('.opt-missing'); const labs = [...c.querySelectorAll('label.opt')];"
               "return {right: Math.round(r.right), win: innerWidth, text: pre && pre.textContent,"
               "ws: pre && getComputedStyle(pre).whiteSpace, ox: pre && getComputedStyle(pre).overflowX,"
               "mono: pre && getComputedStyle(pre).fontFamily, pw: pre && Math.round(pre.getBoundingClientRect().right),"
               "scrolls: pre && pre.scrollWidth > pre.clientWidth, img: img && img.complete && img.naturalWidth,"
               "imgRight: img && Math.round(img.getBoundingClientRect().right), miss: miss && miss.textContent,"
               "previews: labs.map((l) => !!l.querySelector('.opt-preview, .opt-shot, .opt-missing')),"
               "pages: document.documentElement.scrollWidth}; })()")

    def test_option_previews_show_a_sketch_a_picture_and_a_missing_picture_on_both_widths(self):
        # a variant is judged by sight. `preview` of an option: an ASCII block (monospace, spaces and
        # line breaks as written, scrolls sideways inside the card) or a path to a picture (served by the page; a click
        # opens it large, not answers); a picture that is gone is a line, not a broken icon; no preview — as before
        long = "[ OK ]" + " " * 20 + "·" * 200
        self.preview_card(["┌──────┐\n│  OK  │  " + long + "\n└──────┘", "SHOT"])
        shot = os.path.join(tempfile.gettempdir(), "e2e-preview-narrow.png")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Which button is better?"},
                        {"until": "!!document.querySelector('.ask-card img.opt-img') && document.querySelector('.ask-card img.opt-img').complete"
                                  " && !!document.querySelector('.ask-card .opt-missing')", "ms": 10000},
                        {"eval": self.PREVIEW}, {"shot": shot, "width": 390, "height": 900}, {"sleep": 300}, {"eval": self.PREVIEW})
        wide, narrow = got[3]["eval"], got[-1]["eval"]
        self.assertIn("┌──────┐\n│  OK  │", wide["text"], got)           # line breaks and spaces are kept
        self.assertEqual((wide["ws"], wide["ox"]), ("pre", "auto"), got)
        self.assertIn("mono", wide["mono"].lower(), got)                 # monospace: columns of a sketch line up
        self.assertGreater(wide["img"], 0, got)                          # the picture loaded from the page
        self.assertEqual(wide["previews"], [True, True, True, False], got)   # the empty preview adds nothing
        self.assertIn("/nope/gone.png", wide["miss"], got)
        self.assertLessEqual(narrow["right"], 390, got)                  # the card frame is whole on a phone
        self.assertLessEqual(narrow["pw"], 390, got)
        self.assertTrue(narrow["scrolls"], got)                          # the long line scrolls inside the block
        self.assertLessEqual(narrow["pages"], 390, got)                  # the page itself does not scroll sideways
        # a click on the picture opens it large and answers nothing
        got = self.page({"eval": "document.querySelector('.ask-card img.opt-img').click(), 1"},
                        {"until": "!!document.querySelector('.lightbox:not([hidden])')", "ms": 3000},
                        {"eval": "document.querySelector('.lightbox .lb-img').src"})
        self.assertIn("/api/file?path=", got[-1]["eval"])
        self.assertFalse([e for e in self.spooled() if e["type"] == "permission.answered"])

    def test_an_option_preview_is_text_never_html_and_a_picture_loads_only_from_the_file_routes(self):
        # a preview is the session's text: markup in it is shown as written and runs nothing; every picture of a card
        # comes from /api/file or the Files window's /raw, never from an address the text names
        evil = '<img src="http://127.0.0.1:9/x.png" onerror="window.__pwn=1"><b>bold</b><script>window.__pwn=2</script>'
        self.preview_card([evil, "SHOT"])
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Which button is better?"},
                        {"until": "!!document.querySelector('.ask-card img.opt-img') && document.querySelector('.ask-card img.opt-img').complete",
                         "ms": 10000}, {"sleep": 300},
                        {"eval": "(() => { const pre = document.querySelector('.ask-card pre.opt-preview');"
                                 "return {text: pre.textContent, kids: pre.children.length, pwn: window.__pwn || 0,"
                                 "srcs: [...document.querySelectorAll('.ask-card img')].map((i) => i.getAttribute('src'))}; })()"})
        r = got[-1]["eval"]
        self.assertEqual((r["text"], r["kids"], r["pwn"]), (evil, 0, 0), got)
        self.assertTrue(r["srcs"] and all(x.startswith(("/api/file?path=", "http://127.0.0.1:")) and "x.png" not in x
                                          for x in r["srcs"]), got)

    def test_a_preview_path_to_a_report_a_pdf_or_a_folder_is_the_file_not_the_path_as_text(self):
        # a preview naming a report.html used to show the bare path in monospace, cut off at the card's edge. One path to
        # a file that is not a picture is that file: an html report is its live frame from "Files" /render (its pictures
        # load by their relative paths there) above its name, a click opens it whole in a new tab; a pdf goes to the
        # browser's viewer (/raw), a folder to "Files"; a file that is not there is its name, "not found", no link;
        # opening a file answers nothing
        report = os.path.join(os.path.realpath(self.state), "states", "report.html")
        os.makedirs(os.path.dirname(report), exist_ok=True)
        with open(report, "w", encoding="utf-8") as f:
            f.write("<h1>report</h1>")
        with open(os.path.join(os.path.dirname(report), "spec.pdf"), "wb") as f:
            f.write(b"%PDF-1.4")
        from unittest import mock
        home = mock.patch.dict(os.environ, {"HOME": os.path.dirname(report), "USERPROFILE": os.path.dirname(report)})
        home.start()
        self.addCleanup(home.stop)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        q = {"questions": [{"question": "Which layout?", "options": [
            {"label": "Sketch", "preview": "+--+\n|  |\n+--+"},
            {"label": "Report", "preview": report},
            {"label": "Spec", "preview": os.path.join(os.path.dirname(report), "spec.pdf")},
            {"label": "Folder", "preview": pathlib.Path(os.path.dirname(report)).as_uri() + "/"},
            {"label": "Home", "preview": "~/spec.pdf"},   # the session's folder is not under a home: only the server expands "~"
            {"label": "Gone", "preview": "/nope/gone.pdf"}]}]}
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input=q)
        card = ("(() => [...document.querySelectorAll('.ask-card label.opt')].map((l) => {"
                "const b = l.querySelector('.opt-file'), a = b && b.querySelector('a'), f = b && b.querySelector('iframe');"
                "return {file: !!b, pre: !!l.querySelector('pre.opt-preview'), text: b ? b.textContent : null,"
                "name: b && b.querySelector('.opt-file-name').textContent, href: a && a.getAttribute('href'),"
                "tab: a && a.target, icon: !!(b && b.querySelector('svg.icon, .kit-img')),"
                "frame: f && f.getAttribute('src'), sandbox: f && f.getAttribute('sandbox'), inert: f && getComputedStyle(f).pointerEvents,"
                "fw: f ? Math.round(f.getBoundingClientRect().width) : 0,"
                "sw: f ? Math.round(f.parentNode.getBoundingClientRect().width) : 0}; }))()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Which layout?"},
                        {"until": "document.querySelectorAll('.ask-card .opt-file a[href]').length === 4"
                                  " && !!document.querySelector('.ask-card .opt-file.missing')", "ms": 10000},
                        {"sleep": 300}, {"eval": card})
        sketch, rep, pdf, folder, home, gone = got[-1]["eval"]
        self.assertTrue(sketch["pre"] and not sketch["file"], got)       # an ASCII sketch stays a sketch
        for t in (rep, pdf, folder, home, gone):
            self.assertTrue(t["file"] and not t["pre"] and t["icon"], got)   # never the path in monospace
            self.assertNotIn("/", t["text"], got)                         # the name, not the path
        self.assertEqual([t["name"] for t in (rep, pdf, folder, home, gone)],
                         ["report.html", "spec.pdf", "states", "spec.pdf", "gone.pdf"])
        self.assertIn("/render/", rep["frame"], got)                      # the report itself, live
        self.assertTrue(rep["frame"].endswith("/states/report.html"), got)
        self.assertEqual((rep["sandbox"], rep["inert"]), ("allow-scripts", "none"), got)
        self.assertLessEqual(abs(rep["fw"] - rep["sw"]), 3, got)         # scaled down to the option's width
        self.assertEqual((rep["href"], rep["tab"]), (rep["frame"], "_blank"), got)   # a click: the report whole, a new tab
        self.assertRegex(pdf["href"], r"/raw\?root=[^&]+&path=.*spec\.pdf$", got)   # by the root and path the server resolved
        self.assertRegex(home["href"], r"/raw\?root=[^&]+&path=.*spec\.pdf$", got)   # "~/spec.pdf" is a link that works too
        self.assertEqual((pdf["frame"], pdf["tab"]), (None, "_blank"), got)
        self.assertIn("/#/", folder["href"], got)                         # a folder in "Files"
        self.assertEqual(folder["tab"], "_blank", got)
        self.assertIsNone(gone["href"], got)                              # not there: no link, and says so
        self.assertIn(i18n.t("web.cards.file_missing"), gone["text"], got)
        # following the link opens a tab and picks no option (a click inside the option's label)
        got = self.page({"eval": "document.querySelectorAll('.ask-card .opt-file a[href]')[1].click(), 1"}, {"sleep": 500},
                        {"eval": "[...document.querySelectorAll('.ask-card input')].filter((i) => i.checked).length"})
        self.assertEqual(got[-1]["eval"], 0, got)
        self.assertFalse([e for e in self.spooled() if e["type"] == "permission.answered"])

    def test_a_picture_rewritten_under_the_same_path_shows_anew_in_the_next_question(self):
        # a session sent a question with a preview path, then redrew the file under the same name and asked again: the page
        # keeps a loaded picture per address (even under no-store) until it is closed, so the address carries the question
        shot = self.preview_card(["sketch", "SHOT"])
        wide = ("(() => { const i = document.querySelector('.ask-card[data-ask=\"%s\"] img.opt-img');"
                " return i && i.complete ? i.naturalWidth : 0; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Which button is better?"},
                        {"until": wide % "r1" + " > 0", "ms": 10000}, {"eval": wide % "r1"})
        self.assertEqual(got[-1]["eval"], 300, got)
        import struct
        import zlib
        rows = b"".join(b"\0" + b"\x40\x80\xf0" * 200 for _ in range(100))
        chunk = lambda t, d: struct.pack(">I", len(d)) + t + d + struct.pack(">I", zlib.crc32(t + d))  # noqa: E731
        with open(shot, "wb") as f:   # the same path, another picture (200 px wide)
            f.write(b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", 200, 100, 8, 2, 0, 0, 0))
                    + chunk(b"IDAT", zlib.compress(rows)) + chunk(b"IEND", b""))
        q = {"questions": [{"question": "And now?", "options": [{"label": "One", "preview": shot}, {"label": "Two"}]}]}
        self.ev("turn.tool", "a", id="t2", name="AskUserQuestion", input=q)
        self.ev("permission.requested", "a", request_id="r2", tool="AskUserQuestion", interactive=True, input=q)
        got = self.page({"until": wide % "r2" + " > 0", "ms": 10000}, {"eval": wide % "r2"})
        self.assertEqual(got[-1]["eval"], 200, got)   # the new file, not the one the page loaded for the first question

    # the card option has settled: its top did not move for 300 ms. Right after load the feed is still scrolling to the
    # bottom, and a click at the old coordinates lands beside the option (with no redraw at all; under load 1–2 of 6)
    OPT_STEADY = {"until": "(() => { const o = document.querySelector('.ask-card label.opt'); if (!o) return false;"
                           "const t = Math.round(o.getBoundingClientRect().top), now = Date.now();"
                           "if (window.__ot !== t) { window.__ot = t; window.__otAt = now; } return now - window.__otAt > 300; })()", "ms": 8000}

    def test_a_repaint_between_press_and_release_does_not_lose_the_click_on_a_card(self):
        # owner report: the first click on a question card does not work, a radio button cannot be selected on the first
        # try. The feed is redrawn on every snapshot and removes all nodes from the page, the card included; a browser whose
        # pressed node is removed from the page between mouse down and mouse up sends no click
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": "First?", "options": [{"label": "Yes"}, {"label": "No"}]},
                          {"question": "Second?", "options": [{"label": "One"}, {"label": "Two"}]}]})
        # a redraw in the middle of a click is like a snapshot arriving from the stream; we remember the card node and watch
        # whether it was removed
        repaint = ("(() => { const c = document.querySelector('.feed .ask-card'); window.__card = c; window.__out = 0;"
                   "new MutationObserver((ms) => { for (const m of ms) for (const n of m.removedNodes) if (n === c || n.contains?.(c)) window.__out++; })"
                   ".observe(document.querySelector('main'), {childList: true, subtree: true});"
                   "import('/static/js/state.js').then((m) => m.render()); return 1; })()")
        state = ("(() => ({same: document.querySelector('.feed .ask-card') === window.__card, out: window.__out,"
                 "checked: [...document.querySelectorAll('.ask-card input:checked')].map((x) => x.value)}))()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "First?"}, self.OPT_STEADY,
                        {"drag": ".ask-card label.opt", "to": ".ask-card label.opt", "between": repaint},
                        {"sleep": 300}, {"eval": state})
        self.assertEqual(got[-1]["eval"], {"same": True, "out": 0, "checked": ["Yes"]})   # same node, not removed, the choice was accepted

    def test_a_tap_on_the_only_option_answers_even_when_the_feed_repaints_meanwhile(self):
        # the same click on a card with one question and one choice: tapping an option is an immediate answer
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": "Only one?", "options": [{"label": "Yes"}, {"label": "No"}]}]})
        repaint = "import('/static/js/state.js').then((m) => m.render()); 1"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Only one?"}, self.OPT_STEADY,
                        {"drag": ".ask-card label.opt", "to": ".ask-card label.opt", "between": repaint},
                        {"until": "document.querySelectorAll('.feed .ask-card:not(.sent)').length === 0", "ms": 3000})
        self.assertTrue(got[-1]["until"])                    # the card collapsed at once, before the core snapshot
        sent = [e["data"] for e in self.spooled() if e["type"] == "permission.answered"]
        self.assertEqual([d.get("answers") for d in sent], [{"Only one?": "Yes"}])

    def one_question(self):
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": "Only one?", "options": [{"label": "Yes"}, {"label": "No"}]}]})

    # whether the card is collapsed and what is in its row: {sent, line, live}; live: visible options and buttons
    FOLD = ("(() => { const c = document.querySelector('.feed .ask-card'); return c && {sent: c.classList.contains('sent'),"
            "line: c.querySelector('.sent-line')?.textContent || null, err: c.querySelector('.error-text').textContent,"
            "live: [...c.querySelectorAll('.opt, button:not(.card-aim)')].filter((x) => x.offsetParent).length}; })()")

    def test_a_tap_folds_the_card_at_once_while_the_core_is_slow_to_record_the_answer(self):
        # owner report: repeated clicks on the card with no reaction. The page waited for the server's receipt, and the server
        # waits until the core records the answer (decide_wait, up to 3 s; under load 4–5 s from the click until the card
        # leaves), and all that time a single-question card looked untouched. Now on click it collapses at once into a row
        # with the answer, and the receipt changes only the row. The page CPU is 6 times slower, as on a busy machine
        self.one_question()
        self.web.decide_wait = 3   # there is no hubd in the test: the server waits the full 3 s and answers "in the mailbox"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Only one?"}, {"cpu": 6}, self.OPT_STEADY,
                        {"eval": "(window.__t0 = performance.now(), 1)"},
                        {"drag": ".ask-card label.opt", "to": ".ask-card label.opt"},
                        {"until": "document.querySelector('.feed .ask-card.sent') && Math.round(performance.now() - window.__t0)", "ms": 2500},
                        {"eval": self.FOLD},
                        {"until": "!!document.querySelector('.sent-line')?.textContent.includes('queued')", "ms": 8000})
        self.assertTrue(got[3]["until"], got)                # the card stood still: the tap did not miss
        self.assertTrue(got[6]["until"])                     # collapsed without waiting for the server
        self.assertLess(got[6]["until"], 2500)
        self.assertEqual(got[7]["eval"], {"sent": True, "line": "Your answer: Yes — sending…", "err": "", "live": 0})
        self.assertTrue(got[8]["until"])                     # the receipt arrived: the core (absent here) did not record it, so "queued"
        sent = [e["data"] for e in self.spooled() if e["type"] == "permission.answered"]
        self.assertEqual([d.get("answers") for d in sent], [{"Only one?": "Yes"}])

    def test_a_double_tap_and_a_tap_on_the_other_option_send_one_answer(self):
        # a collapsed card does not send twice: neither a double tap on an option, nor a tap on another while the answer is
        # in flight
        self.one_question()
        self.web.decide_wait = 1
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Only one?"},
                        {"eval": "(() => { const o = document.querySelectorAll('.ask-card label.opt input');"
                                 "o[0].click(); o[0].click(); o[1].click(); document.querySelector('.ask-card').requestSubmit(); return 1; })()"},
                        {"until": "!!document.querySelector('.sent-line')?.textContent.includes('queued')", "ms": 5000})
        self.assertTrue(got[-1]["until"])
        sent = [e["data"] for e in self.spooled() if e["type"] == "permission.answered"]
        self.assertEqual([d.get("answers") for d in sent], [{"Only one?": "Yes"}])

    def test_an_answer_the_server_failed_to_take_is_sent_again_once(self):
        # the server did not answer or failed (5xx): the answer stays queued and goes again with the same client_id; once it
        # arrives, there is one, and once the core recorded it the question is removed and the card left with no refusal. The
        # fake server answers 503 until the test has seen "retrying" (the line lives until the next attempt, ~1 s; under load
        # polling could miss it), and accepts the answer afterwards; the tap happens once the option has settled (otherwise
        # under load it landed beside it and there was no request at all)
        self.one_question()
        self.core_decides()
        real, calls, seen = self.web.answer, [], threading.Event()

        def flaky(*a):
            calls.append(a[1].get("client_id"))
            return real(*a) if seen.is_set() else (503, "server busy")
        with mock.patch.object(self.web, "answer", side_effect=flaky):
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Only one?"}, self.OPT_STEADY,
                            {"drag": ".ask-card label.opt", "to": ".ask-card label.opt"},
                            {"until": "!!document.querySelector('.sent-line')?.textContent.includes('retrying')", "ms": 15000})
            self.assertTrue(got[2]["until"] and got[4]["until"])   # the option settled; between attempts: "retrying"
            seen.set()
            got = self.page({"until": "!document.querySelector('.feed .ask-card')", "ms": 20000},
                            {"eval": "document.getElementById('banner').textContent"})
        self.assertEqual((got[0]["until"], got[1]["eval"]), (True, ""))   # the core recorded it: the question is removed, without refusal
        self.assertGreaterEqual(len(calls), 2)
        self.assertEqual(len(set(calls)), 1)                 # every retry is the same answer for the server
        self.assertTrue(calls[0])
        sent = [e["data"] for e in journal.read(self.j.path) if e["type"] == "permission.answered"]
        self.assertEqual([d.get("answers") for d in sent], [{"Only one?": "Yes"}])

    def test_typed_text_stays_when_the_question_goes_while_the_answer_is_still_in_flight(self):
        # review: the owner's own answer is typed and sent, the hub does not respond (retries), and meanwhile the question was
        # removed (answered from Telegram, hub restart): the card vanished together with the typed text, and the late refusal
        # went out silently. Now the card freezes with the text, and the refusal shows in the strip
        self.one_question()
        real, down = self.web.answer, [True]
        with mock.patch.object(self.web, "answer", side_effect=lambda *a: (503, "server busy") if down[0] else real(*a)):
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Only one?"},
                            {"eval": "(() => { const t = document.querySelector('.ask-card [name=other0]'); t.value = 'my text';"
                                     "t.dispatchEvent(new Event('input', {bubbles: true})); document.querySelector('.ask-card').requestSubmit(); return 1; })()"},
                            {"until": "!!document.querySelector('.sent-line')?.textContent.includes('retrying')", "ms": 3000})
            self.assertTrue(got[-1]["until"])
            self.ev("permission.answered", "a", request_id="r1", behavior="allow", answers={"Only one?": "No"},
                    channel="telegram", owner=True)
            got = self.page({"until": "!!document.querySelector('.ask-card.frozen')", "ms": 5000},
                            {"eval": "document.querySelector('.ask-card.frozen [name=other0]')?.value"})
            self.assertTrue(got[0]["until"])
            self.assertEqual(got[1]["eval"], "my text")
            down[0] = False   # the hub is back: the question was already answered by someone else, the refusal is visible
            got = self.page({"until": "!!document.getElementById('banner').textContent.startsWith('Answer not sent')", "ms": 15000})
        self.assertTrue(got[0]["until"])
        self.assertEqual([e for e in self.spooled() if e["type"] == "permission.answered"], [])

    def test_a_queued_answer_says_so_and_opens_again_when_the_core_refuses_it(self):
        # review: 202 queued (the core did not record within decide_wait) was shown as "sent"; the core then refused, so the
        # question is open while the card hung collapsed. Now it shows "queued", the outcome comes via the same request, and a
        # refusal turns the card into one with the reason
        self.one_question()
        self.web.decide_wait = 0
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Only one?"}, self.OPT_STEADY,
                        {"drag": ".ask-card label.opt", "to": ".ask-card label.opt"},
                        {"until": "!!document.querySelector('.sent-line')?.textContent.includes('queued')", "ms": 3000})
        self.assertTrue(got[2]["until"], got)
        self.assertTrue(got[-1]["until"])
        from core import spool
        ((path, item),) = [x for x in spool.take(os.path.join(self.state, "spool")) if x[1]["type"] == "permission.answered"]
        test_web.write_decided(self.j, self.j.event(item["type"], item["entity"], item["data"], src="web"), "Session busy")
        os.unlink(path)
        got = self.page({"until": "document.querySelector('.ask-card .error-text').textContent", "ms": 15000}, {"eval": self.FOLD})
        self.assertEqual(got[1]["eval"], {"sent": False, "line": None, "err": "Answer not sent: Session busy", "live": 4})

    def test_a_refusal_after_leaving_the_session_opens_its_card_again(self):
        # PR #268 review (high): the answer is queued, the owner moved to another session, the core refused: the card stayed
        # collapsed as "queued" forever (the refusal arrived in an off-screen node and only as a strip); now on return it is
        # expanded with the reason
        self.one_question()
        self.ev("session.requested", "b", session_id="s-b", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "b", session_id="s-b")
        self.web.decide_wait = 0
        url = f"http://127.0.0.1:{self.port}/#/s/"
        got = self.page({"go": url + "a"}, {"wait": "Only one?"},
                        {"eval": "import('/static/js/cards.js').then((m) => { Object.assign(m.RETRY, {ms: [300], tries: 33}); window.__retry = 1; }); 1"},
                        {"until": "window.__retry === 1"}, self.OPT_STEADY, {"drag": ".ask-card label.opt", "to": ".ask-card label.opt"},
                        {"until": "!!document.querySelector('.sent-line')?.textContent.includes('queued')", "ms": 3000},
                        {"go": url + "b"}, {"sleep": 500})
        self.assertTrue(got[3]["until"] and got[4]["until"], got)   # the poll is shortened, the card stood still
        self.assertTrue(got[-3]["until"])
        from core import spool
        ((path, item),) = [x for x in spool.take(os.path.join(self.state, "spool")) if x[1]["type"] == "permission.answered"]
        test_web.write_decided(self.j, self.j.event(item["type"], item["entity"], item["data"], src="web"), "Session busy")
        os.unlink(path)
        got = self.page({"sleep": 2500}, {"go": url + "a"}, {"until": "document.querySelector('.ask-card .error-text')?.textContent", "ms": 8000},
                        {"eval": self.FOLD})
        self.assertEqual(got[-1]["eval"], {"sent": False, "line": None, "err": "Answer not sent: Session busy", "live": 4})

    def test_a_queued_answer_the_core_never_records_opens_the_card_again(self):
        # review: the "queued" polling ended and the card stayed collapsed forever: no way to answer again or close it, and
        # nobody asks about a late refusal. Now it is expanded with the reason, as after server failures. Polling is shortened
        self.one_question()
        self.web.decide_wait = 0
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Only one?"},
                        {"eval": "import('/static/js/cards.js').then((m) => { Object.assign(m.RETRY, {ms: [100], tries: 2}); window.__retry = 1; }); 1"},
                        {"until": "window.__retry === 1"}, self.OPT_STEADY,
                        {"drag": ".ask-card label.opt", "to": ".ask-card label.opt"},
                        {"until": "document.querySelector('.ask-card .error-text').textContent", "ms": 5000},
                        {"eval": self.FOLD})
        self.assertTrue(got[3]["until"] and got[4]["until"], got)   # the poll is shortened, the card stood still
        self.assertEqual(got[-1]["eval"], {"sent": False, "line": None, "live": 4,
                                           "err": "Answer not sent: the hub never recorded the answer. Is hubd running? (hub status)"})
        self.assertEqual(len([e for e in self.spooled() if e["type"] == "permission.answered"]), 1)   # polling without a second fact

    def test_a_queued_answer_the_core_takes_leaves_no_frozen_card(self):
        # own answer queued, the core recorded it: the question left the snapshot together with the typed text, so this is our
        # answer (answered[] with our client_id) and there is nothing to freeze
        self.one_question()
        self.web.decide_wait = 0
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Only one?"},
                        {"eval": "(() => { const t = document.querySelector('.ask-card [name=other0]'); t.value = 'my text';"
                                 "t.dispatchEvent(new Event('input', {bubbles: true})); document.querySelector('.ask-card').requestSubmit(); return 1; })()"},
                        {"until": "!!document.querySelector('.sent-line')?.textContent.includes('queued')", "ms": 3000})
        self.assertTrue(got[-1]["until"])
        from core import spool
        for path, item in spool.take(os.path.join(self.state, "spool")):
            self.j.append(item["type"], item["entity"], item["data"], src="web")
            os.unlink(path)
        got = self.page({"until": "!document.querySelector('.ask-card')", "ms": 8000}, {"sleep": 500},
                        {"eval": "document.querySelectorAll('.ask-card').length"})
        self.assertEqual(got[-1]["eval"], 0)

    def test_a_refused_answer_opens_the_card_again_with_the_reason(self):
        # a server refusal (4xx) is pointless to retry: the card expands, the reason is in it, the option can be chosen again
        self.one_question()
        # tap once the card stands still: under load it was still moving and the click missed (the server was not called)
        with mock.patch.object(self.web, "answer", return_value=(409, "Session no longer waits")):
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Only one?"}, self.OPT_STEADY,
                            {"drag": ".ask-card label.opt", "to": ".ask-card label.opt"},
                            {"until": "!!document.querySelector('.ask-card .error-text')?.textContent", "ms": 3000},
                            {"eval": self.FOLD},
                            {"eval": "document.querySelectorAll('.ask-card input:checked').length"})
        self.assertTrue(got[2]["until"], got)
        self.assertTrue(got[4]["until"], got)
        self.assertEqual(got[5]["eval"], {"sent": False, "line": None, "err": "Answer not sent: Session no longer waits",
                                          "live": 4})
        self.assertEqual(got[6]["eval"], 0)                  # the choice is cleared: the same option can be tapped again

    def test_the_card_stays_in_place_inside_a_search_excerpt_and_after_leaving_it(self):
        # the search excerpt built its own feed and again removed the card from the page on every snapshot; and on leaving the
        # excerpt the feed remained its node, without aria-live
        from core import history, journal, reducer
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.turn("a", "old question", said="old beacon")
        for i in range(4):
            self.turn("a", f"noise {i}", said="nothing")
        st = reducer.fold(reducer.empty(), journal.read(self.j.path))
        journal.rotate(self.state, st, keep=2, per_session=2)
        self.j = journal.Journal(self.j.path)
        for i in range(160):
            self.turn("a", f"fresh {i}", said=f"fresh reply {i}")
        history.History(self.state).build_all()
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": "First?", "options": [{"label": "Yes"}, {"label": "No"}]},
                          {"question": "Second?", "options": [{"label": "One"}, {"label": "Two"}]}]})
        self.settle()
        mark = ("(() => { const c = window.__card = document.querySelector('.feed .ask-card'); window.__out = 0;"
                "new MutationObserver((ms) => { for (const m of ms) for (const n of m.removedNodes) if (n === c || n.contains?.(c)) window.__out++; })"
                ".observe(document.querySelector('main'), {childList: true, subtree: true}); return !!c; })()")
        # page redraw; then: whether the card node was removed, whether it is last, and whether the feed has aria-live
        repaint = "import('/static/js/state.js').then((m) => m.render()); 1"
        state = ("(() => { const i = document.querySelector('main .feed-inner'); return {"
                 "same: document.querySelector('.feed .ask-card') === window.__card, out: window.__out, last: i.lastElementChild === window.__card,"
                 "live: i.getAttribute('aria-live'), excerpt: !!document.querySelector('.excerpt-head'),"
                 "cards: document.querySelectorAll('.feed .ask-card').length}; })()")
        with mock.patch.object(history, "SEARCH_BUDGET", 0):
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "First?"},
                            {"eval": "document.querySelector('.fs-lupa').click(), 1"}, {"typed": "old beacon"}, {"sleep": 400},
                            {"key": "Enter"}, {"until": "!!document.querySelector('.excerpt-head')", "ms": 20000},
                            {"sleep": 500}, {"eval": mark}, {"eval": repaint}, {"sleep": 300}, {"eval": state},
                            {"eval": "[...document.querySelectorAll('.excerpt-head button')].find((b) => b.textContent === 'Back to the feed').click(), 1"},
                            {"sleep": 500}, {"eval": state})
        self.assertTrue(got[8]["eval"])
        # in the excerpt there is no aria-live, as before the PR: entering the excerpt is not read out in full
        # (PR #268 review)
        self.assertEqual(got[11]["eval"], {"same": True, "out": 0, "last": True, "live": None, "excerpt": True, "cards": 1})
        self.assertEqual(got[14]["eval"], {"same": True, "out": 0, "last": True, "live": "polite", "excerpt": False, "cards": 1})   # after leaving

    def test_answering_one_of_two_cards_leaves_the_other_where_it_was(self):
        # the set of cards changed, so the feed is rebuilt, but the remaining card is the same one, and the answered one left
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        for rid, q in (("r1", "First?"), ("r2", "Second?")):
            self.ev("permission.requested", "a", request_id=rid, tool="AskUserQuestion", interactive=True, input={
                "questions": [{"question": q, "options": [{"label": "Yes"}, {"label": "No"}]}]})
        mark = "(() => { window.__second = document.querySelectorAll('.feed .ask-card')[1]; return !!window.__second; })()"
        state = ("(() => ({same: document.querySelector('.feed .ask-card:not(.sent)') === window.__second,"
                 "cards: [...document.querySelectorAll('.feed .ask-card:not(.sent)')].map((c) => c.dataset.ask)}))()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Second?"}, {"eval": mark},
                        {"eval": "document.querySelector('.ask-card label.opt input').click(), 1"}, {"sleep": 500}, {"eval": state})
        self.assertTrue(got[2]["eval"])
        self.assertEqual(got[-1]["eval"], {"same": True, "cards": ["r2"]})

    # a link in the text of a reply: a snapshot from the stream (renderLive) arrives between mouse down and mouse up, and the
    # click on the link must still happen. `what` is a css selector of the pressed node (the link or something inside it);
    # `during` is JS run in the page together with the snapshot (m is the state.js module, S its state); `keep` — hold the
    # button down for `hold` ms instead of releasing at once. The page state: the click (the link, whether the pressed node was
    # still in the page when it came), and whether the redraw that was put off has happened since
    def press_link(self, said, what, during="", hold=None, steps=(), redraw="m.renderLive();", feed=None, init=None, pre=()):
        # said=None: the journal is already there (long_feed); redraw is what the page does between the press and the release
        # instead of a snapshot; pre are steps before the press; feed and init are the page's feed mode and its init script
        if said is not None:
            self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
            self.ev("session.started", "a", session_id="s-a")
            self.ev("turn.started", "a", marker=None)
            self.ev("session.said", "a", text=said)
            self.ev("turn.result", "a", text=said)
        go = [{"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/s/a", **({"feed": feed} if feed else {}), **({"init": init} if init else {})}]
        if not (feed or init):
            go = [go[1]]
        # a click on a link is caught (and its navigation cancelled): which link, and how many nodes had been removed by then
        catch = ("(() => { window.__hits = []; document.addEventListener('click', (e) => { const a = e.target.closest?.('a'); "
                 "if (a) { e.preventDefault(); window.__hits.push([a.getAttribute('href'), window.__out]); } }, true); return 1; })()")
        steady = {"until": "(() => { const o = document.querySelector(%s); if (!o) return false;"
                           "const t = Math.round(o.getBoundingClientRect().top), now = Date.now();"
                           "if (window.__ot !== t) { window.__ot = t; window.__otAt = now; } return now - window.__otAt > 300; })()"
                           % json.dumps(what), "ms": 8000}
        # the pressed node and its link are remembered, a removal of either is counted (MutationObserver, not ===: a node
        # taken out and put back is the same node, but the browser has already dropped the click)
        repaint = ("(() => { const n = document.querySelector(%s), a = n.closest('a'); window.__out = 0; window.__node = n;"
                   "new MutationObserver((ms) => { for (const m of ms) for (const r of m.removedNodes) if (r === n || r === a || r.contains?.(n)) window.__out++; })"
                   ".observe(document.querySelector('main'), {childList: true, subtree: true});"
                   "import('/static/js/state.js').then((m) => { const S = m.S; %s %s %s }); return 1; })()") % (json.dumps(what), self.EDIT, during, redraw)
        drag = {"drag": what, "to": what, "between": repaint}
        if hold:
            got = self.page(*go, {"wait": "Summary"},
                            {"until": "!document.querySelector('.path-wait')"}, *pre, {"eval": catch}, steady,
                            {**drag, "keep": True}, {"sleep": hold}, {"eval": "window.__out"}, {"drop": 1}, {"sleep": 400}, *steps)
            return got[-3 - len(steps)]["eval"], got[-1]
        got = self.page(*go, {"wait": "Summary"},
                        {"until": "!document.querySelector('.path-wait')"}, *pre, {"eval": catch}, steady,
                        drag, {"sleep": 500}, *steps)
        return got[-1]

    CLICKED = "(() => ({hits: window.__hits, flushed: window.__out > 0}))()"
    # the redraw during the press changes the pressed reply itself: the feed keeps an unchanged row as the same node, so only
    # a changed one is put in anew — the case where the link would leave the page under the button
    EDIT = ("for (const x of Object.values(S.snap.timelines || {}).flat()) if (typeof x.text === 'string' && x.text.startsWith('Summary'))"
            " x.text += ' (edited)';")

    def test_a_repaint_between_press_and_release_does_not_lose_the_click_on_a_link_in_a_reply(self):
        # owner report: a link in a message sometimes needs several clicks. The feed is redrawn on every snapshot and all
        # its rows are replaced by new nodes; the pressed link is removed from the page between mouse down and mouse up,
        # and the browser sends no click for a removed node. The redraw waits for the release (state.js renderLive)
        got = self.press_link("Summary: [site](https://example.com/x) and more text", ".md a", steps=({"eval": self.CLICKED},))
        self.assertEqual(got["eval"], {"hits": [["https://example.com/x", 0]], "flushed": True})   # the link was there at the click; the redraw came after

    def test_a_repaint_between_press_and_release_does_not_lose_the_click_on_code_inside_a_link(self):
        # the node under the cursor is a child of the link (`code`, bold): removing only it loses the click too
        got = self.press_link("Summary: [`site`](https://example.com/x) and **more** text", ".md a code", steps=({"eval": self.CLICKED},))
        self.assertEqual(got["eval"], {"hits": [["https://example.com/x", 0]], "flushed": True})

    def test_a_snapshot_that_came_while_the_button_was_down_is_drawn_after_the_release(self):
        # the held redraw is not lost: what arrived during the press is on the page right after it, the same as a redraw
        # without a press would have made it
        add = ("S.snap.timelines.a = [...S.snap.timelines.a, {kind: 'out', seq: 99999, ts: Date.now() / 1000, text: 'Arrived during the press'}];")
        got = self.press_link("Summary: [site](https://example.com/x)", ".md a", during=add,
                              steps=({"until": "document.querySelector('.feed').innerText.includes('Arrived during the press')", "ms": 3000},))
        self.assertTrue(got["until"])

    def test_a_snapshot_between_the_release_and_the_click_does_not_lose_the_click_on_a_link(self):
        # the click is a separate event after the release (a touch tap comes after pointerup): a snapshot drawn in that gap
        # takes the link out of the page just as one drawn during the press. The listener stands for it: it redraws right in
        # pointerup, after the page's own handler has seen the release
        late = "document.addEventListener('pointerup', () => m.renderLive(), true);"
        got = self.press_link("Summary: [site](https://example.com/x) and more text", ".md a", during=late, steps=({"eval": self.CLICKED},))
        self.assertEqual(got["eval"], {"hits": [["https://example.com/x", 0]], "flushed": True})

    def test_a_press_the_page_never_sees_released_does_not_freeze_the_redraw(self):
        # the release that never comes (outside the window, a context menu): the redraw is put off, but not for good
        out, _ = self.press_link("Summary: [site](https://example.com/x)", ".md a", hold=3600, steps=({"eval": self.CLICKED},))
        self.assertGreater(out, 0)   # drawn with the button still down, after the hold ran out

    # "Show earlier" in a feed with a link: the page of the past arrives while the button is down. HOLD_HIST keeps the answer
    # of /api/history in the page until window.__held() is called, so the test lets it in at the exact moment (the answer is
    # handed over as an object, so the whole continuation of loadOlder runs in the same task as the call)
    HOLD_HIST = ("(() => { const of = window.fetch; window.__held = null; window.__open = false; window.fetch = (u, o) => { "
                 "if (!String(u).startsWith('/api/history')) return of(u, o); "
                 "return of(u, o).then((r) => r.json()).then((j) => new Promise((go) => { window.__held = () => go({json: () => Promise.resolve(j)}); "
                 "if (window.__open) go({json: () => Promise.resolve(j)}); })); }; return 1; })()")
    LET_IN = "window.__open = true; window.__held && window.__held();"
    OLDER = "↑ Show earlier"

    def long_feed(self, said, name="a", **reg):
        # the first window is 150 rows: the first turn (with text) is above it, the long one is cut, the last has the reply
        self.ev("session.requested", name, session_id=f"s-{name}", cwd="/w", channel="cli", owner=True, **reg)
        self.ev("session.started", name, session_id=f"s-{name}")
        self.turn(name, "Old question", said="Old word")
        self.turn(name, "Long turn", steps=160)
        self.turn(name, "Last question", said=said)
        self.settle()

    def test_history_arriving_while_a_link_is_pressed_does_not_lose_the_click(self):
        # the page of the past ("Show earlier", the retry every 3 s while the archive is built) is drawn by loadOlder: it used
        # to call render() directly, so the pressed link was taken out of the page between mouse down and mouse up
        self.long_feed("Summary: [site](https://example.com/x) and more text")
        got = self.press_link(None, ".md a", redraw=self.LET_IN, feed="full", init=self.NO_SCROLL_LOAD + "; " + self.HOLD_HIST,
                              pre=({"click": self.OLDER}, {"sleep": 300}), steps=(
                                  {"until": "document.querySelector('.feed').innerText.includes('Old word')", "ms": 8000},
                                  {"eval": self.CLICKED}))
        self.assertEqual(got["eval"], {"hits": [["https://example.com/x", 0]], "flushed": True})   # the redraw came after the click

    # the reply of the last turn is the pin: the distance from it to the top of the feed is the reader's place (the steps rows
    # above it merge when older ones arrive, they cannot be compared by key)
    PIN = ("(() => { const f = document.querySelector('main .feed'), r = f.getBoundingClientRect(); "
           "const n = [...f.querySelectorAll('.md')].find((x) => x.innerText.includes('Summary without a link')); "
           "window.__pin = n.getBoundingClientRect().top - r.top; return window.__pin; })()")
    # how far the pin has moved in the feed since PIN (plus 1000: a step with a zero result has no "eval" key in the answer)
    MOVED = ("(() => { const f = document.querySelector('main .feed'), r = f.getBoundingClientRect(); "
             "const n = [...f.querySelectorAll('.md')].find((x) => x.innerText.includes('Summary without a link')); "
             "return Math.round(n.getBoundingClientRect().top - r.top - window.__pin) + 1000; })()")
    UP = "(() => { const f = document.querySelector('main .feed'); f.scrollTop = f.scrollHeight - f.clientHeight - 600; return 1; })()"
    HAVE = {"until": "document.querySelector('.feed').innerText.includes('Old word')", "ms": 8000}

    def test_the_place_in_the_feed_stays_when_history_arrives(self):
        self.place_stays_on_history()

    def test_the_place_in_the_hub_feed_at_the_root_address_stays_when_history_arrives(self):
        # the hub feed at #/ is drawn with no session selected in the address: the place is kept there too
        self.place_stays_on_history("hub", "#/", kind="hub")

    def place_stays_on_history(self, name="a", route="#/s/a", **reg):
        self.long_feed("Summary without a link", name, **reg)
        got = self.page({"go": "about:blank"},
                        {"go": f"http://127.0.0.1:{self.port}/{route}", "feed": "full", "init": self.NO_SCROLL_LOAD + "; " + self.HOLD_HIST},
                        {"wait": "Summary without a link", "ms": 15000}, {"until": "!document.querySelector('.path-wait')"},
                        {"click": self.OLDER}, {"sleep": 300}, {"eval": self.UP}, {"sleep": 300}, {"eval": self.PIN},
                        {"eval": "(" + "() => { " + self.LET_IN + " return 1; })()"}, self.HAVE, {"sleep": 600}, {"eval": self.MOVED})
        self.assertEqual(got[-1].get("eval"), 1000, got[-5:])   # the row the reader had on the screen is in the same place

    def test_the_place_in_the_feed_stays_when_history_arrives_during_a_press_and_the_reader_moves(self):
        self.place_stays_when_the_reader_moves()

    def test_the_place_in_the_hub_feed_at_the_root_address_stays_when_history_arrives_during_a_press(self):
        self.place_stays_when_the_reader_moves("hub", "#/", kind="hub")

    def place_stays_when_the_reader_moves(self, name="a", route="#/s/a", **reg):
        # the redraw waits for the release, and the reader scrolls meanwhile: the distance to the bottom taken when the page
        # arrived is stale by the time of drawing (the place has to be taken at the drawing)
        self.long_feed("Summary without a link", name, **reg)
        got = self.page({"go": "about:blank"},
                        {"go": f"http://127.0.0.1:{self.port}/{route}", "feed": "full", "init": self.NO_SCROLL_LOAD + "; " + self.HOLD_HIST},
                        {"wait": "Summary without a link", "ms": 15000}, {"until": "!document.querySelector('.path-wait')"},
                        {"click": self.OLDER}, {"sleep": 300}, {"eval": self.UP}, {"sleep": 300},
                        {"drag": ".md", "to": ".md", "between": "(() => { " + self.LET_IN + " return 1; })()", "keep": True},
                        {"sleep": 150}, {"eval": "(() => { const f = document.querySelector('main .feed'); f.scrollTop -= 150; return 1; })()"},
                        {"eval": self.PIN}, {"drop": 1}, self.HAVE, {"sleep": 1500}, {"eval": self.MOVED})
        self.assertEqual(got[-1].get("eval"), 1000, got[-5:])

    def test_the_next_page_of_history_is_not_asked_for_while_the_arrived_one_waits_to_be_drawn(self):
        self.next_page_not_asked()

    def test_the_next_page_of_history_is_not_asked_for_in_the_hub_feed_at_the_root_address(self):
        self.next_page_not_asked("hub", "#/", kind="hub")

    def next_page_not_asked(self, name="a", route="#/s/a", **reg):
        # the page has arrived, but the redraw waits (the button is down; during a scroll it is the same): an inertial scroll
        # at the top of the feed must not ask for the next pages before the first one is drawn
        count = ("(() => { const of = window.fetch; window.__asked = 0; window.fetch = (u, o) => { "
                 "if (String(u).startsWith('/api/history')) window.__asked += 1; return of(u, o); }; return 1; })()")
        top = ("(() => { const f = document.querySelector('main .feed'); f.scrollTop = 0; "
               "f.dispatchEvent(new Event('scroll')); return 1; })()")
        self.ev("session.requested", name, session_id=f"s-{name}", cwd="/w", channel="cli", owner=True, **reg)
        self.ev("session.started", name, session_id=f"s-{name}")
        self.turn(name, "Long turn", steps=450)   # more than one window and one page: there is a next page to ask for
        self.turn(name, "Last question", said="Summary without a link")
        self.settle()
        got = self.page({"go": "about:blank"},
                        {"go": f"http://127.0.0.1:{self.port}/{route}", "feed": "full", "init": count + "; " + self.HOLD_HIST},
                        {"wait": "Summary without a link", "ms": 15000}, {"until": "!document.querySelector('.path-wait')"},
                        {"click": self.OLDER}, {"sleep": 300},
                        {"drag": ".md", "to": ".md", "between": "(() => { " + self.LET_IN + " return 1; })()", "keep": True},
                        {"sleep": 150}, {"eval": top}, {"sleep": 150}, {"eval": top}, {"sleep": 150}, {"eval": top},
                        {"sleep": 300}, {"eval": "window.__asked"}, {"drop": 1})
        self.assertEqual(got[-2].get("eval"), 1, got[-6:])   # the one from the button; the page of it is held, not drawn yet

    def test_a_repaint_between_press_and_release_does_not_lose_the_click_on_a_session_row(self):
        # report: in the left panel a session row sometimes needs two clicks too. The list is rebuilt on every snapshot
        # (~7 a minute when idle), and the pressed row is removed from the page between mouse down and mouse up; the browser
        # sends no click for a removed node, so the session does not open (like the cards in the feed)
        for n in ("a", "b"):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True)
            self.ev("session.started", n, session_id=f"s-{n}")
        row = "'#list li[data-s=\"b\"] > .srow'"
        repaint = ("(() => { const r = document.querySelector(%s); window.__row = r; window.__out = 0;"
                   "new MutationObserver((ms) => { for (const m of ms) for (const n of m.removedNodes) if (n === r || n.contains?.(r)) window.__out++; })"
                   ".observe(document.getElementById('list'), {childList: true, subtree: true});"
                   "import('/static/js/state.js').then((m) => m.render()); return 1; })()") % row
        state = ("(() => ({same: document.querySelector(%s) === window.__row, out: window.__out, hash: location.hash}))()") % row
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"until": f"!!document.querySelector({row})"},
                        {"drag": "#list li[data-s=\"b\"] > .srow", "to": "#list li[data-s=\"b\"] > .srow", "between": repaint},
                        {"sleep": 300}, {"eval": state})
        self.assertEqual(got[-1]["eval"], {"same": True, "out": 0, "hash": "#/s/b"})   # same row, not removed, the session is open

    # press a target inside a row, redraw the list between mouse down and mouse up; the pressed node is not removed
    # before: JS run before the redraw (m is the state.js module), what to change in the snapshot while the button is down
    def press_repaint(self, target, until, drag_from=None, before=""):
        repaint = ("(() => { const r = document.querySelector(%s); window.__row = r; window.__out = 0;"
                   "new MutationObserver((ms) => { for (const m of ms) for (const n of m.removedNodes) if (n === r || n.contains?.(r)) window.__out++; })"
                   ".observe(document.getElementById('list'), {childList: true, subtree: true});"
                   "import('/static/js/state.js').then((m) => { " + before + "m.render(); }); return 1; })()") % json.dumps(target)
        state = "(() => ({same: document.querySelector(%s) === window.__row, out: window.__out, hash: location.hash}))()" % json.dumps(target)
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"until": until},
                        {"drag": target, "to": target, "between": repaint}, {"sleep": 300}, {"eval": state})
        return got[-1]["eval"]

    def test_a_repaint_between_press_and_release_does_not_lose_the_click_on_an_executor_row(self):
        # executor rows under the parent (li.forks > ul > li) without a key were removed and reinserted on every snapshot
        self.ev("session.requested", "atlas", session_id="s-atlas", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "atlas", session_id="s-atlas")
        for n in ("atlas-tiles", "atlas-roads"):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", executor=True, raised_by="atlas")
            self.ev("session.started", n, session_id=f"s-{n}")
        # by its key, not by place: the freshest is on top, and Windows writes the journal a few ms apart (roads first)
        row = '#list li.forks ul > li[data-f="atlas-roads"] > .srow'
        open_forks = "(document.querySelector('#list li[data-s=\"atlas\"] .fork-toggle[aria-expanded=\"false\"]')?.click(), 1)"
        self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"until": "!!document.querySelector('#list .fork-toggle')"}, {"eval": open_forks})
        got = self.press_repaint(row, f"!!document.querySelector('{row}')")
        self.assertEqual(got, {"same": True, "out": 0, "hash": "#/s/atlas-roads"})

    def test_a_repaint_between_press_and_release_does_not_lose_the_click_on_a_working_row(self):
        # a working row differs on almost every snapshot (spinner, "· N s"): the press lands on .nm inside the button, and
        # the browser drops the click if not only the button but also its descendant is removed, so the row content is
        # updated in place
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        row = '#list li[data-s="a"] > .srow .nm'
        got = self.press_repaint(row, f"!!document.querySelector('{row}') && !!document.querySelector('#list li[data-s=\"a\"] .glyph.spin')")
        self.assertEqual(got, {"same": True, "out": 0, "hash": "#/s/a"})

