    def test_a_repaint_between_press_and_release_does_not_lose_the_click_on_a_plugin_badge(self):
        # the plugin badge on a row is a button with its own handler; ext.js returns one node per session, and rebuilding
        # the row carried it away from the live row (append into a detached tree): a press on the badge was lost.
        # The node stays in place
        from unittest import mock
        path = os.path.join(self.state, "plug-btn")
        os.makedirs(path)
        with open(os.path.join(path, "hub-plugin.json"), "w") as f:
            json.dump({"name": "rowbtn", "description": "button", "why": "w", "web": "main.js", "hub": "^1.0"}, f)
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"extensions": {"rowbtn": {"path": path, "web": "main.js"}}}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        with open(os.path.join(path, "main.js"), "w") as f:
            f.write("export default function register(hub) {\n"
                    "  hub.addSlot('sidebar.session', { id: 'b', render(root, snap, ctx) {\n"
                    "    if (!root.firstChild) { const b = document.createElement('button'); b.className = 'pb'; b.textContent = 'B';\n"
                    "      b.onclick = () => { window.__badge = (window.__badge || 0) + 1; }; root.append(b); }\n  } });\n}\n")
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")   # a working row changes on every snapshot
        btn = '#list li[data-s="a"] [data-plugin="rowbtn"] .pb'
        got = self.press_repaint(btn, f"!!document.querySelector('{btn}') && !!document.querySelector('#list li[data-s=\"a\"] .glyph.spin')")
        self.assertEqual(got["same"], True)
        self.assertEqual(got["out"], 0)                                                # the badge node was not removed
        clicks = self.page({"eval": "window.__badge || 0"})
        self.assertEqual(clicks[-1]["eval"], 1)                                        # the click reached the badge handler

