    def test_a_repaint_does_not_lose_the_click_on_a_plugin_badge_when_the_tag_before_it_goes(self):
        # a "reply?" tag (the watchdog's guess) stands before the plugin badge on the row; while the badge is pressed, the tag
        # is removed (a click on it, a work result): row [name, caption, tag, badge] → [name, caption, badge]; the tag goes,
        # the badge stays
        self.plugin_button("rowtag")
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("watch.needs_owner", "a", p=0.8, ask="Merge it?", text="Merge it?", channel="watcher")
        btn = '#list li[data-s="a"] [data-plugin="rowtag"] .pb'
        tag = '#list li[data-s="a"] .tag.dismiss'
        off = "m.S.snap.sessions.find((x) => x.name === 'a').attention = null; "
        got = self.press_repaint(btn, f"!!document.querySelector('{btn}') && !!document.querySelector('{tag}')", before=off)
        self.assertEqual(got["same"], True)
        self.assertEqual(got["out"], 0)                                                # the badge node was not removed
        after = self.page({"eval": f"!!document.querySelector('{tag}')"}, {"eval": "window.__badge || 0"})
        self.assertEqual(after[0]["eval"], False)                                      # the tag really went away
        self.assertEqual(after[1]["eval"], 1)                                          # the click reached the badge handler

    def test_the_plugin_badge_of_a_row_without_a_pair_comes_back_from_the_mark_and_takes_clicks(self):
        # the list is rebuilt entirely (a group is being renamed): the old rows go, and instead of plugin nodes the new ones
        # have placeholders, claim replaces them with the nodes; there is one badge, the same node, and a click on it arrives
        self.plugin_button("rowrename")
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        btn = '#list li[data-s="a"] [data-plugin="rowrename"] .pb'
        state = ("JSON.stringify([document.querySelectorAll('#list li[data-s=\"a\"] [data-plugin=\"rowrename\"]').length,"
                 " document.querySelectorAll('#list span[data-plugin]:empty').length,"
                 " document.querySelector(%s) === window.__btn, !!document.querySelector('.gt-edit')])") % json.dumps(btn)
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"until": f"!!document.querySelector({json.dumps(btn)})"},
                        {"click": "+ Group"},
                        {"until": "document.activeElement && document.activeElement.classList.contains('gt-edit')"},
                        {"eval": "window.__btn = document.querySelector(%s), import('/static/js/state.js').then((m) => m.render()), 1" % json.dumps(btn)},
                        {"sleep": 300}, {"eval": state},
                        {"drag": btn, "to": btn}, {"sleep": 200}, {"eval": "window.__badge || 0"})
        self.assertEqual(got[-4]["eval"], "[1,0,true,true]")                           # one, no empty placeholders left, same node
        self.assertEqual(got[-1]["eval"], 1)

    # a list rebuilt from scratch (empty list + render) is compared with the previous one: a running work badge spins
    # the spinner itself (.glyph.spin text changes between frames), and "working · 3 s" changes once a second: they are
    # excluded from the comparison
    SCRATCH = ("(() => { window.__cmp = null; const l = document.getElementById('list'),"
               " flat = (h) => h.replace(/(class=\"glyph spin\"[^>]*>)[^<]*/g, '$1').replace(/· \\d+ [a-z]+/g, '· N'), was = flat(l.innerHTML); l.replaceChildren();"
               "import('/static/js/state.js').then((m) => { m.render(); window.__cmp = was === flat(l.innerHTML); }); return 1; })()")

    def test_the_list_merged_into_place_equals_the_list_built_from_scratch(self):
        # the list is merged into the previous one (reconcile.js): rows stay the same nodes; the result for any state changes
        # is the same as for a list rebuilt from scratch: order, new and departed rows, a caption changed in place
        for n in ("a", "b", "c"):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True)
            self.ev("session.started", n, session_id=f"s-{n}")
        row = lambda n: f"document.querySelector('#list li[data-s=\"{n}\"] > .srow')"
        # hold the row node of b and check that it got a "new" tag (class and dot) while the node is the same
        mark = f"(window.__b = {row('b')}, 1)"
        same = f"JSON.stringify([{row('b')} === window.__b, {row('b')}.classList.contains('unread')])"
        scratch = self.SCRATCH
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"until": f"!!{row('c')}"}, {"eval": scratch},
                        {"until": "window.__cmp !== null"}, {"eval": "window.__cmp"}, {"eval": mark})
        self.assertTrue(got[4]["eval"])                                       # initial view
        self.ev("turn.started", "b", marker=None, prompt_head="x")
        self.ev("turn.result", "b", text="ok-b")                              # the result is unread: b has a "new" tag
        self.ev("session.requested", "d", session_id="s-d", cwd="/w", channel="cli", owner=True)   # a new row
        self.ev("session.started", "d", session_id="s-d")
        got = self.page({"until": f"!!{row('d')} && {row('b')}.classList.contains('unread')", "ms": 8000},
                        {"eval": same}, {"eval": scratch}, {"until": "window.__cmp !== null"}, {"eval": "window.__cmp"})
        self.assertEqual(got[1]["eval"], "[true,true]")                      # node b is the same, the tag appeared
        self.assertTrue(got[-1]["eval"])

    def test_the_merged_list_equals_the_built_one_with_executors_resting_view_and_search(self):
        # the same with nested executors, sleeping ones (the collapsed "Asleep or failed" group), the "Now" toggle and search:
        # at every step the list merged into the previous one matches the list rebuilt from scratch
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.started", "hub", session_id="s-h")
        for n in ("atlas", "maps"):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True)
            self.ev("session.started", n, session_id=f"s-{n}")
        for n, up in (("atlas-tiles", "atlas"), ("atlas-roads", "atlas"), ("maps-x", "maps")):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", executor=True, raised_by=up)
            self.ev("session.started", n, session_id=f"s-{n}")
        self.ev("turn.started", "atlas-tiles", marker=None, prompt_head="x")
        scratch = self.SCRATCH
        check = [{"eval": scratch}, {"until": "window.__cmp !== null"}, {"eval": "window.__cmp"}]
        def step(*pre):
            return self.page(*pre, {"sleep": 300}, *check)[-1]["eval"]
        self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"until": "document.querySelectorAll('#list .fork-toggle').length === 2"})
        click = lambda sel: {"eval": f"(document.querySelector({json.dumps(sel)}).click(), 1)"}
        self.assertTrue(step())
        self.assertTrue(step(click("#list li[data-s=\"atlas\"] .fork-toggle")))        # expanded the executors
        self.ev("session.close_requested", "atlas-roads", retire=True)
        self.ev("session.exited", "atlas-roads", why="sleep")                         # one fell asleep
        self.ev("session.close_requested", "maps", retire=True)
        self.ev("session.exited", "maps", why="sleep")                                # and the specialist is in "Asleep or failed"
        self.assertTrue(step({"sleep": 1500}))
        self.assertTrue(step(click("#active-bar button[data-on=\"true\"]")))             # "Now"
        self.assertTrue(step(click("#active-bar button[data-on=\"false\"]")))            # "All"
        self.assertTrue(step({"eval": "(() => { const f = document.getElementById('filter'); f.value = 'atlas';"
                                      "f.dispatchEvent(new Event('input')); return 1; })()"}))   # search
        self.assertTrue(step({"eval": "(() => { const f = document.getElementById('filter'); f.value = '';"
                                      "f.dispatchEvent(new Event('input')); return 1; })()"}))

    def test_a_group_heading_folds_and_unfolds_with_a_real_click_also_while_searching(self):
        # the same trap as the executors badge: while a search is typed the group heading was a disabled button that looked
        # alive; now a click folds the group until the query changes (what is saved stays), in Clean and in Classic
        for n in ("notes-bot", "web-design"):
            self.ev("session.requested", n, session_id="s-" + n, cwd="/w", channel="cli", owner=True, role="agent")
            self.ev("session.started", n, session_id="s-" + n)
        head = '#list [data-g="agents"] .sgroup-h'
        state = ("[document.querySelector('%s')?.getAttribute('aria-expanded'), document.querySelector('%s')?.disabled,"
                 " document.querySelectorAll('#list [data-g=\"agents\"] ul .srow').length]" % (head, head))
        query = lambda q: {"eval": "(() => { const f = document.getElementById('filter'); f.value = %s;"
                                   "f.dispatchEvent(new Event('input')); return 1; })()" % json.dumps(q)}
        for look in ("clean", "classic"):
            for how in ("mclick", "tap"):
                with self.subTest(look=look, how=how):
                    go = {"go": f"http://127.0.0.1:{self.port}/#/", **({"look": None} if look == "clean" else {})}
                    got = self.page({"go": "about:blank", "look": None}, go, {"until": f"!!document.querySelector('{head}')"},
                                    query("notes"), {"sleep": 400}, {"eval": state}, {how: head}, {"sleep": 300}, {"eval": state},
                                    {how: head}, {"sleep": 300}, {"eval": state}, {how: head}, {"sleep": 300}, {"eval": state},
                                    query("web"), {"sleep": 400}, {"eval": state}, query(""), {"sleep": 400}, {"eval": state})
                    self.assertEqual([g["eval"] for g in got if "eval" in g and isinstance(g["eval"], list)],
                                     [["true", False, 1],      # searching: open for the match
                                      ["false", False, 0],     # a click folds the group (it did nothing)
                                      ["true", False, 1],      # and opens it again
                                      ["false", False, 0],     # folded once more ...
                                      ["true", False, 1],      # ... a new query starts open
                                      ["true", False, 2]], (look, how, got))   # no search: the saved state (open), all the rows

