    def maps_agent(self, parallel=3, git="ok", ctx=None):
        self.ev("owner.settings", None, timezone="UTC", parallel=parallel, channel="core")
        self.ev("session.requested", "maps", session_id="s-m", cwd="/home/x/work/apps/maps", role="agent", about="maps",
                channel="cli", owner=True)
