    def test_own_executors_are_set_from_the_bottom_line(self):
        # owner report: the "(solo)" label is inconvenient, put it in the status bar at the bottom and configure it by click
        self.maps_agent()
        up = ("(() => { const b = document.querySelector('.stat-par .menu-btn').getBoundingClientRect(), m = "
              "document.querySelector('.stat-par .menu').getBoundingClientRect(); return m.bottom <= b.top + 1; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/maps"}, {"until": "!!document.querySelector('.stat-par')"},
                        {"eval": "document.querySelector('.stat-par .menu-btn').innerText"},
                        {"eval": "(document.querySelector('.stat-par .menu-btn').click(), 1)"}, {"sleep": 300},
                        {"eval": up}, {"eval": self.PAR_ITEMS}, {"eval": "document.querySelector('.stat-par .menu').textContent"},
                        {"click": "2 executors"}, {"sleep": 500})
        self.assertEqual(got[2]["eval"], "executors: 3")
        self.assertTrue(got[5]["eval"])                                          # the menu is above the row, not under the window edge
        items = json.loads(got[6]["eval"])
        self.assertEqual(items[:3], [["Default · 3", "true"], ["Solo — no executors", "false"],
                                     ["1 executor", "false"]])
        self.assertEqual(items[-1], ["Another number…", None])
        self.assertIn("Mini-hub", got[7]["eval"])
        self.assertEqual([(e["type"], e["data"].get("n")) for e in self.spooled() if e["type"].startswith("session.")],
                         [("session.parallel_set", 2)])
        got = self.page({"eval": "(document.querySelector('.stat-par .menu-btn').click(), 1)"}, {"sleep": 300},
                        {"click": "Solo — no executors"}, {"sleep": 500})
        self.assertEqual([(e["type"], e["data"].get("on")) for e in self.spooled() if e["type"].startswith("session.")],
                         [("session.solo_set", True)])                          # 0 comes from the previous event (rollback)

