    def test_narrow_bottom_line_keeps_folder_and_context_not_dots(self):
        # phone: the row under the input field collapsed into "· · ·": model, effort and folder shrank to zero and only the
        # separators were left. Now when narrow, effort hides, while the model (the thing people change), the folder and the
        # conversation size stay visible, and there are no empty separators
        self.maps_agent(ctx=150000)
        parts = ("JSON.stringify([...document.querySelectorAll('.status .stat-left > *, .status > .stat-par, .status > .stat-mod')].map((e) => "
                 "[e.className, getComputedStyle(e).display === 'none' ? 0 : Math.round(e.getBoundingClientRect().width)]))")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/maps"}, {"until": "!!document.querySelector('.stat-par')"},
                        {"eval": "document.querySelector('main').style.maxWidth = '390px'; 1"}, {"sleep": 400},
                        {"eval": parts}, {"eval": "document.querySelector('.stat-par .menu-btn').innerText"},
                        {"eval": "document.querySelector('.status .stat-dir').innerText"},
                        {"eval": "[...document.querySelector('.status .stat-left').childNodes].filter((n) => n.nodeType === 3"
                                 " && n.textContent.trim()).length"},
                        {"eval": "Math.round(document.querySelector('.status').getBoundingClientRect().height)"},
                        {"eval": "document.querySelector('.status').innerText.trim().startsWith('ex. 3') && "
                                 "document.querySelector('.status .stat-dir').clientWidth >= "
                                 "document.querySelector('.status .stat-dir').scrollWidth"})
        self.assertTrue(got[9]["eval"])                                         # a hidden model leaves no "·", the folder is shown whole
        widths = {next(c for c in k.split() if c.startswith("stat-")): w for k, w in json.loads(got[4]["eval"])}
        self.assertGreater(widths["stat-dir"], 20)
        self.assertGreater(widths["stat-ctx"], 20)
        self.assertEqual((widths["stat-main"], widths["stat-mod"]), (0, 0))     # narrow, next to the executors chip
        self.assertLess(got[8]["eval"], 30)                                     # no room for the model: it is in the folder's hint
        self.assertEqual(got[5]["eval"].strip(), "ex. 3")
        self.assertEqual(got[6]["eval"], "maps")                                # narrow: only the folder name
        self.assertEqual(got[7]["eval"], 0)                                     # separators are not bare text

