    # the gray tab over the Clean field: is it drawn, its edges, and its visible parts (class, edges, text, cut or whole)
    CLEAN_TAB = ("(() => { const t = document.querySelector('.dock .status > .stat-left'); if (!t) return null; const r = t.getBoundingClientRect();"
                 " const parts = [...t.children].filter((e) => e.getClientRects().length > 0 && e.getBoundingClientRect().width > 0).map((e) => {"
                 " const q = e.getBoundingClientRect(); return {c: e.className, l: q.left, r: q.right, text: e.innerText.trim(), cut: e.scrollWidth > e.clientWidth}; });"
                 " return {shown: t.getClientRects().length > 0 && r.height > 0, l: r.left, r: r.right, parts}; })()")

    def test_the_clean_tab_over_the_phone_field_shows_the_folder_and_is_never_an_empty_strip(self):
        # Clean on a phone: the gray tab over the field hid the folder, so the tab of a session with no conversation size yet was
        # an empty gray strip (on a computer it reads "/w/atlas"). Now the folder name stands at the tab's right on a phone too, a
        # long one is cut with "…" and does not run over the size, and a tab with nothing to show is not drawn
        self.ev("session.requested", "tiles", session_id="s-t", cwd="/home/x/work/apps/tiles", channel="cli", owner=True)
        self.ev("session.started", "tiles", session_id="s-t")
        self.ev("turn.result", "tiles", text="ok", context=150000)
        self.ev("session.requested", "coast", session_id="s-c", cwd="/home/x/work/the-map-tiles-of-the-whole-atlantic-coast-for-the-old-server",
                channel="cli", owner=True)
        self.ev("session.started", "coast", session_id="s-c")
        self.ev("turn.result", "coast", text="ok", context=150000)
        self.ev("session.requested", "bare", session_id="s-b", channel="cli", owner=True)
        self.ev("session.started", "bare", session_id="s-b")
        self.ev("turn.started", "bare", marker=None, prompt_head="x")   # a question: its row goes into the queue plate above the field
        self.ev("permission.requested", "bare", request_id="r1", tool="AskUserQuestion", interactive=True,
                input={"questions": [{"question": "Which tiles?", "options": [{"label": "A"}, {"label": "B"}]}]})
        self.settle()
        steps = [{"go": "about:blank", "look": None}, {"local": {"hub.theme": '{"id":"core:clean"}'}}]
        for name in ("tiles", "coast", "bare"):
            steps += [{"go": f"http://127.0.0.1:{self.port}/#/s/{name}", "look": None}, {"until": "!!document.querySelector('form.composer')", "ms": 8000},
                      {"shot": os.path.join(self.state, f"tab-{name}.png"), "width": 390, "height": 844}, {"sleep": 400}, {"eval": self.CLEAN_TAB}]
        steps += [{"until": "!!document.querySelector('.clean-queue')", "ms": 5000},
                  {"eval": "(() => { const q = document.querySelector('.clean-queue').getBoundingClientRect(), "
                           "c = document.querySelector('form.composer').getBoundingClientRect(); return Math.round(c.top - q.bottom); })()"}]
        got = self.page(*steps)
        tabs = [g["eval"] for g in got if "eval" in g]
        self.assertEqual(len(tabs), 4, got)
        self.assertLess(tabs.pop(), 0, got)   # no tab: the queue plate itself sits on the card (its bottom under it), no gap left for a tab
        tiles, coast, bare = tabs
        for name, tab in (("tiles", tiles), ("coast", coast)):
            self.assertTrue(tab["shown"], (name, tab))
            by = {p["c"]: p for p in tab["parts"]}
            self.assertEqual(sorted(by), ["stat-ctx", "stat-dir"], (name, tab))
            ctx, folder = by["stat-ctx"], by["stat-dir"]
            self.assertTrue(ctx["r"] <= folder["l"] + 0.5 or folder["r"] <= ctx["l"] + 0.5, (name, "the folder runs over the size", tab))
            self.assertTrue(tab["l"] - 0.5 <= folder["l"] and folder["r"] <= tab["r"] + 0.5, (name, "the folder runs out of the tab", tab))
            self.assertFalse(ctx["cut"], (name, tab))
        folder = next(p for p in tiles["parts"] if p["c"] == "stat-dir")
        self.assertEqual((folder["text"], folder["cut"]), ("tiles", False), tiles)   # narrow: only the folder name, whole
        self.assertTrue(next(p for p in coast["parts"] if p["c"] == "stat-dir")["cut"], coast)   # a long name is cut with "…"
        self.assertFalse(bare and bare["shown"], bare)                       # no folder, no size: no gray strip

