    def test_text_scale_is_set_in_the_theme_tab_and_kept(self):
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        scale = "[getComputedStyle(document.documentElement).getPropertyValue('--ui-scale').trim(), localStorage.getItem('hub.textScale')]"
        got = self.page({"local": {"hub.settingsTab": "theme"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"wait": "Text size"}, {"eval": scale}, {"click": "Large"}, {"sleep": 300}, {"eval": scale},
                        {"eval": "document.querySelector('.text-scale [aria-pressed=true]').textContent"},
                        {"click": "Extra large"}, {"sleep": 300}, {"eval": scale}, {"errors": 1500}, {"eval": scale},
                        {"eval": "document.cookie"}, {"click": "Normal"}, {"sleep": 300}, {"eval": "document.cookie"})
        self.assertEqual(got[3]["eval"][1], None)                      # nothing is stored by default
        self.assertEqual(got[6]["eval"], ["1.2", "1.2"])
        self.assertEqual(got[7]["eval"], "Large")
        self.assertEqual(got[10]["eval"], ["1.3333", "1.3333"])
        self.assertEqual(got[12]["eval"], ["1.3333", "1.3333"])        # after reload it is the same, before the first render
        # "Files" is another port: it cannot read this localStorage, so the choice is also left in a cookie (of the host, the
        # ports share it); the default step leaves none
        self.assertRegex(got[13]["eval"], r"^hub\.textScale\.\d+=1\.3333$")   # named by the hub's own "Files" port: two hubs on a host do not clash
        self.assertEqual(got[16]["eval"], "")

