    def files(self, *rel, top=None):
        """Real files in the test folder: a link is made only for what exists (owner decision). top is its own folder instead of the
        state folder."""
        root = os.path.realpath(top or self.state)
        for r in rel:
            os.makedirs(os.path.dirname(os.path.join(root, r)), exist_ok=True)
            open(os.path.join(root, r), "w").close()
        return root

