    @unittest.skipIf(os.name == "nt", "links to absolute paths in the text: POSIX paths start with a slash")
    def test_a_markdown_link_with_a_bare_path_opens_in_files_not_on_the_hub_port(self):
        # owner report: [/Users/…/plan.md](/Users/…/plan.md) led to 127.0.0.1:8787/Users/… with "no such page" (a link without
        # a host belongs to the hub page, not to "Files"). The page recognizes a path in href by its beginning (markdown.js
        # HREF_PATH), and the run folder without a sandbox on Linux is /dev/shm (core/testtmp), so files go under /tmp
        top = tempfile.mkdtemp(dir="/tmp")
        self.addCleanup(shutil.rmtree, top, True)
        root = self.files("w/docs/plan.md", top=top)
        self.ev("session.requested", "a", session_id="s-a", cwd=f"{root}/w")
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None)
