    def test_short_paths_setting_shows_the_file_name_only(self):
        # owner decision: by default the full path is visible; the setting "short file name instead of the whole path" (kept
        # in this browser) shortens the visible text, and the path stays in href and title either way
        root = self.files("w/docs/plan.md")
        self.ev("session.requested", "a", session_id="s-a", cwd=f"{root}/w")
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None)
        said = "Result: `docs/plan.md`, see docs/plan.md:12"
        self.ev("session.said", "a", text=said)
        self.ev("turn.result", "a", text=said)
        links = "[...document.querySelectorAll('.md a')].map((a) => [a.textContent, a.title])"
        pick = ("[...document.querySelectorAll('.feed-opts label')].find(l => /^Short file name/.test(l.textContent))"
                ".querySelector('input').click(); 1")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Result"},
                        {"until": "!document.querySelector('.path-wait')"}, {"eval": links},
                        {"eval": "localStorage.setItem('hub.settingsTab', 'theme'); location.hash = '#/settings'; 1"},
                        {"until": "document.querySelectorAll('.feed-opts input').length > 5"}, {"eval": pick},
                        {"eval": "location.hash = '#/s/a'; 1"}, {"wait": "Result"},
                        {"until": "!document.querySelector('.path-wait')"}, {"eval": links},
                        {"eval": "localStorage.getItem('hub.short_paths')"})
        before, after, saved = got[3]["eval"], got[-2]["eval"], got[-1]["eval"]
        self.assertEqual([t for t, _ in before], ["docs/plan.md", "docs/plan.md:12"])
        self.assertEqual([t for t, _ in after], ["plan.md", "plan.md:12"])
        self.assertTrue(all(title.startswith("docs/plan.md") for _, title in after), after)
