    def test_a_sent_html_or_svg_does_not_run_from_the_address_of_the_page(self):
        # what a session sent (hub send-file) is served by /api/file for any type; html and svg with a script, opened from the
        # page's address in an embedded window, must not write to its localStorage, touch its window or send as the owner
        run = ("try{localStorage.setItem('ran','1')}catch(e){};try{parent.__ran=1}catch(e){};"
               "fetch('/api/send',{method:'POST',headers:{'X-Hub':'1','Content-Type':'application/json'},"
               "body:JSON.stringify({session:'a',text:'ran'})}).catch(function(){})")
        d = tempfile.mkdtemp(prefix="sent-")
        self.addCleanup(shutil.rmtree, d, ignore_errors=True)
        files = {"page.html": f"<html><body><script>{run}</script></body></html>",
                 "logo.svg": f'<svg xmlns="http://www.w3.org/2000/svg" onload="{run}"><rect width="9" height="9"/></svg>'}
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        for name, body in files.items():
            with open(os.path.join(d, name), "w") as f:
                f.write(body)
            self.ev("owner.file", None, path=os.path.join(d, name), caption="", channel="session", owner=False,
                    sender="a")
        self.settle()
        from urllib.parse import quote
        urls = json.dumps([f"/api/file?path={quote(os.path.join(d, n))}" for n in files])
        frames = (f"{urls}.forEach((u) => {{ const f = document.createElement('iframe'); f.src = u; "
                  f"document.body.append(f); }}) || document.querySelectorAll('iframe').length")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Sent you"}, {"eval": frames},
                        {"sleep": 1500}, {"eval": "[localStorage.getItem('ran'), window.__ran || null]"})
        self.assertEqual(got[2]["eval"], 2)   # both windows landed on the page
        self.assertEqual(got[-1]["eval"], [None, None])
        self.assertEqual([e for e in self.spooled() if e["type"] == "message.received"], [])

    @unittest.skipIf(os.name == "nt", "pictures by absolute path in the text: POSIX paths start with a slash")
    def test_pictures_come_from_the_page_and_fall_back_to_files(self):
        # PR #116: over the tailnet "Files" serves only project folders; the snapshot a session showed is served by the page
        # itself (/api/file), and what it does not serve (a path relative to the session folder) comes from "Files" as before
        import base64
        png = base64.b64decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8DwHwAFBQIAX8jx0gAAAABJRU5ErkJggg==")
        shot = os.path.join(self.state, "shots", "abs.png")
        os.makedirs(os.path.dirname(shot), exist_ok=True)
        with open(shot, "wb") as f:
            f.write(png)
        rel_seen = []
        self.files_server(lambda path: path.endswith("/rel.png") and not rel_seen.append(path))
        root = self.files("proj/shots/rel.png")   # a path relative to the session folder is checked on disk by the page
        self.ev("session.requested", "a", session_id="s-a", cwd=f"{root}/proj")
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None)
        said = f"Shots: {shot} and shots/rel.png"
        self.ev("session.said", "a", text=said)
        self.ev("turn.result", "a", text=said)
        look = ("[...document.querySelectorAll('.thumbs img')].map((i) => [new URL(i.src).pathname, i.complete && "
                "i.naturalWidth > 0])")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Shots"},
                        {"until": "[...document.querySelectorAll('.thumbs img')].every((i) => i.complete && i.naturalWidth)"},
                        {"eval": look})
        self.assertEqual(got[-1]["eval"], [["/api/file", True], ["/raw", True]])
        self.assertEqual(rel_seen, [f"{root}/proj/shots/rel.png"])

    def test_the_away_mode_is_a_strip_with_i_am_here(self):
        # /away without a duration was forgotten for a day: forms piled up, and the page said nothing about it
        self.ev("owner.away", None, channel="cli", owner=True)
        strip = "(() => { const b = document.getElementById('away'); return b.hidden ? null : b.textContent; })()"
        click = "(() => { document.querySelector('#away button').click(); return 1; })()"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/"}, {"until": strip}, {"eval": strip}, {"eval": click},
                        {"sleep": 300})
        self.assertIn("Away since", got[2]["eval"])
