    def test_the_voice_section_turns_the_built_in_model_on_and_off(self):
        # spec d2109189: «Turn on voice» starts the setup step `voice` (here a fake run that only writes its status), the
        # section shows the download, then «On» once the model is installed; «Turn off» removes it
        from unittest import mock
        from modules.setup import job as setup_job
        from modules.voice import install
        from tests.test_voice_local import lay_out
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        pins = {"model": {"url": "https://x.test/m", "sha256": "0" * 64, "size": 274_000_000, "id": "gigaam-v3-e2e-rnnt",
                          "name": "GigaAM v3", "file": "m.gguf", "lang": "ru"},
                "vad": {"url": "https://x.test/v", "sha256": "0" * 64, "size": 1_000_000, "id": "silero", "file": "v.gguf"}}
        started = []

        def run(step, lang=None, arg=None):
            started.append(step)
            if step != "voice":
                return 202, {"ok": True}
            from core import catalog
            os.makedirs(setup_job.folder(self.state), exist_ok=True)
            catalog.write_private(setup_job.status_path(self.state, step),
                                  {"step": step, "state": "running", "pid": os.getpid(), "progress": [100_000_000, 298_000_000]})
            return 202, {"ok": True}
        from modules.setup.setup import Setup
        self.web._setup = Setup(self.state, lambda: {})   # the real step files; only the start of the step is faked
        engine = install.engine_pin()   # its size depends on the machine's platform: the sum below is computed, not typed
        if not engine:
            self.skipTest("no voice engine build for this platform: the section offers no model rows here")
        extra = engine["lib"]["size"] + engine["wrapper"]["size"] + pins["vad"]["size"]
        total = int((pins["model"]["size"] + extra) / 1_000_000 + 0.5)   # half up, as the page's Math.round
        for p in (mock.patch.object(install, "model_pin", lambda lang, model=None: pins),
                  mock.patch.object(install, "has_ffmpeg", lambda cfg: True),   # the machine need not have ffmpeg
                  mock.patch.object(self.web._setup, "run", run)):
            p.start()
            self.addCleanup(p.stop)
        shots = os.environ.get("HUB_TEST_SHOTS")   # a folder: the three states as pictures (the spec's check)
        seen = {"eval": "(() => { const c = document.querySelector('.voice-local'); c && c.closest('.module-card')"
                        ".scrollIntoView({block: 'center'}); return 1; })()"}
        sec = "((document.querySelector('.voice-local') || {}).innerText || '')"
        press = ("(() => { const b = [...document.querySelectorAll('.voice-local button')].find((x) => "
                 "x.textContent.startsWith(%s)); if (!b) return 0; b.click(); return 1; })()")
        got = self.page({"local": {"hub.settingsTab": "modules"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": f"{sec}.includes('Turn on voice')", "ms": 8000}, {"eval": sec},
                        *([seen, {"shot": os.path.join(shots, "voice-off.png")}] if shots else []),
                        {"eval": press % "'Turn on voice'"},
                        {"until": f"{sec}.includes('Downloading the model: 100 of 298 MB')", "ms": 8000},
                        *([seen, {"shot": os.path.join(shots, "voice-downloading.png")}] if shots else []))
        self.assertIn(f"Turn on voice · GigaAM v3 · {total} MB", got[3]["eval"])   # the model, the detector and the engine
        self.assertIn("Parakeet Ultra", got[3]["eval"])   # the other row of the hub's language
        self.assertTrue(got[-1 if not shots else -3]["until"])
        self.assertEqual(started.count("voice"), 1)   # (the page may start its own claude step on a stand without one)
        lay_out(self.state)   # the step finished: the files are in place
        from core import catalog
        catalog.write_private(setup_job.status_path(self.state, "voice"), {"step": "voice", "state": "done"})
        got = self.page({"until": f"{sec}.includes('On: GigaAM v3')", "ms": 8000},
                        *([seen, {"shot": os.path.join(shots, "voice-on.png")}] if shots else []),
                        {"eval": press % "'Turn off'"},
                        {"until": f"{sec}.includes('Turn on voice')", "ms": 8000}, {"errors": 1500})
        self.assertTrue(got[0]["until"])
        self.assertTrue(got[-2]["until"])
        self.assertFalse(os.path.exists(os.path.join(self.state, "runtime", "voice.json")))
        self.assertEqual(got[-1]["errors"], [])

