        row = ("(() => { const b = [...document.querySelectorAll('.voice-local button.voice-model')].find((x) => "
               "x.textContent.includes('Whisper Small')); if (!b) return 0; b.scrollIntoView({block: 'center'}); b.click(); return 1; })()")
        press = ("(() => { const b = [...document.querySelectorAll('.voice-local > button')].find((x) => "
                 "x.textContent.startsWith(%s)); if (!b) return 0; b.click(); return 1; })()")
