    def test_the_voice_section_signs_the_hub_in_to_codex_and_turns_the_cloud_row_on(self):
        # spec d2140189: the cloud row is the last one; without the hub's Codex sign-in a press shows the link and the
        # code in the row, the sign-in done — the page turns the row on by itself (the setup step `voice chatgpt`); on,
        # the section says the sound goes to the OpenAI cloud and which local model takes a refusal over
        from modules.setup import job as setup_job
        from modules.voice import chatgpt
        from tests.test_voice_cloud import sign
        from tests.test_voice_local import lay_out
        from core import catalog, codexcli
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        lay_out(self.state)   # GigaAM v3 on: the fallback
        started, logins = [], []

        def run(step, lang=None, arg=None):
            started.append((step, arg))
            os.makedirs(setup_job.folder(self.state), exist_ok=True)
            if (step, arg) == ("voice", "chatgpt"):   # the step's check passed (a stand may start its own claude step)
                chatgpt.choose(self.state)
            catalog.write_private(setup_job.status_path(self.state, step), {"step": step, "state": "done", "model": arg})
            return 202, {"ok": True}

        def start_login(state_dir, **kw):
            logins.append(kw)
            return {"url": "https://auth.example.test/codex/device", "code": "AB12-CD34"}
        from modules.setup.setup import Setup
        self.web._setup = Setup(self.state, lambda: {})
        from modules.voice import install
        for p in (mock.patch.object(self.web._setup, "run", run), mock.patch.object(chatgpt, "codex_ready", return_value=True),
                  mock.patch.object(install, "has_ffmpeg", lambda cfg: True),   # the machine need not have ffmpeg
                  mock.patch("core.codexcli.start_login", start_login)):
            p.start()
            self.addCleanup(p.stop)
        shots = os.environ.get("HUB_TEST_SHOTS")
        sec = "((document.querySelector('.voice-local') || {}).innerText || '')"
        row = ("(() => { const b = [...document.querySelectorAll('.voice-local button.voice-model')].find((x) => "
               "x.textContent.includes('ChatGPT')); if (!b) return 0; b.scrollIntoView({block: 'center'}); b.click(); return 1; })()")
        got = self.page({"local": {"hub.settingsTab": "modules"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": "!!document.querySelector('.voice-local')", "ms": 8000},
                        {"eval": "document.querySelector('.voice-local').closest('details').open = true, 1"},
                        {"until": f"{sec}.includes('press to sign in')", "ms": 8000}, {"eval": sec},
                        *([{"shot": os.path.join(shots, "voice-cloud-row.png")}] if shots else []),
                        {"eval": row}, {"until": f"{sec}.includes('AB12-CD34')", "ms": 8000},
                        *([{"shot": os.path.join(shots, "voice-cloud-code.png")}] if shots else []))
        self.assertTrue(got[4]["until"])
        self.assertIn("kept there as a file", got[5]["eval"])   # the row says where the sound goes, before any press
        self.assertIn("GigaAM v3 recognizes", got[5]["eval"])
        self.assertTrue(got[-1 if not shots else -2]["until"])
        self.assertEqual(len(logins), 1)
        # the tab is drawn anew while the person is entering the code (a new modules list, a language change): the section
        # is a new node, and the old one's wait for the sign-in is gone with it — the new one has to take it over
        mark = "document.querySelector('.voice-local')"
        got = self.page({"eval": f"window.__old = {mark}; window.dispatchEvent(new Event('hub-modules')); 1"},
                        {"until": f"!!{mark} && {mark} !== window.__old", "ms": 8000},
                        {"eval": "document.querySelector('.voice-local').closest('details').open = true, 1"},
                        {"until": f"{sec}.includes('AB12-CD34')", "ms": 8000})
        self.assertTrue(got[1]["until"])
        self.assertTrue(got[-1]["until"])
        sign(codexcli.home_of(self.state))   # the person entered the code: the hub's folder is signed in
        got = self.page({"until": f"{sec}.includes('recognized in the OpenAI cloud')", "ms": 12000}, {"eval": sec},
                        *([{"shot": os.path.join(shots, "voice-cloud-on.png")}] if shots else []), {"errors": 1500})
        self.assertTrue(got[0]["until"])
        self.assertEqual([x for x in started if x[0] == "voice"], [("voice", "chatgpt")])
        self.assertIn("if it refuses, GigaAM v3 recognizes", got[1]["eval"])
        self.assertEqual(got[-1]["errors"], [])

    def test_a_busy_modules_answer_keeps_the_list(self):
        # the page rereads the journal (rotation, language change): /api/modules answers 503 at once instead of waiting, and
        # an already shown "Modules" list does not turn back into "Loading…"
        from unittest import mock
        from modules.web.server import ReaderBusy
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        real, busy = self.web.mod_state, []

        def mod_state(reader):
            busy.append(bool(busy) and busy[0])
            if busy[0]:
                raise ReaderBusy()   # the journal lock was not obtained: 503
            return real(reader)
        busy.append(False)
        text = "document.querySelector('main').innerText.includes('Hub voice is not set up')"
        with mock.patch.object(self.web, "mod_state", mod_state):
            self.page({"local": {"hub.settingsTab": "modules"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                      {"wait": "Hub voice is not set up"})
            busy[0] = True
            got = self.page({"eval": "window.dispatchEvent(new Event('hub-modules')); 1"}, {"sleep": 1500},
                            {"eval": text})
        self.assertTrue(any(busy[1:]), "the tab did not ask /api/modules again")
        self.assertTrue(got[-1]["eval"])

