    def test_voice_press_shows_at_once_and_a_silent_mic_says_so(self):
        # owner report: voice recording broke, space no longer works and the icon does nothing. The page has the permission,
        # but getUserMedia did not answer at all: the press silently waited for it and nothing reached the server
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        mic = "form.composer .btn.round.mic"
        press = (f"document.querySelector('{mic}').dispatchEvent(new PointerEvent('pointerdown', {{button: 0, bubbles: true}})), "
                 "document.dispatchEvent(new PointerEvent('pointerup', {bubbles: true})), 1")
        stub = ("navigator.permissions.query = () => Promise.resolve({state: 'granted'}); "
                "navigator.mediaDevices.getUserMedia = () => new Promise(() => {}); 1")
        live = "navigator.mediaDevices.getUserMedia = () => Promise.resolve(new AudioContext({sinkId: {type: 'none'}}).createMediaStreamDestination().stream); 1"
        bar = "((document.querySelector('form.composer .bar') || {}).innerText || '')"
        with mock.patch.dict(os.environ, {"VOICE_CMD": "true"}):
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": f"!!document.querySelector('{mic}')"},
                            {"eval": stub}, {"eval": press},
                            # 1. the press is accepted at once: a "Turning on the microphone…" bar, not silence
                            {"until": f"{bar}.includes('Turning on the microphone')", "ms": 1500},
                            # 2. the microphone never opened: this is said in words, and the field came back
                            {"until": "document.querySelector('.error-text').textContent", "ms": 9000},
                            {"eval": f"!document.querySelector('form.composer.rec') && !!document.querySelector('{mic}')"},
                            # 3. the next press did not get stuck: the microphone answered and recording goes; Esc cancels
                            {"eval": live}, {"eval": press},
                            {"until": "!!document.querySelector('.recstrip .rec-cancel') && !!document.querySelector('[data-rec-clock]')", "ms": 3000},
                            {"eval": "document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape', bubbles: true})), 1"},
                            {"until": "!document.querySelector('form.composer.rec')", "ms": 3000})
        self.assertTrue(got[4]["until"])
        self.assertIn("The microphone did not turn on", got[5]["until"])
        self.assertTrue(got[6]["eval"])
        self.assertTrue(got[9]["until"])
        self.assertTrue(got[11]["until"])

    def test_a_refused_mic_names_the_real_cause(self):
        # owner report: "the microphone does not turn on, though the browser has the permission". Every getUserMedia
        # refusal said "allow access for this page": also when the page was allowed and macOS did not give the browser the
        # microphone (Chrome: NotAllowedError "Permission denied by system"), when it was busy (NotReadableError) or absent;
        # and when it did not answer, the cause was the microphone chosen in Chrome (an iPhone), not named in the text
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        mic = "form.composer .btn.round.mic"
        press = (f"document.querySelector('{mic}').dispatchEvent(new PointerEvent('pointerdown', {{button: 0, bubbles: true}})), "
                 "document.dispatchEvent(new PointerEvent('pointerup', {bubbles: true})), 1")
        stub = ("window.__perm = {state: 'granted'}; navigator.permissions.query = () => Promise.resolve(window.__perm); "
                "navigator.mediaDevices.getUserMedia = () => window.__why ? Promise.reject(new DOMException(window.__why[1], window.__why[0])) "
                ": new Promise(() => {}); 1")
        err = "document.querySelector('.error-text').textContent"
        steps = []
        for name, message, state in [("NotAllowedError", "Permission denied by system", "granted"),
                                     ("NotReadableError", "Could not start audio source", "granted"),
                                     ("NotFoundError", "Requested device not found", "granted"),
                                     ("NotAllowedError", "Permission denied", "denied"),
                                     # the device chosen in the browser (an iPhone over Continuity) never answers
                                     ("", "", "granted")]:
            why = f"['{name}', '{message}']" if name else "null"
            steps += [{"eval": f"window.__why = {why}; window.__perm.state = '{state}'; "
                               "document.querySelector('.error-text') && (document.querySelector('.error-text').textContent = ''); 1"},
                      {"eval": press},
                      {"until": f"!document.querySelector('form.composer.rec') && document.querySelector('.error-text') && {err}",
                       "ms": 9000}]
        with mock.patch.dict(os.environ, {"VOICE_CMD": "true"}):
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": f"!!document.querySelector('{mic}')"},
                            {"eval": stub}, *steps)
        system, busy, none, denied, stuck = (got[2 + 3 * i + 3]["until"] for i in range(5))
        # the page is allowed: the cause is the system, not the page permission
        self.assertIn("Privacy & Security → Microphone", system)
        self.assertNotIn("for this page", system)
        self.assertIn("another app", busy)
        self.assertNotIn("for this page", busy)
        self.assertIn("No microphone found", none)
        # the page itself is refused: as before
        self.assertIn("for this page", denied)
        # no answer at all: also the microphone chosen in the browser, not only the system
        self.assertIn("which microphone is chosen", stuck)

    def test_voice_in_mobile_safari_says_why_and_starts_inside_the_gesture(self):
        # owner report: voice input does not work in mobile Safari. Not https means no microphone at all: the button silently
        # disappeared; permissions.query in Safari is late or does not work, so an await before getUserMedia ate the gesture;
        # a long press ends with pointercancel, not pointerup, so recording did not stop; mimeType is empty, so the type was
        # invented
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        mic = "form.composer .btn.round.mic"
        down = f"document.querySelector('{mic}').dispatchEvent(new PointerEvent('pointerdown', {{button: 0, bubbles: true}}))"
        up = "document.dispatchEvent(new PointerEvent('pointerup', {bubbles: true}))"
        live = "navigator.mediaDevices.getUserMedia = () => Promise.resolve(new AudioContext({sinkId: {type: 'none'}}).createMediaStreamDestination().stream); 1"
        err = "((document.querySelector('.error-text') || {}).textContent || '')"
        insecure = "Object.defineProperty(window, 'isSecureContext', {value: false, configurable: true}); 1"
        norec = "Object.defineProperty(window, 'MediaRecorder', {value: undefined, configurable: true}); 1"
        slow = ("navigator.permissions.query = () => new Promise(() => {}); window.__gum = 0; "
                "const g = navigator.mediaDevices.getUserMedia.bind(navigator.mediaDevices); "
                "navigator.mediaDevices.getUserMedia = (c) => { window.__gum++; return g(c); }; 1")
        fake = ("window.MediaRecorder = class { constructor() { this.mimeType = ''; } start() {} "
                "stop() { this.ondataavailable({data: new Blob([new Uint8Array([0, 0, 0, 28, 102, 116, 121, 112])], {type: 'audio/mp4'})}); this.onstop(); } }; "
                "window.__sent = null; const f = window.fetch; "
                "window.fetch = (u, o) => { if (String(u).includes('/api/voice')) window.__sent = JSON.parse(o.body); return f(u, o); }; 1")
        with mock.patch.dict(os.environ, {"VOICE_CMD": "true"}):
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": f"!!document.querySelector('{mic}')"},
                            # 1. over http the browser gives no microphone: the icon is in place, and a press says it in words
                            {"eval": insecure}, {"eval": down + ", " + up + ", 1"},
                            {"until": f"{err}.includes('https')", "ms": 3000},
                            {"eval": f"!document.querySelector('form.composer.rec') && !!document.querySelector('{mic}')"},
                            # 2. an old browser without MediaRecorder: also in words
                            {"eval": "Object.defineProperty(window, 'isSecureContext', {value: true, configurable: true}); 1"},
                            {"eval": norec}, {"eval": down + ", " + up + ", 1"},
                            {"until": f"{err}.includes('MediaRecorder')", "ms": 3000})
        self.assertTrue(got[4]["until"])
        self.assertTrue(got[5]["eval"])
        self.assertTrue(got[9]["until"])
        with mock.patch.dict(os.environ, {"VOICE_CMD": "true"}):
            got = self.page({"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/s/a"},
                            {"until": f"!!document.querySelector('{mic}')"}, {"eval": live}, {"eval": slow},
                            # 3. the microphone is requested in the press handler itself, not after the permissions.query answer
                            {"eval": down + ", window.__gum"},
                            {"until": "!!document.querySelector('[data-rec-clock]')", "ms": 3000},
                            # 4. a long press interrupted by the system (pointercancel): the recording ends instead of hanging
                            {"eval": "new Promise((r) => setTimeout(r, 500)).then(() => document.dispatchEvent(new PointerEvent('pointercancel', {bubbles: true}))), 1"},
                            {"until": "!document.querySelector('form.composer.rec')", "ms": 5000},
                            # 5. mimeType is empty (Safari-like recording): the type is taken from the recording, not invented
                            {"eval": fake}, {"eval": down + ", " + up + ", 1"},
                            {"until": "!!document.querySelector('[data-rec-clock]')", "ms": 3000},
                            {"eval": "document.querySelector('form.composer .btn.round.stop').click(), 1"},
                            {"until": "window.__sent !== null", "ms": 5000}, {"eval": "window.__sent.mime"})
        self.assertEqual(got[5]["eval"], 1)
        self.assertTrue(got[6]["until"])
        self.assertTrue(got[8]["until"])
        self.assertTrue(got[11]["until"])
        self.assertTrue(got[13]["until"])
        self.assertEqual(got[-1]["eval"], "audio/mp4")

    def test_autostop_decides_from_the_level_and_a_clock_the_test_feeds_in(self):
        # a recording stops by itself: 20 s of quiet in a row after sound — use it; no sound at all — "nosound" (the page
        # stops and sends it too); 10 minutes — stop and use it. The decision takes the level and the time as arguments (no real clock)
        probe = (
            "import('/static/js/autostop.js').then((m) => { window.__probe = (() => {"
            " const C = m.AUTOSTOP;"
            " const run = (script, listening = true) => { const w = m.newWatch(0, listening); return script.map(([at, db]) => m.step(w, db, at)); };"
            " const every = []; for (let at = 1000; at <= C.MAX_MS; at += 1000) every.push([at, -20]);"
            " const loud = run(every), idle = [];"
            " for (let at = 1000; at <= C.MAX_MS; at += 1000) idle.push([at, null]);"
            " const idled = run(idle);"
            " return {"
            "  cfg: [C.SILENCE_MS, C.MAX_MS, C.QUIET_DB],"
            "  spoke: run([[1000, -20], [10000, -70], [20999, -70], [21000, -70]]),"
            "  spoke_again: run([[1000, -20], [10000, -70], [15000, -20], [34999, -70], [35000, -70]]),"
            "  no_sound: run([[5000, -70], [19999, -70], [20000, -70]]),"
            "  loud_to_the_limit: [loud.slice(0, -1).filter(Boolean).length, loud.at(-1)],"
            "  no_reading: [idled.slice(0, -1).filter(Boolean).length, idled.at(-1)],"
            "  not_listening: run([[30000, -70], [C.MAX_MS, -70]], false),"
            "  db: [String(m.levelDb(new Float32Array(8).fill(0.5))), String(m.levelDb(new Float32Array(8))), String(m.levelDb([]))],"
            " }; })(); }), 1")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/"}, {"eval": probe}, {"until": "!!window.__probe", "ms": 3000},
                        {"eval": "window.__probe"})[-1]["eval"]
        self.assertEqual(got["cfg"], [20000, 600000, -50])
        self.assertEqual(got["spoke"], ["", "", "", "silence"])
        self.assertEqual(got["spoke_again"], ["", "", "", "", "silence"])
        self.assertEqual(got["no_sound"], ["", "", "nosound"])
        self.assertEqual(got["loud_to_the_limit"], [0, "max"])
        self.assertEqual(got["no_reading"], [0, "max"])   # the level cannot be read: quiet is never concluded, only the limit
        self.assertEqual(got["not_listening"], ["", "max"])
        self.assertEqual([round(float(got["db"][0]), 1), got["db"][1], got["db"][2]], [-6.0, "-Infinity", "-Infinity"])

    def test_a_recording_stops_by_itself_and_the_cross_cancels_without_sending(self):
        # owner request: a forgotten microphone does not record for hours. The level comes from an AnalyserNode on the
        # stream; the clock is Date.now, replaced by the test
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        mic = "form.composer .btn.round.mic"
        down = f"document.querySelector('{mic}').dispatchEvent(new PointerEvent('pointerdown', {{button: 0, bubbles: true}}))"
        up = "document.dispatchEvent(new PointerEvent('pointerup', {bubbles: true}))"
        click_record = down + ", " + up + ", 1"
        err = "((document.querySelector('.error-text') || {}).textContent || '')"
        recording = "!!document.querySelector('[data-rec-clock]')"
        fakes = (
            "window.__now = 1000000; Date.now = () => window.__now; window.__level = 0.5; window.__closed = 0; window.__sent = null; "
            "navigator.mediaDevices.getUserMedia = () => Promise.resolve({getTracks: () => [{stop() {}}]}); "
            "window.AudioContext = class { constructor() { this.state = 'running'; } resume() { return Promise.resolve(); } "
            "close() { window.__closed++; return Promise.resolve(); } createMediaStreamSource() { return {connect() {}}; } "
            "createAnalyser() { return {fftSize: 0, getFloatTimeDomainData(b) { b.fill(window.__level); }}; } }; "
            "window.MediaRecorder = class { constructor() { this.mimeType = 'audio/webm'; } start() {} "
            "stop() { this.ondataavailable({data: new Blob([new Uint8Array([1, 2, 3, 4])], {type: 'audio/webm'})}); this.onstop(); } }; "
            # window.__reply — the answer /api/voice gives (the server's own 422 is covered in test_web)
            "window.__reply = null; const f = window.fetch; window.fetch = (u, o) => { if (String(u).includes('/api/voice')) { "
            "window.__sent = JSON.parse(o.body); if (window.__reply) return Promise.resolve(new Response(JSON.stringify(window.__reply), "
            "{status: 422, headers: {'Content-Type': 'application/json'}})); } return f(u, o); }; "
            "import('/static/js/i18n.js').then((m) => { window.__nospeech = m.t('web.srv.no_speech'); }); 1")
        later = lambda ms: {"eval": f"window.__now += {ms}, 1"}
        with mock.patch.dict(os.environ, {"VOICE_CMD": "true"}):
            got = self.page(
                {"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": f"!!document.querySelector('{mic}')"}, {"eval": fakes},
                # 1. sound, then 20 s of quiet: the recording ends and is sent
                {"eval": click_record}, {"until": recording, "ms": 3000},
                {"sleep": 700}, later(5000), {"sleep": 700}, {"eval": "window.__level = 0, 1"}, later(20000),
                {"until": "!document.querySelector('form.composer.rec') && window.__sent !== null", "ms": 5000},
                # 2. quiet from the very start: the recording stops and still goes to /api/voice — the page's level is a
                # guess (a quiet voice, a far microphone), "no speech" is the transcription's answer, shown as usual
                {"eval": "window.__sent = null, window.__level = 0, window.__reply = {error: window.__nospeech}, 1"},
                {"eval": click_record}, {"until": recording, "ms": 3000},
                {"sleep": 700}, later(20000),
                {"until": "!document.querySelector('form.composer.rec')", "ms": 5000},
                {"until": f"window.__sent !== null && ({err}) === window.__nospeech", "ms": 5000},
                {"eval": f"[window.__sent && window.__sent.data, {err}]"},
                {"eval": "1"},
                {"eval": "window.__nospeech"},
                # 3. sound all the way: at 10 minutes it ends and is sent
                {"eval": "window.__sent = null, window.__level = 0.5, window.__reply = null, 1"}, {"eval": click_record},
                {"until": recording, "ms": 3000}, {"sleep": 700}, later(599000), {"sleep": 700}, {"eval": "window.__sent"}, later(1000),
                {"until": "window.__sent !== null", "ms": 5000},
                # 4. the cross during a recording: no sending, no error, the sound is released
                {"until": f"!document.querySelector('form.composer.rec') && !!document.querySelector('{mic}')", "ms": 5000},
                {"eval": "window.__sent = null, 1"}, {"eval": click_record}, {"until": recording, "ms": 3000},
                {"eval": "(() => { const b = document.querySelector('.recstrip .rec-cancel'); return [!!b, !!(b && b.querySelector('.icon')), b && b.getAttribute('aria-label')]; })()"},
                {"eval": "document.querySelector('.recstrip .rec-cancel').click(), 1"},
                {"until": "!document.querySelector('form.composer.rec')", "ms": 5000}, {"sleep": 500},
                {"eval": f"[window.__sent, {err}, window.__closed]"},
            )
        self.assertTrue(got[10]["until"])
        self.assertTrue(got[17]["until"])
        sent_after_silence = got[18]["eval"]
        self.assertTrue(sent_after_silence[0])                           # no sound by the page's level: still sent
        self.assertEqual(sent_after_silence[1], got[20]["eval"])         # and the server's "no speech" is on screen
        self.assertTrue(got[20]["eval"])
        self.assertIsNone(got[27]["eval"])                               # 599 s: still recording
        self.assertTrue(got[29]["until"])
        self.assertEqual(got[34]["eval"][:2], [True, True])               # the cross is a button with an icon
        self.assertTrue(got[34]["eval"][2])
        self.assertEqual(got[-1]["eval"][:2], [None, ""])                # cancelled: nothing sent
        self.assertEqual(got[-1]["eval"][2], 4)                          # every recording released its audio context

    def test_a_browser_that_refuses_sinkid_none_still_stops_a_recording_by_the_level(self):
        # review of PR #441: the dictation level asks for no output device (sinkId none); a browser that knows the option
        # and refuses it must not lose the level — the context is made without it, the quiet still ends the recording
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        mic = "form.composer .btn.round.mic"
        click_record = (f"document.querySelector('{mic}').dispatchEvent(new PointerEvent('pointerdown', {{button: 0, bubbles: true}})), "
                        "document.dispatchEvent(new PointerEvent('pointerup', {bubbles: true})), 1")
        recording = "!!document.querySelector('[data-rec-clock]')"
        fakes = (
            "window.__now = 1000000; Date.now = () => window.__now; window.__level = 0.5; window.__sent = null; window.__asked = []; "
            "navigator.mediaDevices.getUserMedia = () => Promise.resolve({getTracks: () => [{stop() {}}]}); "
            "window.AudioContext = class { constructor(o) { window.__asked.push(JSON.stringify(o || null)); "
            "if (o && o.sinkId) throw new DOMException('no such sink', 'NotAllowedError'); this.state = 'running'; } "
            "resume() { return Promise.resolve(); } close() { return Promise.resolve(); } createMediaStreamSource() { return {connect() {}}; } "
            "createAnalyser() { return {fftSize: 0, getFloatTimeDomainData(b) { b.fill(window.__level); }}; } }; "
            "window.MediaRecorder = class { constructor() { this.mimeType = 'audio/webm'; } start() {} "
            "stop() { this.ondataavailable({data: new Blob([new Uint8Array([1, 2, 3, 4])], {type: 'audio/webm'})}); this.onstop(); } }; "
            "const f = window.fetch; window.fetch = (u, o) => { if (String(u).includes('/api/voice')) window.__sent = JSON.parse(o.body); "
            "return f(u, o); }; 1")
        later = lambda ms: {"eval": f"window.__now += {ms}, 1"}
        with mock.patch.dict(os.environ, {"VOICE_CMD": "true"}):
            got = self.page(
                {"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": f"!!document.querySelector('{mic}')"}, {"eval": fakes},
                {"eval": click_record}, {"until": recording, "ms": 3000},
                {"sleep": 700}, later(5000), {"sleep": 700}, {"eval": "window.__level = 0, 1"}, later(20000),
                {"until": "!document.querySelector('form.composer.rec') && window.__sent !== null", "ms": 5000},
                {"eval": "window.__asked"},
            )
        self.assertTrue(got[4]["until"])
        self.assertTrue(got[10]["until"])                                # stopped by the quiet, not by the 10-minute limit
        self.assertEqual(got[-1]["eval"], ['{"sinkId":{"type":"none"}}', "null"])   # asked for no output first, then without

    def test_a_held_recording_waits_for_the_release_and_an_old_analyser_keeps_the_limit(self):
        # review of the self-stopping recording: quiet while the button is held must not send under the finger
        # ("release to send"), and an analyser without getFloatTimeDomainData (older Safari) must not stop the time limit
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        mic = "form.composer .btn.round.mic"
        down = f"document.querySelector('{mic}').dispatchEvent(new PointerEvent('pointerdown', {{button: 0, bubbles: true, pointerId: 7}}))"
        up = "document.dispatchEvent(new PointerEvent('pointerup', {bubbles: true, pointerId: 7}))"
        recording = "!!document.querySelector('[data-rec-clock]')"
        fakes = (
            "window.__now = 1000000; Date.now = () => window.__now; window.__level = 0; window.__sent = null; window.__old = false; "
            "navigator.mediaDevices.getUserMedia = () => Promise.resolve({getTracks: () => [{stop() {}}]}); "
            "window.AudioContext = class { constructor() { this.state = 'running'; } resume() { return Promise.resolve(); } "
            "close() { return Promise.resolve(); } createMediaStreamSource() { return {connect() {}}; } "
            "createAnalyser() { return window.__old ? {fftSize: 0} : {fftSize: 0, getFloatTimeDomainData(b) { b.fill(window.__level); }}; } }; "
            "window.MediaRecorder = class { constructor() { this.mimeType = 'audio/webm'; } start() {} "
            "stop() { this.ondataavailable({data: new Blob([new Uint8Array([1, 2, 3, 4])], {type: 'audio/webm'})}); this.onstop(); } }; "
            "const f = window.fetch; window.fetch = (u, o) => { if (String(u).includes('/api/voice')) window.__sent = JSON.parse(o.body); return f(u, o); }; 1")
        later = lambda ms: {"eval": f"window.__now += {ms}, 1"}
        with mock.patch.dict(os.environ, {"VOICE_CMD": "true"}):
            got = self.page(
                {"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": f"!!document.querySelector('{mic}')"}, {"eval": fakes},
                # 1. held, quiet for a minute: still recording; the release sends
                {"eval": down + ", 1"}, {"until": recording, "ms": 3000}, {"sleep": 700}, later(60000), {"sleep": 1000},
                {"eval": f"[{recording}, window.__sent]"},
                {"eval": up + ", 1"}, {"until": "window.__sent !== null", "ms": 5000},
                # 2. an analyser without getFloatTimeDomainData: no level, but at 10 minutes it stops and sends
                {"until": f"!document.querySelector('form.composer.rec') && !!document.querySelector('{mic}')", "ms": 5000},
                {"eval": "window.__sent = null, window.__old = true, 1"},
                {"eval": down + ", " + up + ", 1"}, {"until": recording, "ms": 3000},
                {"sleep": 700}, later(30000), {"sleep": 700}, {"eval": f"[{recording}, window.__sent]"},
                later(600000), {"until": "window.__sent !== null", "ms": 5000},
            )
        self.assertEqual(got[8]["eval"], [True, None])    # held: quiet did not stop it
        self.assertTrue(got[10]["until"])                  # released: sent
        self.assertEqual(got[18]["eval"], [True, None])    # no level: quiet is not concluded
        self.assertTrue(got[-1]["until"])                  # the limit still works

    def test_a_transcription_ready_while_a_file_uploads_stays_in_the_field(self):
        # the words were recognized while an attachment was still uploading: the send is refused ("wait for the files"), and
        # the field was redrawn from the empty draft — the transcription was lost, neither in the field nor in the feed
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        disk = os.path.join(self.state, "disk")
        os.makedirs(disk)
        with open(os.path.join(disk, "pic.txt"), "w") as f:
            f.write("x")
        mic = "form.composer .btn.round.mic"
        press = (f"document.querySelector('{mic}').dispatchEvent(new PointerEvent('pointerdown', {{button: 0, bubbles: true}})), "
                 "document.dispatchEvent(new PointerEvent('pointerup', {bubbles: true})), 1")
        stub = ("navigator.permissions.query = () => Promise.resolve({state: 'granted'}); "
                "navigator.mediaDevices.getUserMedia = () => Promise.resolve(new AudioContext({sinkId: {type: 'none'}})"
                ".createMediaStreamDestination().stream); "
                "const of = window.fetch; window.fetch = (u, o) => { const p = String(u); "
                "if (p.startsWith('/api/upload')) return new Promise(() => {}); "   # the upload never ends
                "if (p.startsWith('/api/send')) window.__sent = (window.__sent || 0) + 1; "
                "if (p.startsWith('/api/voice')) return new Promise((ok) => { window.__voice = () => ok(new Response("
                "JSON.stringify({text: 'make a report'}), {status: 200})); }); "
                "return of(u, o); }; 1")
        field = "document.querySelector('#msg').value"
        err = "((document.querySelector('form.composer .error-text') || {}).textContent || '')"
        with mock.patch.dict(os.environ, {"VOICE_CMD": "true"}):
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": f"!!document.querySelector('{mic}')"},
                            {"eval": stub}, {"eval": press},
                            {"until": "!!document.querySelector('[data-rec-clock]')", "ms": 5000}, {"sleep": 800},
                            {"eval": "document.querySelector('form.composer .btn.round.stop').click(), 1"},
                            {"until": "!!window.__voice", "ms": 5000},
                            # the file is dropped during the recognition and does not finish uploading
                            {"dropfiles": [os.path.join(disk, "pic.txt")], "on": "form.composer"},
                            {"until": "!!document.querySelector('form.composer .pchip')", "ms": 5000},
                            {"eval": "window.__voice(), 1"},
                            {"until": f"{field}.includes('make a report')", "ms": 5000}, {"eval": field}, {"eval": err})
        self.assertTrue(got[-3]["until"], "the transcription vanished from the field")
        self.assertIn("make a report", got[-2]["eval"])
        # the voice message waits for the file in the field (it goes out with it once uploaded), it is not refused
        self.assertNotIn("Wait for the files", got[-1]["eval"])
        self.assertFalse(self.page({"sleep": 600}, {"eval": "window.__sent || 0"})[-1]["eval"])

    def test_a_screenshot_added_while_recording_goes_out_with_the_voice_message(self):
        # owner report (Android, Clean): while a voice message records, a screenshot cannot be added — "+" was hidden,
        # Cmd+V went nowhere (the field is hidden), only a drop worked and its "[Image #1]" mark was lost under the words.
        # All three ways now add the file, the recording goes on, and one message carries the voice and the files
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        disk = os.path.join(self.state, "disk")
        os.makedirs(disk)
        with open(os.path.join(disk, "notes.txt"), "w") as f:
            f.write("x")
        mic = "form.composer .btn.round.mic"
        press = (f"document.querySelector('{mic}').dispatchEvent(new PointerEvent('pointerdown', {{button: 0, bubbles: true}})), "
                 "document.dispatchEvent(new PointerEvent('pointerup', {bubbles: true})), 1")
        stub = ("navigator.permissions.query = () => Promise.resolve({state: 'granted'}); "
                "navigator.mediaDevices.getUserMedia = () => Promise.resolve(new AudioContext({sinkId: {type: 'none'}})"
                ".createMediaStreamDestination().stream); window.__sends = []; "
                "const of = window.fetch; window.fetch = (u, o) => { const p = String(u); "
                "if (p.startsWith('/api/voice')) return Promise.resolve(new Response(JSON.stringify({text: 'look here'}), {status: 200})); "
                "if (p.startsWith('/api/send')) window.__sends.push(JSON.parse(o.body)); "
                "return of(u, o); }; 1")
        # a screenshot in the clipboard, pasted with the focus on the page (the field is hidden while recording)
        paste = ("(() => { const b = Uint8Array.from(atob('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8DwHwAFBQIAX8jx0gAAAABJRU5ErkJggg=='), (c) => c.charCodeAt(0)); "
                 "const dt = new DataTransfer(); dt.items.add(new File([b], 'image.png', {type: 'image/png'})); "
                 "(document.activeElement || document.body).dispatchEvent(new ClipboardEvent('paste', {clipboardData: dt, bubbles: true, cancelable: true})); return 1; })()")
        plus = "form.composer > .attach"
        # "+" is shown, nothing covers its middle, and it does not sit over the stop button
        seen = (f"(() => {{ const a = document.querySelector('{plus}'), s = document.querySelector('form.composer .btn.round.stop'); "
                "if (!a || !s) return 'missing'; const r = a.getBoundingClientRect(), q = s.getBoundingClientRect(); "
                "if (!r.width || getComputedStyle(a).visibility === 'hidden') return 'hidden'; "
                "if (!a.contains(document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2))) return 'covered'; "
                "if (r.right > q.left && r.left < q.right && r.bottom > q.top && r.top < q.bottom) return 'over stop'; return 'ok'; })()")
        # where the stop button sits (its right edge and bottom on the screen) and where "+" sits against the card's corner:
        # top-right in the classic look, bottom-left (the action row) in Clean
        place = (f"(() => {{ const f = document.querySelector('form.composer').getBoundingClientRect(), a = document.querySelector('{plus}'), "
                 "s = document.querySelector('form.composer .btn.round.stop'), r = a && a.getBoundingClientRect(), q = s && s.getBoundingClientRect(); "
                 "const clean = document.documentElement.classList.contains('th-clean'); "
                 "return JSON.stringify({plus: r && r.width ? (clean ? [Math.round(r.left - f.left), Math.round(f.bottom - r.bottom)] "
                 ": [Math.round(f.right - r.right), Math.round(r.top - f.top)]) : null, "
                 "stop: q ? `${Math.round(q.right)},${Math.round(q.bottom)}` : null}); })()")
        picked = "document.getElementById('file-input').dataset.for"
        chips = "document.querySelectorAll('form.composer .pchip').length"
        for look in ("clean", "classic"):
            with self.subTest(look=look), mock.patch.dict(os.environ, {"VOICE_CMD": "true"}):
                go = {"go": f"http://127.0.0.1:{self.port}/#/s/a", **({"look": None} if look == "clean" else {})}
                steps = [{"go": "about:blank", "look": None}, go, {"until": f"!!document.querySelector('{mic}')"}]
                at = {}
                def mark(name, *more):
                    steps.extend(more)
                    at[name] = len(steps) - 1
                mark("idle", {"sleep": 400}, {"eval": place})
                steps += [{"eval": stub}, {"eval": press}, {"until": "!!document.querySelector('[data-rec-clock]')", "ms": 5000}]
                mark("rec0", {"sleep": 400}, {"eval": place})
                mark("seen", {"eval": seen})
                mark("plus", {"eval": f"document.getElementById('file-input').dataset.for = ''; document.querySelector('{plus}').click(), {picked}"})
                mark("pasted", {"eval": paste}, {"until": f"{chips} == 1", "ms": 3000})
                mark("rec1", {"sleep": 400}, {"eval": place})   # the chip row has grown the card: the drop point is taken after it settles
                mark("dropped", {"dropfiles": [os.path.join(disk, "notes.txt")], "on": "form.composer"}, {"until": f"{chips} == 2", "ms": 3000})
                mark("rec2", {"sleep": 400}, {"eval": place})
                mark("still", {"eval": "!!document.querySelector('form.composer.rec [data-rec-clock]')"})
                steps += [{"eval": "document.querySelector('form.composer .btn.round.stop').click(), 1"},
                          {"until": "window.__sends.length > 0", "ms": 8000}, {"sleep": 500}, {"eval": "window.__sends"}]
                got = self.page(*steps)
                self.assertEqual(got[at["seen"]]["eval"], "ok", look)
                self.assertEqual(got[at["plus"]]["eval"], "a", look)          # "+" opens the file picker for this field
                self.assertTrue(got[at["pasted"]]["until"], f"{look}: the pasted screenshot was not added")
                self.assertTrue(got[at["dropped"]]["until"], f"{look}: the dropped file was not added")
                self.assertTrue(got[at["still"]]["eval"], f"{look}: adding a file stopped the recording")
                # the stop button keeps one place with 0, 1 and 2 files (a finger on it never lands on "+"), and "+" keeps
                # its place in the card's corner as in the plain field
                idle, *rec = (json.loads(got[at[k]]["eval"]) for k in ("idle", "rec0", "rec1", "rec2"))
                self.assertEqual({r["stop"] for r in rec} | set(), {rec[0]["stop"]}, f"{look}: the stop button moves: {rec}")
                self.assertEqual([r["plus"] for r in rec], [idle["plus"]] * 3, f"{look}: '+' moves while recording: {idle} {rec}")
                sends = got[-1]["eval"]
                self.assertEqual(len(sends), 1, sends)                # one message: the voice and the files together
                self.assertTrue(sends[0]["text"].startswith("🎤"), sends)
                self.assertIn("look here", sends[0]["text"])
                self.assertIn("[Image #1]", sends[0]["text"])        # the mark stays: the session sees which image is meant
                self.assertEqual(len(sends[0].get("attachments") or []), 2, sends)

    def test_the_file_picker_opened_while_recording_holds_the_silence_stop(self):
        # "+" during a recording opens the file picker: the person looks for a screenshot and says nothing. Before, 20 s of
        # that quiet stopped the recording and the voice message went out without the file. The quiet is counted again once
        # the picker closes (the level and the clock are the test's)
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        mic = "form.composer .btn.round.mic"
        click_record = (f"document.querySelector('{mic}').dispatchEvent(new PointerEvent('pointerdown', {{button: 0, bubbles: true}})), "
                        "document.dispatchEvent(new PointerEvent('pointerup', {bubbles: true})), 1")
        recording = "!!document.querySelector('form.composer.rec [data-rec-clock]')"
        fakes = (
            "window.__now = 1000000; Date.now = () => window.__now; window.__level = 0.5; window.__sent = null; "
            "navigator.mediaDevices.getUserMedia = () => Promise.resolve({getTracks: () => [{stop() {}}]}); "
            "window.AudioContext = class { constructor() { this.state = 'running'; } resume() { return Promise.resolve(); } "
            "close() { return Promise.resolve(); } createMediaStreamSource() { return {connect() {}}; } "
            "createAnalyser() { return {fftSize: 0, getFloatTimeDomainData(b) { b.fill(window.__level); }}; } }; "
            "window.MediaRecorder = class { constructor() { this.mimeType = 'audio/webm'; } start() {} "
            "stop() { this.ondataavailable({data: new Blob([new Uint8Array([1, 2, 3, 4])], {type: 'audio/webm'})}); this.onstop(); } }; "
            "const f = window.fetch; window.fetch = (u, o) => { if (String(u).includes('/api/voice')) { window.__sent = 1; "
            "return new Promise(() => {}); } return f(u, o); }; 1")
        later = lambda ms: {"eval": f"window.__now += {ms}, 1"}
        with mock.patch.dict(os.environ, {"VOICE_CMD": "true"}):
            got = self.page(
                {"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": f"!!document.querySelector('{mic}')"}, {"eval": fakes},
                {"eval": click_record}, {"until": recording, "ms": 3000},
                {"sleep": 700}, later(3000), {"sleep": 700}, {"eval": "window.__level = 0, 1"},
                {"eval": "document.querySelector('form.composer > .attach').click(), 1"},
                later(25000), {"sleep": 1000}, {"eval": f"[{recording}, window.__sent]"},   # the picker is open: still recording
                {"eval": "document.getElementById('file-input').dispatchEvent(new Event('cancel')), 1"},
                {"sleep": 700}, later(10000), {"sleep": 700}, {"eval": f"[{recording}, window.__sent]"},   # closed: counted anew
                later(11000), {"until": f"!({recording}) && window.__sent === 1", "ms": 5000},
            )
        self.assertEqual(got[12]["eval"], [True, None], "the recording stopped on the quiet while the file picker was open")
        self.assertEqual(got[17]["eval"], [True, None], "the quiet before the picker closed was counted")
        self.assertTrue(got[-1]["until"], "20 s of quiet after the picker closed did not stop the recording")

    def test_a_voice_message_waiting_for_its_file_goes_out_after_a_session_switch(self):
        # the words wait in the field for a screenshot still uploading; the person opens another session meanwhile and the
        # field is rebuilt. Once the file is uploaded the voice message still goes out, once, with the file
        from unittest import mock
        for name in ("a", "b"):
            self.ev("session.requested", name, session_id=f"s-{name}", cwd="/w")
            self.ev("session.started", name, session_id=f"s-{name}")
        disk = os.path.join(self.state, "disk")
        os.makedirs(disk)
        with open(os.path.join(disk, "pic.png"), "wb") as f:
            f.write(base64.b64decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8DwHwAFBQIAX8jx0gAAAABJRU5ErkJggg=="))
        mic = "form.composer .btn.round.mic"
        press = (f"document.querySelector('{mic}').dispatchEvent(new PointerEvent('pointerdown', {{button: 0, bubbles: true}})), "
                 "document.dispatchEvent(new PointerEvent('pointerup', {bubbles: true})), 1")
        stub = ("navigator.permissions.query = () => Promise.resolve({state: 'granted'}); "
                "navigator.mediaDevices.getUserMedia = () => Promise.resolve(new AudioContext({sinkId: {type: 'none'}})"
                ".createMediaStreamDestination().stream); window.__sends = []; "
                "const of = window.fetch; window.fetch = (u, o) => { const p = String(u); "
                "if (p.startsWith('/api/upload')) return new Promise((ok) => { window.__upload = () => ok(of(u, o)); }); "   # held by the test
                "if (p.startsWith('/api/voice')) return Promise.resolve(new Response(JSON.stringify({text: 'look here'}), {status: 200})); "
                "if (p.startsWith('/api/send')) window.__sends.push(JSON.parse(o.body)); "
                "return of(u, o); }; 1")
        field = "(document.querySelector('form.composer textarea') || {}).value"
        chips = "document.querySelectorAll('form.composer .pchip').length"
        with mock.patch.dict(os.environ, {"VOICE_CMD": "true"}):
            got = self.page(
                {"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": f"!!document.querySelector('{mic}')"}, {"eval": stub},
                {"eval": press}, {"until": "!!document.querySelector('[data-rec-clock]')", "ms": 5000},
                {"dropfiles": [os.path.join(disk, "pic.png")], "on": "form.composer"}, {"until": f"{chips} == 1", "ms": 3000},
                {"sleep": 400}, {"eval": "document.querySelector('form.composer .btn.round.stop').click(), 1"},
                {"until": f"({field} || '').includes('look here')", "ms": 5000},   # the words wait for the file
                {"eval": "location.hash = '#/s/b', 1"}, {"until": "!document.querySelector('form.composer .pchip')", "ms": 5000},
                {"eval": "window.__upload(), 1"}, {"until": "window.__sends.length > 0", "ms": 5000}, {"sleep": 600},
                {"eval": "window.__sends"},
                {"eval": "location.hash = '#/s/a', 1"}, {"until": f"!!document.querySelector('{mic}')", "ms": 5000},
                {"eval": f"[{field}, {chips}]"},
            )
        self.assertTrue(got[9]["until"], "the words did not wait in the field")
        self.assertTrue(got[13]["until"], "the voice message was not sent after the field was rebuilt")
        sends = got[15]["eval"]
        self.assertEqual(len(sends), 1, sends)
        self.assertEqual(sends[0]["session"], "a")
        self.assertIn("look here", sends[0]["text"])
        self.assertIn("[Image #1]", sends[0]["text"])
        self.assertEqual(len(sends[0].get("attachments") or []), 1, sends)
        self.assertEqual(got[-1]["eval"], ["", 0])   # back in the session: nothing left to send again

    def test_retry_transcription_keeps_the_words_typed_after_the_failure(self):
        # the transcription failed; the person typed a line into the field and pressed "Retry transcription": the voice words
        # go in front of it, the typed line is not dropped
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        mic = "form.composer .btn.round.mic"
        press = (f"document.querySelector('{mic}').dispatchEvent(new PointerEvent('pointerdown', {{button: 0, bubbles: true}})), "
                 "document.dispatchEvent(new PointerEvent('pointerup', {bubbles: true})), 1")
        stub = ("navigator.permissions.query = () => Promise.resolve({state: 'granted'}); "
                "navigator.mediaDevices.getUserMedia = () => Promise.resolve(new AudioContext({sinkId: {type: 'none'}})"
                ".createMediaStreamDestination().stream); window.__sends = []; window.__voices = 0; "
                "const of = window.fetch; window.fetch = (u, o) => { const p = String(u); "
                "if (p.startsWith('/api/voice')) return Promise.resolve(window.__voices++ ? new Response(JSON.stringify({text: 'look here'}), {status: 200}) "
                ": new Response(JSON.stringify({error: 'The engine failed.', id: 'x'}), {status: 502})); "
                "if (p.startsWith('/api/send')) window.__sends.push(JSON.parse(o.body)); "
                "return of(u, o); }; 1")
        retry = "[...document.querySelectorAll('.error-text button')].find((b) => b.textContent === 'Retry transcription')"
        typed = ("(() => { const ta = document.querySelector('#msg'); ta.value = 'also the logs'; "
                 "ta.dispatchEvent(new Event('input', {bubbles: true})); return 1; })()")
        with mock.patch.dict(os.environ, {"VOICE_CMD": "true"}):
            got = self.page(
                {"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": f"!!document.querySelector('{mic}')"}, {"eval": stub},
                {"eval": press}, {"until": "!!document.querySelector('[data-rec-clock]')", "ms": 5000}, {"sleep": 400},
                {"eval": "document.querySelector('form.composer .btn.round.stop').click(), 1"},
                {"until": f"!!{retry}", "ms": 5000}, {"eval": typed},
                {"eval": f"{retry}.click(), 1"}, {"until": "window.__sends.length > 0", "ms": 5000}, {"eval": "window.__sends"},
            )
        self.assertTrue(got[7]["until"], "no Retry after the failed transcription")
        self.assertTrue(got[10]["until"], "Retry sent nothing")
        text = got[-1]["eval"][0]["text"]
        self.assertTrue(text.startswith("🎤"), text)
        self.assertIn("also the logs", text)
        self.assertLess(text.index("look here"), text.index("also the logs"), text)

    def test_a_recording_that_failed_to_transcribe_is_kept_with_retry_and_download(self):
        # the recording was not transcribed: the page does not discard it, it offers "Retry transcription" and "Download the
        # recording"
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        fail = ("import('/static/js/voice.js').then((v) => v.transcribeRecording({data: 'AAAA', mime: 'audio/webm', "
                "blob: new Blob(['x']), session: 'a'}, () => {})); 1")
        btns = "[...document.querySelectorAll('.error-text button')].map((b) => b.textContent)"
        with mock.patch.dict(os.environ, {"VOICE_CMD": "true"}):
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"},
                            {"until": "!!document.querySelector('form.composer .btn.round.mic')"}, {"eval": fail},
                            {"until": f"{btns}.length == 2", "ms": 15000}, {"eval": btns},
                            {"eval": "document.querySelector('.error-text').firstChild.textContent"})
        self.assertEqual(got[-2]["eval"], ["Retry transcription", "Download the recording"])
        # next to the "could not transcribe" line: a short reason from the hub (ffmpeg not found…), without a path
        shown = got[-1]["eval"]
        self.assertRegex(shown, r"^The hub couldn't transcribe the voice message — the recording is saved, you can play it back: [^/]+$")
        self.assertEqual(len(os.listdir(os.path.join(self.state, "voice-failed"))), 1)   # and a copy on the server

