    def test_a_recording_without_speech_is_not_offered_for_retry(self):
        # the server answers 422 "no speech in the recording" (PR #288): that is an outcome, not a
        # failure, and "Retry transcription" would help nothing; an earlier failed recording (engine failure) is not
        # displaced, but it is not offered under an error that is not its own either
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        rec = "{data: 'AAAA', mime: 'audio/webm', blob: new Blob(['x']), session: 'a'}"
        fail = f"import('/static/js/voice.js').then((v) => v.transcribeRecording({rec}, () => {{}})); 1"
        silent = ("window.fetch = () => Promise.resolve(new Response(JSON.stringify({error: 'No speech in the recording.'}), "
                  f"{{status: 422}})); import('/static/js/voice.js').then((v) => v.transcribeRecording({rec}, () => {{}})); 1")
        btns = "[...document.querySelectorAll('.error-text button')].map((b) => b.textContent)"
        text = "((document.querySelector('.error-text') || {}).textContent || '')"
        with mock.patch.dict(os.environ, {"VOICE_CMD": "true"}):
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"},
                            {"until": "!!document.querySelector('form.composer .btn.round.mic')"},
                            # 1. the recording was not transcribed (engine failure): the offers are in place
                            {"eval": fail}, {"until": f"{btns}.length == 2", "ms": 15000},
                            # 2. the next recording has no speech: an error with the server's words, no buttons
                            {"eval": silent}, {"until": f"{text}.includes('No speech in the recording')", "ms": 5000},
                            {"eval": btns})
        self.assertTrue(got[3]["until"])
        self.assertTrue(got[5]["until"])
        self.assertEqual(got[-1]["eval"], [])
        self.assertEqual(len(os.listdir(os.path.join(self.state, "voice-failed"))), 1)

    # voice while typing: with text in the field the round button stays "Send" and a dictation microphone appears next to it
    VT_SEND = "form.composer .bar > .btn.round.send"
    VT_DICT = "form.composer .bar > .btn.round.dictate"
    VT_MIC = "form.composer .bar > .btn.round.mic:not(.dictate)"
    VT_TA = "form.composer textarea"
    VT_SHOWN = staticmethod(lambda sel: f"(() => {{ const b = document.querySelector('{sel}'); "
                                        "return !!b && !b.hidden && getComputedStyle(b).display !== 'none'; })()")
    VT_TYPE = staticmethod(lambda text, at: "(() => { const t = document.querySelector('form.composer textarea'); t.focus(); "
                                             f"t.value = {json.dumps(text)}; t.dispatchEvent(new Event('input', {{bubbles: true}})); "
                                             f"t.setSelectionRange({at}, {at}); return 1; }})()")

    def _voicetext_page(self):
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        env = mock.patch.dict(os.environ, {"VOICE_CMD": "true"})
