    def test_with_text_in_the_field_the_microphone_stays_and_dictates_at_the_caret(self):
        # owner report: typing text blocked voice (the one round button turned into "Send"). Now "Send" keeps its place, a
        # microphone appears next to it, the recording goes into the field at the caret and nothing is sent by itself
        self._voicetext_page()
        sh = self.VT_SHOWN
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"},
                        {"until": sh(self.VT_MIC), "ms": 9000}, {"eval": self.DICTATE_STUB},
                        # empty field: only the microphone, no Send, no second one
                        {"eval": f"[{sh(self.VT_MIC)}, {sh(self.VT_SEND)}, {sh(self.VT_DICT)}]"},
                        {"eval": self.VT_TYPE("hello world", 5)}, {"until": sh(self.VT_DICT), "ms": 3000},
                        {"eval": f"[{sh(self.VT_MIC)}, {sh(self.VT_SEND)}, {sh(self.VT_DICT)}, "
                                 f"document.querySelector('{self.VT_DICT}').getAttribute('aria-label')]"},
                        {"shot": os.path.join(self.state, "voicetext-after.png"), "width": 1280, "height": 800},
                        {"eval": self.dz_click(self.VT_DICT)}, {"until": self.dz_rec(self.VT_DICT), "ms": 4000},
                        # while it records the field stays on screen with its text; Space in it is a space
                        {"eval": f"[!!document.querySelector('form.composer.rec'), document.querySelector('{self.VT_TA}').value, "
                                 f"{sh(self.VT_TA)}]"},
                        {"eval": self.dz_click(self.VT_DICT)},
                        {"until": f"document.querySelector('{self.VT_TA}').value.includes('good world')", "ms": 5000},
                        {"eval": f"document.querySelector('{self.VT_TA}').value"},
                        {"eval": "JSON.stringify(window.__posts)"})
        self.assertEqual(got[3]["eval"], [True, False, False])
        self.assertEqual(got[6]["eval"], [False, True, True, "Dictate"])
        self.assertEqual(got[10]["eval"], [False, "hello world", True])
        self.assertEqual(got[-2]["eval"], "hello good world world")   # at the caret (after "hello"), the rest is kept
        posts = json.loads(got[-1]["eval"])
        self.assertEqual(posts.count("/api/voice"), 1)
        self.assertNotIn("/api/send", posts)   # nothing went out by itself

    def named(self, *items):
        """self.page with names for the steps: items are a step, or (name, step); returns {name: result}."""
        steps = [i[1] if isinstance(i, tuple) else i for i in items]
        got = self.page(*steps)
        return {i[0]: got[n] for n, i in enumerate(items) if isinstance(i, tuple)}

    def voice_on(self):
        env = mock.patch.dict(os.environ, {"VOICE_CMD": "true"})
        env.start()
        self.addCleanup(env.stop)

    # a recording with a stub for /api/voice (its answer is held until window.__go() when window.__hold is set; __voice counts the
    # calls) and for /api/send (__sends)
    VOICE_STUB = ("navigator.permissions.query = () => Promise.resolve({state: 'granted'}); "
                  "navigator.mediaDevices.getUserMedia = () => Promise.resolve(new AudioContext({sinkId: {type: 'none'}})"
                  ".createMediaStreamDestination().stream); window.__sends = []; window.__voice = 0; window.__hold = false; "
                  "const of = window.fetch; window.fetch = (u, o) => { const p = String(u); "
                  "if (p.startsWith('/api/voice')) { window.__voice++; const ans = () => new Response(JSON.stringify({text: 'look here'}), "
                  "{status: 200, headers: {'Content-Type': 'application/json'}}); "
                  "return window.__hold ? new Promise((ok) => { window.__go = () => ok(ans()); }) : Promise.resolve(ans()); } "
                  "if (p.startsWith('/api/send')) window.__sends.push(JSON.parse(o.body)); return of(u, o); }; 1")
    MIC = "form.composer .btn.round.mic"
    CLICK_MIC = (f"document.querySelector('{MIC}').dispatchEvent(new PointerEvent('pointerdown', {{button: 0, bubbles: true, pointerId: 7}})), "
                 "document.dispatchEvent(new PointerEvent('pointerup', {bubbles: true, pointerId: 7})), 1")
    SHOT_PASTE = ("(() => { const b = Uint8Array.from(atob('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8DwHwAFBQIAX8jx0gAAAABJRU5ErkJggg=='), (c) => c.charCodeAt(0)); "
                  "const dt = new DataTransfer(); dt.items.add(new File([b], 'image.png', {type: 'image/png'})); "
                  "(document.activeElement || document.body).dispatchEvent(new ClipboardEvent('paste', {clipboardData: dt, bubbles: true, cancelable: true})); return 1; })()")

    def test_done_ends_the_recording_and_puts_the_words_into_the_field_without_sending(self):
        # owner decision (Clean's designer): next to the cross a "Done" button — the recognized words go into the field to be
        # read and corrected, nothing is sent. The words are in the draft too (a session switch and back keeps them); a
        # screenshot added during the recording keeps its mark in front of them; the field's send button sends them as a plain message
        self.voice_on()
        for n in ("a", "b"):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w")
            self.ev("session.started", n, session_id=f"s-{n}")
        strip = "[!!document.querySelector('.recstrip .rec-done'), document.querySelector('.recstrip .rec-done')?.textContent.trim(), !!document.querySelector('.recstrip .rec-cancel')]"
        for look in ("clean", "classic"):
            with self.subTest(look=look):
                go = {"go": f"http://127.0.0.1:{self.port}/#/s/a", **({"look": None} if look == "clean" else {})}
                got = self.named({"go": "about:blank", "look": None}, go, {"until": f"!!document.querySelector('{self.MIC}')"}, {"eval": self.VOICE_STUB},
                                 {"eval": self.CLICK_MIC}, {"until": "!!document.querySelector('[data-rec-clock]')", "ms": 5000},
                                 ("strip", {"eval": strip}), {"eval": self.SHOT_PASTE}, {"until": "document.querySelectorAll('form.composer .pchip').length == 1", "ms": 3000},
                                 {"eval": "document.querySelector('.recstrip .rec-done').click(), 1"},
                                 ("filled", {"until": "!document.querySelector('form.composer.rec') && document.querySelector('form.composer textarea').value.includes('look here')", "ms": 8000}),
                                 ("text", {"eval": "document.querySelector('form.composer textarea').value"}),
                                 ("focus", {"until": "document.activeElement === document.querySelector('form.composer textarea')", "ms": 3000}),   # to read and add to
                                 ("sent0", {"eval": "window.__sends.length"}),
                                 # the draft holds them: another session and back
                                 {"eval": "location.hash = '#/s/b', 1"}, {"until": "main.dataset.for === 'b'"},
                                 {"eval": "location.hash = '#/s/a', 1"}, {"until": "main.dataset.for === 'a'"},
                                 ("back", {"until": "document.querySelector('form.composer textarea').value.includes('look here')", "ms": 3000}),
                                 # they go as an ordinary message (no voice head), with the screenshot
                                 {"eval": "document.querySelector('form.composer .btn.round.send').click(), 1"},
                                 {"until": "window.__sends.length == 1", "ms": 5000}, ("sends", {"eval": "window.__sends"}))
                self.assertEqual(got["strip"]["eval"], [True, "Done", True])
                self.assertTrue(got["filled"]["until"], got)
                self.assertEqual(got["text"]["eval"], "[Image #1] look here")
                self.assertTrue(got["focus"]["until"], got)                     # the caret is in the field
                self.assertEqual(got["sent0"]["eval"], 0)                       # nothing went out by itself
                self.assertTrue(got["back"]["until"], got)
                sent = got["sends"]["eval"][0]
                self.assertEqual(sent["text"], "[Image #1] look here")
                self.assertEqual(len(sent.get("attachments") or []), 1)

    def test_the_red_button_still_sends_and_done_is_not_in_the_held_press(self):
        # a held press has no "Done" (releasing sends it); after a click-started recording the red button sends as before
        # ("🎤 voice: …") and "Done" is offered
        self.voice_on()
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        down = f"document.querySelector('{self.MIC}').dispatchEvent(new PointerEvent('pointerdown', {{button: 0, bubbles: true, pointerId: 7}})), 1"
        up = "document.dispatchEvent(new PointerEvent('pointerup', {bubbles: true, pointerId: 7})), 1"
        done = "!!document.querySelector('.recstrip .rec-done')"
        url = f"http://127.0.0.1:{self.port}/#/s/a"
        held = self.named({"go": url}, {"until": f"!!document.querySelector('{self.MIC}')"}, {"eval": self.VOICE_STUB},
                          {"eval": down}, {"until": "!!document.querySelector('[data-rec-clock]')", "ms": 5000}, {"sleep": 500}, ("done", {"eval": done}),
                          {"eval": up}, {"until": "window.__sends.length == 1", "ms": 8000}, ("text", {"eval": "window.__sends[0].text"}))
        self.assertFalse(held["done"]["eval"])
        self.assertEqual(held["text"]["eval"], "\U0001f3a4 voice: look here")
        clicked = self.named({"go": "about:blank"}, {"go": url}, {"until": f"!!document.querySelector('{self.MIC}')"}, {"eval": self.VOICE_STUB},
                             {"eval": self.CLICK_MIC}, {"until": "!!document.querySelector('[data-rec-clock]')", "ms": 5000}, ("done", {"eval": done}),
                             {"eval": "document.querySelector('form.composer .btn.round.stop').click(), 1"},
                             {"until": "window.__sends.length == 1", "ms": 8000}, ("text", {"eval": "window.__sends[0].text"}))
        self.assertTrue(clicked["done"]["eval"])
        self.assertEqual(clicked["text"]["eval"], "\U0001f3a4 voice: look here")

    def test_the_cross_and_the_clock_stay_while_the_speech_is_recognized_and_the_cross_drops_the_answer(self):
        # owner decision: while the recording is recognized the strip keeps the length of the recording and the cross; the cross
        # (and Esc) lets the answer go — nothing is sent, nothing is put into the field, the microphone is free
        self.voice_on()
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        busy = ("[document.querySelector('.recstrip .rec-wait')?.textContent, document.querySelector('.recstrip .t')?.textContent, "
                "!!document.querySelector('.recstrip [data-rec-clock]'), !!document.querySelector('.recstrip .rec-cancel'), !!document.querySelector('.recstrip .rec-done')]")
        for look in ("clean", "classic"):
            for how in ("cross", "esc"):
                if look == "clean" and how == "esc":
                    continue   # Clean keeps a single Esc for itself and cancels on two (clean.js, tests/clean/voice-keys.test.mjs)
                with self.subTest(look=look, how=how):
                    go = {"go": f"http://127.0.0.1:{self.port}/#/s/a", **({"look": None} if look == "clean" else {})}
                    leave = ({"eval": "document.querySelector('.recstrip .rec-cancel').click(), 1"} if how == "cross" else {"key": "Escape"})
                    got = self.named({"go": "about:blank", "look": None}, go, {"until": f"!!document.querySelector('{self.MIC}')"}, {"eval": self.VOICE_STUB},
                                     {"eval": "window.__hold = true, 1"}, {"eval": self.CLICK_MIC}, {"until": "!!document.querySelector('[data-rec-clock]')", "ms": 5000},
                                     {"sleep": 1200}, {"eval": "document.querySelector('form.composer .btn.round.stop').click(), 1"},
                                     ("waiting", {"until": "window.__voice == 1 && !!document.querySelector('.recstrip .rec-wait')", "ms": 5000}), ("busy", {"eval": busy}),
                                     leave,
                                     ("free", {"until": f"!document.querySelector('form.composer.rec') && !!document.querySelector('{self.MIC}')", "ms": 5000}),
                                     {"eval": "window.__go(), 1"}, {"sleep": 500},
                                     ("end", {"eval": "[document.querySelector('form.composer textarea').value, window.__sends.length, !!document.querySelector('form.composer.rec')]"}))
                    self.assertTrue(got["waiting"]["until"], got)
                    text, clock, ticking, cancel, done = got["busy"]["eval"]
                    self.assertTrue(text)
                    self.assertRegex(clock, r"^0:0[1-9]$")   # the length of the recording (a second or two) stands, it does not tick
                    self.assertEqual((ticking, cancel, done), (False, True, False), got)
                    self.assertTrue(got["free"]["until"], got)
                    self.assertEqual(got["end"]["eval"], ["", 0, False])   # the late answer went nowhere

    def test_a_recording_ended_with_done_keeps_its_aim_through_a_failed_recognition_and_retry(self):
        # "Retry transcription" of a recording ended with "Done" puts the words into the field too, not into a sent message
        self.voice_on()
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        stub = ("window.__n = 0; window.fetch = () => Promise.resolve(window.__n++ ? new Response(JSON.stringify({text: 'second try'}), "
                "{status: 200, headers: {'Content-Type': 'application/json'}}) : new Response(JSON.stringify({error: 'down'}), {status: 502})); "
                "window.__sent = []; window.__filled = []; "
                "import('/static/js/voice.js').then((v) => v.transcribeRecording({data: 'AAAA', mime: 'audio/webm', blob: new Blob(['x']), session: 'a', insert: true}, "
                "(t) => window.__sent.push(t), (t) => window.__filled.push(t))); 1")
        btns = "[...document.querySelectorAll('.error-text button')].map((b) => b.textContent)"
        got = self.named({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": f"!!document.querySelector('{self.MIC}')"},
                         {"eval": stub}, ("kept", {"until": f"{btns}.length == 2", "ms": 8000}),
                         {"eval": "document.querySelector('.error-text button').click(), 1"},
                         ("filled", {"until": "window.__filled.length == 1", "ms": 5000}), ("end", {"eval": "[window.__sent, window.__filled]"}))
        self.assertTrue(got["kept"]["until"] and got["filled"]["until"], got)
        self.assertEqual(got["end"]["eval"], [[], ["second try"]])

    def direction_stand(self):
        """The direction maps with a board of three cards and one message in its feed."""
        root = os.path.join(self.state, "directions")
        d = os.path.join(root, "maps", "backlog", "tasks")
        os.makedirs(d)
        for i, st in enumerate(["To Do", "To Do", "In Progress"], 1):
            with open(os.path.join(d, f"task-{i}.md"), "w") as f:
                f.write(f"---\nid: TASK-{i}\ntitle: 'Slice {i}'\nstatus: {st}\n---\n\n## Description\n\nDetails {i}\n")
        env = mock.patch.dict(os.environ, {"HUB_DIRECTIONS": root})
        env.start()
        self.addCleanup(env.stop)
        self.ev("session.requested", "maps", session_id="s-m", cwd="/m", channel="cli", owner=True)
        self.ev("session.started", "maps", session_id="s-m")
        self.ev("session.said", "maps", text="Noted: the map stays on the old server.")

    def test_the_to_chip_has_a_cross_only_while_the_message_is_addressed_away_from_the_session(self):
        # owner decision (Clean's designer): one press takes the addressee off — the cross on the "To" chip does what "Cancel" of the
        # reply bar does; with nothing to take off (a plain message to this session) there is no cross
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("session.said", "a", text="Noted: the map stays on the old server.")
        cross = "document.querySelector('.to-line .to-x')"
        shown = f"(() => {{ const x = {cross}; return !!x && x.getClientRects().length > 0; }})()"
        for look in ("clean", "classic"):
            with self.subTest(look=look):
                go = {"go": f"http://127.0.0.1:{self.port}/#/s/a", **({"look": None} if look == "clean" else {})}
                got = self.named({"go": "about:blank", "look": None}, go, {"until": "!!document.querySelector('.to-line')"},
                                 {"shot": os.path.join(self.state, "to-x.png"), "width": 1300, "height": 1000},   # a window shorter than 900 hides "To"
                                 ("plain", {"eval": shown}), {"until": "!!document.querySelector('.reply-btn')"},
                                 {"eval": "[...document.querySelectorAll('.reply-btn')].pop().click(), 1"},
                                 {"until": "!!document.querySelector('.reply-chip')?.textContent"}, ("aimed", {"eval": shown}),
                                 ("label", {"eval": f"{cross}.getAttribute('aria-label')"}),
                                 {"mclick": ".to-line .to-x"}, ("off", {"until": "!document.querySelector('.reply-bar')", "ms": 3000}), ("after", {"eval": shown}),
                                 ("to", {"eval": "document.querySelector('.to-line b').textContent"}))
                self.assertFalse(got["plain"]["eval"], got)                  # no reply: no cross
                self.assertTrue(got["aimed"]["eval"], got)                   # a reply: the cross
                self.assertIn("a", got["label"]["eval"])                     # it says where the message goes then
                self.assertTrue(got["off"]["until"], got)                    # the reply is off
                self.assertFalse(got["after"]["eval"], got)
                self.assertEqual(got["to"]["eval"], "a")

    def test_a_board_that_did_not_load_says_what_to_do_and_retry_loads_it_again(self):
        # owner decision (Clean's designer): the error line has a second line and a "Retry" button that asks at once; the class
        # .boards-error is the theme's hook
        self.direction_stand()
        down = ("window.__up = false; const f0 = window.fetch; window.fetch = (u, o) => String(u).includes('/api/backlog') && !window.__up "
                "? Promise.reject(new Error('down')) : f0(u, o); 1")
        for look in ("clean", "classic"):
            with self.subTest(look=look):
                got = self.named({"go": "about:blank", "look": None},
                                 {"go": f"http://127.0.0.1:{self.port}/#/board/maps", "init": down, **({"look": None} if look == "clean" else {})},
                                 {"until": "!!document.querySelector('.boards-body .boards-retry')", "ms": 8000},
                                 ("error", {"eval": "[document.querySelector('.boards-error').textContent, document.querySelector('.boards-error-more').textContent, "
                                                    "document.querySelector('.boards-retry').textContent, !!document.querySelector('.board')]"}),
                                 {"eval": "window.__up = true, 1"}, {"mclick": ".boards-retry"},
                                 ("loaded", {"until": "document.querySelectorAll('.board .board-card').length == 3", "ms": 8000}),
                                 ("end", {"eval": "[!!document.querySelector('.boards-error'), !!document.querySelector('.boards-retry')]"}))
                self.assertEqual(got["error"]["eval"], ["The board did not load", "Check the connection to the hub and try again", "Retry", False], got)
