    def test_on_a_phone_the_search_closes_with_a_word_and_the_head_switches_are_in_the_more_menu(self):
        # owner decision (Clean's designer): on a phone the feed search has a text "Cancel" instead of the cross; "Brief | Detailed" and
        # "Feed | Board" leave the header for the "More" menu (they are there on a wide screen too, hidden, for a theme's narrow header)
        self.direction_stand()
        items = "[...document.querySelectorAll('.menu .menu-item')].filter((b) => b.getClientRects().length).map((b) => b.textContent.trim())"
        segs = "[...document.querySelectorAll('main > .head > .seg')].filter((b) => b.getClientRects().length).length"
        vis = lambda sel: f"(() => {{ const e = document.querySelector('{sel}'); return !!e && e.getClientRects().length > 0; }})()"
        checks = "[...document.querySelectorAll('.menu .menu-item.check')].map((b) => b.getAttribute('aria-checked'))"
        for look in ("clean", "classic"):
            with self.subTest(look=look):
                go = {"go": f"http://127.0.0.1:{self.port}/#/s/maps", **({"look": None} if look == "clean" else {})}
                got = self.named({"go": "about:blank", "look": None}, {"touch": False}, go, {"until": "!!document.querySelector('main .head .menu-btn')"},
                                 {"shot": os.path.join(self.state, "wide.png"), "width": 1500, "height": 900},
                                 {"mclick": "main .head .menu-btn"}, {"until": "!!document.querySelector('.menu')"},
                                 ("wide_items", {"eval": items}), ("wide_segs", {"eval": segs}),
                                 {"key": "Escape"}, {"until": "!document.querySelector('.menu')"},
                                 {"touch": True}, {"shot": os.path.join(self.state, "phone.png"), "width": 390, "height": 800},
                                 {"until": "!!document.querySelector('.fs-lupa')"}, ("phone_segs", {"eval": segs}),
                                 {"tap": "main .head .menu-btn"}, {"until": "!!document.querySelector('.menu')"}, ("phone_items", {"eval": items}),
                                 ("before", {"eval": checks}),
                                 {"tap": ".menu-item.head-fold-view[aria-checked=false]"}, {"sleep": 300},
                                 {"tap": "main .head .menu-btn"}, {"until": "!!document.querySelector('.menu')"}, ("after", {"eval": checks}),
                                 {"key": "Escape"}, {"until": "!document.querySelector('.menu')"},
                                 {"tap": ".fs-lupa"}, {"until": "!!document.querySelector('.fsearch input')"},
                                 ("word", {"eval": f"[{vis('.fs-cancel')}, {vis('.fs-close')}, document.querySelector('.fs-cancel').textContent]"}),
                                 {"tap": ".fs-cancel"}, ("closed", {"until": "!document.querySelector('.fsearch')", "ms": 3000}))
                self.assertFalse({"Feed", "Brief", "Detailed"} & set(got["wide_items"]["eval"]) or any(x.startswith("Board") for x in got["wide_items"]["eval"]), got)   # a wide header: none of the switches' items shows
                self.assertEqual(got["wide_segs"]["eval"], 2, got)                    # and the header has both switches
                self.assertEqual(got["phone_segs"]["eval"], 0, got)                   # a phone: no switches in the header
                self.assertEqual(got["phone_items"]["eval"][:4], ["Feed", "Board 3", "Brief", "Detailed"], got)
                self.assertNotEqual(got["before"]["eval"], got["after"]["eval"], got)   # an item switched the view
                self.assertEqual(got["word"]["eval"], [True, False, "Cancel"], got)    # "Cancel" instead of the cross
                self.assertTrue(got["closed"]["until"], got)

