    def test_searching_the_list_replaces_the_group_buttons_with_a_line(self):
        # owner decision (Clean's designer): the list is a filter while searching, not groups — the buttons give way to a line saying so
        self.direction_stand()
        type_ = "(() => { const i = document.getElementById('filter'); i.value = '%s'; i.dispatchEvent(new Event('input')); return 1; })()"
        state = "[[...document.querySelectorAll('#list .g-tools .btn')].length, document.querySelector('#list .g-tools-note')?.textContent || '']"
        for look in ("clean", "classic"):
            with self.subTest(look=look):
                go = {"go": f"http://127.0.0.1:{self.port}/#/", **({"look": None} if look == "clean" else {})}
                got = self.named({"go": "about:blank", "look": None}, go, {"until": "!!document.querySelector('#list .g-tools')"}, ("idle", {"eval": state}),
                                 {"eval": type_ % "ma"}, {"until": "!!document.querySelector('#list .g-tools-note')", "ms": 3000}, ("typed", {"eval": state}),
                                 {"eval": type_ % "zzz"}, {"until": "!document.querySelector('#list .g-tools-note')", "ms": 3000},
                                 ("nothing", {"eval": "[...document.querySelectorAll('#list > p.hint')].map((p) => p.textContent)"}),   # the empty answer is one line
                                 {"eval": type_ % ""}, {"until": "!!document.querySelector('#list .g-tools')", "ms": 3000}, ("cleared", {"eval": state}))
                self.assertEqual(got["idle"]["eval"][1], "")
                self.assertGreater(got["idle"]["eval"][0], 0)
