                        {"eval": self.VT_TYPE("x", 1)}, {"until": sh(self.VT_DICT), "ms": 3000},
                        {"eval": self.VT_TYPE("", 0)}, {"until": f"!{sh(self.VT_DICT)} && {sh(self.VT_MIC)}", "ms": 3000},
