    def test_the_dictation_stop_button_stays_while_it_records_even_if_the_field_is_cleared(self):
        # review of PR #565: clearing the field (or sending) in the middle of a dictation hid the red stop button, nothing
        # else could stop that recording. The button is hidden only while the field is empty AND the dictation is idle
        self._voicetext_page()
        sh = self.VT_SHOWN
        val = f"document.querySelector('{self.VT_TA}').value"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"},
                        {"until": sh(self.VT_MIC), "ms": 9000}, {"eval": self.DICTATE_STUB},
                        {"eval": self.VT_TYPE("hello world", 5)}, {"until": sh(self.VT_DICT), "ms": 3000},
                        {"eval": self.dz_click(self.VT_DICT)}, {"until": self.dz_rec(self.VT_DICT), "ms": 4000},
                        {"eval": self.VT_TYPE("", 0)}, {"sleep": 400},
                        {"eval": f"[{sh(self.VT_DICT)}, {self.dz_rec(self.VT_DICT)}]"},
                        {"eval": self.dz_click(self.VT_DICT)},
                        {"until": f"{val}.includes('good world')", "ms": 6000},
                        {"eval": "[...document.querySelectorAll('form.composer .stop')].length"},
                        {"eval": "JSON.stringify(window.__posts)"})
        self.assertTrue(all(g["until"] for g in got if "until" in g), got)
        self.assertEqual(got[9]["eval"], [True, True])   # still visible, still the stop button
        self.assertEqual(got[-2]["eval"], 0)             # it stopped
        self.assertNotIn("/api/send", json.loads(got[-1]["eval"]))

    def test_send_keeps_the_right_edge_when_the_dictation_microphone_appears(self):
        # review of PR #565: the dictation button sat after the action button, so Send jumped left when the first character
        # was typed and a tap at the right edge started a recording. Order: …, hint, spacer, dict, action; checked in the
        # wide layout, at 390px and in RTL
        self._voicetext_page()
        sh = self.VT_SHOWN
        shots = os.environ.get("VT_SHOTS", self.state)
        act = "document.querySelector('form.composer .bar > .btn.round:not(.dictate)')"
        geo = (f"(() => {{ const a = {act}.getBoundingClientRect(), d = document.querySelector('{self.VT_DICT}'); "
               "const r = d.getBoundingClientRect(); const kids = [...document.querySelector('form.composer .bar').children]; "
               "return [Math.round(a.left), Math.round(a.right), Math.round(r.left), Math.round(r.right), "
               "kids.indexOf(d) < kids.indexOf(" + act + ".closest('.bar > *')), getComputedStyle(document.documentElement).direction]; })()")
        before = f"(() => {{ const a = {act}.getBoundingClientRect(); return [Math.round(a.left), Math.round(a.right)]; }})()"
        steps = [{"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": sh(self.VT_MIC), "ms": 9000}]
        for name, width, rtl in (("wide", 1280, False), ("phone", 390, False), ("rtl", 390, True)):
            steps += [{"eval": f"(document.documentElement.dir = {json.dumps('rtl' if rtl else 'ltr')}, 1)"},
                      {"eval": self.VT_TYPE("", 0)}, {"until": f"!{sh(self.VT_DICT)}", "ms": 3000},
                      {"shot": os.path.join(shots, f"voicetext-{name}-empty.png"), "width": width, "height": 700},
                      {"eval": before}, {"eval": self.VT_TYPE("hello world", 5)}, {"until": sh(self.VT_DICT), "ms": 3000},
                      {"shot": os.path.join(shots, f"voicetext-{name}-text.png"), "width": width, "height": 700},
                      {"eval": geo}, {"eval": before}]
        got = self.page(*steps)
        self.assertTrue(all(g["until"] for g in got if "until" in g), got)
        evals = [g["eval"] for g in got if "eval" in g and isinstance(g["eval"], list)]
        for i, rtl in enumerate((False, False, True)):
            empty, geometry, after = evals[i * 3:i * 3 + 3]
            # the microphone and Send are boxes of different sizes (48/38px): the edge may differ by a few px, not by a button
            self.assertLessEqual(abs(empty[1 - rtl] - after[1 - rtl]), 10, "the action button moved when the first character was typed")
            al, ar, dl, dr, first, _ = geometry
            self.assertTrue(first, "the dictation button must come before the action button")
            self.assertTrue(dl >= ar if rtl else dr <= al, geometry)

    def test_a_dictation_does_not_clear_someone_elses_error_and_a_cleared_line_resets_the_red_button(self):
        # review of PR #565: a successful dictation erased an unrelated error under the field (a failed send); and after
        # the line of a failed dictation was cleared by a send, the button stayed red with the old reason
        self._voicetext_page()
        sh = self.VT_SHOWN
        err = "[...document.querySelectorAll('form.composer .error-text')].map((n) => n.textContent).join('|')"
        red = f"document.querySelector('{self.VT_DICT}').classList.contains('err')"
        failsend = ("(() => { const f = window.fetch; window.fetch = async (u, o) => String(u) === '/api/send' "
                    "? new Response(JSON.stringify({error: 'send refused'}), {status: 400}) : f(u, o); return 1; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"},
                        {"until": sh(self.VT_MIC), "ms": 9000}, {"eval": self.DICTATE_STUB}, {"eval": failsend},
                        # 1. a failed send leaves its error and the text under the field
                        {"eval": self.VT_TYPE("hello", 5)}, {"until": sh(self.VT_DICT), "ms": 3000},
                        {"eval": f"document.querySelector('{self.VT_SEND}').click()"},
                        {"until": f"{err}.includes('refused')", "ms": 8000},
                        # 2. a successful dictation leaves that error alone
                        {"eval": self.dz_click(self.VT_DICT)}, {"until": self.dz_rec(self.VT_DICT), "ms": 4000},
                        {"eval": self.dz_click(self.VT_DICT)},
                        {"until": f"document.querySelector('{self.VT_TA}').value.includes('good world')", "ms": 6000},
                        {"sleep": 300}, {"eval": err},
                        # 3. a failed dictation turns the button red; the error line is then replaced by a send
                        {"eval": "(window.__voice.push({status: 502, body: {error: 'transcription failed'}}), 1)"},
                        {"eval": self.dz_click(self.VT_DICT)}, {"until": self.dz_rec(self.VT_DICT), "ms": 4000},
                        {"eval": self.dz_click(self.VT_DICT)}, {"until": red, "ms": 6000},
                        {"eval": "(window.fetch = window.fetch, 1)"},
                        {"eval": f"document.querySelector('{self.VT_SEND}').click()"},
                        {"until": f"!{err}.includes('transcription failed')", "ms": 8000},
                        {"eval": self.VT_TYPE("again", 5)}, {"until": sh(self.VT_DICT), "ms": 3000}, {"sleep": 300},
                        {"eval": f"[{red}, document.querySelector('{self.VT_DICT}').getAttribute('aria-label')]"})
        self.assertTrue(all(g["until"] for g in got if "until" in g), got)
        self.assertIn("refused", got[13]["eval"])
        self.assertEqual(got[-1]["eval"], [False, "Dictate"])

    def test_a_failed_dictation_with_text_in_the_field_shows_the_error_and_keeps_the_text(self):
        # the transcription fails: the reason is under the field with "Retry" and "Download", the typed text is untouched,
        # "Retry" puts the words into the field and nothing is sent
        self._voicetext_page()
        sh = self.VT_SHOWN
        err = "[...document.querySelectorAll('form.composer .error-text')].map((n) => n.textContent).join('|')"
        links = "[...document.querySelectorAll('form.composer .error-text .linkbtn')].map((b) => b.textContent)"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"},
                        {"until": sh(self.VT_MIC), "ms": 9000}, {"eval": self.DICTATE_STUB},
                        {"eval": "(window.__voice.push({status: 502, body: {error: 'transcription failed'}}), 1)"},
                        {"eval": self.VT_TYPE("hello world", 11)}, {"until": sh(self.VT_DICT), "ms": 3000},
                        {"eval": self.dz_click(self.VT_DICT)}, {"until": self.dz_rec(self.VT_DICT), "ms": 4000},
                        {"eval": self.dz_click(self.VT_DICT)},
                        {"until": f"{links}.length == 2", "ms": 6000},
                        {"eval": f"[{err}, {links}, document.querySelector('{self.VT_TA}').value, {sh(self.VT_DICT)}]"},
                        {"eval": "(document.querySelector('form.composer .error-text .linkbtn').click(), 1)"},
                        {"until": f"document.querySelector('{self.VT_TA}').value.includes('good world')", "ms": 6000},
                        {"eval": f"[{err}, document.querySelector('{self.VT_TA}').value]"},
                        {"eval": "JSON.stringify(window.__posts)"})
        self.assertTrue(all(g["until"] for g in got if "until" in g), got)
        shown = got[10]["eval"]
        self.assertIn("transcription failed", shown[0])
        self.assertEqual(shown[1:], [["Retry transcription", "Download the recording"], "hello world", True])
        self.assertEqual(got[13]["eval"], ["", "hello world good world"])
        self.assertNotIn("/api/send", json.loads(got[-1]["eval"]))

    def test_a_double_click_on_the_dictation_microphone_and_a_reload_do_not_lose_or_stick(self):
        # a click that comes before the microphone has opened cancels it (as everywhere); a double click on "stop" does not
        # transcribe twice; the typed text survives both; a reloaded page is not left recording
        self._voicetext_page()
        sh = self.VT_SHOWN
        dbl = (f"(() => {{ const b = document.querySelector('{self.VT_DICT}'); for (let i = 0; i < 2; i++) {{ "
               "b.dispatchEvent(new PointerEvent('pointerdown', {button: 0, bubbles: true})); "
               "document.dispatchEvent(new PointerEvent('pointerup', {bubbles: true})); } return 1; })()")
        val = f"document.querySelector('{self.VT_TA}').value"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"},
                        {"until": sh(self.VT_MIC), "ms": 9000}, {"eval": self.DICTATE_STUB},
                        {"eval": self.VT_TYPE("hello world", 11)}, {"until": sh(self.VT_DICT), "ms": 3000},
                        # 1. two quick clicks: the second cancels the opening; the field is as it was, a new click records
                        {"eval": dbl}, {"sleep": 800},
                        {"eval": f"[{val}, {self.dz_rec(self.VT_DICT)}, {sh(self.VT_DICT)}]"},
                        {"eval": self.dz_click(self.VT_DICT)}, {"until": self.dz_rec(self.VT_DICT), "ms": 4000},
                        # 2. a double click on stop: one transcription, one insertion
                        {"eval": "(window.__hold = new Promise((r) => { window.__go = r; }), 1)"},
                        {"eval": dbl}, {"sleep": 600}, {"eval": "(window.__go(), 1)"},
                        {"until": f"{val}.includes('good world')", "ms": 6000}, {"sleep": 500},
                        {"eval": f"[{val}, JSON.stringify(window.__posts)]"},
                        # 3. the tab reloads in the middle of a recording: nothing is left recording
                        {"eval": self.dz_click(self.VT_DICT)}, {"until": self.dz_rec(self.VT_DICT), "ms": 4000})
        self.assertTrue(all(g["until"] for g in got if "until" in g), got)
        self.assertEqual(got[7]["eval"], ["hello world", False, True])
        text, posts = got[-3]["eval"][0], json.loads(got[-3]["eval"][1])
        self.assertEqual(text.count("good world"), 1)
        self.assertEqual(posts.count("/api/voice"), 1)
        from unittest import mock
        with mock.patch.dict(os.environ, {"VOICE_CMD": "true"}):
            after = self.page({"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/s/a"},
                              {"until": sh(self.VT_MIC), "ms": 9000},
                              {"eval": f"[!!document.querySelector('form.composer.rec'), !!document.querySelector('.stop')]"})
        self.assertEqual(after[-1]["eval"], [False, False])

