    def test_every_select_draws_its_own_arrow_with_room_on_the_right(self):
        # owner report: the "Most popular first" arrow in the catalog is pressed against the right edge and sits crooked,
        # since the system arrow has no inset. Like .theme-pick in "Files": its own arrow, room on the right, vertically
        # centered; the rule is common to the page's select, and the own padding of .plugin-sort, .set-row and .retarget does
        # not cancel it
        from unittest import mock
        from modules.market import market
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        found = [{"name": n, "repo": f"bob/hub-plugin-{n}", "description": "x", "kinds": ["page"], "missing": []}
                 for n in ("owl", "fox")]   # sorting applies from two plugins on
        probe = """(() => { try {
          const mk = (host, cls) => { const h = document.createElement(host); if (cls) h.className = cls;
            h.append(document.createElement('select')); document.body.append(h); return h.querySelector('select'); };
          const sels = {sort: document.querySelector('.plugin-sort'), bare: mk('div'), setting: mk('label', 'set-row'),
                        retarget: mk('form', 'retarget')};
          const out = {};
          for (const [k, el] of Object.entries(sels)) {
            const c = getComputedStyle(el);
            out[k] = [c.appearance, parseFloat(c.paddingRight), c.backgroundImage.includes('gradient'),
                      c.backgroundPositionY, c.backgroundPositionX.includes('calc')];
          }
          return JSON.stringify(out);
        } catch (e) { return e.stack; } })()"""
        with mock.patch.object(market.Market, "search", return_value=found):
            got = self.page({"local": {"hub.settingsTab": "plugins"}},
                            {"go": f"http://127.0.0.1:{self.port}/#/settings"}, {"wait": "owl"}, {"eval": probe})
        for name, (appearance, pad, gradient, y, x_calc) in json.loads(got[3]["eval"]).items():
            with self.subTest(name):
                self.assertEqual((appearance, gradient, y, x_calc), ("none", True, "50%, 50%", True))   # two layers: two halves of the checkmark
                self.assertGreaterEqual(pad, 20)   # the arrow is no closer than 8px to the border, the room for it is in the padding

