    # owner decision: on entering a session, if it is empty and has only "Show earlier", load at once up to the first
    # block with text. The button always searches up to a text or to the start of history
    HIST = ("(() => { window.__hist = 0; const of = window.fetch; window.fetch = (u, o) => { "
            "if (String(u).startsWith('/api/history')) window.__hist++; return of(u, o); }; return 1; })()")

    # the feed loads the past by itself even without a press: by scrolling a short feed (Brief collapses the steps) and by
    # searching for text when the first window has none, and on the page this depends on the order of renders. The test is
    # about the press, so we disable feed scrolling before the page loads and count history requests from the start
    NO_SCROLL_LOAD = ("const add = EventTarget.prototype.addEventListener; EventTarget.prototype.addEventListener = "
                      "function (t, ...a) { if (t === 'scroll' && this.classList && this.classList.contains('feed')) "
                      "return; return add.call(this, t, ...a); }")

    def turn(self, name, text, steps=0, said=None, then=0, done=True, **msg):
        """A turn of session name: a message (taken by the turn with its label, so delivered), steps steps, a reply said, then more steps."""
        m = self.j.append("message.received", None, {"to": name, "text": text, "channel": "web", "owner": True, **msg})
        self.ev("turn.started", name, marker=f"m{m['seq']}")
        for i in range(steps):
            self.tool(name, f"{name}-{m['seq']}-{i}", f"step-{i}")
        if said:
            self.ev("session.said", name, text=said)
        for i in range(then):
            self.tool(name, f"{name}-{m['seq']}-then-{i}", f"step-{i}")
        if done:
            self.ev("turn.result", name, is_error=False)

    OWNER = {"channel": "web", "owner": True}
    # the "New · N, from HH:MM" mark and the "To the latest" button (as in messengers)
    DIVIDER = ("(() => { const f = document.querySelector('main .feed'), d = [...f.querySelectorAll('.row.newdiv')]; "
               "if (!d.length) return null; const fr = f.getBoundingClientRect(), r = d[0].getBoundingClientRect(); "
               "return {n: d.length, tag: d[0].querySelector('.nlab').innerText, since: d[0].querySelector('.nsince')?.innerText ?? null, "
               "aria: d[0].getAttribute('aria-label'), in: r.top >= fr.top && r.bottom <= fr.bottom, "
               "at: (r.top - fr.top) / fr.height, "
               "gap: f.scrollHeight - f.scrollTop - f.clientHeight, top: f.scrollTop, "
               "above: d[0].previousElementSibling ? parseInt(d[0].previousElementSibling.dataset.key, 10) : null}; })()")
    JUMP = ("(() => { const b = document.querySelector('main > .jumpnew'); if (!b) return null; "
            "const r = b.getBoundingClientRect(), f = document.querySelector('main .feed').getBoundingClientRect(), n = b.querySelector('.n'); "
            "return {label: b.querySelector('.l').innerText, count: n.hidden ? null : n.innerText, aria: b.getAttribute('aria-label'), "
            "live: b.querySelector('[aria-live=polite]').textContent, "
            "inside: r.bottom <= f.bottom + 1 && r.right <= f.right + 1 && r.top >= f.top, "
            "after: b.previousElementSibling?.classList.contains('feed') === true, "
            "icon: !!b.querySelector('svg.icon use[href$=\"i-down\"]') && b.querySelector('svg.icon').getAttribute('aria-hidden') === 'true'}; })()")

    def unread_session(self, steps=40, before=25, early=None, quote=None, said="New result about the beacon", more=0, last=None, start=True):
        """Session a: `before` read turns, then a turn on the owner's word (quoting the line `early`) with the result `said` — it is
        unread; `more` — that many more turns with no owner word, each with its own result (the last — `last`, if given)."""
        if start:
            self.ev("session.requested", "a", session_id="s-a", cwd="/w", **self.OWNER)
            self.ev("session.started", "a", session_id="s-a")
        if early:
            self.turn("a", "old question", said=early)
        for i in range(before):
            self.turn("a", f"question {i}", said=f"answer {i}")
        m = self.j.append("message.received", None, {"to": "a", "text": "question about the new", **self.OWNER, **({"quote": quote} if quote else {})})
        self.ev("turn.started", "a", marker=f"m{m['seq']}", prompt_head="x")
        for i in range(steps):
            self.tool("a", f"n-{i}", f"new-step-{i}")
        self.ev("session.said", "a", text=said)
        self.ev("turn.result", "a", text=said, is_error=False)
        for i in range(more):
            self.ev("turn.started", "a", marker=f"auto-{i}")
            self.tool("a", f"more-{i}", "ls")
            text = last if last and i == more - 1 else f"Another result {i} about the beacon"
            self.ev("session.said", "a", text=text)
            self.ev("turn.result", "a", text=text, is_error=False)
        return m["seq"]

    def test_a_session_with_news_opens_at_the_last_read_line_with_a_jump_button(self):
        seen = self.unread_session(more=2)
        self.settle()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "New result about the beacon", "ms": 15000},
                        {"until": "!!document.querySelector('.feed .row.newdiv')", "ms": 8000}, {"sleep": 600},
                        {"eval": self.DIVIDER}, {"eval": self.JUMP})
        d, jump = got[4]["eval"], got[5]["eval"]
        self.assertIsNotNone(d, "the \"Last read\" line is missing")
        self.assertEqual(d["n"], 1)
        self.assertEqual(d["tag"], "New · 3")               # answers below the mark — three, the turn steps do not count
        self.assertRegex(d["since"], r"^since \d\d:\d\d( [AP]M)?$")           # time of the first unread
        self.assertTrue(d["in"])                               # the mark is in the feed window — not at the end
        self.assertGreater(d["gap"], 100)                      # there is still unread below
        self.assertEqual(d["above"], seen)                     # above the mark — the last read one
        self.assertEqual(jump["label"], "Latest")
        self.assertEqual(jump["count"], "3")
        self.assertEqual(jump["aria"], "To the latest reply, new: 3")
        self.assertEqual(jump["live"], "New: 3")
        self.assertTrue(jump["inside"])
        self.assertTrue(jump["icon"])                          # the arrow is an SVG icon, not a text glyph
        self.assertTrue(jump["after"])                         # in Tab order the button comes right after the feed, before the input field
        # repaints by snapshots do not remove the line, though opening is already marked as read
        got = self.page({"sleep": 2500}, {"eval": self.DIVIDER}, {"eval": self.JUMP},
                        {"eval": "document.querySelector('main > .jumpnew').click(), 1"}, {"sleep": 400},
                        {"eval": self.DIVIDER}, {"eval": self.JUMP})
        self.assertEqual(got[1]["eval"]["n"], 1)
        self.assertTrue(got[1]["eval"]["in"])
        self.assertIsNotNone(got[2]["eval"])
        self.assertLess(got[5]["eval"]["gap"], 5)              # the answer is shorter than the window — the button goes to the end of the feed
        self.assertEqual(got[5]["eval"]["n"], 1)               # the mark is in place
        self.assertIsNone(got[6]["eval"])                      # no button while the end of the feed is shown

    AT_END_SAID = "A new result about the beacon"

    def test_with_open_at_end_a_session_with_news_opens_at_the_bottom_and_is_marked_read(self):
        # the "Open a session at the end of the feed" checkbox (Appearance, stored in the browser): unread does not hold the feed at the
        # "New" line — it opens at the last message, the line stays in its place, and the end on screen marks the news read
        self.unread_session(more=2, said=self.AT_END_SAID)
        self.settle()
        url = f"http://127.0.0.1:{self.port}/#/s/a"
        at_end = "(() => { const f = document.querySelector('main .feed'); return f.scrollHeight - f.scrollTop - f.clientHeight < 5; })()"
        # off (the default): the feed stands at the line, there is unread below it
        got = self.page({"go": url}, {"wait": self.AT_END_SAID, "ms": 15000},
                        {"until": "!!document.querySelector('.feed .row.newdiv')", "ms": 8000}, {"eval": self.DIVIDER})
        self.assertTrue(got[3]["eval"]["in"])
        self.assertGreater(got[3]["eval"]["gap"], 100)
        # the line stayed in the window — the page marks it read; the core is not fed owner.seen: seen stays, the session is
        # unread on the next opening (the mark is waited for here, so that it does not land in the second half)
        end, marks = time.time() + 10, []
        while not marks and time.time() < end:
            marks = [e for e in self.spooled() if e["type"] == "owner.seen"]
            time.sleep(0.2)
        self.assertEqual(len(marks), 1)
        # on — the checkbox in Settings → Appearance: the feed is at the bottom, the line is in the feed above, no "To the latest"
        # button, the news is marked read — only once the feed is loaded: the feed rows come late, and an empty feed is "at the
        # end" too. The place of the previous opening is forgotten: a reload returns the reader to it
        slow = ("window.__seen = []; const of = window.fetch; window.fetch = (u, o) => { const p = String(u); "
                "if (p.startsWith('/api/seen')) window.__seen.push(!!document.querySelector('.feed .row.newdiv')); "
                "return p.startsWith('/api/timeline') ? new Promise((r) => setTimeout(r, 1500)).then(() => of(u, o)) : of(u, o); }")
        pick = ("[...document.querySelectorAll('.feed-opts label')].find(l => l.textContent.startsWith(%s))"
                ".querySelector('input').click(); 1") % json.dumps(i18n.t("web.brief.at_end"))
        got = self.page({"eval": "localStorage.setItem('hub.settingsTab', 'theme'); location.hash = '#/settings'; 1"},
                        {"until": "document.querySelectorAll('.feed-opts input').length > 5"}, {"eval": pick},
                        {"eval": "localStorage.getItem('hub.feed_at_end')"}, {"eval": "sessionStorage.clear(), 1"},
                        {"go": "about:blank"}, {"go": url, "init": slow}, {"wait": self.AT_END_SAID, "ms": 15000},
                        {"until": "!!document.querySelector('.feed .row.newdiv')", "ms": 8000},
                        {"until": at_end, "ms": 8000}, {"eval": self.DIVIDER}, {"eval": self.JUMP},
                        {"until": "window.__seen.length > 0", "ms": 5000}, {"eval": "window.__seen"})
        self.assertEqual(got[3]["eval"], "1")                  # kept in this browser
        self.assertTrue(got[9]["until"], "the feed did not open at the end")
        self.assertEqual(got[10]["eval"]["n"], 1)              # the line is in its place
        self.assertEqual(got[10]["eval"]["tag"], i18n.t("web.main.new_count", n=3))
        self.assertIsNone(got[11]["eval"])
        self.assertEqual(got[13]["eval"], [True], "marked read before the feed was on screen")
        end, marks = time.time() + 10, []
        while not marks and time.time() < end:
            marks = [e for e in self.spooled() if e["type"] == "owner.seen"]
            time.sleep(0.2)
        self.assertEqual(len(marks), 1, "the end was on screen, but the news was not marked read")

    def test_with_open_at_end_a_session_opened_in_a_background_tab_is_marked_read_when_the_tab_shows(self):
        # opened at the end in a background tab: the page does not mark it read while the tab is hidden, and the first unread
        # is above the window, so nothing else reports it on return — the end on screen marks the news read when the tab shows
        self.unread_session(more=2, said=self.AT_END_SAID)
        self.settle()
        self.spooled()
        hidden = ("window.__vis = 'hidden'; Object.defineProperty(document, 'visibilityState', "
                  "{ configurable: true, get: () => window.__vis }); Object.defineProperty(document, 'hidden', "
                  "{ configurable: true, get: () => window.__vis !== 'visible' })")
        at_end = "(() => { const f = document.querySelector('main .feed'); return f.scrollHeight - f.scrollTop - f.clientHeight < 5; })()"
        got = self.page({"local": {"hub.feed_at_end": "1"}}, {"go": f"http://127.0.0.1:{self.port}/#/s/a", "init": hidden},
                        {"wait": self.AT_END_SAID, "ms": 15000},
                        {"until": "!!document.querySelector('.feed .row.newdiv')", "ms": 8000}, {"until": at_end, "ms": 8000})
        self.assertTrue(got[4]["until"], "the feed did not open at the end")
        self.assertEqual([e for e in self.spooled() if e["type"] == "owner.seen"], [], "marked read in a hidden tab")
        self.page({"eval": "window.__vis = 'visible', document.dispatchEvent(new Event('visibilitychange')), 1"})
        end, marks = time.time() + 10, []
        while not marks and time.time() < end:
            marks = [e for e in self.spooled() if e["type"] == "owner.seen"]
            time.sleep(0.2)
        self.assertEqual(len(marks), 1, "the tab showed the end of the feed, but the news was not marked read")

    def test_with_open_at_end_a_tall_open_question_card_opens_with_its_top_in_view(self):
        # "at the end" must not undo the open question card: a card taller than the window opens with its top at the top of the
        # window, as without the checkbox — the very bottom would leave only its buttons in view, the question above the window
        self.unread_session(more=1, said=self.AT_END_SAID)
        long = "\n".join(f"Line {k} of a long question that does not fit the window." for k in range(60))
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": long, "options": [{"label": "Yes"}, {"label": "No"}]}]})
        self.settle()
        got = self.page({"local": {"hub.feed_at_end": "1"}}, {"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"},
                        {"wait": "Line 0 of a long question", "ms": 15000},
                        {"until": "!!document.querySelector('.feed .row.newdiv')", "ms": 8000}, {"sleep": 600}, {"eval": self.CARD})
        c = got[5]["eval"]
        self.assertIsNotNone(c)
        self.assertFalse(c["in"], c)                            # the card is taller than the window
        self.assertTrue(0 <= c["top"] <= 40, c)                 # its top is at the top of the window
        self.assertGreater(c["gap"], 100, c)                    # not the very bottom

    def test_with_open_at_end_a_reload_keeps_the_reading_place_in_a_session_with_news(self, card=False):
        # "as without news": a reload returns a reader who was higher up to the same place, neither to the line nor to the bottom
        self.unread_session(more=2, said=self.AT_END_SAID)
        if card:
            self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input={
                "questions": [{"question": "Go ahead?", "options": [{"label": "Yes"}, {"label": "No"}]}]})
        self.settle()
        place = "sessionStorage.setItem('hub.scroll', JSON.stringify({name: 'a', gap: 600, ts: Date.now()}))"
        gap = "(() => { const f = document.querySelector('main .feed'); return Math.round(f.scrollHeight - f.scrollTop - f.clientHeight); })()"
        got = self.page({"local": {"hub.feed_at_end": "1"}}, {"go": f"http://127.0.0.1:{self.port}/#/s/a", "init": place},
                        {"wait": self.AT_END_SAID, "ms": 15000},
                        {"until": "!!document.querySelector('.feed .row.newdiv')", "ms": 8000}, {"sleep": 1200}, {"eval": gap})
        self.assertLess(abs(got[5]["eval"] - 600), 40, got[5]["eval"])

    def test_with_open_at_end_a_reload_keeps_the_reading_place_also_with_an_open_question(self):
        self.test_with_open_at_end_a_reload_keeps_the_reading_place_in_a_session_with_news(card=True)

    GROW = ("(() => { const f = document.querySelector('main .feed'), s = document.createElement('div'); "
            "s.className = 'grown'; s.style.height = Math.round(f.clientHeight * %s) + 'px'; "
            "f.firstElementChild.append(s); return 1; })()")

    def test_the_last_read_line_stays_in_view_while_the_feed_grows_after_opening(self):
        # opened the thread in "Brief" — the feed is at the very bottom, the line is above the top edge. After scrolling to the line
        # the feed kept growing (backfill, images, layout) and, pinned to the bottom, drifted away from it
        self.unread_session(steps=3, before=6)
        self.settle()
        url = f"http://127.0.0.1:{self.port}/#/s/a"
        got = self.page({"go": url, "feed": "compact"}, {"wait": "New result about the beacon", "ms": 15000},
                        {"until": "!!document.querySelector('.feed .row.newdiv')", "ms": 8000}, {"sleep": 600},
                        {"eval": self.DIVIDER}, {"eval": self.GROW % "0.5"}, {"sleep": 400}, {"eval": self.DIVIDER},
                        {"eval": self.GROW % "1.5"}, {"sleep": 400}, {"eval": self.DIVIDER})
        self.assertTrue(got[4]["eval"]["in"], "short unread: the line is not on screen right after opening")
        self.assertTrue(got[7]["eval"]["in"], "after the feed grew the line left the window")
        self.assertTrue(got[10]["eval"]["in"], "after growth above the window the line left the window")
        self.assertGreater(got[10]["eval"]["gap"], 100)        # more unread than a screen — the line is not at the end
        self.assertTrue(0.45 <= got[10]["eval"]["at"] <= 0.55, got[10]["eval"]["at"])   # and it stays in the middle of the window

