    CARD = ("(() => { const f = document.querySelector('main .feed'), c = f.querySelector('.feed-inner > .ask-card'); "
            "if (!c) return null; const fr = f.getBoundingClientRect(), r = c.getBoundingClientRect(); "
            "return {in: r.top >= fr.top - 1 && r.bottom <= fr.bottom + 1, top: Math.round(r.top - fr.top), "
            "line: !!f.querySelector('.row.newdiv'), gap: Math.round(f.scrollHeight - f.scrollTop - f.clientHeight)}; })()")

