    # small text of the mark and the counter: on the light theme the base --primary (#4f6cf6) gives 4.37:1 — less than 4.5
    CONTRAST = ("(() => { const g = document.createElement('canvas').getContext('2d', { willReadFrequently: true }); "
                "const rgb = (c) => { g.clearRect(0, 0, 1, 1); g.fillStyle = '#000'; g.fillStyle = c; g.fillRect(0, 0, 1, 1); return [...g.getImageData(0, 0, 1, 1).data]; }; "
                "const f = (v) => { v /= 255; return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; }; "
                "const lum = (c) => 0.2126 * f(c[0]) + 0.7152 * f(c[1]) + 0.0722 * f(c[2]); "
                "const cr = (a, b) => { const x = lum(a), y = lum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); }; "
                "const t = document.querySelector('.row.newdiv .nlab'), n = document.querySelector('main > .jumpnew .n'); "
                "const st = (e) => getComputedStyle(e); "
                "return {tag: cr(rgb(st(t).color), rgb(st(t).backgroundColor)), count: cr(rgb(st(n).color), rgb(st(n).backgroundColor)), "
                "dark: matchMedia('(prefers-color-scheme: dark)').matches}; })()")

