    def test_the_last_read_line_goes_after_the_last_read_row_when_the_steps_row_has_no_key(self):
        # a turn ended with "—": no reply, the steps (and the intermediate result) are one "Brief" line with no record key. It was counted
        # neither as read nor as new: there was no line at all, though the result in it is unread
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", **self.OWNER)
        self.ev("session.started", "a", session_id="s-a")
        self.turn("a", "Old question", said="Old answer")
        m = self.j.append("message.received", None, {"to": "a", "text": "question about the new", **self.OWNER})
        self.ev("turn.started", "a", marker=f"m{m['seq']}", prompt_head="x")
        self.ev("session.said", "a", text="Result about the beacon")
        self.ev("turn.result", "a", text="Result about the beacon", is_error=False)
        self.ev("turn.started", "a", marker="auto")
        for i in range(30):
            self.tool("a", f"n-{i}", f"new-step-{i}")
        self.ev("session.said", "a", text="—")
        self.ev("turn.result", "a", text="—", is_error=False)
        self.settle()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "compact", "brief": {"steps": True}},
                        {"wait": "question about the new", "ms": 20000},
                        {"until": "!!document.querySelector('.feed .row.newdiv')", "ms": 8000}, {"sleep": 600}, {"eval": self.DIVIDER})
        d = got[4]["eval"]
        self.assertIsNotNone(d, "no line")
        self.assertEqual(d["above"], m["seq"])                 # above the line — the last read row with a key
        self.assertEqual(d["tag"], "New")                    # no reply, only steps — without a number and without a time
        self.assertIsNone(d["since"])

    def test_the_new_label_counts_replies_and_not_the_steps(self):
        self.unread_session(steps=40, more=1)
        self.settle()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "Another result 0 about the beacon", "ms": 15000},
                        {"until": "!!document.querySelector('.feed .row.newdiv')", "ms": 8000}, {"sleep": 600},
                        {"eval": self.DIVIDER}, {"eval": self.JUMP},
                        {"eval": "document.querySelectorAll('.feed .row.tool').length"})
        self.assertGreater(got[6]["eval"], 20)                 # many steps below the mark, in "Detailed" they are in view
        self.assertEqual(got[4]["eval"]["tag"], "New · 2")   # two answers
        self.assertIsNone(got[5]["eval"])                      # two answers — no button, though there are many steps

    LONG = "\n\n".join(f"Paragraph {i} about the beacon" for i in range(60))

    def other_reply(self, name, text):
        """A result for a hub task (REPLIED to the hub): not addressed to the owner — the core does not count it as "new" (no owner_out)."""
        d = self.j.append("delegation.created", None, {"session": name, "for_session": "hub", "context": "collect the log",
                                                       "channel": "session", "owner": False, "sender": "hub"})
        self.ev("turn.started", name, marker=f"m{d['seq']}")
        said = self.j.append("session.said", name, {"text": text})
        self.ev("turn.result", name, text=text, is_error=False)
        return said["seq"]

    def test_the_cores_replied_line_in_the_hub_feed_has_no_service_tag(self):
        # the core writes "REPLIED d22: ..." into the hub's feed when an executor answers a task raised for another
        # session; the snapshot's sender is ":core" (the page compared with "core" and never cut the tag). Neither
        # "Detailed" nor "Brief" shows it (the line carries its task, so "Brief" does not fold it into a run). In Russian
        # the line comes translated (label)
        self.replied_in_the_hub_feed("ru")

    def test_the_cores_replied_line_has_no_service_tag_in_english_and_its_continuation(self):
        # English: no translated label, the page cuts the tag from the text itself; the continuation is
        # "REPLIED d22 (continuation): ..."
        self.replied_in_the_hub_feed("en")

    def test_the_cores_replied_line_has_no_service_tag_in_chinese(self):
        # zh-CN writes "REPLIED d22：" with a full-width colon and the continuation as "REPLIED d22（续）："
        self.replied_in_the_hub_feed("zh-CN")

    def test_the_cores_replied_line_has_no_service_tag_in_japanese(self):
        # ja writes the continuation as "REPLIED d22（続き）:"
        self.replied_in_the_hub_feed("ja")

    def test_the_line_under_a_message_takes_the_themes_muted_colour(self):
        # the time and status line under a message is the regular small size, in the theme's own muted-foreground: a
        # theme that sets it (a brown one here) keeps it there
        path = os.path.join(self.state, "market", "bob", "brown")
        os.makedirs(path)
        with open(os.path.join(path, "brown.json"), "w") as f:
            json.dump({"name": "Brown", "colors": {"background": "#fcf3d8", "foreground": "#000000", "primary": "#e52521",
                                                   "muted-foreground": "#4a3a1a"}}, f)
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"extensions": {"bob:brown": {"path": path, "source": "bob/hub-plugin-brown", "themes": ["brown.json"]}}}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", **self.OWNER)
        self.ev("session.started", "a", session_id="s-a")
        m = self.j.append("message.received", None, {"to": "a", "text": "Check the route", **self.OWNER})
        self.ev("turn.started", "a", marker=f"m{m['seq']}", prompt_head="Check the route")
        self.ev("session.said", "a", text="The route is checked")
        self.ev("turn.result", "a", text="The route is checked", is_error=False)
        self.settle()
        # [its colour, its size against a probe of the regular small size (--text-sm)]
        meta = ("(() => { const m = getComputedStyle(document.querySelector('.feed .row .meta'));"
                " const p = document.body.appendChild(document.createElement('span')); p.style.fontSize = 'var(--text-sm)';"
                " const sm = getComputedStyle(p).fontSize; p.remove(); return [m.color, m.fontSize === sm]; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/"}, {"hash": "#/theme/bob%3Abrown%3Abrown.json"},
                        {"until": "localStorage.getItem('hub.theme')?.includes('brown')", "ms": 8000},
                        {"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"},
                        {"until": "!!document.querySelector('.feed .row .meta')", "ms": 15000}, {"eval": meta})
        self.assertTrue(got[2]["until"])
        self.assertTrue(got[4]["until"])
        self.assertEqual(got[5]["eval"], ["rgb(74, 58, 26)", True])

    def replied_in_the_hub_feed(self, lang):
        """Two replies of an executor to tasks set for session b, then a continuation the hub gets because b is gone; the
        hub's feed in `lang`, detailed and brief, shows the replies without the core's tag."""
        cfg = os.path.join(self.state, f"hub-{lang}.json")
        with open(cfg, "w") as f:
            json.dump({"update": {"enabled": False}, "language": lang}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        self.addCleanup(i18n.use, i18n.current())
        i18n.use(lang)   # the server's texts: the hub's language (core/i18n.py current)
        self.ev("session.requested", "hub", session_id="s-hub", cwd="/w", kind="hub", **self.OWNER)
        self.ev("session.started", "hub", session_id="s-hub")
        for name in ("a", "b"):
            self.ev("session.requested", name, session_id=f"s-{name}", cwd="/w", **self.OWNER)
            self.ev("session.started", name, session_id=f"s-{name}")
        for i in range(2):
            d = self.j.append("delegation.created", None, {"session": "a", "for_session": "b", "context": f"collect the log {i}",
                                                           "channel": "session", "owner": False, "sender": "hub"})
            self.ev("turn.started", "a", marker=f"m{d['seq']}")
            self.j.append("session.said", "a", {"text": f"Log {i} collected for session b"})
            r = self.j.append("turn.result", "a", {"text": f"Log {i} collected for session b", "is_error": False})
            self.ev("turn.started", "hub", marker=f"m{r['seq']}", prompt_head="REPLIED")   # the hub reads the core's line
            self.ev("turn.result", "hub", text="—")
            self.ev("turn.stopped", "hub")
        self.ev("turn.stopped", "a")
        # b is gone: the next result of a goes to the hub as the continuation (core/delegations.py, REPLIED_MORE)
        self.ev("session.ended", "b")
        self.ev("session.remove_requested", "b", **self.OWNER)
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        self.j.append("session.said", "a", {"text": "The build on the stand is green"})
        r = self.j.append("turn.result", "a", {"text": "The build on the stand is green", "is_error": False})
        self.ev("turn.stopped", "a")
        self.ev("turn.started", "hub", marker=f"m{r['seq']}", prompt_head="REPLIED")
        self.ev("turn.result", "hub", text="—")
        self.ev("turn.stopped", "hub")
        self.settle()
        from core import journal, reducer
        st = reducer.fold(reducer.empty(), journal.read(self.j.path))
        to_hub = [m["text"] for m in st["messages"].values() if m.get("to") == "hub"]
        self.assertTrue(any(re.match(r"REPLIED d\d+ \(continuation\): ", x) for x in to_hub), to_hub)   # the core's form
        said = ("Log 0 collected for session b", "Log 1 collected for session b", "The build on the stand is green")
        feed_text = "((document.querySelector('.feed') || {}).innerText || '')"
        both = f"{json.dumps(said)}.every((x) => {feed_text}.includes(x))"
        for feed in ("full", "compact"):
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/hub", "feed": feed}, {"until": both, "ms": 15000},
                            {"eval": feed_text})
            self.assertTrue(got[1]["until"], (lang, feed, got[2]["eval"]))
            for x in said:
                self.assertIn(x, got[2]["eval"], (lang, feed))
            self.assertNotIn("REPLIED", got[2]["eval"], (lang, feed))

    def test_the_new_label_counts_only_what_the_core_calls_new_for_the_owner(self):
        # in the hub's session "New · 17" with one new answer (the rest is core service), the line with an old date
        # because of a four-day-old reply to the hub: the page counted any answer after seen as new. New is what the core
        # counts as new for the owner (the news row); the line goes after the last service one, before the steps of the new turn
        self.ev("session.requested", "hub", session_id="s-hub", cwd="/w", kind="hub", **self.OWNER)
        self.ev("session.started", "hub", session_id="s-hub")
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", **self.OWNER)
        self.ev("session.started", "a", session_id="s-a")
        for i in range(4):
            self.turn("a", f"question {i}", said=f"answer {i}")
        self.ev("owner.seen", "a", seq=self.j.seq, **self.OWNER)
        theirs = self.other_reply("a", "Log collected for the hub")
        for i in range(3):
            self.ev("turn.started", "a", marker=f"auto-{i}")
            self.tool("a", f"n-{i}", f"new-step-{i}")
            self.ev("session.said", "a", text=f"New result {i} about the beacon")
            self.ev("turn.result", "a", text=f"New result {i} about the beacon", is_error=False)
        self.settle()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "New result 2 about the beacon", "ms": 15000},
                        {"until": "!!document.querySelector('.feed .row.newdiv')", "ms": 8000}, {"sleep": 600},
                        {"eval": self.DIVIDER})
        d = got[4]["eval"]
        self.assertIsNotNone(d, "no line")
        self.assertEqual(d["tag"], "New · 3")                # three answers to the owner; the reply to the hub and the hub task do not count
        self.assertEqual(d["above"], theirs)                   # the line goes after the service one, not above it

    def test_the_last_read_line_is_found_without_loading_the_far_past_when_the_news_are_marked(self):
        # the boundary (seen) is beyond reach — there was no line at all. New is marked by the core (news):
        # the line is placed by it, the past up to read is not loaded
        self.ev("session.requested", "hub", session_id="s-hub", cwd="/w", kind="hub", **self.OWNER)
        self.ev("session.started", "hub", session_id="s-hub")
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", **self.OWNER)
        self.ev("session.started", "a", session_id="s-a")
        self.turn("a", "Old question", said="Old answer")
        self.ev("owner.seen", "a", seq=self.j.seq, **self.OWNER)
        self.ev("turn.started", "a", marker="auto-far")
        for i in range(250):                                   # more service rows than the first feed window
            self.tool("a", f"n-{i}", f"far-step-{i}")
        self.ev("session.said", "a", text="Result of the far turn")
        self.ev("turn.result", "a", text="Result of the far turn", is_error=False)
        self.settle()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"eval": self.HIST}, {"wait": "Result of the far turn", "ms": 15000},
                        {"until": "!!document.querySelector('.feed .row.newdiv')", "ms": 20000}, {"sleep": 800},
                        {"eval": self.DIVIDER}, {"eval": "window.__hist"})
        self.assertIsNotNone(got[5]["eval"], "no line")
        self.assertEqual(got[5]["eval"]["tag"], "New · 1")
        self.assertTrue(got[5]["eval"]["in"])
        self.assertEqual(got[6]["eval"], 0, "the past was loaded although new is marked")

    def test_leaving_a_search_excerpt_brings_back_the_line_the_button_and_the_place(self):
        # after "Back to the feed" from a search excerpt the "New · 4" mark was 50 screens below the window, the "To the latest"
        # button was missing, the feed stood anywhere: new not yet seen — the feed is at the mark, the button in place; seen
        # (the first new one stayed in the window) — the feed is at the bottom, as on opening a session
        from core import history, journal, reducer
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", **self.OWNER)
        self.ev("session.started", "a", session_id="s-a")
        for k in range(2):   # two archives with "old beacon"
            self.turn("a", f"old question {k}", said=f"old beacon {k}")
            for i in range(4):
                self.turn("a", f"noise {k}-{i}", said="nothing")
            st = reducer.fold(reducer.empty(), journal.read(self.j.path))
            journal.rotate(self.state, st, keep=2, per_session=2)
            self.j = journal.Journal(self.j.path)
        self.unread_session(steps=3, before=160, more=3, last=self.LONG, start=False)
        history.History(self.state).build_all()
        self.settle()
        back = "[...document.querySelectorAll('.excerpt-head button')].find((b) => b.textContent === 'Back to the feed').click(), 1"
        search = [{"eval": "document.querySelector('.fs-lupa').click(), 1"}, {"typed": "old beacon"}, {"sleep": 400},
                  {"key": "Enter"}, {"until": "!!document.querySelector('.excerpt-head')", "ms": 20000},
                  {"sleep": 500}, {"eval": self.JUMP}, {"eval": back}, {"sleep": 900}, {"eval": self.DIVIDER}, {"eval": self.JUMP}]
        with mock.patch.object(history, "SEARCH_BUDGET", 0):
            # new not seen: scrolled up, the first unread is out of the window
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "Paragraph 59 about the beacon", "ms": 15000},
                            {"until": "!!document.querySelector('main > .jumpnew')", "ms": 8000}, {"sleep": 400},
                            {"wheel": -1500}, {"sleep": 300}, *search)
            self.assertIsNone(got[12]["eval"])                 # no button in the excerpt
            d, jump = got[15]["eval"], got[16]["eval"]
            self.assertIsNotNone(d, "no line after the excerpt")
            self.assertTrue(d["in"], f"after the excerpt the feed is not at the line: {d}")
            self.assertIsNotNone(jump, "after the excerpt there is no \"To the latest\" button, though new is not shown")
            self.assertEqual(jump["count"], "4")
            # new seen (the first unread stayed in the window for a second): the feed is at the bottom
            got = self.page({"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "Paragraph 59 about the beacon", "ms": 15000},
                            {"until": "!!document.querySelector('main > .jumpnew')", "ms": 8000}, {"sleep": 1600}, *search)
            self.assertLess(got[14]["eval"]["gap"], 5, "new was seen, yet after the excerpt the feed is not at the bottom")

    def test_navigation_keys_in_the_input_keep_the_feed_in_place_and_typing_takes_it_to_the_end(self):
        # Tab, Shift+Tab and modifiers in the field also carried the feed to the end while the mark held — from the field one could not
        # go back with Shift+Tab to the "To the latest" button. Typing text and sending lead the feed to the end
        self.unread_session(more=2)
        self.settle()
        repaint = "import('/static/js/state.js').then((m) => m.render()); 1"   # snapshots come by themselves; in the test — on demand
        go = [{"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "Another result 1 about the beacon", "ms": 15000},
              {"until": "!!document.querySelector('.feed .row.newdiv')", "ms": 8000}, {"sleep": 600},
              {"eval": "document.querySelector('.dock textarea').focus(), 1"}]
        got = self.page(*go, {"key": "Tab"}, {"key": "Tab", "mods": ["shift"]}, {"key": "Shift"}, {"key": "ArrowLeft"},
                        {"key": "Tab", "mods": ["shift"]}, {"key": "Tab", "mods": ["shift"]}, {"eval": repaint}, {"sleep": 500},
                        {"eval": self.DIVIDER}, {"eval": self.JUMP},
                        {"eval": "document.activeElement.className"})
        d = got[-3]["eval"]
        self.assertTrue(d["in"], f"navigation keys in the field carried the feed away: {d}")
        self.assertGreater(d["gap"], 100)
        self.assertIsNotNone(got[-2]["eval"])                  # the button is in place
        self.assertIn("jumpnew", got[-1]["eval"])              # Shift+Tab from the field reached the button (via the paperclip)
        got = self.page({"go": "about:blank"}, *go, {"typed": "a"}, {"eval": repaint}, {"sleep": 500}, {"eval": self.DIVIDER})
        self.assertLess(got[-1]["eval"]["gap"], 5, "typing text did not lead the feed to the end")

    def test_news_that_come_while_the_reader_is_scrolled_up_are_not_marked_read_until_seen(self):
        # the reader scrolled up, four long answers arrived — the page immediately marked the session as read
        # (no mark, no button): "read — when seen". The "New · N" mark and "To the latest · N" — as on opening
        self.unread_session(steps=3, before=20)
        self.ev("owner.seen", "a", seq=self.j.seq, **self.OWNER)
        self.settle()
        self.spooled()
        top = "Math.round(document.querySelector('main .feed').scrollTop)"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "New result about the beacon", "ms": 15000},
                        {"sleep": 1500}, {"wheel": -600, "times": 4}, {"sleep": 400}, {"eval": self.DIVIDER}, {"eval": top})
        self.assertIsNone(got[-2]["eval"])                     # nothing was unread — no mark
        for i in range(4):
            self.ev("turn.started", "a", marker=f"auto-up-{i}")
            self.ev("session.said", "a", text=self.LONG)
            self.ev("turn.result", "a", text=self.LONG, is_error=False)
        self.settle()
        got2 = self.page({"until": "!!document.querySelector('.feed .row.newdiv')", "ms": 8000}, {"sleep": 1800},
                         {"eval": self.DIVIDER}, {"eval": self.JUMP}, {"eval": top})
        d, jump = got2[2]["eval"], got2[3]["eval"]
        self.assertIsNotNone(d, "no \"New\" mark")
        self.assertEqual(d["tag"], "New · 4")
        self.assertIsNotNone(jump, "no \"To the latest\" button")
        self.assertEqual(jump["count"], "4")
        self.assertLess(abs(got2[4]["eval"] - got[-1]["eval"]), 5, "the reader above was carried away")
        self.assertEqual([e for e in self.spooled() if e["type"] == "owner.seen"], [], "marked as read before it was seen")

    def test_news_after_the_reader_saw_the_old_ones_and_scrolled_up_get_a_new_border_and_are_not_marked_read(self):
        # opened with new, saw it (the core moved seen), scrolled up, one more answer came: the seen mark must not
        # cover the new one — the boundary moves to the new seen, and /api/seen is not sent for the new answer
        seen = self.unread_session(steps=3, before=20)
        self.settle()
        self.spooled()
        top = "Math.round(document.querySelector('main .feed').scrollTop)"
        self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "New result about the beacon", "ms": 15000},
                  {"until": "!!document.querySelector('.feed .row.newdiv')", "ms": 8000}, {"sleep": 2500})
        marks = [e["data"] for e in self.spooled() if e["type"] == "owner.seen"]
        self.assertEqual(len(marks), 1, "saw the new — the page should have marked it")
        self.ev("owner.seen", "a", seq=marks[0]["seq"], **self.OWNER)   # the core accepted it
        self.settle()
        got = self.page({"sleep": 600}, {"wheel": -600, "times": 4}, {"sleep": 400}, {"eval": top})
        self.ev("turn.started", "a", marker="auto-after-seen")
        self.ev("session.said", "a", text=self.LONG)
        self.ev("turn.result", "a", text=self.LONG, is_error=False)
        self.settle()
        # the "New · 1" mark is right even before the new answer (the old, seen one) — wait until the line moves under the seen one
        moved = "document.querySelector('.feed .row.newdiv')?.previousElementSibling?.innerText.includes('New result about the beacon') === true"
        got2 = self.page({"until": moved, "ms": 8000}, {"sleep": 1800}, {"eval": self.DIVIDER}, {"eval": top})
        self.assertEqual(got2[2]["eval"]["n"], 1)
        self.assertEqual(got2[2]["eval"]["tag"], "New · 1")
        self.assertGreater(got2[2]["eval"]["above"], seen, "the boundary did not move under the seen one")
        self.assertLess(abs(got2[3]["eval"] - got[-1]["eval"]), 5, "the reader above was carried away")
        self.assertEqual([e for e in self.spooled() if e["type"] == "owner.seen"], [], "marked as read before it was seen")

    def test_news_that_come_before_the_core_took_the_seen_mark_are_not_marked_read_either(self):
        # race window: the page marked the seen (/api/seen), the core has not yet moved seen, the reader scrolled up, one more
        # answer came — it is not closed by the seen mark: the boundary is under the seen one, no second /api/seen
        seen = self.unread_session(steps=3, before=20)
        self.settle()
        self.spooled()
        self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "New result about the beacon", "ms": 15000},
                  {"until": "!!document.querySelector('.feed .row.newdiv')", "ms": 8000}, {"sleep": 2500})
        marks = [e["data"] for e in self.spooled() if e["type"] == "owner.seen"]
        self.assertEqual(len(marks), 1, "saw the new — the page should have marked it")
        self.page({"sleep": 600}, {"wheel": -600, "times": 4}, {"sleep": 400})   # owner.seen is not fed to the core: seen is still the old one
        self.ev("turn.started", "a", marker="auto-before-core")
        self.ev("session.said", "a", text=self.LONG)
        self.ev("turn.result", "a", text=self.LONG, is_error=False)
        self.settle()
        moved = "document.querySelector('.feed .row.newdiv')?.previousElementSibling?.innerText.includes('New result about the beacon') === true"
        got = self.page({"until": moved, "ms": 8000}, {"sleep": 1800}, {"eval": self.DIVIDER})
        self.assertEqual(got[2]["eval"]["tag"], "New · 1")
        self.assertGreater(got[2]["eval"]["above"], seen, "the boundary did not move under the seen one")
        self.assertEqual([e for e in self.spooled() if e["type"] == "owner.seen"], [], "marked as read before it was seen")

    def test_a_theme_can_change_the_pill_radius_and_the_button_shadow(self):
        # plugin themes (e.g. flat corners, --radius-pill 3px) change
        # the "New" mark, the counter and the "To the latest" button and the button shadow via tokens, without own rules
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", **self.OWNER)
        self.ev("session.started", "a", session_id="s-a")
        self.turn("a", "word " * 80, said="answer")
        self.unread_session(steps=3, before=3, more=2, last=self.LONG, start=False)
        self.settle()
        probe = ("(() => { const r = document.documentElement, q = (s) => document.querySelector(s), cs = (s) => getComputedStyle(q(s)); "
                 "const get = () => ({nlab: cs('.row.newdiv .nlab').borderRadius, btn: cs('main > .jumpnew').borderRadius, count: cs('main > .jumpnew .n').borderRadius, "
                 "shadow: cs('main > .jumpnew').boxShadow}); "
                 "const before = get(); r.style.setProperty('--radius-pill', '3px'); "
                 "r.style.setProperty('--jump-shadow', 'none'); return {before, after: get()}; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "Paragraph 59 about the beacon", "ms": 15000},
                        {"until": "!!document.querySelector('main > .jumpnew')", "ms": 8000}, {"sleep": 600}, {"eval": probe})
        before, after = got[-1]["eval"]["before"], got[-1]["eval"]["after"]
        self.assertEqual((before["nlab"], before["btn"], before["count"]), ("999px", "999px", "999px"))   # as it was
        self.assertEqual((after["nlab"], after["btn"], after["count"]), ("3px", "3px", "3px"))
        self.assertEqual(after["shadow"], "none")

    def test_the_new_label_is_a_solid_pill_with_more_room_above_than_below(self):
        # 36 px above the boundary, 20 below — the mark belongs to the new block; a solid pill and a full-strength line
        # of the same color as the counter of the "To the latest" button (--on-light): "new" looks the same in both places
        self.unread_session(more=2)
        self.settle()
        probe = ("(() => { const cs = (e, p) => getComputedStyle(e, p), l = document.querySelector('.row.newdiv'), t = l.querySelector('.nlab'), "
                 "n = document.querySelector('main > .jumpnew .n'), gap = parseFloat(cs(l.parentElement).rowGap), "
                 "r = (e) => e.getBoundingClientRect(); "
                 "return {pillBg: cs(t).backgroundColor, countBg: cs(n).backgroundColor, pillFg: cs(t).color, countFg: cs(n).color, "
                 "line: cs(l, '::after').backgroundColor, above: parseFloat(cs(l).marginTop) + gap, below: parseFloat(cs(l).marginBottom) + gap, "
                 "pad: cs(t).padding}; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Another result 1 about the beacon", "ms": 15000},
                        {"until": "!!document.querySelector('main > .jumpnew')", "ms": 8000}, {"sleep": 600}, {"eval": probe})
        r = got[-1]["eval"]
        self.assertEqual(r["pillBg"], r["countBg"])            # solid, in the counter's color
        self.assertEqual(r["pillFg"], r["countFg"])
        self.assertEqual(r["line"], r["pillBg"])               # the line at full strength
        self.assertEqual((r["above"], r["below"]), (36, 20))
        self.assertEqual(r["pad"], "4px 10px")

    def test_the_jump_button_leads_to_the_start_of_the_last_reply_and_counts_new_ones(self):
        self.unread_session(steps=3, more=2, last=self.LONG)
        self.settle()
        top = ("(() => { const f = document.querySelector('main .feed'), r = [...f.querySelectorAll('.row.out')].pop(); "
               "return [r.getBoundingClientRect().top - f.getBoundingClientRect().top, r.innerText.includes('Paragraph 0'), f.scrollHeight - f.scrollTop - f.clientHeight]; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "Paragraph 59 about the beacon", "ms": 15000},
                        {"until": "!!document.querySelector('main > .jumpnew')", "ms": 8000}, {"sleep": 600},
                        {"eval": "document.querySelector('main > .jumpnew').click(), 1"}, {"sleep": 500},
                        {"eval": top}, {"eval": self.JUMP}, {"eval": self.DIVIDER})
        place, gone, line = got[6]["eval"], got[7]["eval"], got[8]["eval"]
        self.assertTrue(place[1])
        self.assertTrue(0 <= place[0] <= 40, place)            # the reply byline is at the top of the window
        self.assertGreater(place[2], 100)                      # and not at the end: the reply is longer than the window
        self.assertIsNone(gone)                                # arrived — no button
        self.ev("turn.started", "a", marker="auto-n")
        self.ev("session.said", "a", text="Fresh result about the beacon")
        self.ev("turn.result", "a", text="Fresh result about the beacon", is_error=False)
        got = self.page({"until": "!!document.querySelector('main > .jumpnew')", "ms": 8000}, {"sleep": 300},
                        {"eval": self.JUMP}, {"eval": self.DIVIDER})
        self.assertEqual(got[2]["eval"]["count"], "1")         # the counter is only what came while reading
        self.assertEqual(got[2]["eval"]["live"], "New: 1")
        self.assertEqual(got[3]["eval"]["tag"], "New · 4")   # the mark is at the old boundary, the number grew
        self.assertLess(abs(got[3]["eval"]["top"] - line["top"]), 3)   # did not move the feed

    def test_one_or_two_replies_get_no_jump_button_and_three_that_fit_get_none_either(self):
        # the button is for three new messages that do not fit the window; one long one — without it
        self.unread_session(steps=3, said=self.LONG)
