    def test_typing_in_the_input_does_not_drag_a_reader_scrolled_up_to_the_end(self):
        # typing in the field removed the mark hold — but also did "pin to the bottom" for everyone reading above: the nearest feed growth
        # dragged them down ("rolls back down")
        self.unread_session()
        self.settle()
        top = "document.querySelector('main .feed').scrollTop"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "New result about the beacon", "ms": 15000},
                        {"until": "!!document.querySelector('.feed .row.newdiv')", "ms": 8000}, {"sleep": 600},
                        {"wheel": -600, "times": 2}, {"sleep": 400}, {"eval": top},
                        {"eval": "document.querySelector('.dock textarea').focus(), 1"}, {"key": "a"}, {"sleep": 300},
                        {"eval": self.GROW % "0.5"}, {"sleep": 800}, {"eval": top})
        self.assertLess(abs(got[12]["eval"] - got[6]["eval"]), 5, "after typing in the field the feed was dragged to the end")

    def test_the_border_goes_before_a_result_that_came_while_the_owners_message_was_queued(self):
        # the owner's message into a busy session waits in the queue (the core's seen = its seq), the result of the busy turn comes earlier,
        # and in the feed the message lies by delivery time — after the result. The line must stand before this result.
        # "Full": "Brief" folds the busy turn's result (it is not shown there at all), so it checks nothing there
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", **self.OWNER)
        self.ev("session.started", "a", session_id="s-a")
        for i in range(3):
            self.turn("a", f"question {i}", said=f"answer {i}")
        self.ev("turn.started", "a", marker="auto-q")
        m = self.j.append("message.received", None, {"to": "a", "text": "question from the queue", **self.OWNER})
        self.ev("session.said", "a", text="Result of the busy turn about the beacon")
        self.ev("turn.result", "a", text="Result of the busy turn about the beacon", is_error=False)
        self.ev("turn.started", "a", marker=f"m{m['seq']}")
        self.ev("session.said", "a", text="Answer to the question from the queue")
        self.ev("turn.result", "a", text="Answer to the question from the queue", is_error=False)
        self.settle()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "Answer to the question from the queue", "ms": 15000},
                        {"until": "!!document.querySelector('.feed .row.newdiv')", "ms": 8000}, {"sleep": 600},
                        {"eval": self.DIVIDER})
        d = got[4]["eval"]
        self.assertIsNotNone(d)
        self.assertEqual(d["tag"], "New · 2", "the result that came before the question was delivered ended up above the line")

