    def test_the_bus_liaison_is_named_in_the_pages_language_and_only_the_system_one(self):
        # owner 02.11: the bus's system session "liaison" read as an English word in the Russian page. The row, the header
        # and the search say the page's word for liaison; the name (the address, the tooltip) is as before; someone's own agent of that name
        # is not renamed
        self.ev("session.requested", "liaison", session_id="s-l", cwd="/w", role="agent", channel="core", owner=True)
        self.ev("session.started", "liaison", session_id="s-l")
        nm = "document.querySelector('#list li[data-s=\"liaison\"] .nm')"
        # not a system session: an ordinary agent that happens to carry the name keeps it
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/liaison"}, {"until": f"!!{nm}", "ms": 10000},
                        {"eval": f"{nm}.textContent.trim()"},
                        {"until": "document.querySelector('main .head h2')?.textContent === 'liaison'", "ms": 10000})
        self.assertEqual(got[2]["eval"].split()[-1], "liaison")
