    def test_a_long_question_with_inline_numbering_becomes_a_real_list(self):
        # owner report: the question itself is unreadable nonsense, the numbering is on one line. A long question without line
        # breaks with "(1) …; (2) …; (3) …" was printed by marked as one line of text, with no indents and no list
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        q = ("How does our hub differ from main origin right now? (1) merge into local main and run the tests; (2) push "
             "the branch and open a PR in the shared repository; (3) do nothing, just show the list of differences. "
             "I recommend (1), because it is safer and you can check it yourself before the push.")
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": q, "options": [{"label": "Merge into main"}, {"label": "Push the branch"},
                                                       {"label": "Just show"}]}]})
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "The session is waiting for your answer"},
                        {"eval": "[...document.querySelectorAll('.card legend ol li')].map(li => li.textContent)"},
                        {"eval": "document.querySelector('.card legend').textContent"})
        self.assertEqual(got[-2]["eval"], ["merge into local main and run the tests",
                                           "push the branch and open a PR in the shared repository",
                                           "do nothing, just show the list of differences"])
        # a reference to an option in the explanation ("I recommend (1)") is not a fourth list item but
        # plain text
        self.assertIn("I recommend (1), because", got[-1]["eval"])

