    def test_a_theme_colors_the_waiting_card_header_and_its_corners_follow_the_card(self):
        # owner decision: no cosmetics that break themes — a theme recoloured the question card in its own calm colour and
        # made it square, while the PR #82 header landed on top as a red strip with rounded corners. The header colour is
        # the theme token --attention, the corners come from the card itself (it clips the header), not from --radius-lg
        from unittest import mock
        cfgdir = os.path.join(self.state, "cfg")
        own = os.path.join(cfgdir, "themes")
        os.makedirs(own)
        with open(os.path.join(own, "amber.json"), "w") as f:
            json.dump({"name": "Amber","dark": True, "colors": {"background": "#1c1a17", "foreground": "#e0d6c0",
                                                                "primary": "#e0b050", "attention": "#806a40"}}, f)
        with open(os.path.join(cfgdir, "hub.json"), "w") as f:
            json.dump({}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": os.path.join(cfgdir, "hub.json")})
        env.start()
        self.addCleanup(env.stop)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": "Which scale?", "options": [{"label": "1:500"}, {"label": "1:1000"}]}]})
        square = ("(() => { const s = document.createElement('style'); s.textContent = '.card { border: 0; border-radius: 0; }';"
                  " document.head.append(s); return 1; })()")
        corner = ("(() => { const h = document.querySelector('.card .card-head'), c = h.closest('.card'); "
                  "return [getComputedStyle(h).backgroundColor, getComputedStyle(c).overflow, "
                  "getComputedStyle(h).borderTopLeftRadius]; })()")
        got = self.page({"local": {"hub.settingsTab": "theme"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"wait": "Amber"}, {"sleep": 1500}, {"click": "Amber"}, {"sleep": 800},
                        {"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "The session is waiting for your answer"},
                        {"eval": square}, {"eval": corner})
        bg, clip, radius = got[-1]["eval"]
        self.assertEqual(bg, "rgb(128, 106, 64)")   # the theme's colour, not the hub's red
        self.assertEqual((clip, radius), ("hidden", "0px"))   # the header's corners are the card's corners

