    def test_a_missing_picture_does_not_blink_on_every_redraw(self):
        # "the text in the chat jumps": under a reply naming a deleted image, on every feed snapshot (a turn in progress)
        # its placeholder line reappeared and vanished after three requests, shoving the text above it. The feed now
        # remembers an image that was not found: it does not show the guess at all, and a full path becomes a chip at once
        self.ev("session.requested", "a", session_id="s-a", cwd="/w/proj", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.files_server(lambda path: False)
        self.ev("session.said", "a", text="Nearby is `notion-ref.png`, and this one is file:///w/proj/gone.png")
        self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Nearby is"},
                  {"until": "document.querySelectorAll('.feed .thumbs img.broken').length === 1"
                            " && document.querySelectorAll('.feed .thumbs img').length === 1"},
                  {"eval": "window.__blink = []; new MutationObserver((ms) => { for (const m of ms) for (const n of m.addedNodes) "
                           "for (const i of n.nodeType === 1 ? (n.matches('.thumbs img') ? [n] : n.querySelectorAll('.thumbs img')) : []) "
                           "if (!i.classList.contains('broken')) window.__blink.push(i.alt); })"
                           ".observe(document.body, {childList: true, subtree: true}); 1"})
        self.ev("session.said", "a", text="next reply")
        got = self.page({"until": "document.querySelector('.feed').innerText.includes('next reply')"}, {"sleep": 800},
                        {"eval": "JSON.stringify(window.__blink)"})
        self.assertEqual(json.loads(got[-1]["eval"]), [])

