    def test_a_picture_overwritten_under_the_same_path_shows_its_new_look_in_the_next_message(self):
        # issue: the feed asked for a picture by its bare path, and Chrome keeps a picture by its address for the life of
        # the tab: a file rewritten under the same path showed its old look in the next message. The address now carries
        # the number of the message's event (&v=), the way the question card's preview does
        import struct
        import zlib

        def solid(r, g, b):
            chunk = lambda t, d: struct.pack(">I", len(d)) + t + d + struct.pack(">I", zlib.crc32(t + d))  # noqa: E731
            raw = b"".join(b"\0" + bytes((r, g, b)) * 2 for _ in range(2))
            return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", 2, 2, 8, 2, 0, 0, 0))
                    + chunk(b"IDAT", zlib.compress(raw)) + chunk(b"IEND", b""))
        self.files_server(lambda path: True)
        root = self.files("proj/shots/b.png", "proj/shots/c.png")
        shots = f"{root}/proj/shots"
        upload = os.path.join(attach.root(self.state), "a.png")   # an owner attachment is served from attachments/ only
        os.makedirs(os.path.dirname(upload), exist_ok=True)
        self.ev("session.requested", "a", session_id="s-a", cwd=f"{root}/proj", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        url = pathlib.Path(shots).as_uri()

        def round_(color, said):
            for path in (upload, f"{shots}/b.png", f"{shots}/c.png"):
                with open(path, "wb") as f:
                    f.write(solid(*color))
            e = self.j.append("message.received", None, {"to": "a", "text": said, "channel": "cli", "owner": True,
                              "attachments": [{"path": upload, "name": "a.png", "mime": "image/png", "size": 1}]})
            self.ev("turn.started", "a", marker=f"m{e['seq']}", prompt_head=said)
            text = f"{said}: {url}/b.png"
            self.ev("session.said", "a", text=text)
            self.ev("turn.result", "a", text=text)
            self.ev("turn.stopped", "a")
            self.ev("owner.file", None, path=f"{shots}/c.png", channel="session", owner=False, sender="a")
        imgs = "[...document.querySelectorAll('.feed .thumbs img, .feed .attach-list img')]"
        # the colour of every picture of the feed from its first pixel, once it has loaded
        look = (f"{imgs}.map((i) => {{ if (!i.complete || !i.naturalWidth) return null; const c = document.createElement('canvas'); "
                "c.width = c.height = 1; const g = c.getContext('2d'); g.drawImage(i, 0, 0); "
                "return [...g.getImageData(0, 0, 1, 1).data].slice(0, 3); })")
        round_((200, 0, 0), "first")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "first"},
                        {"until": f"{imgs}.length === 3 && {look}.every((x) => x)", "ms": 8000}, {"eval": look})
        self.assertTrue(got[-2]["until"], got)
        self.assertEqual(got[-1]["eval"], [[200, 0, 0]] * 3)
        round_((0, 200, 0), "second")
        got = self.page({"until": "document.querySelector('.feed').innerText.includes('second')"},
                        {"until": f"{imgs}.length === 6 && {look}.every((x) => x)", "ms": 8000}, {"eval": look},
                        {"eval": f"{imgs}.map((i) => (i.getAttribute('src') || '').match(/&v=(\\d+)/)?.[1] || null)"})
        self.assertTrue(got[1]["until"], got)
        self.assertEqual(got[2]["eval"][3:], [[0, 200, 0]] * 3)   # the new message shows the new look
        versions = got[3]["eval"]
        self.assertTrue(all(versions), versions)                  # every feed picture carries its event's number
        self.assertFalse(set(versions[:3]) & set(versions[3:]), versions)   # each message has its own

