    def test_a_big_picture_fits_the_screen_and_a_click_shows_it_full_size(self):
        # owner request: fix screenshots so they can be viewed properly on click — before/after: a 1482×1941 snapshot
        # in the lightbox overflowed the bottom of the window under the caption, and it could not be seen whole
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("session.said", "a", text="Snapshots ready")
        put = ("(() => { const c = document.createElement('canvas'); c.width = 1482; c.height = 1941; "
               "const g = c.getContext('2d'); g.fillStyle = '#4a8'; g.fillRect(0, 0, 1482, 1941); "
               "const t = document.createElement('div'); t.className = 'thumbs'; const i = new Image(); i.src = c.toDataURL(); "
               "t.append(i); document.querySelector('.feed').append(t); return 1; })()")
        fit = ("(() => { const b = document.querySelector('.lightbox'), r = b.querySelector('.lb-img').getBoundingClientRect(), "
               "bar = b.querySelector('.lb-bar').getBoundingClientRect(); return {top: r.top >= 0, left: r.left >= 0, "
               "right: r.right <= innerWidth, bottom: r.bottom <= bar.top, h: Math.round(r.height), "
               "zoom: b.classList.contains('zoom'), scroll: b.scrollHeight > b.clientHeight}; })()")
        click = "document.querySelector('.lightbox .lb-img').click(), 1"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Snapshots ready"}, {"eval": put},
                        {"until": "document.querySelector('.feed .thumbs img')?.complete"},
                        {"eval": "document.querySelector('.feed .thumbs img').click(), 1"}, {"sleep": 200}, {"eval": fit},
                        {"eval": click}, {"sleep": 150}, {"eval": fit},
                        {"eval": click}, {"sleep": 150}, {"eval": fit})
        shown, zoomed, back = [g["eval"] for g in got if "eval" in g][2::2]
        self.assertEqual({k: shown[k] for k in ("top", "left", "right", "bottom", "zoom")},
                         {"top": True, "left": True, "right": True, "bottom": True, "zoom": False})   # fully on screen
        self.assertGreater(shown["h"], 500)                                # and not a tiny stamp
        self.assertEqual((zoomed["zoom"], zoomed["scroll"], zoomed["h"]), (True, True, 1941))   # a click — as is, with scrolling
        self.assertEqual((back["zoom"], back["bottom"]), (False, True))   # another click — whole again

    def test_scrolling_up_a_little_is_not_undone_by_new_events(self):
        # owner complaint: the feed scrolls by itself while the owner moves the mouse and cannot read what came
        # before: the feed treated anything within 120 px of the bottom as "pinned to the bottom" and on every event of a
        # running session (several per second) returned it down — the first wheel movements up were cancelled at once
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        for i in range(12):
            self.ev("session.said", "a", text=f"Paragraph {i}: " + "a line of text " * 30)
        bottom = "(() => { const f = document.querySelector('main .feed'); return Math.round(f.scrollHeight - f.scrollTop - f.clientHeight); })()"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Paragraph 11"}, {"sleep": 300}, {"eval": bottom},
                        # wheel up by 60 px — less than the old "near the bottom" threshold
                        {"eval": "(() => { const f = document.querySelector('main .feed'); "
                                 "f.dispatchEvent(new WheelEvent('wheel', {deltaY: -60, bubbles: true})); f.scrollTop -= 60; "
                                 "f.dispatchEvent(new Event('scroll')); return 1; })()"}, {"sleep": 150}, {"eval": bottom})
        self.assertLess(got[3]["eval"], 5)            # opened — at the bottom
        self.assertGreater(got[-1]["eval"], 40)       # scrolled up
        for i in range(3):                            # the session is working: events keep coming
            self.ev("session.said", "a", text=f"New {i}")
            got = self.page({"until": f"document.body.innerText.includes('New {i}')", "ms": 5000}, {"sleep": 200}, {"eval": bottom})
            self.assertGreater(got[-1]["eval"], 40, f"after event {i} the feed went back down")
        # scrolled to the bottom by hand — pinned again: new content is visible at once
        self.page({"eval": "(() => { const f = document.querySelector('main .feed'); f.scrollTop = f.scrollHeight; "
                           "f.dispatchEvent(new Event('scroll')); return 1; })()"}, {"sleep": 150})
        self.ev("session.said", "a", text="Final")
        got = self.page({"until": "document.body.innerText.includes('Final')", "ms": 5000}, {"sleep": 300}, {"eval": bottom})
        self.assertLess(got[-1]["eval"], 5)

    def test_an_update_waits_while_the_owner_is_scrolling_the_feed(self):
        # owner complaint: the scroll jumps back again and cannot be scrolled up: while a session works, every event rebuilt the
        # whole feed, and the position was read one frame late — a wheel step made between events was rolled back
        # (measured on a journal copy: 5 of 25 steps). Server updates now wait while the feed is scrolling and are drawn
        # right after; the feed itself stays the same node the scrolling happens on
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        for i in range(12):
            self.ev("session.said", "a", text=f"Paragraph {i}: " + "a line of text " * 30)
        bottom = "(() => { const f = document.querySelector('main .feed'); return Math.round(f.scrollHeight - f.scrollTop - f.clientHeight); })()"
        self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Paragraph 11"}, {"sleep": 300},
                  {"eval": "window.__feed = document.querySelector('main .feed'); window.__n = 0; "
                           "window.__t = setInterval(() => { document.querySelector('main .feed').scrollTop -= 15; "
                           "if (++window.__n >= 25) clearInterval(window.__t); }, 60); 1"})   # ~1.5 s of scrolling up
        self.ev("session.said", "a", text="New in the middle of scrolling")
        got = self.page({"sleep": 700},
                        {"eval": "[document.querySelector('main .feed') === window.__feed, window.__n < 25, "
                                 "document.body.innerText.includes('New in the middle of scrolling')]"})
        self.assertEqual(got[-1]["eval"], [True, True, False], "the feed was rebuilt in the middle of scrolling")
        got = self.page({"until": "document.body.innerText.includes('New in the middle of scrolling')", "ms": 6000},
                        {"sleep": 300}, {"eval": bottom})
        self.assertTrue(got[0]["until"], "the update was never drawn after scrolling")
        self.assertGreater(got[-1]["eval"], 300)   # the scroll position was not lost and did not return down

    def test_the_feed_stays_the_same_node_and_the_scroll_is_left_alone(self):
        # owner complaint: the scroll trouble again, fix it once and for all: a redraw replaced the feed with a new node and
        # gave it the position read from the old one — any redraw (an event, loading more agent steps, a click) could roll
        # a step back up and cut off touchpad inertia. Now for the same session the feed is the same node, only the content
        # changes, and the page does not touch the position of a feed that was scrolled up at all
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        for i in range(12):
            self.ev("session.said", "a", text=f"Paragraph {i}: " + "a line of text " * 30)
        top = "(() => { const f = document.querySelector('main .feed'); return [f === window.__feed, f.scrollTop]; })()"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Paragraph 11"}, {"sleep": 300},
                        {"eval": "(() => { const f = document.querySelector('main .feed'); window.__feed = f; "
                                 "f.scrollTop -= 437; return f.scrollTop; })()"}, {"sleep": 500})
        at = got[3]["eval"]
        for i in range(3):
            self.ev("session.said", "a", text=f"New {i}")
            got = self.page({"until": f"document.body.innerText.includes('New {i}')", "ms": 5000}, {"sleep": 200}, {"eval": top})
            self.assertEqual(got[-1]["eval"], [True, at], f"after event {i}: the feed was replaced or shifted")

    def test_what_the_owner_reads_does_not_drift_while_the_session_works(self):
        # owner complaint, with a screen recording: the scroll is still not fixed — scrolled up in the feed of a working
        # session, and after a couple of seconds the text being read moved down by itself. The page keeps 400 feed rows;
        # in a tab opened long ago the window is full, and every new row at the bottom pushed out the oldest one at the top —
        # everything above the reading spot got shorter and the text drifted, although the scroll position did not change
        # (earlier measurements watched it and saw no shift). While the owner reads higher up, old rows are not dropped,
        # and the place is anchored to the row itself
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        for i in range(160):
            self.ev("message.received", None, to="a", text=f"Question {i}", channel="cli", owner=True)
            self.ev("session.said", "a", text=f"Paragraph {i}: " + "a line of text " * (3 + i % 7))
        self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "Paragraph 159"}, {"sleep": 300})
        for k in range(160, 330, 34):   # the tab was opened long ago: the feed window is full
            for i in range(k, k + 34):
                self.ev("message.received", None, to="a", text=f"Question {i}", channel="cli", owner=True)
                self.ev("session.said", "a", text=f"Paragraph {i}: " + "a line of text " * (3 + i % 7))
            self.page({"until": f"document.body.innerText.includes('Paragraph {k + 33}')", "ms": 8000})
        spot = ("(() => { const f = document.querySelector('main .feed'), top = f.getBoundingClientRect().top; "
                "const n = [...f.querySelectorAll('.row')].find((r) => r.getBoundingClientRect().bottom > top + 40); "
                "return [(n.innerText.match(/(Paragraph|Question) \\d+/) || [''])[0], Math.round(n.getBoundingClientRect().top - top)]; })()")
        got = self.page({"until": "document.body.innerText.includes('Paragraph 329')", "ms": 10000}, {"sleep": 500},
                        {"eval": "(() => { const f = document.querySelector('main .feed'); f.scrollTop = f.scrollHeight / 2; "
                                 "f.dispatchEvent(new WheelEvent('wheel', {deltaY: -1})); f.dispatchEvent(new Event('scroll')); return 1; })()"},
                        {"sleep": 500}, {"eval": spot})
        before = got[-1]["eval"]
        for i in range(20):
            self.ev("session.said", "a", text=f"New {i}: " + "a line of text " * 20)
        got = self.page({"until": "document.body.innerText.includes('New 19')", "ms": 8000}, {"sleep": 500}, {"eval": spot})
        self.assertTrue(got[0]["until"])
        self.assertEqual(got[-1]["eval"][0], before[0], (before, got[-1]["eval"]))
        self.assertLess(abs(got[-1]["eval"][1] - before[1]), 3, (before, got[-1]["eval"]))

    def test_an_open_question_does_not_cut_the_scroll_when_other_sessions_change(self):
        # owner complaint: it rolls back on events when someone writes or a question appears — a session has an open
        # question, you scroll up a little, and other sessions get new questions and replies. The question card is the same
        # node between redraws: building the new feed took it out of the visible one, the feed briefly became shorter by the
        # card, and the layout read clipped the scroll by its height
        for n in "ab":
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True)
            self.ev("session.started", n, session_id=f"s-{n}")
            self.ev("turn.started", n, marker=None, prompt_head="x")
        for i in range(40):
            self.ev("session.said", "a", text=f"Paragraph {i}: " + "a line of text " * (3 + i % 7))
        ask = lambda n, r: self.ev("permission.requested", n, request_id=r, tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": f"Question {n}: what to do?",
                           "options": [{"label": "This way", "description": "explanation " * 10}, {"label": "That way"}]}]})
        ask("a", "r1")
        top = "Math.round(document.querySelector('main .feed').scrollTop)"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "Question a"}, {"sleep": 800},
                        {"wheel": -60}, {"sleep": 500}, {"eval": top})
        at = got[-1]["eval"]
        ask("b", "r2")   # a new question in another session — in the open one the "Waiting for you" strip changes and everything is redrawn
        got = self.page({"until": "document.querySelector('main .dock').innerText.includes('b')", "ms": 5000},
                        {"sleep": 800}, {"eval": top})
        self.assertEqual(got[-1]["eval"], at, "the scroll was cut off")

    def test_a_tall_question_card_keeps_the_place_in_its_middle(self):
        # owner report: a question form with several questions does not fit the screen; scrolled to its middle, it throws
        # the reader up, then down. Rows above the card change while the session works; the redraw kept the place by the first
        # feed row at the top of the view, and the card had no key — the card moved by every change above it
        for n in "ab":
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True)
            self.ev("session.started", n, session_id=f"s-{n}")
            self.ev("turn.started", n, marker=None, prompt_head="x")
        for i in range(10):
            self.ev("session.said", "a", text=f"Paragraph {i}: " + "a line of text " * 20)
        self.tool("a", "t1", "make build")
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": f"Question {q}: what to do?",
                           "options": [{"label": f"Option {q}{o}", "description": "explanation " * 30} for o in range(4)]}
                          for q in range(4)]})
        card = ("(() => { const f = document.querySelector('main .feed'), c = f.querySelector('.ask-card'); "
                "return Math.round(c.getBoundingClientRect().top - f.getBoundingClientRect().top); })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "Question 3"}, {"sleep": 800},
                        {"eval": "document.querySelector('main .ask-card').offsetHeight > document.querySelector('main .feed').clientHeight"},
                        {"wheel": -120, "times": 5, "every": 40}, {"sleep": 600}, {"eval": card})
        self.assertTrue(got[3]["eval"], "card fits the screen")
        at = got[-1]["eval"]
        self.assertLess(at, 0, "not inside the card")
        # above the card: the step ends with a long result, the session writes, another session writes
        self.ev("turn.tool_result", "a", id="t1", text="\n".join(f"line {i}" for i in range(20)), error=False)
        self.ev("session.said", "a", text="this session writes " * 20)
        self.ev("session.said", "b", text="another session writes")
        got = self.page({"until": "document.querySelector('main .feed').innerText.includes('this session writes')", "ms": 5000},
                        {"sleep": 800}, {"eval": card})
        # ±1 px: chrome-headless-shell rounds the fractional scroll position the other way (-1417 vs -1418); the bug
        # moved the card by the height of the rows above it
        self.assertLessEqual(abs(got[-1]["eval"] - at), 1, f"the card moved: {at} -> {got[-1]['eval']}")

    def test_the_question_being_read_stays_put_when_messages_arrive(self):
        # a message arriving while the owner reads the options of a question card lands above the card, and the place
        # was kept by a row above it: the card got pushed down by the height of the new rows; at the bottom the queue
        # strip made it jump. While the card is in view, the card itself keeps its place
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        for i in range(30):
            self.ev("session.said", "a", text=f"Paragraph {i}: " + "a line of text " * (3 + i % 7))
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": "Question: what to do?",
                           "options": [{"label": f"Option {k}", "description": "explanation " * 20} for k in range(4)]}]})
        self.ev("turn.stopped", "a")
        card = ("(() => { const f = document.querySelector('main .feed'); "
                "return Math.round(f.querySelector('.ask-card').getBoundingClientRect().top - f.getBoundingClientRect().top); })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "Question: what to do"},
                        self.OPT_STEADY, {"eval": card})   # the card drawn and still (a fixed 800 ms missed it under load)
        self.assertTrue(got[-2]["until"], got)
        at = got[-1]["eval"]
        for k, wheel in enumerate((0, -60)):   # at the bottom, then a bit higher while reading the card
            if wheel:
                at = self.page({"wheel": wheel}, {"sleep": 500}, {"eval": card})[-1]["eval"]
            e = self.j.append("message.received", None, {"to": "a", "text": f"Message {k}", "channel": "session",
                                                         "owner": False, "sender": "b"})
            got = self.page({"until": f"document.body.innerText.includes('Message {k}')", "ms": 5000}, {"sleep": 400},
                            {"eval": card})
            self.assertLess(abs(got[-1]["eval"] - at), 3, f"queued: the card moved ({k})")
            self.ev("turn.started", "a", marker=f"m{e['seq']}", prompt_head="x")
            self.ev("session.said", "a", text=f"Reply {k}: " + "a line of text " * 20)
            self.ev("turn.stopped", "a")
            got = self.page({"until": f"document.body.innerText.includes('Reply {k}')", "ms": 5000}, {"sleep": 400},
                            {"eval": card})
            self.assertLess(abs(got[-1]["eval"] - at), 3, f"delivered: the card moved ({k})")
        # answered and scrolled to the bottom: new rows are in view right away again
        self.ev("permission.answered", "a", request_id="r1", channel="web", owner=True)
        bottom = "(() => { const f = document.querySelector('main .feed'); return Math.round(f.scrollHeight - f.scrollTop - f.clientHeight); })()"
        self.page({"until": "!document.querySelector('main .ask-card')", "ms": 5000},
                  {"eval": "(() => { const f = document.querySelector('main .feed'); f.scrollTop = f.scrollHeight; "
                           "f.dispatchEvent(new Event('scroll')); return 1; })()"}, {"sleep": 200})
        self.ev("session.said", "a", text="The last one")
        got = self.page({"until": "document.body.innerText.includes('The last one')", "ms": 5000}, {"sleep": 300}, {"eval": bottom})
        self.assertLess(got[-1]["eval"], 5)

    def test_the_feed_that_blinks_out_and_back_keeps_the_reading_place(self):
        # owner request: if the reader is not at the very bottom, remember the state so the text does not jump: the hub
        # vanished from the snapshot for a moment (restart, sleep) and came back — the feed is rebuilt and used to slide down
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.started", "hub", session_id="s-h")
        for i in range(14):
            self.ev("session.said", "hub", text=f"Paragraph {i}: " + "a line of text " * 30)
        gap = "(() => { const f = document.querySelector('main .feed'); return f ? Math.round(f.scrollHeight - f.scrollTop - f.clientHeight) : -1; })()"
        up = ("(() => { const f = document.querySelector('main .feed'); f.dispatchEvent(new WheelEvent('wheel', {deltaY: -700, bubbles: true})); "
              "f.scrollTop -= 700; f.dispatchEvent(new Event('scroll')); return 1; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/"}, {"wait": "Paragraph 13"}, {"sleep": 500}, {"eval": up}, {"sleep": 300}, {"eval": gap})
        before = got[-1]["eval"]
        self.assertGreater(before, 500)
        self.ev("session.ended", "hub")
        self.page({"until": "!document.querySelector('main .feed')", "ms": 5000})
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.started", "hub", session_id="s-h")
        got = self.page({"wait": "Paragraph 13", "ms": 8000}, {"sleep": 800}, {"eval": gap})
        self.assertLess(abs(got[-1]["eval"] - before), 60, (before, got[-1]["eval"]))

    def test_a_page_reload_keeps_the_place_where_the_owner_was_reading(self):
        # owner complaint: reading the chat text while the page refreshes (the hub updated — the tab reloads itself) and the
        # scroll resets to the bottom: after a reload, a reader who was higher up returns to the same place
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        for i in range(14):
            self.ev("session.said", "a", text=f"Paragraph {i}: " + "a line of text " * 30)
        gap = "(() => { const f = document.querySelector('main .feed'); return Math.round(f.scrollHeight - f.scrollTop - f.clientHeight); })()"
        up = ("(() => { const f = document.querySelector('main .feed'); f.scrollTop -= 700; "
              "f.dispatchEvent(new Event('scroll')); return 1; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Paragraph 13"}, {"sleep": 400},
                        {"eval": up}, {"sleep": 300}, {"eval": gap}, {"eval": "location.reload(); 1"})
        before = got[5]["eval"]
        self.assertGreater(before, 500)                       # scrolled up
        got = self.page({"wait": "Paragraph 13"}, {"sleep": 1200}, {"eval": gap})
        self.assertLess(abs(got[-1]["eval"] - before), 40, (before, got[-1]["eval"]))   # stayed in the same place

    def test_own_answer_is_multiline_shift_enter_newline_enter_sends(self):
        # owner complaint: Shift+Enter for a new line does not work in the message field
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": "Which option?", "options": [{"label": "A"}, {"label": "B"}]}]})
        key = ("(() => { const t = document.querySelector('.ask-card [name=other0]'); "
               "const e = new KeyboardEvent('keydown', {key: 'Enter', shiftKey: %s, bubbles: true, cancelable: true}); "
               "t.dispatchEvent(e); return e.defaultPrevented; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "The session is waiting for your answer"},
                        {"eval": "document.querySelector('.ask-card [name=other0]').tagName"},
                        {"eval": "(document.querySelector('.ask-card [name=other0]').value = 'first\\nsecond', 1)"},
                        {"eval": key % "true"}, {"sleep": 300})
        self.assertEqual(got[2]["eval"], "TEXTAREA")
        self.assertFalse(got[4]["eval"])                                   # Shift+Enter — the browser inserts a line break
        self.assertFalse([e for e in self.spooled() if e["type"] == "permission.answered"])   # and does not send
        got = self.page({"eval": key % "false"}, {"sleep": 800})
        self.assertTrue(got[0]["eval"])                                    # Enter — send, no line break
        sent = [e["data"] for e in self.spooled() if e["type"] == "permission.answered"]
        self.assertEqual([d["answers"] for d in sent], [{"Which option?": "first\nsecond"}])

    def test_answered_card_folds_at_once_and_is_not_sent_twice(self):
        # owner complaint: pressing the button on an ask question does nothing, it takes several clicks: the answer
        # got through on the first click, but the card hung until the next snapshot (seconds under load), and the button
        # became active again; 7 more clicks — 7 core rejections "permission.answered in idle" (in the journal)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": "Which option?", "options": [{"label": "A"}, {"label": "B"}]}]})
        shown = "!!document.querySelector('.ask-card[data-ask=r1]:not(.sent)')"   # the expanded card: a collapsed one is a row with the answer
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "The session is waiting for your answer"},
                        {"eval": "document.querySelector('.ask-card input[value=\"A\"]').click(), 1"},   # a tap = the answer
                        {"eval": "document.querySelector('.ask-card button[type=submit]')?.click(), 1"},
                        {"sleep": 600}, {"eval": shown},
                        # a snapshot without the core's answer (the question is still pending) — the card does not expand again
                        {"eval": "import('/static/js/state.js').then((m) => m.render()), 1"}, {"sleep": 300}, {"eval": shown})
        self.assertEqual((got[5]["eval"], got[8]["eval"]), (False, False))
        sent = [e for e in self.spooled() if e["type"] == "permission.answered"]
        self.assertEqual(len(sent), 1)

    def test_a_card_taken_away_elsewhere_keeps_the_typed_text(self):
        # review finding: a question was answered from Telegram or another device and the session withdrew it — the card
        # vanished together with what the owner had typed in "your own answer". The typed text stays: the card is frozen,
        # it cannot be answered from, and the text goes to the input field with one button; without typed text the card
        # goes away as before
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        ask = {"questions": [{"question": "Which option?", "options": [{"label": "A"}, {"label": "B"}]}]}
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input=ask)
        typed = ("(() => { const t = document.querySelector('.ask-card[data-ask=%s] [name=other0]'); t.value = '%s'; "
                 "t.dispatchEvent(new Event('input', {bubbles: true})); return 1; })()")
        look = ("(() => { const c = document.querySelector('.ask-card.frozen'); if (!c) return null; "
                "const ta = c.querySelector('[name=other0]'); return {note: c.querySelector('.frozen-note').textContent, "
                "ro: ta.readOnly, text: ta.value, live: [...c.querySelectorAll('.opt input, .btns')].filter((x) => "
                "!x.disabled && !x.hidden).length + c.querySelectorAll('.other-row .btn:not([hidden])').length, "
                "under: c.lastElementChild.className}; })()")   # the strip is at the bottom, in place of the answer buttons
        self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "The session is waiting for your answer"},
                  {"eval": typed % ("r1", "my own answer")})
        self.ev("permission.answered", "a", request_id="r1", behavior="allow", answers={"Which option?": "A"},
                channel="telegram", owner=True)
        got = self.page({"until": "document.querySelector('.ask-card.frozen .frozen-note')?.textContent.startsWith('Already')",
                         "ms": 5000}, {"eval": look},
                        {"eval": "document.querySelector('.ask-card.frozen').requestSubmit(), 1"}, {"sleep": 400})
        self.assertEqual(got[1]["eval"], {"note": "Already answered — your text is kept", "ro": True, "text": "my own answer",
                                          "live": 0, "under": "frozen-bar"})
        self.assertEqual(len([e for e in self.spooled() if e["type"] == "permission.answered"]), 0)  # nothing was sent from it
        got = self.page({"eval": "[...document.querySelectorAll('.frozen-bar button')][0].click(), 1"}, {"sleep": 300},
                        {"eval": "document.getElementById('msg').value"},
                        {"eval": "document.querySelectorAll('.ask-card').length"})
        self.assertEqual((got[2]["eval"], got[3]["eval"]), ("my own answer", 0))   # the text is in the field, no card
        # the question was closed without an answer in Telegram — "Question closed"; with no typed text the card goes
        # away as before
        self.ev("permission.requested", "a", request_id="r2", tool="AskUserQuestion", interactive=True, input=ask)
        self.page({"until": "!!document.querySelector('.ask-card[data-ask=r2]')", "ms": 5000},
                  {"eval": typed % ("r2", "more text")})
        self.ev("question.dismissed", "a", request_id="r2", channel="telegram", owner=True)
        got = self.page({"until": "!!document.querySelector('.ask-card.frozen')", "ms": 5000}, {"sleep": 600}, {"eval": look},
                        {"eval": "[...document.querySelectorAll('.frozen-bar button')][1].click(), 1"}, {"sleep": 300},
                        {"eval": "document.querySelectorAll('.ask-card').length"})
        self.assertEqual(got[2]["eval"]["note"], "Question closed — your text is kept")
        self.assertEqual(got[5]["eval"], 0)                                    # "Close" — it went away
        self.ev("permission.requested", "a", request_id="r3", tool="AskUserQuestion", interactive=True, input=ask)
        self.assertTrue(self.page({"until": "!!document.querySelector('.ask-card[data-ask=r3]')", "ms": 5000})[0]["until"])
        self.ev("permission.answered", "a", request_id="r3", behavior="allow", answers={"Which option?": "B"},
                channel="telegram", owner=True)
        got = self.page({"until": "!document.querySelector('.ask-card')", "ms": 5000}, {"sleep": 600},
                        {"eval": "document.querySelectorAll('.ask-card').length"})
        self.assertEqual(got[-1]["eval"], 0)

    def test_hide_button_folds_cards_and_strip_rows_together(self):
        # owner request: with several open questions the cards and the "Waiting for you" rows get in the way of writing to
        # the session. One "Hide/Show" button (askfold.js) hides both places at once; with one question there is no button
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        ask = lambda r: self.ev("permission.requested", "a", request_id=r, tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": f"Question {r}?", "options": [{"label": "A"}, {"label": "B"}]}]})
        look = ("({btn: [...document.querySelectorAll('.strip-host .strip-row[data-k=wait] .btn')].map((b) => b.textContent).filter((x) => /[▾▸]/.test(x)), "
                "cards: document.querySelectorAll('.ask-card').length, "
                "rows: document.querySelectorAll('.strip-host .strip-row').length, "
                "note: document.querySelector('.strip-host .strip-row .t')?.textContent || ''})")
        click = "([...document.querySelectorAll('.strip-host .strip-row[data-k=wait] .btn')].find((b) => /[▾▸]/.test(b.textContent)).click(), 1)"
        ask("r1")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": "!!document.querySelector('.ask-card')", "ms": 5000},
                        {"eval": look})
        self.assertEqual(got[-1]["eval"], {"btn": [], "cards": 1, "rows": 1, "note": "Question: Question r1?"})   # one question — as before
        ask("r2")
        got = self.page({"until": "document.querySelectorAll('.ask-card').length == 2", "ms": 5000}, {"eval": look},
                        {"eval": click}, {"sleep": 300}, {"eval": look}, {"eval": click}, {"sleep": 300}, {"eval": look})
        self.assertEqual(got[1]["eval"], {"btn": ["Hide ▾"], "cards": 2, "rows": 2, "note": "Question: Question r1?"})
        self.assertEqual(got[4]["eval"], {"btn": ["Show ▸"], "cards": 0, "rows": 1, "note": "2 questions waiting"})
        self.assertEqual(got[7]["eval"], {"btn": ["Hide ▾"], "cards": 2, "rows": 2, "note": "Question: Question r1?"})
        # the button is in the first row, right after "To the question", in the flow; the second row has longer text
        # (a step)
        geo = self.page({"eval": "(() => { const rows = document.querySelectorAll('.strip-host .strip-row[data-k=wait]'), "
                                 "bs = [...rows[0].querySelectorAll('.btn')], c = document.querySelector('.strip-host .strip').getBoundingClientRect(); "
                                 "return {names: bs.map((b) => b.textContent), "
                                 "order: bs.length == 2 && bs[0].getBoundingClientRect().right <= bs[1].getBoundingClientRect().left, "
                                 "inflow: getComputedStyle(bs[1]).position != 'absolute', "
                                 "inside: bs[1].getBoundingClientRect().right <= c.right, "
                                 "second: rows[1].querySelectorAll('.btn').length, "
                                 "noscroll: document.documentElement.scrollWidth <= innerWidth}; })()"},
                        {"shot": os.path.join(self.state, "fold-inline.png"), "width": 2000, "height": 1410})[0]["eval"]
        self.assertEqual(geo, {"names": ["To the question", "Hide ▾"], "order": True, "inflow": True, "inside": True,
                               "second": 1, "noscroll": True})
        # the button's border is the same colour as the red bar of "Waiting for you"; "To the question" next to it stays
        # normal
        col = self.page({"eval": "(() => { const bs = [...document.querySelectorAll('.strip-host .strip-row[data-k=wait] .btn')], "
                                 "p = document.createElement('i'); p.style.color = 'var(--attention-line)'; document.body.append(p); "
                                 "const red = getComputedStyle(p).color; p.remove(); "
                                 "return {fold: getComputedStyle(bs[1]).borderTopColor, red, ask: getComputedStyle(bs[0]).borderTopColor, "
                                 "w: parseFloat(getComputedStyle(bs[1]).borderTopWidth) > parseFloat(getComputedStyle(bs[0]).borderTopWidth)}; })()"},
                        {"shot": os.path.join(self.state, "fold-red.png"), "width": 2000, "height": 1410})[0]["eval"]
        self.assertEqual(col["fold"], col["red"])
        self.assertNotEqual(col["ask"], col["red"])
        self.assertTrue(col["w"])

    def test_hide_button_exists_when_the_questions_are_only_shown_to_the_hub(self):
        # questions of other sessions shown to the hub (`hub question show`) are s.shown and have no "Waiting for you" rows:
        # the "Hide/Show" button must still be in the strip, otherwise the folded state cannot be undone
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.started", "hub", session_id="s-h")
