    def test_fold_button_border_follows_the_attention_line_in_every_theme(self):
        # owner request: check this button on different themes, whether all its elements are shared — the "Hide/Show"
        # border is always --attention-line (a muted --st-wait mixed with the theme's --border) (system light/dark, a plugin
        # theme with its own --destructive and without it); size, radius, thickness and background are as for "To the
        # question" next to it, and "To the question" itself does not turn red
        from unittest import mock
        cfgdir = os.path.join(self.state, "cfg")
        own = os.path.join(cfgdir, "themes")
        os.makedirs(own)
        base = {"background": "#1c1a17", "foreground": "#e0d6c0", "primary": "#e0b050"}
        with open(os.path.join(own, "amber.json"), "w") as f:
            json.dump({"name": "Amber glow", "dark": True, "colors": {**base, "destructive": "#22aa44"}}, f)
        with open(os.path.join(own, "plain.json"), "w") as f:
            json.dump({"name": "Plain paper", "dark": False, "colors": {"background": "#f4efe6", "foreground": "#2a2118", "primary": "#2060a0"}}, f)
        with open(os.path.join(own, "mono.json"), "w") as f:
            json.dump({"name": "Mono blue", "dark": True, "colors": {"background": "#14202b", "foreground": "#c4d4e2", "primary": "#6f9ec4"}}, f)
        with open(os.path.join(cfgdir, "hub.json"), "w") as f:
            json.dump({}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": os.path.join(cfgdir, "hub.json")})
        env.start()
        self.addCleanup(env.stop)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        for r in ("r1", "r2"):
            self.ev("permission.requested", "a", request_id=r, tool="AskUserQuestion", interactive=True, input={
                "questions": [{"question": f"Question {r}?", "options": [{"label": "A"}, {"label": "B"}]}]})
        look = ("(() => { const bs = [...document.querySelector('.strip-host .strip-row[data-k=wait]').querySelectorAll('.btn')], "
                "p = document.createElement('i'); p.style.color = 'var(--attention-line)'; document.body.append(p); "
                "const red = getComputedStyle(p).color; p.remove(); const [ask, fold] = bs.map((b) => { const c = getComputedStyle(b), r = b.getBoundingClientRect(); "
                "return {color: c.borderTopColor, w: c.borderTopWidth, style: c.borderTopStyle, radius: c.borderTopLeftRadius, h: r.height, "
                "bg: c.backgroundColor, fg: c.color, size: c.fontSize}; }); return {names: bs.map((b) => b.textContent), red, ask, fold}; })()")
        url = f"http://127.0.0.1:{self.port}"
        ready = {"until": "document.querySelectorAll('.strip-host .strip-row[data-k=wait] .btn').length == 2", "ms": 6000}
        got = self.page({"go": f"{url}/#/s/a"}, ready,
                        {"shot": os.path.join(self.state, "fold-dark.png"), "width": 2000, "height": 1410, "theme": "dark"}, {"eval": look},
                        {"shot": os.path.join(self.state, "fold-light.png"), "width": 2000, "height": 1410, "theme": "light"}, {"eval": look})
        runs = {"dark": got[-3]["eval"], "light": got[-1]["eval"]}
        got = self.page({"local": {"hub.settingsTab": "theme"}}, {"go": "about:blank"}, {"go": f"{url}/#/settings"}, {"wait": "Amber glow"}, {"sleep": 1500},
                        {"click": "Amber glow"}, {"sleep": 800}, {"go": f"{url}/#/s/a"}, ready, {"sleep": 300}, {"eval": look},
                        {"eval": "(getComputedStyle(document.documentElement).getPropertyValue('--destructive').trim())"})
        runs["amber"] = got[-2]["eval"]
        self.assertEqual(got[-1]["eval"], "#22aa44")
        got = self.page({"go": f"{url}/#/settings"}, {"wait": "Plain paper"}, {"sleep": 1500}, {"click": "Plain paper"}, {"sleep": 800},
                        {"go": f"{url}/#/s/a"}, ready, {"sleep": 300}, {"eval": look},
                        {"shot": os.path.join(self.state, "fold-plain.png"), "width": 2000, "height": 1410})
        runs["plain"] = got[-2]["eval"]
        got = self.page({"go": f"{url}/#/settings"}, {"wait": "Mono blue"}, {"sleep": 1500}, {"click": "Mono blue"}, {"sleep": 800},
                        {"go": f"{url}/#/s/a"}, ready, {"sleep": 300}, {"eval": look},
                        {"eval": "(() => { const p = document.createElement('i'); p.style.color = 'var(--st-wait)'; document.body.append(p); "
                                 "const c = getComputedStyle(p).color; p.remove(); return c; })()"},
                        {"shot": os.path.join(self.state, "fold-mono.png"), "width": 2000, "height": 1410})
        runs["mono"] = got[-3]["eval"]
        self.assertNotEqual(runs["mono"]["red"], got[-2]["eval"])                   # muted: not the pure --st-wait
        for name, r in runs.items():
            with self.subTest(theme=name):
                self.assertEqual(r["names"], ["To the question", "Hide ▾"])
                self.assertEqual(r["fold"]["color"], r["red"])                       # the border is the theme's --attention-line
                self.assertNotEqual(r["ask"]["color"], r["red"])                     # "To the question" is normal
                for k in ("style", "radius", "h", "bg", "fg", "size"):
                    self.assertEqual(r["fold"][k], r["ask"][k], k)                   # everything else is shared
                self.assertGreater(float(r["fold"]["w"][:-2]), float(r["ask"]["w"][:-2]))   # the border is thicker than the neighbour's
        self.assertNotEqual(runs["dark"]["red"], runs["light"]["red"])
        self.assertNotEqual(runs["amber"]["red"], runs["plain"]["red"])              # every theme has its own shade

    def test_hide_button_hides_only_questions_and_forgets_when_fewer_than_two_remain(self):
        # PR review: a permission request (it blocks the turn) is not a question, "Hide" neither hides nor counts it; a
        # folded state with two questions does not come back hidden when the next two arrive
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        ask = lambda r: self.ev("permission.requested", "a", request_id=r, tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": f"Question {r}?", "options": [{"label": "A"}, {"label": "B"}]}]})
        self.ev("permission.requested", "a", request_id="p1", tool="Bash", input={"command": "ls"})
        look = ("({btn: [...document.querySelectorAll('.strip-host .btn')].map((b) => b.textContent).filter((x) => /[▾▸]/.test(x)), "
                "asks: document.querySelectorAll('.ask-card').length, "
                "perm: document.querySelectorAll('.feed .card:not(.ask-card)').length, "
                "rows: [...document.querySelectorAll('.strip-host .strip-row')].map((r) => r.querySelector('.t')?.textContent || '')})")
        click = "([...document.querySelectorAll('.strip-host .btn')].find((b) => /[▾▸]/.test(b.textContent)).click(), 1)"
        url = f"http://127.0.0.1:{self.port}/#/s/a"
        got = self.page({"go": url}, {"until": "!!document.querySelector('.strip-host .strip-row')", "ms": 5000}, {"eval": look})
        self.assertEqual(got[-1]["eval"]["btn"], [])                  # one permission — not questions, no button
        ask("r1")
        got = self.page({"until": "document.querySelectorAll('.ask-card').length == 1", "ms": 5000}, {"eval": look})
        self.assertEqual(got[-1]["eval"]["btn"], [])                  # a question and a permission — there is one question
        ask("r2")
        got = self.page({"until": "document.querySelectorAll('.ask-card').length == 2", "ms": 5000}, {"eval": look},
                        {"eval": click}, {"sleep": 300}, {"eval": look})
        self.assertEqual(got[1]["eval"]["btn"], ["Hide ▾"])
        folded = got[-1]["eval"]
        self.assertEqual((folded["btn"], folded["asks"], folded["perm"]), (["Show ▸"], 0, 1))   # the permission stayed
        self.assertEqual(sum("Bash" in r for r in folded["rows"]), 1)
        self.ev("permission.answered", "a", request_id="r1", channel="web", owner=True)
        got = self.page({"until": "document.querySelectorAll('.ask-card').length == 1 && "
                                  "![...document.querySelectorAll('.strip-host .btn')].some((b) => /[▾▸]/.test(b.textContent))", "ms": 5000},
                        {"eval": look})
        self.assertEqual(got[-1]["eval"]["btn"], [])                  # one question left — no button and no folding
        ask("r3")
        got = self.page({"until": "document.querySelectorAll('.ask-card').length == 2", "ms": 5000}, {"sleep": 500}, {"eval": look})
        self.assertEqual(got[-1]["eval"]["btn"], ["Hide ▾"])        # a new pair — in view, the earlier "Hide" did not come back

    def test_feed_that_failed_to_load_shows_the_connection_status(self):
        # an unloaded thread feed is not an error with a "Retry" button: it is the same neutral status as the connection
        # banner ("Connecting to the hub… · in N s"); it retries by itself on a Fibonacci pause, and a tap retries now
        for n in ("a", "b"):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True)
            self.ev("session.started", n, session_id=f"s-{n}")
        self.ev("session.said", "b", text="feed line B")
        broken = ("(() => { window.__tl = 0; window.__fetch = window.fetch; window.fetch = (u, ...r) => String(u).startsWith('/api/timeline') "
                  "? (window.__tl++, Promise.resolve(new Response('oops', {status: 500}))) : window.__fetch(u, ...r); return 1; })()")
        wait = "document.querySelector('main .feed .feed-wait')"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Message to session a"}, {"eval": broken},
                        {"eval": "(location.hash = '#/s/b', 1)"}, {"until": f"!!{wait}", "ms": 5000},
                        {"eval": f"({wait}.innerText)"}, {"eval": "document.querySelector('main .feed').innerText"},
                        {"eval": "[...document.querySelectorAll('main .feed button')].some((b) => b.textContent === 'Retry')"},
                        {"eval": f"[{wait}.getAttribute('role'), {wait}.getAttribute('aria-label'), {wait}.querySelector('[data-conn-at]').getAttribute('aria-hidden')]"})
        self.assertTrue(got[4]["until"])
        self.assertIn("Connecting to the hub", got[5]["eval"])
        self.assertNotIn("Couldn't load the feed", got[6]["eval"])
        self.assertFalse(got[7]["eval"])                          # no "Retry" button
        self.assertEqual(got[8]["eval"], ["button", "Retry", "true"])   # the name stays while the seconds count down
        got = self.page({"sleep": 2500}, {"eval": "window.__tl"})  # pauses 1, 1, 2 s: a few tries, not a 300 ms loop
        self.assertTrue(2 <= got[-1]["eval"] <= 4, got[-1]["eval"])
        got = self.page({"eval": "(window.fetch = window.__fetch, 1)"}, {"eval": f"{wait}.click(), 1"},
                        {"until": "document.querySelector('main .feed').innerText.includes('feed line B')", "ms": 5000},
                        {"eval": f"!!{wait}"})
        self.assertEqual((got[2]["until"], got[3]["eval"]), (True, False))

