    def test_a_single_question_is_answered_by_a_tap_without_radio_or_button(self):
        # owner decision: tapping an answer is enough; "Answer" is only for the owner's own answer
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": "Which option?", "options": [{"label": "A"}, {"label": "B"}]}]})
        look = ("(() => { const c = document.querySelector('.ask-card'); const r = c.querySelector('input[type=radio]'); "
                "const ok = c.querySelector('.btns button[type=submit]'); return [getComputedStyle(r).opacity, !!ok && !ok.hidden, "
                "c.querySelector('.other-row button').hidden]; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "The session is waiting for your answer"},
                        {"eval": look},
                        {"eval": "document.querySelector('.ask-card .opt.pick:last-of-type').click(), 1"}, {"sleep": 800})
        self.assertEqual(got[2]["eval"], ["0", False, True])   # no radio circle, no general "Answer", and for the field it is hidden
        sent = [e["data"] for e in self.spooled() if e["type"] == "permission.answered"]
        self.assertEqual([d["answers"] for d in sent], [{"Which option?": "B"}])

    def test_several_questions_wait_for_the_answer_button(self):
        # owner request: a tap sends only a card with a single question; with several, the last tap sent everything at
        # once, and it was no longer possible to change your mind on the top question
        self.ask_two_questions()
        click = "document.querySelector('.ask-card input[value=\"%s\"]').click(), 1"
        look = "(() => { const ok = document.querySelector('.ask-card .btns button[type=submit]'); return !!ok && !ok.hidden; })()"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "The session is waiting for your answer"},
                        {"eval": click % "Browser 1"}, {"eval": click % "Yes"}, {"sleep": 600}, {"eval": look})
        self.assertTrue(got[-1]["eval"])                    # the "Answer" button is visible
        self.assertFalse([e for e in self.spooled() if e["type"] == "permission.answered"])   # the choice did not go out by itself
        self.page({"eval": "document.querySelector('.ask-card .btns button[type=submit]').click(), 1"}, {"sleep": 800})
        sent = [e["data"] for e in self.spooled() if e["type"] == "permission.answered"]
        self.assertEqual([d["answers"] for d in sent], [{"Which Chrome?": "Browser 1", "And the tests?": "Yes"}])

