    def aim_and_send(self, nth, text, then="1"):
        """Press "reply" on the nth open question card, run `then`, type text into the session's field and send it."""
        say = ("(() => { %s; const m = document.querySelector('#msg'); "
               "m.value = %s; m.dispatchEvent(new Event('input', {bubbles: true})); m.form.requestSubmit(); return 1; })()")
        return self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": "document.querySelectorAll('.ask-card .card-aim').length > 0"},
                         {"eval": "document.querySelectorAll('.ask-card .card-aim')[%d].click(); 1" % nth}, {"sleep": 300},
                         {"eval": "[[...document.querySelectorAll('.ask-card')].map((c) => c.classList.contains('aimed')), "
                                  "document.querySelector('.reply-chip')?.textContent]"},
                         {"eval": then + "; 1"}, {"sleep": 300},
                         {"eval": "document.querySelector('.reply-chip')?.textContent"},
                         {"eval": say % ("1", json.dumps(text))}, {"sleep": 900},
                         {"eval": "[document.querySelector('.reply-chip')?.isConnected || false, document.querySelector('#msg').value, "
                                  "[...document.querySelectorAll('.ask-card')].map((c) => c.classList.contains('sent'))]"})

    def two_cards(self):
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        for rid, head in (("r1", "Release"), ("r2", "Runs")):
            self.ev("permission.requested", "a", request_id=rid, tool="AskUserQuestion", interactive=True, input={
                "questions": [{"question": f"What about {head}?", "header": head, "options": [{"label": "A"}, {"label": "B"}]}]})

    def test_reply_button_of_a_card_sends_the_comment_from_the_message_box_as_that_cards_answer(self):
        # owner request: with several cards open, pick one and write the comment to it from the message box (voice and
        # all); the words used to go to the session as a plain message, and the card stayed open
        self.two_cards()
        got = self.aim_and_send(1, "later, after the tests")
        self.assertEqual(got[4]["eval"][0], [False, True])   # the picked card is the marked one
        self.assertIn("Runs", got[4]["eval"][1])   # and the bar over the field names it
        spooled = self.spooled()
        sent = [e["data"] for e in spooled if e["type"] == "permission.answered"]
        self.assertEqual([(d["request_id"], d["answers"]) for d in sent], [("r2", {"What about Runs?": "later, after the tests"})])
        self.assertFalse([e for e in spooled if e["type"] == "message.received"])   # not a message to the session as well
        # the answered card collapsed, the field is empty and aimed at nothing
        self.assertEqual(got[-1]["eval"], [False, "", [False, True]])

