    SAY = ("(() => { const m = document.querySelector('#msg'); m.value = %s; m.dispatchEvent(new Event('input', {bubbles: true})); "
           "m.form.requestSubmit(); return 1; })()")

    def test_words_aimed_at_a_card_answered_elsewhere_do_not_go_as_a_plain_message(self):
        # the aimed card was answered in another place (Telegram) meanwhile: the aim used to vanish silently and the words
        # went as a plain message, which the core took for the answer to the other card still open
        self.two_cards()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": "document.querySelectorAll('.ask-card .card-aim').length > 1"},
                        {"eval": "document.querySelectorAll('.ask-card .card-aim')[1].click(); 1"}, {"sleep": 300})
        self.assertTrue(got[1]["until"], got)
        self.ev("permission.answered", "a", request_id="r2", behavior="allow", answers={"What about Runs?": "A"},
                channel="telegram", owner=True)
        got = self.page({"until": "document.querySelectorAll('.ask-card').length === 1", "ms": 8000},
                        {"eval": "document.querySelector('.reply-chip')?.textContent || null"},
                        {"eval": self.SAY % json.dumps("later, after the tests")}, {"sleep": 900},
                        {"eval": "[document.querySelector('#msg').value, document.querySelector('#msg-err').textContent]"})
        self.assertTrue(got[0]["until"], got)
        self.assertIn("already closed", got[1]["eval"])
        self.assertEqual(got[4]["eval"][0], "later, after the tests")   # the words stay in the field, the reason under it
        self.assertIn("already closed", got[4]["eval"][1])
        self.assertFalse([e for e in self.spooled() if e["type"] in ("message.received", "permission.answered")])
        # said once: the next Enter is the owner's word to send them as a message
        self.page({"eval": "(document.querySelector('#msg').form.requestSubmit(), 1)"}, {"sleep": 900})
        self.assertEqual([e["data"]["text"] for e in self.spooled() if e["type"] == "message.received"], ["later, after the tests"])

    def test_words_of_a_comment_the_core_refuses_come_back_into_the_message_box(self):
        # the field is emptied when the comment goes; a refusal that comes later (the card already answered) put the reason
        # on the card, and the words from the field were lost
        self.two_cards()
        with mock.patch.object(self.web, "answer", return_value=(409, "Session no longer waits")):
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": "document.querySelectorAll('.ask-card .card-aim').length > 1"},
                            {"eval": "document.querySelectorAll('.ask-card .card-aim')[1].click(); 1"}, {"sleep": 300},
                            {"eval": self.SAY % json.dumps("later, after the tests")},
                            {"until": "document.querySelector('#msg').value", "ms": 5000},
                            {"eval": "[document.querySelector('#msg-err').textContent, document.querySelector('.reply-chip')?.textContent]"})
        self.assertEqual(got[5]["until"], "later, after the tests")
        self.assertIn("Session no longer waits", got[6]["eval"][0])
        self.assertIn("Runs", got[6]["eval"][1])   # aimed at the same card again: Enter tries once more

