    def test_esc_and_the_cross_close_a_question_without_an_answer(self):
        # owner request: Esc does not close the Ask panel, and it needs a cross at its top right
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": "Which option?", "options": [{"label": "A"}, {"label": "B"}]}]})
        box = "(() => { const c = document.querySelector('.card-x'), r = c.getBoundingClientRect(), " \
              "f = c.closest('.card').getBoundingClientRect(); return [c.getAttribute('aria-label'), " \
              "Math.round(f.right - r.right), Math.round(r.top - f.top), !!c.querySelector('svg use[href$=\"#i-close\"]')]; })()"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Esc: close the question"},
                        {"eval": box},
                        {"eval": "document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape', bubbles: true}))"},
                        {"sleep": 400})
        label, right, top, svg = got[2]["eval"]
        self.assertEqual(label, "Close the question without answering")
        self.assertTrue(svg)                                                    # an icon from the page's set
        self.assertLess(right, 16)                                              # top right
        self.assertLess(top, 16)
        evs = self.spooled()
        self.assertEqual([(e["type"], e["data"]["request_id"]) for e in evs if e["type"] == "question.dismissed"],
                         [("question.dismissed", "r1")])
        self.assertFalse([e for e in evs if e["type"] == "session.interrupt_requested"])   # Esc did not stop the turn
        # the cross — same
        self.ev("question.dismissed", "a", request_id="r1", channel="web", owner=True)   # the core removed the first one
        self.ev("permission.requested", "a", request_id="r2", tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": "Another question?", "options": [{"label": "Yes"}, {"label": "No"}]}]})
        self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Another question?"},
                  {"eval": "document.querySelector('.card-x').click()"}, {"sleep": 400})
        self.assertEqual([e["data"]["request_id"] for e in self.spooled() if e["type"] == "question.dismissed"], ["r2"])

    def test_the_list_with_sleeping_sessions_draws_without_errors(self):
        # commit ec5be4a: `.map(sessionRow)` passed the index and the array as the third argument — shortName failed on
        # under.replace, the list was not drawn, and messages from the page were not sent
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.started", "hub", session_id="s-h")
        self.ev("session.requested", "old-task", session_id="s-o", cwd="/w", executor=True, raised_by="hub",
                about="old task")
        self.ev("session.started", "old-task", session_id="s-o")
        self.ev("session.close_requested", "old-task", retire=True)
        self.ev("session.exited", "old-task", why="sleep")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"sleep": 1500}, {"errors": 2500},
                        {"eval": "[...document.querySelectorAll('details.resting .srow .nm')].map(n => n.textContent)"})
        self.assertEqual(got[2]["errors"], [])
        self.assertEqual(got[3]["eval"], ["old-task"])                           # asleep — in "Asleep or failed"

    def test_the_session_list_keeps_its_scroll_when_it_redraws(self):
        # colleague feedback: the list in the left sidebar jumps when some agent updates... you scroll to the very bottom and
        # it sharply scrolls itself up. The list was rebuilt: first only the hub (the list briefly shorter than the window —
        # the browser clipped the scroll to zero), then the groups. A redraw now keeps the scroll position
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.started", "hub", session_id="s-h")
        for i in range(60):
            self.ev("session.requested", f"w{i:02d}", session_id=f"s-{i}", cwd="/w")
            self.ev("session.started", f"w{i:02d}", session_id=f"s-{i}")
        bottom = "(() => { const l = document.getElementById('list'); l.scrollTop = l.scrollHeight; return l.scrollTop; })()"
        # a plugin or row code that reads layout in the middle of a redraw (offsetHeight, getBoundingClientRect) forces the
        # browser to lay out the list while it holds only the hub — that is what jumped; here layout is read on every append
        redraw = ("(() => { const {render} = window.__m, l = document.getElementById('list'), orig = Element.prototype.append; "
                  "Element.prototype.append = function (...a) { void l.scrollHeight; return orig.apply(this, a); }; "
                  "try { render(); } finally { Element.prototype.append = orig; } return l.scrollTop; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"sleep": 1500}, {"eval": self.PREP}, {"sleep": 300},
                        {"eval": bottom}, {"eval": redraw})
        at, after = got[-2]["eval"], got[-1]["eval"]
        self.assertGreater(at, 200, got)
        self.assertEqual(after, at, got)

    def test_the_session_list_keeps_its_scroll_past_a_footer_plugin(self):
        # sidebar.footer plugins are drawn after the list and may reorder its rows: one that takes the rows out and puts
        # them back in another order, reading layout in between, makes the list briefly short and the browser clips the
        # scroll; the list scroll was restored before the footer
        from unittest import mock
        path = os.path.join(self.state, "plug-foot")
        os.makedirs(path)
        with open(os.path.join(path, "hub-plugin.json"), "w") as f:
            json.dump({"name": "foot", "description": "footer", "why": "w", "web": "main.js", "hub": "^1.28"}, f)
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"extensions": {"foot": {"path": path, "web": "main.js"}}}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        with open(os.path.join(path, "main.js"), "w") as f:
            f.write("export default function register(hub) {\n"
                    "  hub.addSlot('sidebar.footer', { id: 'foot', render(root) {\n"
                    "    root.textContent = 'footer';\n"
                    "    if (!window.__reorder) return;\n"
                    "    const ul = [...document.querySelectorAll('#list ul')].sort((a, b) => b.children.length - a.children.length)[0];\n"
                    "    const rows = [...ul.children];\n"
                    "    ul.replaceChildren(); void ul.offsetHeight;\n"
                    "    ul.append(...rows.reverse()); } });\n}\n")
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.started", "hub", session_id="s-h")
        for i in range(60):
            self.ev("session.requested", f"w{i:02d}", session_id=f"s-{i}", cwd="/w")
            self.ev("session.started", f"w{i:02d}", session_id=f"s-{i}")
        bottom = "(() => { const l = document.getElementById('list'); l.scrollTop = l.scrollHeight; return l.scrollTop; })()"
        redraw = ("(() => { window.__reorder = true; try { window.__m.render(); } finally { window.__reorder = false; } "
                  "return document.getElementById('list').scrollTop; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"errors": 1500},
                        {"until": "document.getElementById('aside-foot').textContent.includes('footer')", "ms": 8000},
                        {"eval": self.PREP}, {"sleep": 300}, {"eval": bottom}, {"eval": redraw})
        self.assertEqual(got[1]["errors"], [])
        at, after = got[-2]["eval"], got[-1]["eval"]
        self.assertGreater(at, 200, got)
        self.assertEqual(after, at, got)

    def test_session_head_is_compact(self):
        # owner complaint: where does such a wild design come from, why is so much space taken at the top? — the board, two
        # background agents and the buttons took a third of the screen: buttons go in the top row with the name, board and
        # background in one line
        import time as _t
        from unittest import mock
        root = os.path.join(self.state, "directions")
        d = os.path.join(root, "rex", "backlog", "tasks")
        os.makedirs(d)
        with open(os.path.join(d, "task-1.md"), "w") as f:
            f.write("---\nid: task-1\ntitle: 'Slice 1: scouting, is the move realistic and where to start'\nstatus: In Progress\n---\n")
        env = mock.patch.dict(os.environ, {"HUB_DIRECTIONS": root})
        env.start()
        self.addCleanup(env.stop)
        self.ev("session.requested", "rex", session_id="s-r", cwd="/w", channel="cli", owner=True, tools=[])
        self.ev("session.started", "rex", session_id="s-r")
        self.ev("turn.started", "rex", marker=None, prompt_head="x")
        for i, title in enumerate(("Precedents recomp on ARM64", "Graphics and CPU perf")):
            self.j.append("session.background", "rex", {"id": f"a{i}", "kind": "agent", "title": title}, ts=_t.time() - 60)
        measure = ("(() => { const h = document.querySelector('main > .head'), r = (q) => h.querySelector(q)?.getBoundingClientRect(); "
                   "const t = r('h2'), seg = r('.seg'), m = r('.head-meta'); "
                   "return [Math.abs(seg.top - t.top) < 12, m && m.height < 30, Math.round(h.getBoundingClientRect().height), "
                   "document.documentElement.scrollWidth, h.querySelectorAll('.head-meta').length, "
                   "(h.querySelector('.head-meta')?.title || '').includes('Graphics and CPU perf')]; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/rex"}, {"wait": "Board:"}, {"sleep": 500},
                        {"shot": os.path.join(tempfile.gettempdir(), "e2e-head.png"), "width": 1300, "height": 800}, {"eval": measure},
                        {"shot": os.path.join(tempfile.gettempdir(), "e2e-head-phone.png"), "width": 420, "height": 800}, {"eval": measure})
        wide, phone = got[4]["eval"], got[6]["eval"]
        self.assertEqual(wide[:2], [True, True], wide)       # buttons in the row with the name; board and background in one line
        self.assertLess(wide[2], 130, wide)                  # the header is short (it was ~240 px on this data set)
        self.assertEqual((wide[4], wide[5]), (1, True))      # one line; what did not fit is in the hint
        self.assertLessEqual(phone[3], 420)                  # on a phone — no horizontal scroll
        self.assertLess(phone[2], 800 * 0.4, phone)          # and under 40% of the screen

    def helpers_stand(self):
        """Sessions whose own helper agents run in the background (18.11: a hub's three ran for half an hour and the owner
        took the work for stopped): tiles — idle, three helpers on one model; geo — working, a helper with no model named
        and a command; ops — idle, a helper on opus and a command."""
        import time as _t
        for n in ("tiles", "geo", "ops"):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True, tools=[])
            self.ev("session.started", n, session_id=f"s-{n}")
            self.ev("turn.started", n, marker=None, prompt_head="go")
        for i, title in enumerate(("/root/review_security", "/root/review_perf", "/root/review_ops")):
            self.j.append("session.background", "tiles", {"id": f"ag{i}", "kind": "agent", "title": title,
                                                         "model": "gpt-6.2-astra"}, ts=_t.time() - 300 + i)
        self.j.append("session.background", "geo", {"id": "ag9", "kind": "agent", "title": "Map the geocoder"}, ts=_t.time() - 60)
        self.j.append("session.background", "geo", {"id": "b9", "kind": "bash", "title": "tools/test.py"}, ts=_t.time() - 50)
        self.j.append("session.background", "ops", {"id": "ag8", "kind": "agent", "title": "Check the logs",
                                                    "model": "opus"}, ts=_t.time() - 60)
        self.j.append("session.background", "ops", {"id": "b8", "kind": "bash", "title": "Wait"}, ts=_t.time() - 50)
        for n in ("tiles", "ops"):
            self.ev("turn.stopped", n)
        self.settle()

    ROW_CAPTION = ("((n) => { const r = [...document.querySelectorAll('#list .srow')].find((x) => [...x.querySelector('.nm').childNodes]"
                   ".filter((c) => c.nodeType === 3).map((c) => c.nodeValue.trim()).filter(Boolean).pop() === n); "
                   "return r ? [r.querySelector('.lb').textContent, r.title] : 'none'; })")   # the tooltip is the row's

    def test_a_sessions_own_helper_agents_show_in_its_row_with_their_model(self):
        self.helpers_stand()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"until": "document.querySelectorAll('#list .srow').length >= 3"},
                        {"sleep": 400}, *[{"eval": self.ROW_CAPTION + f"('{n}')"} for n in ("tiles", "geo", "ops")])
        tiles, geo, ops = (g["eval"] for g in got[-3:])
        self.assertRegex(tiles[0], r"^3 helpers · gpt-6\.2-astra · \d+ min( \d+ s)?$")   # idle: the count, the model and how long, not a title
        self.assertIn("/root/review_perf · gpt-6.2-astra · ", tiles[1])         # the tooltip names each with its model
        self.assertRegex(geo[0], r" · 1 helper · in background 1$")            # working: no model named — the count alone
        self.assertTrue(ops[0].startswith("1 helper · opus · in background: Wait · "), ops)   # the command keeps its caption

    def test_a_file_sent_to_the_owner_is_shown_in_the_feed(self):
        # owner request: check that screenshots can be forwarded to the page: hub send-file went only to Telegram, and the
        # feed had one line with the command. An image is shown as an image on the page (/api/file: "Files" does not serve
        # foreign folders over the tailnet), a document as a link
        from urllib.parse import quote
        shot = os.path.join(self.state, "shots", "sent-shot.png")   # real: the page serves it itself
        os.makedirs(os.path.dirname(shot), exist_ok=True)
        import base64
        with open(shot, "wb") as f:
            f.write(base64.b64decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8DwHwAFBQIAX8jx0gAAAABJRU5ErkJggg=="))
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        self.ev("owner.file", None, path=shot, caption="a map, **looks like this**",
                channel="session", owner=False, sender="a")
        self.ev("owner.file", None, path="/w/report.md", caption=None, channel="session", owner=False, sender="a")
        # a copy in attachments (hub send-file): the document goes as the source in "Files", where the comments on it live
        self.ev("owner.file", None, path=os.path.join(self.state, "attachments", "x1", "plan.md"), source="/w/plan.md",
                caption=None, channel="session", owner=False, sender="a")
        files = ("JSON.stringify([...document.querySelectorAll('.feed .sent-file')].map(f => [f.innerText, "
                 "f.querySelector('img')?.getAttribute('src') || '', f.querySelector('a')?.getAttribute('href') || '']))")
        for mode in ("full", "compact"):     # in "Brief" the sent item is visible too: it is a milestone for the owner
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"},
                            {"eval": f"localStorage.setItem('hub.feed', '{mode}'); location.reload(); 1"},
                            {"until": "document.querySelectorAll('.feed .sent-file').length === 3"}, {"eval": files},
                            {"errors": 300})
            self.assertEqual(got[-1]["errors"], [])
            (shot_text, img, href), (doc_text, no_img, doc_href), (_, _, kept_href) = json.loads(got[-2]["eval"])
            self.assertIn("/open?path=%2Fw%2Fplan.md", kept_href)
            self.assertIn("&alt=" + quote(os.path.join(self.state, "attachments", "x1", "plan.md"), safe=""), kept_href)
            self.assertIn("looks like this", shot_text)
            self.assertIn("/api/file?path=" + quote(shot, safe=""), href)
            self.assertRegex(img, "^" + re.escape("/api/file?path=" + quote(shot, safe="")) + r"&v=\d+$")
            self.assertIn("report.md", doc_text)
            self.assertEqual(no_img, "")
            # a document goes to the "Files" viewer (markdown is rendered there), not as raw text (owner complaint: why were
            # md files sent as raw?)
            self.assertIn("/open?path=%2Fw%2Freport.md", doc_href)
            self.assertNotIn("raw?", doc_href)

    def test_a_video_sent_to_the_owner_plays_in_the_feed(self):
        # a video sent with hub send-file showed a card without a player and a 404 on the page. Now there is a player, and a
        # feed redraw (a new session event) does not replace it with a new node: viewing and seeking are not interrupted
        from urllib.parse import quote
        clip = os.path.join(self.state, "clips", "demo.mp4")
        os.makedirs(os.path.dirname(clip), exist_ok=True)
        with open(clip, "wb") as f:
            f.write(b"\x00\x00\x00\x18ftypmp42" + b"0" * 64)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        self.ev("owner.file", None, path=clip, caption="screen recording", channel="session", owner=False, sender="a")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"},
                        {"until": "document.querySelector('.feed .sent-file video')"},
                        {"eval": "const v = document.querySelector('.feed .sent-file video'); window.__v = v; "
                                 "JSON.stringify([v.getAttribute('src'), v.controls, "
                                 "document.querySelector('.feed .sent-file').innerText.includes('screen recording')])"})
