    def reactions_module(self, on):
        """The "Reactions and folding of the answered" module — the reactions.enabled key in hub.json (off by default)."""
        cfg = self.web.config
        self.web.config = lambda: {**cfg(), "reactions": {"enabled": on}}

    def fold_probe(self, on, fold=None):
        """Two session replies with an owner message between them: what the page did in Brief with the earlier and the fresh one.
        fold — the "Fold the answered" checkbox in this browser (None — untouched)."""
        self.reactions_module(on)
        old = "Old long report. " + "Detail after detail. " * 20
        new = "Fresh long report. " + "Detail after detail. " * 20
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None)
        self.ev("session.said", "a", text=old)
        self.ev("turn.stopped", "a")
        e = self.j.append("message.received", None, {"to": "a", "text": "got it, go on", "channel": "web", "owner": True})
        self.ev("turn.started", "a", marker=f"m{e['seq']}", prompt_head="got it")
        self.ev("session.said", "a", text=new)
        self.ev("turn.stopped", "a")
        probe = ("(() => { const o = [...document.querySelectorAll('.out')]; "
                 "const f = (t) => o.find((x) => x.textContent.includes(t)); "
                 "const a = f('Old long'), b = f('Fresh long'); "
                 "return {old: a && a.classList.contains('resolved') && !!a.querySelector('.clamp-2'), "
                 "fresh: b && !b.classList.contains('resolved') && !b.querySelector('.clamp-2')}; })()")
        brief = {} if fold is None else {"brief": {"resolved": fold}}
        # both replies drawn, not a fixed pause: under load (Windows, 4 cores) 1.5 s was not enough — an empty probe
        drawn = ("[...document.querySelectorAll('.out')].filter((x) => x.textContent.includes('long report')).length"
                 " === 2")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "compact", **brief},
                        {"until": drawn, "ms": 15000}, {"sleep": 300}, {"eval": probe})
        self.assertTrue(got[1]["until"], got)
        return got[-1].get("eval")

    def test_answered_replies_fold_to_grey_two_lines_and_the_last_turn_stays_open(self):
        """The answered reply becomes short grey folded text, so there is no need to guess whether the owner has replied.
        A session reply after which the owner has already written is two lines and "more"; the last turn is open in full.
        Later owner decision: folding is the Brief checkbox "Fold the answered" and does not depend on the Reactions module."""
        self.assertEqual(self.fold_probe(False, fold=True), {"old": True, "fresh": True})

    def test_replies_are_not_folded_by_default(self):
        """The feed look changes for all hubs — without the checkbox everything is as before, and with the reactions module too if the checkbox is cleared."""
        self.assertEqual(self.fold_probe(False), {"old": False, "fresh": True})

    def test_a_cleared_fold_box_keeps_replies_open_with_the_reactions_module(self):
        self.assertEqual(self.fold_probe(True, fold=False), {"old": False, "fresh": True})

    def test_the_reactions_module_does_not_fold_the_answered(self):
        """An answered reply the owner is still reading neither folds nor grays when the next message goes: folding is the
        "Fold the answered" checkbox alone, off until checked — the "Reactions" module does not turn it on."""
        self.assertEqual(self.fold_probe(True), {"old": False, "fresh": True})

    def test_the_fold_box_stays_off_with_the_reactions_module(self):
        """A "Fold the answered" checkbox that was not touched is off, the Reactions module turned on or off."""
        self.reactions_module(False)
        box = ("(() => { const l = [...document.querySelectorAll('label.opt')].find((x) => x.textContent.includes("
               "'Fold the answered')); return l && l.querySelector('input').checked; })()")
        on = "(() => { const {S, render} = window.__m; S.snap = {...S.snap, features: ['reactions']}; render(); return 1; })()"
        got = self.page({"local": {"hub.settingsTab": "theme"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"wait": "Fold the answered"}, {"eval": box}, {"eval": self.PREP}, {"sleep": 300}, {"eval": on}, {"sleep": 300}, {"eval": box})
        self.assertEqual((got[3]["eval"], got[-1]["eval"]), (False, False), got)

    @cut.needs("gateway")
    def test_gateway_switch_in_accounts_settings(self):
        """"Settings → Accounts": the accounts gateway toggle with an explanation; turning it on sets the gateway.enabled key through
        the settings allowlist; a failed self-check shows the status line in the trouble colour."""
        from modules.gateway import gateway as gw
        open_tab = ({"local": {"hub.settingsTab": "accounts"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                    {"wait": "Account gateway"})
        box = ("(() => { const g = document.querySelector('.ac-gw'); const i = g && g.querySelector('input'); "
               "const st = g && g.querySelector('.ac-gw-state'); return g && [i.checked, st.dataset.level, st.textContent]; })()")
        kind = "((document.querySelector('.ac-gw-note') || {dataset: {}}).dataset.kind || '')"
        note = "((document.querySelector('.ac-gw-note') || {}).textContent || '')"
        # Settings is drawn anew with every snapshot: the note and the switch keep what the click made them (a snapshot
        # that came while the request ran took "…" and then the answer with it — red on a loaded machine). The server
        # holds the request until the page has a snapshot that came meanwhile
        from modules.web import server as web_server
        real, release = web_server.Web.settings_set, threading.Event()

        def held(web, key, value):
            self.ev("session.requested", "maps", session_id="s-maps", cwd="/w")   # any event: a new snapshot
            release.wait(30)
            return real(web, key, value)
        redrawn = "import('/static/js/state.js').then((m) => { m.render(); window.__drawn = 1; }), 1"
        self.addCleanup(release.set)   # a failed step does not leave the server's thread waiting
        with mock.patch.object(web_server.Web, "settings_set", held):
            got = self.page(*open_tab, {"eval": box},
                            {"eval": "import('/static/js/state.js').then((m) => { window.__m = m; }), 1"}, {"until": "!!window.__m"},
                            {"eval": "document.querySelector('.ac-gw input').click(); 1"},
                            {"until": f"window.__m.S.snap.sessions.some((s) => s.name === 'maps') && !!document.querySelector('.ac-gw') && {note} === '…'",
                             "ms": 10000},
                            {"eval": "[document.querySelector('.ac-gw input').checked, document.querySelector('.ac-gw input').disabled]"})
            release.set()
            done = self.page({"until": f"{kind} === 'starting'", "ms": 10000}, {"eval": redrawn}, {"until": "!!window.__drawn"},
                             {"eval": kind})
        self.assertEqual(got[3]["eval"][:2], [False, "off"], got)
        self.assertTrue(got[7]["until"], got)                  # "…" outlived the snapshot that came meanwhile
        self.assertEqual(got[8]["eval"], [True, True], got)    # clicked on, waiting for the answer
        self.assertTrue(done[0]["until"], done)                # a hook for themes: what the note says
        self.assertEqual(done[-1]["eval"], "starting", done)   # and a redraw keeps it
        sets = [e["data"] for e in self.spooled() if e["type"] == "settings.changed"]
        self.assertEqual([(d["what"], d["new"]) for d in sets], [("gateway.enabled", True)])
        cfg = self.web.config
        self.web.config = lambda: {**cfg(), "gateway": {"enabled": True}}
        gw.write(self.state, "status.json", {"ts": 1, "serving": False, "probe": {"ok": False, "why": "no search"}})
        # the same address, only the hash: reload. Settings changed without a journal event: the stream could have served a
        # shared build no older than STREAM_GAP (modules/web/server.py, stream_view) — a fresh one follows
        got = self.page({"go": "about:blank"}, *open_tab, {"until": f"(() => {{ const v = {box}; return !!v && v[0]; }})()",
                                                          "ms": 5000}, {"eval": box})
        self.assertTrue(got[4]["until"], got)
        self.assertEqual(got[5]["eval"][:2], [True, "bad"], got)
        self.assertIn("no search", got[5]["eval"][2])   # the probe's reason, in the module's words
        # turning it off asks for a second click, and a snapshot in between keeps the question (it used to forget it)
        got = self.page({"eval": "document.querySelector('.ac-gw input').click(); 1"}, {"until": f"{kind} === 'sure'", "ms": 5000},
                        {"eval": "window.__drawn = 0; " + redrawn}, {"until": "!!window.__drawn"},
                        {"eval": f"[{kind}, document.querySelector('.ac-gw input').checked]"},
                        {"eval": "document.querySelector('.ac-gw input').click(); 1"},
                        {"until": f"{kind} !== 'sure' && !document.querySelector('.ac-gw input').disabled", "ms": 10000})
        self.assertTrue(got[1]["until"], got)
        self.assertEqual(got[4]["eval"], ["sure", True], got)
        self.assertTrue(got[-1]["until"], got)
        sets = [e["data"] for e in self.spooled() if e["type"] == "settings.changed"]
        self.assertEqual([(d["what"], d["new"]) for d in sets][-1], ("gateway.enabled", False))

    def test_a_removed_or_command_message_does_not_fold_the_reply(self):
        """Folding is decided by the core — a turn that took the owner's message (reactions.taken): one removed from the queue does not fold the reply."""
        self.reactions_module(False)
        old = "Old long report. " + "Detail after detail. " * 20
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None)
        self.ev("session.said", "a", text=old)
        e = self.j.append("message.received", None, {"to": "a", "text": "wrong one, will remove", "channel": "web", "owner": True})
        self.ev("message.cancel", f"m{e['seq']}", channel="web", owner=True)
        self.ev("turn.stopped", "a")
        probe = ("(() => { const a = [...document.querySelectorAll('.out')].find((x) => x.textContent.includes('Old long')); "
                 "return a && !a.classList.contains('resolved'); })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "compact", "brief": {"resolved": True}}, {"wait": "Old long"},
                        {"sleep": 500}, {"eval": probe})
        self.assertTrue(got[-1]["eval"], got)

    def reacted_turn(self):
        """A turn on an owner message with a reply: the core sets 👀, then 👍."""
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a")
        e = self.j.append("message.received", None, {"to": "a", "text": "make a report", "channel": "web", "owner": True})
        self.asked = f"m{e['seq']}"
        self.ev("turn.started", "a", marker=f"m{e['seq']}", prompt_head="make")
        said = self.j.append("session.said", "a", {"text": "Report ready."})
        self.ev("turn.result", "a", text="Report ready.")
        self.ev("turn.stopped", "a")
        return said

    GRID = ("(() => { const b = [...document.querySelectorAll('.row.out > .b')].find((x) => x.querySelector(':scope > .byline')); "
            "return b && getComputedStyle(b).gridTemplateColumns.trim().split(/\\s+/).length; })()")

    def test_without_the_module_the_feed_has_no_reactions(self):
        """The module is off (default): no badge on the owner's own message, no "Reactions" under the reply, and the reply row grid has
        three columns, as without the module ("Reply" does not shift)."""
        self.reacted_turn()
        probe = ("(() => ({chips: document.querySelectorAll('.react-chip, .reactions').length, "
                 "add: [...document.querySelectorAll('button')].filter((b) => b.textContent === 'Reaction').length, "
                 "reply: [...document.querySelectorAll('button')].filter((b) => b.textContent === 'Reply').length}))()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Report ready"}, {"sleep": 300},
                        {"eval": probe}, {"eval": self.GRID})
        self.assertEqual(got[-2]["eval"], {"chips": 0, "add": 0, "reply": 2}, got)   # the session's reply and the owner's own message
        self.assertEqual(got[-1]["eval"], 3, got)

    def test_receipts_checkbox_hides_the_core_receipts_under_the_own_message_only(self):
        """The "Core receipts" view checkbox (on by default): off, the core's 👀/👍 under the owner's own message are not drawn; a
        reaction the owner put on a session's reply stays."""
        self.reactions_module(True)
        said = self.reacted_turn()
        self.ev("message.reacted", None, target=str(said["seq"]), emoji="👍", session="a", quote="Report ready.",
                channel="web", owner=True)
        chips = "(() => [...document.querySelectorAll('.react-chip')].map((x) => x.closest('.row').className + ' ' + x.textContent))()"
        url = f"http://127.0.0.1:{self.port}/#/s/a"
        on = self.page({"go": url}, {"wait": "Report ready"}, {"sleep": 300}, {"eval": chips})
        self.assertEqual(on[-1]["eval"], ["row me mine 👍", "row out 👍"], on)   # the receipt on his message, his reaction on the reply
        off = self.page({"go": "about:blank"}, {"go": url, "brief": {"receipts": False}}, {"wait": "Report ready"}, {"sleep": 300}, {"eval": chips})
        self.assertEqual(off[-1]["eval"], ["row out 👍"], off)                  # only the reply's one

    def test_reactions_core_marks_the_own_message_and_the_owner_reacts_to_a_reply(self):
        """Emoji reactions as in Telegram: 👀 "took it" → 👍 "answered" on the owner's own message; a session reply carries one
        reaction, which can be changed. Needs the "Reactions and folding of the answered" module. The picker closes on a
        second click; the chosen reaction is aria-pressed."""
        self.reactions_module(True)
        said = self.reacted_turn()
        chips = "(() => [...document.querySelectorAll('.react-chip')].map((x) => x.textContent))()"
        picks = "(() => document.querySelectorAll('.react-pick').length)()"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Report ready"}, {"sleep": 300},
                        {"eval": chips}, {"eval": self.GRID},
                        {"click": "Reaction"}, {"sleep": 200}, {"eval": picks},
                        {"click": "Reaction"}, {"sleep": 200}, {"eval": picks},
                        {"click": "Reaction"}, {"sleep": 200},
                        {"eval": "(() => { const b = [...document.querySelectorAll('.react-pick')].find((x) => x.textContent === '👍'); "
                                 "b.click(); return b.getAttribute('aria-pressed'); })()"},
                        {"sleep": 500})
        self.assertEqual(got[3]["eval"], ["👍"], got)            # on the owner's own message: answered
        self.assertEqual(got[4]["eval"], 4, got)                 # "Reaction" as the fourth column
        self.assertEqual((got[7]["eval"], got[10]["eval"]), (5, 0), got)   # opened and closed
        self.assertEqual(got[13]["eval"], "false", got)
        (ev,) = [e for e in self.spooled() if e["type"] == "message.reacted"]   # the owner put 👍 on the session's reply
        self.assertEqual((ev["data"]["target"], ev["data"]["emoji"], ev["data"]["session"], ev["data"]["quote"]),
                         (str(said["seq"]), "👍", "a", "Report ready."))
        self.ev("message.reacted", None, target=str(said["seq"]), emoji="👍", session="a", quote="Report ready.",
                channel="web", owner=True)
        pressed = ("(() => [...document.querySelectorAll('.react-pick[aria-pressed=\"true\"]')].map((x) => x.textContent))()")
        got = self.page({"until": "document.querySelectorAll('.react-chip').length === 2", "ms": 8000},
                        {"eval": "(() => { document.querySelectorAll('.react-chip')[1].click(); return true; })()"},
                        {"sleep": 300}, {"eval": pressed})
        self.assertEqual(got[-1]["eval"], ["👍"], got)

