    def test_snapshots_do_not_measure_the_input_field(self):
        # page lag (29.10): every snapshot redrew the field, and its auto-height read scrollHeight — a forced layout of
        # the whole page on each patch. Now it measures only when the text, the window height or the width changes
        self.ev("session.requested", "gs", session_id="s-gs", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "gs", session_id="s-gs")
        count = ("(() => { const d = Object.getOwnPropertyDescriptor(Element.prototype, 'scrollHeight'); window.__reads = 0; "
                 "Object.defineProperty(HTMLTextAreaElement.prototype, 'scrollHeight', { configurable: true, "
                 "get() { window.__reads++; return d.get.call(this); } }); return 'ok'; })()")
        self.page({"go": f"http://127.0.0.1:{self.port}/#/s/gs"}, {"until": "document.querySelector('form textarea')"},
                  {"sleep": 500}, {"eval": count})
        for i in range(4):
            m = self.j.append("message.received", None, {"to": "gs", "text": f"question {i}", "channel": "web", "owner": True})
            self.ev("turn.started", "gs", marker=f"m{m['seq']}")
            self.ev("turn.result", "gs", text=f"answer {i}", is_error=False)
            self.ev("turn.stopped", "gs")
        got = self.page({"wait": "question 3"}, {"sleep": 500}, {"eval": "window.__reads"},
                        {"eval": "(() => { const t = document.querySelector('form textarea'); t.value = 'a\\nb\\nc'; "
                                 "t.dispatchEvent(new Event('input')); return window.__reads; })()"})
        self.assertEqual(got[-2]["eval"], 0)   # snapshots alone measure nothing
        self.assertEqual(got[-1]["eval"], 1)   # typing still grows the field

    # --- reply to selected text (owner's option B: a panel with "Reply", reactions and "Copy") -----
    SAID = "First sentence of the report. Second important point. Third at the end."

    def quote_turn(self):
        """Two session replies to an owner message; a piece of the first one is selected."""
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a")
        e = self.j.append("message.received", None, {"to": "a", "text": "make the report", "channel": "web", "owner": True})
        self.ev("turn.started", "a", marker=f"m{e['seq']}", prompt_head="make")
        said = self.j.append("session.said", "a", {"text": self.SAID})
        self.j.append("session.said", "a", {"text": "Second line of the session reply."})
        self.ev("turn.result", "a", text="Second line of the session reply.")
        self.ev("turn.stopped", "a")
        return said

    @staticmethod
    def select_js(start, end=None):
        """Select in the feed from the start of the text start to the end of the text end (by default start itself), as with a mouse;
        end is looked for after start (the same word in an earlier row does not turn the range around)."""
        end = end or start
        return ("(() => { const w = document.createTreeWalker(document.querySelector('.feed'), NodeFilter.SHOW_TEXT); "
                "const find = (s, from) => { if (from) { const k = from[0].data.indexOf(s, from[1]); if (k >= 0) return [from[0], k]; "
                "w.currentNode = from[0]; } else w.currentNode = w.root; let n; while ((n = w.nextNode())) { const i = n.data.indexOf(s); "
                "if (i >= 0) return [n, i]; } }; const [a, i] = find(" + json.dumps(start) + "), [b, j] = find(" + json.dumps(end)
                + ", [a, i]); const r = document.createRange(); r.setStart(a, i); r.setEnd(b, j + "
                + str(len(end)) + "); const s = getSelection(); s.removeAllRanges(); s.addRange(r); "
                "return s.toString(); })()")

    PANEL = ("(() => { const p = document.querySelector('.quote-bar'); if (!p || p.hidden) return null; "
             "const r = p.getBoundingClientRect(), s = getSelection(), q = s.rangeCount && s.getRangeAt(0).getBoundingClientRect(); "
             "const m = document.getElementById('msg'), c = m && m.closest('.composer').getBoundingClientRect(); "
             "return {strip: p.classList.contains('strip'), above: !!q && r.bottom <= q.top + 1, "
             "overComposer: !!c && r.bottom <= c.top + 1 && c.top - r.bottom < 40, "
             "buttons: [...p.querySelectorAll('button')].map((b) => b.textContent.trim() || b.getAttribute('aria-label'))}; })()")

    def test_selecting_part_of_a_reply_offers_a_reply_with_only_that_fragment(self):
        """Selecting a piece of one reply shows a panel above the selection: "Reply", reactions (the same set as on the message)
        and "Copy". "Reply" quotes only the selection, the addressee is the same as for the "Reply" button of that reply."""
        self.reactions_module(True)
        self.quote_turn()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Second important"}, {"eval": self.PREP},
                        {"sleep": 300}, {"eval": self.select_js("Second important point")},
                        {"until": "!!document.querySelector('.quote-bar:not([hidden])')", "ms": 3000}, {"eval": self.PANEL},
                        {"eval": "(() => { document.querySelector('.quote-bar .qb-reply').click(); return 1; })()"},
                        {"until": "!!document.querySelector('.reply-chip')?.textContent"},
                        {"eval": "document.querySelector('.reply-chip').textContent"},
                        {"eval": "JSON.stringify(window.__m.S.replyTarget)"},
                        {"eval": "!!document.querySelector('.quote-bar:not([hidden])')"})
        panel = got[6]["eval"]
        self.assertEqual((panel["strip"], panel["above"]), (False, True), got)
        self.assertEqual(panel["buttons"], ["Reply", "👍", "✅", "👀", "❤️", "🙏", "Copy"], got)
        self.assertIn("Second important point", got[9]["eval"])
        self.assertNotIn("First", got[9]["eval"])
        target = json.loads(got[10]["eval"])
        self.assertEqual((target["session"], target["quote"], target["view"]), ("a", "Second important point", "a"))
        self.assertFalse(got[11]["eval"], got)   # the reply is chosen — no panel

    def test_a_reaction_from_the_selection_carries_the_fragment(self):
        """A reaction from the panel goes to the same reply, but with the selected piece: the badge sits on the row, the fragment is its hint."""
        self.reactions_module(True)
        said = self.quote_turn()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Second important"}, {"sleep": 300},
                        {"eval": self.select_js("Second important")},
                        {"until": "!!document.querySelector('.quote-bar:not([hidden])')", "ms": 3000},
                        {"eval": "(() => { [...document.querySelectorAll('.quote-bar .qb-react')].find((b) => b.textContent === '❤️').click(); return 1; })()"},
                        {"sleep": 600})
        (ev,) = [e for e in self.spooled() if e["type"] == "message.reacted"]
        self.assertEqual((ev["data"]["target"], ev["data"]["emoji"], ev["data"]["quote"], ev["data"].get("part")),
                         (str(said["seq"]), "❤️", "Second important", True))
        self.ev("message.reacted", None, **ev["data"])
        chip = ("(() => { const c = document.querySelector('.row.out .react-chip'); return c && [c.textContent, c.title, "
                "c.getAttribute('aria-label')]; })()")
        got = self.page({"until": "!!document.querySelector('.row.out .react-chip')", "ms": 8000}, {"eval": chip})
        text, title, label = got[-1]["eval"]
        self.assertEqual(text, "❤️")
        self.assertIn("“Second important”", title)
        self.assertEqual(label, title)

    def test_any_line_with_message_text_offers_a_reply_to_its_author(self):
        """Not only a session reply: the caption of a sent file, a message from another session and a notification — select a
        piece and the panel appears; "Reply" quotes the selection, the addressee is the row's author (for a file and a
        notification — the feed's session)."""
        for name in ("a", "b"):
            self.ev("session.requested", name, session_id=f"s-{name}", cwd="/w")
            self.ev("session.started", name)
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.started", "hub", session_id="s-h")
        self.ev("owner.file", None, path="/w/report.md", caption="File caption: **comparison** on the left and right",
                channel="session", owner=False, sender="a")
        e = self.j.append("message.received", None, {"to": "a", "text": "Message from a neighbouring session about the report",
                                                     "channel": "session", "owner": False, "sender": "b"})
        self.ev("turn.started", "a", marker=f"m{e['seq']}", prompt_head="Message")
        self.ev("turn.result", "a", text="Accepted.")
        self.ev("turn.stopped", "a")
        self.ev("owner.notify", None, text="Notification about readiness", title="Note", source="mon", channel="cli", owner=True)
        shown = "!!document.querySelector('.quote-bar:not([hidden])')"
        click = "(() => { document.querySelector('.quote-bar .qb-reply').click(); return 1; })()"
        for view, what, session, wait in (("a", "comparison", "a", "Message from a neighbouring"),
                                          ("a", "from a neighbouring session", "b", "Message from a neighbouring"),
                                          ("hub", "about readiness", "hub", "Notification about")):
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/{view}"}, {"wait": wait}, {"eval": self.PREP},
                            {"sleep": 400}, {"eval": self.select_js(what)},
                            {"until": shown, "ms": 3000}, {"eval": self.PANEL}, {"eval": click}, {"sleep": 200},
                            {"eval": "JSON.stringify(window.__m.S.replyTarget)"})
            self.assertTrue(got[5]["until"], (what, got))
            self.assertEqual(got[6]["eval"]["buttons"], ["Reply", "Copy"], (what, got))
            reply = json.loads(got[-1]["eval"])
            self.assertEqual((reply["session"], reply["quote"], reply["view"]), (session, what, view), (what, got))

    def test_no_panel_for_a_selection_across_messages_or_outside_the_feed(self):
        self.reactions_module(True)
        self.quote_turn()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Second line"}, {"sleep": 300},
                        {"eval": self.select_js("First sentence", "Second line")}, {"sleep": 700},
                        {"eval": "!!document.querySelector('.quote-bar:not([hidden])')"})
        self.assertIn("Second line", got[3]["eval"])
        self.assertFalse(got[5]["eval"], got)
        # the owner's own message is quotable too (its fragment gets the panel); the click is in
        # test_the_owner_replies_to_his_own_words_and_to_his_answer_on_a_card
        got = self.page({"eval": self.select_js("make the report")}, {"sleep": 700},
                        {"eval": "!!document.querySelector('.quote-bar:not([hidden])')"},
                        {"eval": "getSelection().removeAllRanges()"}, {"until": "!document.querySelector('.quote-bar:not([hidden])')", "ms": 3000})
        self.assertTrue(got[2]["eval"], got)
        self.assertTrue(got[-1]["until"], got)
        # from text to the time and the buttons of the same row: the panel is there, but the quote is only the reply text,
        # without "Reply"
        got = self.page({"eval": self.PREP}, {"sleep": 200}, {"eval": self.select_js("Third at the end", "Reply")},
                        {"until": "!!document.querySelector('.quote-bar:not([hidden])')", "ms": 3000},
                        {"eval": "(() => { document.querySelector('.quote-bar .qb-reply').click(); return 1; })()"},
                        {"sleep": 200}, {"eval": "window.__m.S.replyTarget && window.__m.S.replyTarget.quote"})
        self.assertIn("Reply", got[2]["eval"])
        self.assertEqual(got[-1]["eval"], "Third at the end.", got)
        got = self.page({"eval": self.select_js("Second important")}, {"sleep": 700},   # control: within one reply — it appears
                        {"eval": "!!document.querySelector('.quote-bar:not([hidden])')"})
        self.assertTrue(got[-1]["eval"], got)

    def test_the_selection_panel_goes_on_escape_scroll_and_a_click_elsewhere(self):
        self.reactions_module(True)
        self.quote_turn()
        show = ({"eval": self.select_js("Second important")},
                {"until": "!!document.querySelector('.quote-bar:not([hidden])')", "ms": 3000})
        shown = "!!document.querySelector('.quote-bar:not([hidden])')"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Second important"}, {"sleep": 300},
                        *show, {"key": "Escape"}, {"sleep": 200}, {"eval": shown},
                        *show, {"eval": "document.querySelector('.feed').dispatchEvent(new Event('scroll')), 1"},
                        {"sleep": 200}, {"eval": shown},
                        *show, {"eval": "getSelection().removeAllRanges(), 1"}, {"sleep": 400}, {"eval": shown})
        self.assertEqual([got[i]["until"] for i in (4, 9, 14)], [True] * 3, got)   # the panel appeared every time
        self.assertEqual([got[i]["eval"] for i in (7, 12, 17)], [False, False, False], got)

    @staticmethod
    def pointer_js(type, kind, at="end"):
        """Press or release (pointerdown/up) by a pointer of kind kind — at the end of the selection (end) or at the start of the feed."""
        return ("(() => { const s = getSelection(); const r = s.rangeCount && " + ("s.getRangeAt(0).getClientRects()" if at == "end" else "null")
                + "; const q = r && r.length ? r[r.length - 1] : document.querySelector('.feed').getBoundingClientRect(); "
                "const x = Math.round(q.right - 4), y = Math.round(q.top + q.height / 2); "
                "document.querySelector('.feed .row.out .md').dispatchEvent(new PointerEvent('" + type + "', {pointerType: '" + kind
                + "', bubbles: true, clientX: x, clientY: y})); return [x, y]; })()")

    QBAR = ("(() => { const p = document.querySelector('.quote-bar'); if (!p || p.hidden) return null; const r = p.getBoundingClientRect(); "
           "return {strip: p.classList.contains('strip'), cx: r.left + r.width / 2, bottom: r.bottom, left: r.left, right: r.right}; })()")

    def test_the_panel_stands_where_the_mouse_was_let_go(self):
        """The panel should always be close to the cursor: with a mouse — above the point where the button was released, not above
        the middle of the selection."""
        self.reactions_module(True)
        self.quote_turn()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Second important"}, {"sleep": 300},
                        {"eval": self.pointer_js("pointerdown", "mouse", at="feed")},
                        {"eval": self.select_js("First sentence", "Second important point")},
                        {"eval": self.pointer_js("pointerup", "mouse")},
                        {"until": "!!document.querySelector('.quote-bar:not([hidden])')", "ms": 3000}, {"eval": self.QBAR},
                        {"eval": "(() => { const r = getSelection().getRangeAt(0).getBoundingClientRect(); return r.left + r.width / 2; })()"})
        (x, y), bar, middle = got[5]["eval"], got[7]["eval"], got[8]["eval"]
        self.assertFalse(bar["strip"], got)
        self.assertLess(abs(bar["cx"] - x), 2, got)              # at the cursor
        self.assertGreater(abs(bar["cx"] - middle), 60, got)    # not at the middle of the selection
        self.assertTrue(0 < y - bar["bottom"] <= 20, got)        # slightly above the cursor
        # a stray click that did not touch the selection (scrollbar) — the panel stays at the selection, not at the click
        got = self.page({"eval": self.pointer_js("pointerdown", "mouse", at="feed")},
                        {"eval": self.pointer_js("pointerup", "mouse", at="feed")}, {"sleep": 300}, {"eval": self.QBAR},
                        {"eval": "(() => { const r = [...getSelection().getRangeAt(0).getClientRects()].pop(); return r.right; })()"})
        (cx, _), bar, end = got[1]["eval"], got[3]["eval"], got[4]["eval"]
        self.assertGreater(abs(bar["cx"] - cx), 60, got)
        self.assertLess(abs(bar["cx"] - end), 2, got)

    def test_a_narrow_window_with_a_mouse_gets_the_panel_and_a_finger_gets_the_strip(self):
        """The strip above the input field appears only when the selection was made with a finger (above the selection there is the
        OS system menu); a narrow window with a mouse — the same panel at the cursor."""
        self.reactions_module(True)
        self.quote_turn()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Second important"},
                        {"shot": os.path.join(tempfile.gettempdir(), "e2e-quote-narrow.png"), "width": 390, "height": 800},
                        {"sleep": 300}, {"eval": self.pointer_js("pointerdown", "mouse", at="feed")},
                        {"eval": self.select_js("Second important")}, {"eval": self.pointer_js("pointerup", "mouse")},
                        {"until": "!!document.querySelector('.quote-bar:not([hidden])')", "ms": 3000}, {"eval": self.QBAR},
                        {"eval": "getSelection().removeAllRanges(), 1"}, {"sleep": 400},
                        {"eval": self.pointer_js("pointerdown", "touch", at="feed")},
                        {"eval": self.select_js("Second important")},
                        {"until": "!!document.querySelector('.quote-bar:not([hidden])')", "ms": 3000}, {"eval": self.PANEL})
        mouse, finger = got[8]["eval"], got[-1]["eval"]
        self.assertFalse(mouse["strip"], got)
        self.assertGreaterEqual(mouse["left"], 0, got)
        self.assertLessEqual(mouse["right"], 390, got)           # inside the window
        self.assertEqual((finger["strip"], finger["overComposer"]), (True, True), got)
        self.assertEqual((finger["buttons"][0], finger["buttons"][-1]), ("Reply", "Copy"))

    def test_theme_font_for_the_whole_page_and_its_scale(self):
        # A terminal theme needs the font beyond headings: the feed and lists stayed in Plex, and a pixel font is smaller at the
        # same px. "font_scope": "all" applies the theme font to the whole page (the standard ones as a fallback),
        # "font_scale" is the size-adjust of its @font-face; without the fields — as before; errors in the fields — the theme
        # is not applied
        from unittest import mock
        cfgdir = os.path.join(self.state, "cfg")
        own = os.path.join(cfgdir, "themes")
        os.makedirs(own)
        with open(os.path.join(own, "term.woff2"), "wb") as fh:
            fh.write(b"wOF2")
        colors = {"background": "#001100", "foreground": "#33ff66", "primary": "#33ff66"}
        for name, extra in (("Phosphor", {"font": "term.woff2", "font_scope": "all", "font_scale": 1.2}),
                            ("Heads only", {"font": "term.woff2"}),
                            ("Code only", {"font": "term.woff2", "font_scope": "mono"}),
                            ("Too big", {"font": "term.woff2", "font_scale": 2}),
                            ("Unknown scope", {"font": "term.woff2", "font_scope": "everything"}),
                            ("No font", {"font_scope": "all"})):
            with open(os.path.join(own, f"{name}.json"), "w") as f:
                json.dump({"name": name, "dark": True, "colors": colors, **extra}, f)
        with open(os.path.join(cfgdir, "hub.json"), "w") as f:
            json.dump({}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": os.path.join(cfgdir, "hub.json")})
        env.start()
        self.addCleanup(env.stop)
        # the font of the feed, code (the search kbd) and headings; the scale is in @font-face
        state = ("[getComputedStyle(document.body).fontFamily, getComputedStyle(document.querySelector('.search kbd'))"
                 ".fontFamily, getComputedStyle(document.documentElement).getPropertyValue('--font-display')]"
                 ".map((f) => f.includes('hub-theme-font')).concat(/size-adjust: *120%/.test("
                 "document.getElementById('theme-font')?.textContent || ''))")
        # the bottom-left line with a wide font wraps in parts, the number does not detach from its label (parts are span,
        # nowrap)
        counts = ("[document.querySelector('.aside-foot .counts').textContent, [...document.querySelectorAll("
                  "'.aside-foot .counts span')].map((s) => getComputedStyle(s).whiteSpace)]")
        root, display = "document.documentElement", "getComputedStyle(document.documentElement).getPropertyValue('--font-display')"
        errors = ("['font_scale: a number from 0.8 to 1.5', 'font_scope: “all”, “titles” or “mono”', "
                  "'font_scope and font_scale only work together with font'].map((e) => document.body.innerText.includes(e))")
        got = self.page({"local": {"hub.settingsTab": "theme"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"wait": "Phosphor"}, {"until": f"{errors}.every(Boolean)"}, {"eval": errors},
                        {"click": "Phosphor"}, {"until": f"{root}.classList.contains('theme-font-all')"}, {"eval": state},
                        {"click": "Heads only"}, {"until": f"!{root}.classList.contains('theme-font-all')"},
                        {"eval": state},
                        # "monospace only where the system theme has it too": code and paths use the theme font, text and headings are as in
                        # the system theme
                        {"click": "Code only"}, {"until": f"{root}.classList.contains('theme-font-mono')"}, {"eval": state},
                        {"click": "Classic"}, {"until": f"!{root}.classList.contains('theme-font-mono')"},
                        {"eval": state}, {"eval": counts})
        evals = [g["eval"] for g in got if "eval" in g]
        self.assertEqual(evals.pop(), ["No sessions", ["nowrap"]])   # footer by state (redesign): with no sessions, one part
        self.assertEqual(evals[0], [True, True, True])
        self.assertEqual(evals[1:], [[True, True, True, True], [False, False, True, False],
                                     [False, True, False, False], [False, False, False, False]])

    def test_theme_sets_the_width_of_the_text_line(self):
        # "measure": "110ch" in a theme is the longest line of the feed text (--measure on the page); without the field or with
        # a value out of range (not "<number>ch", below 40, above 200) — the 68ch of the system theme; another theme or
        # "Classic" takes it back
        from unittest import mock
        cfgdir = os.path.join(self.state, "cfg")
        own = os.path.join(cfgdir, "themes")
        os.makedirs(own)
        colors = {"background": "#001100", "foreground": "#33ff66", "primary": "#33ff66"}
        for name, extra in (("Wide", {"measure": "110ch"}), ("Plain", {}), ("Huge", {"measure": "9999ch"}),
                            ("Words", {"measure": "wide"}), ("Number", {"measure": 110})):
            with open(os.path.join(own, f"{name}.json"), "w") as f:
                json.dump({"name": name, "dark": True, "colors": colors, **extra}, f)
        with open(os.path.join(cfgdir, "hub.json"), "w") as f:
            json.dump({}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": os.path.join(cfgdir, "hub.json")})
        env.start()
        self.addCleanup(env.stop)
        measure = "getComputedStyle(document.documentElement).getPropertyValue('--measure').trim()"
        root = "document.documentElement"
        got = self.page({"local": {"hub.settingsTab": "theme"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"wait": "Wide"}, {"click": "Wide"}, {"until": f"{measure} === '110ch'"}, {"eval": measure},
                        {"click": "Plain"}, {"until": f"{measure} === '68ch'"}, {"eval": measure},
                        {"click": "Wide"}, {"until": f"{measure} === '110ch'"},
                        {"click": "Classic"}, {"until": f"{measure} === '68ch'"}, {"eval": f"{root}.style.getPropertyValue('--measure')"},
                        {"click": "Huge"}, {"sleep": 400}, {"eval": measure},
                        {"click": "Words"}, {"sleep": 400}, {"eval": measure},
                        {"click": "Number"}, {"sleep": 400}, {"eval": measure})
        self.assertEqual([g["eval"] for g in got if "eval" in g], ["110ch", "68ch", "", "68ch", "68ch", "68ch"])

    def test_dark_theme_shell_keeps_the_hue_of_its_background(self):
        # a dark theme with an almost grey background (#1e2326) gave a brownish-pink shell: color-mix(in oklch, bg, black) —
        # black has hue none in oklch, a low-chroma background gives none too, and none is drawn as 0 (red)
        from unittest import mock
        cfgdir = os.path.join(self.state, "cfg")
        own = os.path.join(cfgdir, "themes")
        os.makedirs(own)
        with open(os.path.join(own, "forest.json"), "w") as f:
            json.dump({"name": "Forest", "dark": True,
                       "colors": {"background": "#1e2326", "foreground": "#b8c8b0", "primary": "#83c092"}}, f)
        with open(os.path.join(cfgdir, "hub.json"), "w") as f:
            json.dump({}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": os.path.join(cfgdir, "hub.json")})
        env.start()
        self.addCleanup(env.stop)
        # the shell colour in sRGB via canvas: the red channel is not above blue and green (a cold background, not pink)
        rgb = ("(()=>{const c=document.createElement('canvas').getContext('2d');c.fillStyle=getComputedStyle(document.body)"
               ".backgroundColor;c.fillRect(0,0,1,1);return [...c.getImageData(0,0,1,1).data].slice(0,3)})()")
        got = self.page({"local": {"hub.settingsTab": "theme"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"wait": "Forest"}, {"sleep": 1500}, {"click": "Forest"}, {"sleep": 800}, {"eval": rgb})
        r, g, b = [x for x in got if "eval" in x][0]["eval"]
        self.assertLessEqual(r, min(g, b), (r, g, b))

    def test_theme_color_code_bg_paints_code_and_the_system_theme_is_unchanged(self):
        # a theme sets the code background with "code-bg" (API 1.31): inline code gets a plate, code blocks change their
        # backdrop; without the color (the system theme, a theme without it) the look is as before — blocks on --muted,
        # inline code without a plate; switching back to the system theme drops the variable
        from unittest import mock
        cfgdir = os.path.join(self.state, "cfg")
        own = os.path.join(cfgdir, "themes")
        os.makedirs(own)
        with open(os.path.join(own, "plate.json"), "w") as f:
            json.dump({"name": "Plaque", "dark": False, "colors": {
                "background": "#ffffff", "foreground": "#27272a", "primary": "#4f6cf6", "code-bg": "#112233"}}, f)
        with open(os.path.join(cfgdir, "hub.json"), "w") as f:
            json.dump({}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": os.path.join(cfgdir, "hub.json")})
        env.start()
        self.addCleanup(env.stop)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None)
        said = "Launched `ls -la` in the folder\n\n```\nmake test\n```"
        self.ev("session.said", "a", text=said)
        self.ev("turn.result", "a", text=said)
        look = ("(() => { const c = document.querySelector('.md :not(pre) > code'), p = document.querySelector('.md pre'), "
                "css = getComputedStyle(document.documentElement); return {var: css.getPropertyValue('--code-bg').trim(), "
                "block: getComputedStyle(p).backgroundColor, muted: css.getPropertyValue('--muted').trim(), "
                "plate: getComputedStyle(c).boxShadow, inline: getComputedStyle(c).backgroundColor, "
                "box: [c.offsetWidth, c.offsetHeight, p.offsetWidth, p.offsetHeight]}; })()")
        var_is = lambda v: f"getComputedStyle(document.documentElement).getPropertyValue('--code-bg').trim() === '{v}'"
        base = f"http://127.0.0.1:{self.port}"
        got = self.page({"local": {"hub.settingsTab": "theme"}}, {"go": f"{base}/#/settings"}, {"wait": "Plaque"}, {"sleep": 1500},
                        {"go": f"{base}/#/s/a"}, {"wait": "Launched"}, {"eval": look},
                        {"go": f"{base}/#/settings"}, {"wait": "Plaque"}, {"click": "Plaque"}, {"until": var_is("#112233")},
                        {"go": f"{base}/#/s/a"}, {"wait": "Launched"}, {"eval": look},
                        {"go": f"{base}/#/settings"}, {"wait": "Classic"}, {"click": "Classic"}, {"until": var_is("")},
                        {"go": f"{base}/#/s/a"}, {"wait": "Launched"}, {"eval": look})
        before, themed, after = [x["eval"] for x in got if isinstance(x.get("eval"), dict)]
        self.assertEqual(themed["var"], "#112233")
        self.assertEqual(themed["block"], "rgb(17, 34, 51)")      # the code block backdrop is the theme's
        self.assertEqual(themed["inline"], "rgba(0, 0, 0, 0)")    # the inline plate is a shadow ring: the box does not grow
        self.assertIn("rgb(17, 34, 51)", themed["plate"])
        self.assertEqual(themed["box"], before["box"])            # same geometry as in the system theme
        for system in (before, after):                            # no variable: as before the color existed
            self.assertEqual(system["var"], "")
            self.assertEqual(system["plate"], "none")
            self.assertEqual(system["inline"], "rgba(0, 0, 0, 0)")
            self.assertNotEqual(system["block"], "rgb(17, 34, 51)")
        self.assertEqual(after["box"], before["box"])

    def test_selection_is_visible_in_own_message(self):
        # owner complaint: own text in the right-hand bubble "does not get selected, it drags like an image" — ::selection and
        # the bubble background were the same colour (--front-soft): the selection existed but was invisible, and the next
        # drag dragged it
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.started", "hub", session_id="s-h")
        self.ev("message.received", None, to="hub", text="my text to copy", channel="web", owner=True)
        colors = ("(()=>{const b=document.querySelector('.row.mine .b');return b?[getComputedStyle(b).backgroundColor,"
                  "getComputedStyle(b,'::selection').backgroundColor]:null})()")
        delivered = ("(() => { const {S, render} = window.__m; S.snap.timelines.hub.filter((i) => i.kind === 'in')"
                     ".forEach((i) => { S.snap.messages[i.id] = {...S.snap.messages[i.id], state: 'delivered'}; }); render(); return 1; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/hub"}, {"wait": "my text"}, {"eval": self.PREP}, {"sleep": 300},
                        {"eval": delivered}, {"sleep": 300}, {"eval": colors})
        plate, selection = got[-1]["eval"]
        self.assertNotEqual(plate, selection)

    def test_selection_contrasts_on_dark_and_light(self):
        # owner complaint: the selection is not contrasty at all — on the dark theme ::selection (--front-soft, 12% of the
        # accent colour) almost merged with the background. Selection contrast against the page background and against the
        # own-message bubble — in both themes
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.started", "hub", session_id="s-h")
        self.ev("message.received", None, to="hub", text="my text to copy", channel="web", owner=True)
        # dark theme — the values of the dark block of tokens.css on the root; colours in sRGB via canvas, contrast per WCAG
        probe = ("(()=>{const px=(c)=>{const x=document.createElement('canvas').getContext('2d');x.fillStyle=c;x.fillRect(0,0,1,1);"
                 "return [...x.getImageData(0,0,1,1).data].slice(0,3)};const L=(c)=>{const v=px(c).map((u)=>{u/=255;"
                 "return u<=0.03928?u/12.92:((u+0.055)/1.055)**2.4});return 0.2126*v[0]+0.7152*v[1]+0.0722*v[2]};"
                 "const k=(a,b)=>{const [x,y]=[L(a),L(b)].sort((p,q)=>q-p);return (x+0.05)/(y+0.05)};"
                 "const r=document.documentElement,out={};for(const mode of ['light','dark']){if(mode==='dark'){"
                 "r.style.setProperty('--background','#1c1c20');r.style.setProperty('--primary','var(--blue-400)');}"
                 "const sel=getComputedStyle(document.body,'::selection').backgroundColor,bg=getComputedStyle(r).getPropertyValue('--background'),"
                 "plate=getComputedStyle(document.querySelector('.row.mine .b')).backgroundColor;"
                 "out[mode]=[k(sel,bg),k(sel,plate)]}return out})()")
        delivered = ("(() => { const {S, render} = window.__m; S.snap.timelines.hub.filter((i) => i.kind === 'in')"
                     ".forEach((i) => { S.snap.messages[i.id] = {...S.snap.messages[i.id], state: 'delivered'}; }); render(); return 1; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/hub"}, {"wait": "my text"}, {"eval": self.PREP},
                        {"sleep": 300}, {"eval": delivered}, {"sleep": 300}, {"eval": probe})
        out = got[-1].get("eval")
        self.assertIsInstance(out, dict, out)
        for mode, (page, plate) in out.items():
            self.assertGreaterEqual(page, 1.5, (mode, out))
            self.assertGreaterEqual(plate, 1.25, (mode, out))

