        self.ev("session.started", "alpha", session_id="s-a")
        row = "document.querySelector('#list li[data-s=\"alpha\"] .avatar')"
        pal = ("(() => { " + row + ".click(); const l = [...document.querySelectorAll('.palette .pal-e')].map(b => b.getAttribute('aria-label')); "
               "return JSON.stringify([l.slice(0, 3), l.length, new Set(l).size]); })()")
