    def test_a_one_line_answer_takes_little_height(self):
        # the point was to save vertical space — a one-line session reply took 97 px: name, text, time on its own
        # line and "Reply" on another; between turns another 16 px
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        for i in range(2):
            e = self.j.append("message.received", None, {"to": "a", "text": f"question {i}", "channel": "web", "owner": True})
            self.ev("turn.started", "a", marker=f"m{e['seq']}", prompt_head="x")
            self.ev("session.said", "a", text=f"Short answer {i}")
            self.ev("turn.result", "a", text=f"Short answer {i}")
            self.ev("turn.stopped", "a")
        sizes = ("JSON.stringify((() => { const outs = [...document.querySelectorAll('.feed-inner > .row.out')]; const o = outs.pop(); "
                 "const r = o.getBoundingClientRect(), n = o.nextElementSibling, p = o.previousElementSibling; "
                 "return [Math.round(r.height), Math.round(r.top - p.getBoundingClientRect().bottom), "
                 "o.querySelector('.meta') && Math.round(o.querySelector('.meta').getBoundingClientRect().top - o.querySelector('.byline').getBoundingClientRect().top)]; })())")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Short answer 1"}, {"click": "Brief"},
                        {"sleep": 500}, {"eval": sizes})
        height, gap, meta_vs_name = json.loads([g["eval"] for g in got if "eval" in g][-1])
        self.assertLessEqual(height, 60)          # name with time on one line, text on the second
        self.assertLessEqual(abs(meta_vs_name), 4)   # time on the name line

