    def test_page_can_be_added_to_the_home_screen(self):
        # iPhone ("Add to Home Screen") and Android ("Install") take the manifest, icons and meta from head; Chrome parses
        # the manifest without errors. viewport-fit=cover is not set — safe-area is not handled everywhere in the styles; no
        # service worker
        head = ("JSON.stringify({link: [...document.head.querySelectorAll('link[rel=manifest], link[rel=apple-touch-icon]')]"
                ".map((l) => [l.rel, l.getAttribute('href')]), meta: [...document.head.querySelectorAll('meta')]"
                ".filter((m) => /theme-color|capable|status-bar|viewport/.test(m.name)).map((m) => [m.name, m.content, m.media])})")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/"}, {"until": "document.querySelector('#app')"},
                        {"eval": head}, {"manifest": 1})
        info = json.loads(next(g["eval"] for g in got if "eval" in g))
        self.assertEqual(info["link"], [["manifest", "/manifest.webmanifest"],
                                        ["apple-touch-icon", "/static/icons/apple-touch-icon.png"]])
        metas = {(n, m) for n, _, m in info["meta"] if n == "theme-color"}
        self.assertEqual(metas, {("theme-color", "(prefers-color-scheme: light)"), ("theme-color", "(prefers-color-scheme: dark)")})
        by = {n: c for n, c, _ in info["meta"]}
        self.assertEqual((by["mobile-web-app-capable"], by["apple-mobile-web-app-capable"]), ("yes", "yes"))
        self.assertNotIn("cover", by["viewport"])
        man = next(g["manifest"] for g in got if "manifest" in g)
        self.assertEqual(man["errors"], [])
        self.assertTrue(man["url"].endswith("/manifest.webmanifest"))
        self.assertEqual((man["data"]["display"], man["data"]["start_url"]), ("standalone", "/"))
        self.assertEqual(len(man["data"]["icons"]), 3)

    def test_header_buttons_stay_on_the_name_line_when_space_is_short(self):
        # with the right panel open, "Stop" and "More" moved to the second header row — the hub's schedule and task badges
        # now shrink with an ellipsis, and the buttons stay on the name row
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        for i in range(2):
            self.ev("schedule.set", f"job-{i}", session="a", every=600, prompt="check", channel="cli", owner=True)
        same = ("(() => { const h = document.querySelector('main .head h2').getBoundingClientRect(); "
                "const b = [...document.querySelectorAll('main .head button')].find((x) => x.textContent.includes('More')); "
                "return b ? Math.abs(b.getBoundingClientRect().top - h.top) < h.height : 'no button'; })()")
        lupa = "document.querySelector('main .head .fs-lupa').getClientRects().length > 0"
        cmd_f = ("document.dispatchEvent(new KeyboardEvent('keydown', {key: 'f', code: 'KeyF', ctrlKey: true, "
                 "bubbles: true})), 1")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": "document.querySelector('main .head .chip')"},
                        {"eval": lupa},
                        {"eval": "document.querySelector('main').style.maxWidth = '620px'; 1"}, {"sleep": 300}, {"eval": same},
                        {"eval": lupa}, {"eval": cmd_f}, {"until": "document.querySelector('main > .fsearch')"},
                        {"sleep": 300}, {"eval": same}, {"eval": lupa})
        evals = [g["eval"] for g in got if "eval" in g]
        self.assertIs(evals[0], True)    # wide header — the search magnifier is in place
        self.assertIs(evals[2], True)
        self.assertIs(evals[3], False)   # narrow (the magnifier pushed out "More") — it is hidden, search is ⌘F / Ctrl+F
        self.assertEqual(evals[5:], [True, False])   # search opened from the keyboard — buttons on the row, no magnifier

    MODEL_ITEMS = ("JSON.stringify([...document.querySelectorAll('.stat-mod .menu [role=menuitemcheckbox]')]"
                   ".filter((b) => b.getClientRects().length).map((b) => [b.textContent, b.getAttribute('aria-checked')]))")

    def test_model_in_the_bottom_line_opens_the_models_and_changes_this_session(self):
        # the model under the input field — by full name; a click opens the model menu above the row with the selected one
        # marked (PR #132); with no model of its own, "Default" is marked and there is no extra "Opus 5.5" row; selecting
        # uses the existing /api/session/model
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("session.info", "a", model="claude-opus-5-5", effort="high", mode="bypassPermissions")
        self.ev("session.requested", "b", session_id="s-b", cwd="/w", channel="cli", owner=True)
        up = ("(() => { const b = document.querySelector('.stat-mod .menu-btn').getBoundingClientRect(), m = "
              "document.querySelector('.stat-mod .menu').getBoundingClientRect(); return m.bottom <= b.top + 1; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": "document.querySelector('.stat-mod .menu-btn')"},
                        {"eval": "!!document.querySelector('.composer select')"},
                        {"eval": "document.querySelector('.stat-mod .menu-btn').innerText"},
                        {"eval": "(document.querySelector('.stat-mod .menu-btn').click(), 1)"}, {"sleep": 300},
                        {"eval": up}, {"eval": self.MODEL_ITEMS},
                        {"eval": "document.activeElement.getAttribute('aria-checked')"},
                        {"eval": "!!document.querySelector('dialog[open]')"},
                        {"click": "Sonnet"}, {"sleep": 500})
        self.assertFalse(got[2]["eval"])                                         # no model picker in the input field
        self.assertEqual(got[3]["eval"], "Opus 5.5")
        self.assertTrue(got[6]["eval"])                                          # menu above the row
        self.assertEqual(json.loads(got[7]["eval"]), [["Opus", "false"], ["Sonnet", "false"], ["Fable", "false"],
                                                      ["Haiku", "false"], ["Default", "true"]])
        self.assertEqual(got[8]["eval"], "true")                                 # focus is on the selected one
        self.assertFalse(got[9]["eval"])                                         # the explanation dialog is gone
        changes = [(e["entity"], e["data"]["model"]) for e in self.spooled() if e["type"] == "session.model_set"]
        self.assertEqual(changes, [("a", "sonnet")])                             # exactly one change, for this session

    def test_model_menu_marks_the_own_model_and_warns_an_executor(self):
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.model_set", "a", model="opus", channel="cli", owner=True)
