                        {"eval": "(document.querySelector('.stat-mod .menu-btn').click(), 1)"}, {"sleep": 300},
                        {"eval": self.MODEL_ITEMS}, {"eval": "document.querySelector('.stat-mod .menu').textContent"},
                        {"key": "Escape"}, {"sleep": 200},
