    def test_selected_text_survives_live_updates(self):
        # the selection got reset, so selecting text was almost impossible — each feed update rebuilt the feed,
        # and the selection went away with the old nodes
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("session.said", "a", text="line to select")
        select = ("(() => { const n = [...document.querySelectorAll('.feed *')].find((e) => e.childNodes.length === 1"
                  " && e.firstChild.nodeType === 3 && e.textContent.includes('line to select'));"
                  " const r = document.createRange(); r.selectNodeContents(n); const s = getSelection();"
                  " s.removeAllRanges(); s.addRange(r); return s.toString(); })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "line to select"}, {"eval": select})
        self.ev("session.said", "a", text="new feed line")   # an update arrives when text is already selected
        got += self.page({"sleep": 2500},
                         {"eval": "[getSelection().toString(), document.body.innerText.includes('new feed line')]"},
                         {"eval": "getSelection().removeAllRanges()"}, {"wait": "new feed line"})
        evals = [g["eval"] for g in got if "eval" in g]
        self.assertEqual(evals[0], "line to select")
        self.assertEqual(evals[1], ["line to select", False])   # selection intact, the feed waits
        self.assertTrue([g for g in got if "wait" in g][-1]["ok"])     # selection cleared — the new content arrives

