    def test_executors_keep_their_names_and_a_sleeping_one_says_whose_task(self):
        # executors are named after the task they are doing, and when they fall asleep, it shows whose task it was;
        # a direction's executor goes under the direction
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.requested", "frontend", session_id="s-fe", cwd="/fe", role="agent", about="Frontend",
                channel="cli", owner=True)
        self.ev("session.requested", "atlas", session_id="s-at", cwd="/a", channel="cli", owner=True)
        self.ev("session.started", "atlas", session_id="s-at")
        self.ev("task.backlog", None, slug="atlas", channel="session", owner=False, sender="atlas")
        for n, up, about in (("frontend-ci", "frontend", "Fix CI secrets"), ("atlas-tiles", "atlas", "Slice the tiles"),
                             ("atlas-maps", "atlas", "Assemble maps"), ("frontend-ci-sub-task", "frontend-ci", "Subtask")):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", executor=True, raised_by=up, about=about)
            self.ev("session.started", n, session_id=f"s-{n}")
        self.ev("session.close_requested", "atlas-tiles", retire=True)
        self.ev("session.exited", "atlas-tiles", why="sleep")
        rows = ("JSON.stringify([...document.querySelectorAll('.srow')].map(b => (b.querySelector('.nm').innerText + ' '"
                " + b.querySelector('.lb').innerText).replace(/\\s+/g, ' ').trim()))")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"sleep": 2000},
                        {"eval": "[...document.querySelectorAll('.fork-toggle')].forEach(t => t.click()); 1"}, {"sleep": 500},
                        {"eval": rows})
        rows = json.loads(got[-1]["eval"])
        self.assertFalse([r for r in rows if "Fix CI secrets" in r])        # the session name, not the task text
        # under the parent — without its name (the naming need not be duplicated)
        self.assertTrue([r for r in rows if r.startswith("ci ")])
        self.assertFalse([r for r in rows if "frontend-ci" in r])
        tiles = next(r for r in rows if r.startswith("tiles "))
        self.assertIn("asleep", tiles)
        self.assertNotIn("task from", tiles)                                     # under atlas itself — redundant
        names = [r.split()[0] for r in rows]
        self.assertLess(names.index("maps"), names.index("tiles"))               # working above sleeping
        # an executor's executor (an executor raised by an auto-executor vanished from the list) — under the same specialist
        self.assertTrue([r for r in rows if r.startswith("ci-sub-task ")])

    def test_executors_of_an_executor_the_hub_raised_sit_under_it(self):
        # beta and gamma stood outside a group: the hub raised executor alpha, which raised its own beta and gamma; the
        # chain upward ended at the hub, and beta and gamma stood as separate rows. The parent is the top executor of the
        # chain (one level of nesting); a specialist's executor stays under the specialist, as before. Same in "All" and
        # "Now"
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.started", "hub", session_id="s-h")
        self.ev("session.requested", "maps", session_id="s-m", cwd="/m", channel="cli", owner=True)
        self.ev("session.started", "maps", session_id="s-m")
        for n, up in (("alpha", "hub"), ("beta", "alpha"), ("gamma", "alpha"), ("maps-x", "maps")):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", executor=True, raised_by=up)
            self.ev("session.started", n, session_id=f"s-{n}")
        for n in ("beta", "gamma", "maps-x"):   # busy — in "Now" as rows under the parent
            self.ev("turn.started", n, marker=None, prompt_head="x")
        tree = ("JSON.stringify([...document.querySelectorAll('#list li:is([data-s], [data-m])')].map(li => {"
                " const n = li.dataset.s || li.dataset.m, f = li.nextElementSibling;"
                " return [n, f && f.classList.contains('forks') ? [...f.querySelectorAll('.srow .nm')]"
                ".map(x => x.textContent.trim().split(/\\s+/).pop()).sort() : []]; }).filter(x => x[0] !== 'hub'))")
        want = [["alpha", ["beta", "gamma"]], ["maps", ["x"]]]
        # STEADY passes while the list is still empty (the snapshot comes later; on a slow machine, later than 300 ms): wait
        # for both toggles
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, self.STEADY,
                        {"until": "document.querySelectorAll('#list .fork-toggle').length === 2"},
                        {"eval": "[...document.querySelectorAll('.fork-toggle[aria-expanded=\"false\"]')].forEach(t => t.click()); 1"},
                        {"until": "document.querySelectorAll('#list li.forks').length === 2"}, {"eval": tree})
        self.assertEqual(sorted(json.loads(got[-1]["eval"])), want)
        got = self.page({"local": {"hub.sidebar": "active"}}, {"go": f"http://127.0.0.1:{self.port}/#/"},
                        {"until": "document.querySelectorAll('#list li.forks').length === 2"}, {"eval": tree})
        self.assertEqual(sorted(json.loads(got[-1]["eval"])), want)

    def test_executors_of_a_sleeping_executor_sit_under_it_in_resting(self):
        # review: a sleeping hub executor goes to "Asleep or failed" — its executors do not disappear (rows there were drawn
        # without nested ones), and "Delete all" also deletes the sleeping ones among them, otherwise they would surface as
        # rows after the parent is deleted. A sleeper whose executor is not asleep (delta handed over, epsilon works) stays
        # there too (as with a specialist), epsilon under it, and "Delete all" does not take it
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.started", "hub", session_id="s-h")
        for n, up in (("alpha", "hub"), ("beta", "alpha"), ("gamma", "alpha")):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", executor=True, raised_by=up)
            self.ev("session.started", n, session_id=f"s-{n}")
            self.ev("session.close_requested", n, retire=True)
            self.ev("session.exited", n, why="sleep")
        for n, up in (("delta", "hub"), ("epsilon", "delta")):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", executor=True, raised_by=up)
            self.ev("session.started", n, session_id=f"s-{n}")
        self.ev("session.close_requested", "delta", retire=True)
        self.ev("session.exited", "delta", why="sleep")
        self.ev("turn.started", "epsilon", marker=None, prompt_head="x")
        where = ("JSON.stringify(['delta', 'epsilon'].map(n => { const r = [...document.querySelectorAll('#list .srow')]"
                 ".find(b => b.querySelector('.nm').textContent.trim().split(/\\s+/).pop() === n);"
                 " return r ? [!!r.closest('details.resting'), r.closest('li.forks')?.previousElementSibling?.dataset.m || null] : null; }))")
        under = ("JSON.stringify([...document.querySelectorAll('#list details.resting li[data-m=\"alpha\"] + li.forks .srow .nm')]"
                 ".map(x => x.textContent.trim().split(/\\s+/).pop()).sort())")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, self.STEADY,
                        {"eval": "(document.querySelector('#list details.resting').open = true, 1)"},
                        {"until": "!!document.querySelector('#list details.resting li[data-m=\"alpha\"] .fork-toggle')"},
                        {"eval": "(document.querySelector('#list details.resting .fork-toggle').click(), 1)"},
                        {"until": "!!document.querySelector('#list details.resting li.forks')"}, {"eval": under},
                        {"eval": "[...document.querySelectorAll('.fork-toggle[aria-expanded=\"false\"]')].forEach(t => t.click()); 1"},
                        {"until": "document.querySelectorAll('#list details.resting li.forks').length === 2"}, {"eval": where},
                        {"eval": "(document.querySelector('#list details.resting .btn.danger').click(), 1)"},
                        {"eval": "document.getElementById('confirm-title').textContent"})
        self.assertEqual(json.loads(got[-6]["eval"]), ["beta", "gamma"])
        self.assertEqual(json.loads(got[-3]["eval"]), [[True, None], [True, "delta"]])
        self.assertEqual(got[-1]["eval"], "Remove 4 sessions from the list?")   # alpha, beta, gamma, delta — not epsilon

