    def test_mermaid_payloads_from_advisories_run_no_script(self):
        # a session that quoted someone else's diagram must not run a script from the hub page. The payloads follow the
        # mermaid advisories GHSA-7rqq-prvp-x9jh (sequence label with KaTeX), GHSA-8gwm-58g9-j8pw (iconText in architecture)
        # and GHSA-ghcm-xqfw-q4vr (classDef in state escapes the SVG)
        seq = ("sequenceDiagram\n    participant A as Alice<img src=\"x\" onerror=\"window.__xss_seq=1\">$$\\\\text{Alice}$$\n"
               "    A->>John: Hello John")
        arch = ("architecture-beta\n    group api(cloud)[API]\n"
                "    service db \"<img src=x onerror=\\\"window.__xss_arch=1\\\">\" [Database] in api")
        state = ("stateDiagram-v2\n  classDef xss fill:red</style></svg><img src=x onerror=\"window.__xss_state=1\">"
                 "<div id=\"pwned-box\">HACKED</div><svg><style>a:b\n  [*] --> A:::xss")
        good = "flowchart LR\n  A[Hub] --> B[Specialist]"
        text = "\n\n".join(f"```mermaid\n{c}\n```" for c in (seq, arch, state, good))
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        self.ev("session.said", "a", text="Diagrams:\n\n" + text)
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Diagrams"},
                        {"until": "[...document.querySelectorAll('.mermaid-box svg')].some(s => s.textContent.includes('Specialist'))",
                         "ms": 15000},
                        {"sleep": 1500},
                        {"eval": "[window.__xss_seq, window.__xss_arch, window.__xss_state]"},
                        {"eval": "[...document.querySelectorAll('.mermaid-box :is(img, script, iframe, [onerror], [onload])')].length"},
                        {"eval": "!!document.getElementById('pwned-box')"})
        self.assertTrue(got[2]["until"], "an ordinary diagram next to the payloads is still drawn")
        self.assertEqual(got[4]["eval"], [None, None, None])
        self.assertEqual(got[5]["eval"], 0)
        self.assertFalse(got[6]["eval"], "markup from classDef escaped the diagram")

