    def test_markdown_drops_classes_of_the_page(self):
        # a class or data-* from the text borrows the page's own layers and hooks: class="lightbox" is a fixed layer
        # over the page, a fake viewer on top of the hub; data-next is rewritten by a ticker. Only marked's language-*
        # on a code block stays (highlighter, diagrams)
        text = ('Look:\n\n<div class="lightbox open">fake viewer</div><span class="btn primary">fake button</span>'
                '<code class="language-js lightbox">x</code><span data-next="1" data-key="row-1">fake clock</span>'
                '<span data-conn-at="1">fake wait</span>'
                '\n\n```python\nprint(1)\n```')
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        self.ev("session.said", "a", text=text)
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "fake viewer"},
                        {"eval": "[...document.querySelectorAll('.md *')].filter(n => getComputedStyle(n).position === 'fixed').length"},
                        {"eval": "[...document.querySelectorAll('.md :is(div, span)')].filter(n => /fake/.test(n.textContent))"
                                 ".map(n => n.className)"},
                        {"eval": "[...document.querySelectorAll('.md code')].map(n => n.className)"},
                        {"eval": "document.querySelectorAll('.md :is([data-next], [data-key], [data-conn-at])').length"})
        self.assertEqual(got[2]["eval"], 0, "no fixed layer from the text")
        self.assertEqual(got[3]["eval"], ["", "", "", ""])
        self.assertEqual(got[5]["eval"], 0, "the page's tickers and scroll anchor do not find the text")
        self.assertEqual(got[4]["eval"][0], "language-js")
        self.assertIn("language-python", got[4]["eval"][1])

    def test_a_diagram_label_is_not_taken_for_a_clock_of_the_page(self):
        # a diagram's HTML labels are the text's own markup, and the page finds its nodes by data-* and classes: the
        # clock rewrote a label with data-next (or class "elapsed") every second. data-* go from the labels (mermaid puts
        # none there), the classes stay (formulas need theirs) — the clocks look only at the page's own nodes
        text = ('Plan:\n\n```mermaid\nflowchart LR\n  A["<span data-next=\'1\'>Clock label</span>"] --> B[Two]\n'
                '  B --> C["<span class=\'elapsed\'>Watch label</span>"]\n```')
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        self.ev("session.said", "a", text=text)
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Plan"},
                        {"until": "[...document.querySelectorAll('.mermaid-box svg')].some(s => s.textContent.includes('Two'))",
                         "ms": 15000},
                        {"eval": "document.querySelectorAll('.mermaid-box foreignObject [data-next]').length"},
                        {"eval": "[...document.querySelectorAll('.mermaid-box svg *')].some(n => !n.closest('foreignObject')"
                                 " && [...n.attributes].some(a => a.name.startsWith('data-')))"},
                        {"sleep": 2500},
                        {"eval": "[...document.querySelectorAll('.mermaid-box foreignObject span')].map(n => n.textContent)"
                                 ".filter(x => /label/.test(x))"},
                        {"eval": "document.querySelectorAll('.mermaid-box .elapsed').length"})
        self.assertTrue(got[2]["until"], "the diagram is drawn")
        self.assertEqual(got[3]["eval"], 0, "a label keeps no data-*")
        self.assertTrue(got[4]["eval"], "mermaid's own data-* on the SVG nodes stay")
        self.assertIn("Clock label", got[6]["eval"])
        self.assertIn("Watch label", got[6]["eval"])
        self.assertEqual(got[7]["eval"], 1, "the label keeps its class: the case is real")

    def test_code_block_has_a_copy_button(self):
        # a code block in a reply (a terminal command) is copied whole by a button, with no button label; at an address on
        # the home network (http, not localhost) navigator.clipboard is absent — the fallback path copies
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        self.ev("session.said", "a", text="Enter the command:\n\n```\nsudo passwd user\n```\n\nand then:\n\n```sh\nls -la\npwd\n```")
        def clipboard(api):
            return (f"window.copied = window.copied || []; Object.defineProperty(navigator, 'clipboard', "
                    f"{{configurable: true, value: {api}}}); 1")
        api = "{writeText: (t) => { copied.push(t); return Promise.resolve(); }}"
        refused = "{writeText: (t) => Promise.reject(new Error('NotAllowedError'))}"
        by_hand = ("document.execCommand = (c) => { copied.push(c + ':' + document.getSelection().toString()); "
                   "return window.handWorks; }; 1")
        def click(i):
            return f"(() => {{ document.querySelectorAll('.md .code-copy')[{i}].click(); return 1; }})()"
        def sign(i):
            return f"document.querySelectorAll('.md .code-copy')[{i}].querySelector('use').getAttribute('href').split('#')[1]"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Enter the command"},
                        {"eval": clipboard(api)}, {"eval": click(0)}, {"sleep": 200},                        # 4
                        {"eval": f"[copied, document.querySelector('.md .code-copy').title, {sign(0)}]"},   # 5
                        {"eval": clipboard("undefined")}, {"eval": "window.handWorks = true; " + by_hand},
                        {"eval": click(1)}, {"sleep": 200}, {"eval": "copied"},                            # 10
                        {"eval": clipboard(refused)}, {"eval": click(1)}, {"sleep": 200},
                        {"eval": "copied"},                                                                # 14
                        {"eval": "window.handWorks = false; 1"}, {"eval": click(1)}, {"sleep": 200},
                        {"eval": f"[{sign(1)}, document.querySelectorAll('.md .code-copy')[1].title]"},   # 18
                        {"eval": "[getComputedStyle(document.querySelectorAll('.md .code-box')[1]).marginBottom, "
                                 "document.querySelectorAll('.code-copy-src').length]"})
        copied, label, check = got[5]["eval"]
        self.assertEqual(copied, ["sudo passwd user"])
        self.assertEqual([label, check], ["Copied", "i-allow"])   # a check-mark icon instead of "copy"
        self.assertEqual(got[10]["eval"][-1], "copy:ls -la\npwd")
        self.assertEqual(got[14]["eval"][1:], ["copy:ls -la\npwd"] * 2)   # writeText refused — the fallback path copies
        self.assertEqual(got[18]["eval"], ["i-deny", "Could not copy"])   # the failure is visible even without a tooltip
        self.assertEqual(got[19]["eval"], ["0px", 0])   # a code block at the end of a reply — no bottom padding; textarea removed

    def test_stop_says_it_is_stopping_and_takes_one_press(self):
        # analysis: six presses of "Stop" in two seconds — the button gave no response
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="long work")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Stop"}, {"click": "Stop"},
                        {"wait": "Stopping"}, {"eval": "[...document.querySelectorAll('main button')].find(b => b.textContent.includes('Stopping')).disabled"},
                        {"sleep": 300})
