    # a keystroke in the field is on the screen by the next frame: from the input event to the frame after it, the median
    # is under this (ms), and no keystroke waits longer than the worst (a busy test machine draws slower than a person's)
    KEY_MEDIAN_MS, KEY_WORST_MS = 50, 150

    def test_keystrokes_appear_at_once_with_a_long_feed_and_a_working_session(self):
        # owner's requirement: the client is responsive — no stutter, typed keys appear without delay; here the field is
        # typed into while the session works and its long feed grows by a message every 150 ms. A key's delay is the time
        # until the page handled it (measured outside the page: a key waiting behind a long task is counted) plus the
        # time from the end of its handling to the next painted frame (the handling itself is counted once)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        for i in range(300):
            self.ev("session.said", "a", text=f"line {i}: **bold** words, `code`, a [link](https://example.com/{i}) and a list:\n- one\n- two")
        self.ev("turn.started", "a", marker=None, prompt_head="long work")
        stop = threading.Event()
        def grow():
            n = 0
            while not stop.wait(0.15):
                n += 1
                self.ev("session.said", "a", text=f"live {n}: the session keeps writing while the owner types")
        live = threading.Thread(target=grow, daemon=True)
        watch = ("(() => { window.__lat = []; const f = document.querySelector('#msg'); f.focus(); "
                 "f.addEventListener('input', (e) => { const seen = performance.now(); requestAnimationFrame(() => "
                 "setTimeout(() => window.__lat.push(performance.now() - seen), 0)); }); return 1; })()")
        word = "the quick brown fox jumps over the lazy dog"
        live.start()
        try:
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "line 299"}, {"sleep": 500}, {"eval": watch},
                            *[{"typed": c} for c in word], {"sleep": 400},
                            {"eval": "[document.querySelector('#msg').value, window.__lat]"})
        finally:
            stop.set()
            live.join()
        value, paint = got[-1]["eval"]
        handled = [s["ms"] for s in got if "typed" in s]
        self.assertEqual(value, word)
        self.assertEqual(len(paint), len(word))
        lat = sorted(h + p for h, p in zip(handled, paint))
        self.assertLessEqual(lat[len(lat) // 2], self.KEY_MEDIAN_MS, lat)
        self.assertLessEqual(lat[-1], self.KEY_WORST_MS, lat)

    def vitals_stand(self):
        for n in ("a", "b", "c"):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True)
            self.ev("session.started", n, session_id=f"s-{n}")
        for n in ("b", "c"):   # busy: Clean shows a state sign only for a session that is doing something
            self.ev("turn.started", n, marker=None, prompt_head="work")
        for i in range(200):
            self.ev("session.said", "a", text=f"line {i}: **bold** words, `code` and a list:\n- one\n- two")
            self.ev("message.received", None, to="a", text=f"question {i} from the owner", channel="web", owner=True)

    # Google's "good" limits for a page (the ones Lighthouse scores): the layout moves by at most this much while it loads
    # (Cumulative Layout Shift), and the largest thing on the first screen is drawn within this many ms
    # (Largest Contentful Paint); the page is local, so its paint is far faster than the limit
    CLS_GOOD, LCP_GOOD_MS = 0.1, 2500
    VITALS = ("(window.__vitals = null, new Promise((done) => { let cls = 0, lcp = 0; "
              "new PerformanceObserver((l) => { for (const e of l.getEntries()) if (!e.hadRecentInput) cls += e.value; })"
              ".observe({type: 'layout-shift', buffered: true}); "
              "new PerformanceObserver((l) => { for (const e of l.getEntries()) lcp = Math.max(lcp, e.startTime); })"
              ".observe({type: 'largest-contentful-paint', buffered: true}); "
              "setTimeout(() => done([Math.round(cls * 1000) / 1000, Math.round(lcp)]), 300); })"
              ".then((v) => { window.__vitals = v; }), 1)")

    def test_the_page_loads_without_layout_shifts_and_paints_fast_on_a_phone_and_a_desktop(self):
        # owner's requirement: load progress, layout shifts and render speed by Google Lighthouse's criteria — the list
        # and a session's long feed, Classic and Clean, a phone and a desktop: the shifts of the whole load (with the
        # snapshot, the feed, the plugins) stay under "good", and the largest paint comes within it
        self.vitals_stand()
        base = f"http://127.0.0.1:{self.port}"
        for theme in ("core:classic", "core:clean"):
            for width, height in ((390, 844), (1440, 900)):
                for where, ready in (("#/", "document.querySelectorAll('#list .srow').length >= 3"),
                                     ("#/s/a", "document.querySelector('main .feed')?.innerText.includes('line 199')")):
                    got = self.page({"go": "about:blank", "look": None}, {"local": {"hub.theme": json.dumps({"id": theme})}},
                                    {"shot": os.path.join(self.state, "vitals.png"), "width": width, "height": height},
                                    {"go": f"{base}/{where}", "look": None}, {"until": ready, "ms": 10000}, {"sleep": 1500},
                                    {"eval": self.VITALS}, {"until": "!!window.__vitals"}, {"eval": "window.__vitals"})
                    what = (theme, width, where)
                    self.assertTrue(got[4]["until"], what)
                    cls, lcp = got[-1]["eval"]
                    self.assertLessEqual(cls, self.CLS_GOOD, what)
                    self.assertGreater(lcp, 0, what)
                    self.assertLessEqual(lcp, self.LCP_GOOD_MS, what)

    # the parts that stand in one line or one column are aligned to the pixel: the header's controls on one centre line,
    # the list's rows with their state icons and names in one column, the feed's messages of one kind in one column
    ALIGNED = ("(() => { const vis = (n) => n && n.getClientRects().length && getComputedStyle(n).visibility !== 'hidden'; "
               "const box = (n) => n.getBoundingClientRect(); const out = {}; "
               "const head = document.querySelector('main .head'); "
               "out.head = head ? [...head.children].filter((c) => vis(c) && box(c).height > 0 && box(c).width > 0)"
               ".map((c) => Math.round(box(c).top + box(c).height / 2)) : []; "
               "const rows = [...document.querySelectorAll('#list .sgroup > ul > li[data-s] > .srow, #list > li[data-s] > .srow')].filter(vis); "
               "out.glyph = rows.map((r) => r.querySelector('.glyph')).filter(vis).map((g) => Math.round(box(g).left)); "
               "out.name = rows.map((r) => r.querySelector('.txt')).filter(vis).map((t) => Math.round(box(t).left)); "
               "const kinds = {}; for (const r of document.querySelectorAll('main .feed .row')) { if (!vis(r)) continue; "
               "const b = r.querySelector(':scope > .b'); if (!vis(b)) continue; const right = r.classList.contains('mine'); "
               "(kinds[r.className] ||= []).push(Math.round(right ? box(b).right : box(b).left)); } "
               "out.feed = kinds; return out; })()")

    def spread(self, xs):
        return max(xs) - min(xs) if xs else 0

    def test_the_header_the_list_and_the_feed_are_aligned(self):
        # owner's requirement: everything is aligned (the UI Polish check) — Classic and Clean, light and dark, a phone
        # and a desktop: what stands in a line has one centre, what stands in a column has one left edge
        self.vitals_stand()
        base = f"http://127.0.0.1:{self.port}"
        for theme in ("core:classic", "core:clean", "core:clean-dark"):
            for width, height in ((390, 844), (1440, 900)):
                for where in ("#/", "#/s/a"):
                    got = self.page({"go": "about:blank", "look": None}, {"local": {"hub.theme": json.dumps({"id": theme})}},
                                    {"shot": os.path.join(self.state, "aligned.png"), "width": width, "height": height},
                                    {"go": f"{base}/{where}", "look": None},
                                    {"until": "document.querySelectorAll('#list .srow').length >= 3 && "
                                              + ("document.querySelector('main .feed')?.innerText.includes('line 199')" if where == "#/s/a" else "true"),
                                     "ms": 10000}, {"sleep": 800}, {"eval": self.ALIGNED})
                    what = (theme, width, where)
                    seen = got[-1]["eval"]
                    if width > 760 and where == "#/s/a":   # everything measured is on screen here: an empty match is a broken selector
                        self.assertTrue(seen["head"] and seen["glyph"] and seen["name"] and seen["feed"], (what, seen))
                    self.assertLessEqual(self.spread(seen["head"]), 1, (what, "header", seen["head"]))
                    self.assertLessEqual(self.spread(seen["glyph"]), 1, (what, "list icons", seen["glyph"]))
                    self.assertLessEqual(self.spread(seen["name"]), 1, (what, "list names", seen["name"]))
                    for kind, xs in seen["feed"].items():
                        self.assertLessEqual(self.spread(xs), 1, (what, "feed", kind, xs))

