    def unread_stand(self, name="a", step_ago=90, step_after=False):
        """A busy session (name; "maps-x" — an executor of maps) in one long Bash step that started step_ago seconds ago,
        and the hub's urgent line inserted into it in the middle of that step (hub send --now); step_after — the line
        came before the step started (Claude Code passed a step boundary, so the step is not what it waits behind)."""
        t0 = time.time() - step_ago - 5
        at = lambda dt, type, entity=None, **data: self.j.append(type, entity, data, ts=t0 + dt)
        at(0, "session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        at(0, "session.started", "hub", session_id="s-h")
        if name == "maps-x":
            at(0, "session.requested", "maps", session_id="s-m", cwd="/w", channel="cli", owner=True)
            at(0, "session.started", "maps", session_id="s-m")
        at(1, "session.requested", name, session_id="s-x", cwd="/w", channel="cli", owner=True,
           **({"executor": True, "raised_by": "maps"} if name == "maps-x" else {}))
        at(1, "session.started", name, session_id="s-x")
        at(2, "turn.started", name, marker=None, prompt_head="long work")
        line = {"to": name, "text": "STOP, interrupt the step", "now": True, "channel": "session", "owner": False, "sender": "hub"}
        e = step_after and at(3, "message.received", None, **line)
        at(5, "turn.tool", name, id="t1", name="Bash", input={"command": "sleep 600"})
        e = e or self.j.append("message.received", None, line)
        self.settle()
        return f"m{e['seq']}"

    UNREAD_META = ("[...document.querySelectorAll('main .feed .row')].filter((r) => r.textContent.includes('STOP, interrupt the step'))"
                   ".map((r) => r.querySelector('.meta').textContent)")
    UNREAD_ROW = "document.querySelector('.strip-row[data-k=unread]')"

    def test_an_insertion_mid_step_says_not_read_yet_with_the_step_and_a_button_to_interrupt(self):
        # 27.10: "STOP" inserted mid-step waited 4 min 45 s for the step to end while the page said "delivered"
        mid = self.unread_stand()
        row = self.UNREAD_ROW
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": "main.dataset.for === 'a'"},
                        {"eval": self.PREP}, {"until": f"!!{row}"}, {"eval": self.UNREAD_META},
                        {"eval": f"[{row}.querySelector('.k').textContent, {row}.querySelector('.t').textContent, "
                                 f"{row}.querySelector('.t').title, [...{row}.querySelectorAll('button')].map((b) => b.textContent)]"},
                        {"eval": f"({row}.querySelector('button').click(), 1)"},
                        {"until": f"{row}.querySelector('button').textContent === 'Stopping…'"}, {"sleep": 300})
        self.assertTrue(got[3]["until"] and got[7]["until"], got)
        (meta,) = got[4]["eval"]
        self.assertRegex(meta, r"inserted, not read yet · Bash step running 1 min \d+ s$")
        k, text, hint, buttons = got[5]["eval"]
        self.assertEqual(k, "Not read yet")
        self.assertRegex(text, r"^Bash step running 1 min \d+ s — what was inserted mid-turn is not read yet: ")
        self.assertIn("a reading inside the turn without it is not visible", hint)   # the core does not see a reading inside the turn
        self.assertEqual(buttons, ["Interrupt turn"])   # not an executor: the turn, as Esc
        asked = [e for e in self.spooled() if e["type"] in ("session.interrupt_requested", "session.stop_requested")]
        self.assertEqual([(e["type"], e["entity"]) for e in asked], [("session.interrupt_requested", "a")])
        # read: a turn with its mark started — "delivered", no row
        self.ev("turn.tool_result", "a", id="t1", is_error=False, text="ok")
        self.ev("turn.started", "a", marker=mid, prompt_head="(urgent — came in the middle of your turn: take it into account now) STOP")
        self.settle()
        got = self.page({"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/s/a"},
                        {"until": "main.dataset.for === 'a'"},
                        {"until": "document.querySelector('main').innerText.includes('STOP, interrupt the step')"},
                        {"eval": self.UNREAD_META}, {"eval": f"!!{row}"})
        self.assertTrue(got[3]["until"], got)
        self.assertEqual(got[4]["eval"], [got[4]["eval"][0]])
        self.assertNotIn("not read yet", got[4]["eval"][0])
        self.assertIn("delivered", got[4]["eval"][0])
        self.assertFalse(got[5]["eval"])

