    def test_more_menu_stays_inside_the_pane_when_the_button_wraps_left(self):
        # in a narrower window the "More" button wraps to the start of the header's second row, and the menu opened to the
        # left of it — under the side panel, items clipped. The menu aligns to the button's right edge only if there is room
        # on the left
        self.ev("session.requested", "maps", session_id="s-m", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "maps", session_id="s-m")
        self.ev("turn.started", "maps", marker=None)
        edge = ("(() => { const m = document.querySelector('.menu'), main = document.querySelector('main');"
                " return [Math.round(m.getBoundingClientRect().left - main.getBoundingClientRect().left),"
                " Math.round(main.getBoundingClientRect().right - m.getBoundingClientRect().right)]; })()")
        btn = "(() => { const r = document.querySelector('.menu-btn').getBoundingClientRect(); return [Math.round(r.left), Math.round(r.top)]; })()"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/maps"}, {"wait": "More"},
                        {"eval": "(document.querySelector('main').style.maxWidth = '560px', 1)"}, {"sleep": 200}, {"eval": btn}, {"eval": "(document.querySelector('.menu-btn').click(), 1)"},
                        {"until": "document.querySelector('.menu')"}, {"sleep": 100}, {"eval": edge})
        left, right = [g["eval"] for g in got if "eval" in g][-1]
        self.assertGreaterEqual(left, 0, got)        # does not go left of its panel
        self.assertGreaterEqual(right, 0, got)

