    def test_the_app_updates_by_its_button_and_can_return_the_previous_version(self):
        # installer S3: the app never installs by itself — "Update" and "Return <previous>" go straight to the update
        # process (its flag files), not through a turn of the hub session, which may not even be signed in
        from unittest import mock
        from core import packaged
        mark = os.path.join(self.state, "PACKAGED-app")
        with open(mark, "w") as f:
            json.dump({"format": "app", "runtime": 1}, f)
        p = mock.patch.object(packaged, "MARK", mark)
        p.start()
        self.addCleanup(p.stop)
        self.ev("update.checked", None, result="available", behind=2, version="v9.0.1", app=True, previous="v9.0.0",
                notes=["something new"], channel="cli", owner=True)
        box = "((document.querySelector('.upd-check') || {}).innerText || '')"
        got = self.page({"local": {"hub.settingsTab": "about"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": f"{box}.includes('v9.0.1')"}, {"eval": box},
                        {"eval": "[...document.querySelectorAll('.upd-check button')].find(b => b.textContent === 'Update').click()"},
                        {"until": "(() => { const b = [...document.querySelectorAll('.upd-check button')]"
                                  ".find(b => b.textContent === 'Return v9.0.0'); if (b) b.click(); return !!b; })()"},
                        {"sleep": 800})
        self.assertTrue(got[2]["until"])
        text = got[3]["eval"]
        self.assertIn("Update installs it", text)
        self.assertNotIn("installs itself", text)                      # never "installs itself after …"
        self.assertTrue(got[5]["until"])
        self.assertTrue(os.path.exists(os.path.join(self.state, "update.install")))
        with open(os.path.join(self.state, "update.rollback")) as f:
            self.assertEqual(f.read(), "v9.0.0")                       # the release the button named: a repeat goes no further
        self.assertEqual([e for e in self.spooled() if e["type"] == "message.received"], [])

