    def test_about_says_what_to_do_when_github_does_not_let_the_hub_in(self):
        # R1: the update check showed git's raw text, and the private modules line always said "accept the invitation"
        # whatever the cause; now each cause gets its own thing to do, an unrecognised one stays as git worded it
        self.ev("update.checked", None, result="error", channel="cli", owner=True,
                error="git fetch origin: fatal: could not read Username for 'https://github.com': No such device or address")
        self.ev("update.modules", None, ok=False, access=False, missing=["stats"], modules={"stats": "missing"}, ref="pm-v1.0.0",
                why="git@github.com: Permission denied (publickey).", channel="cli", owner=True)
        # not all of "main": "What is new" there carries the text of CHANGES
        facts = "((document.querySelector('.about-facts') || {}).innerText || '') + ((document.querySelector('.upd-check') || {}).innerText || '')"
        got = self.page({"local": {"hub.settingsTab": "about"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": f"(() => {{ const t = {facts}; return t.includes('gh auth login') && t.includes('ssh key'); }})()"},
                        {"eval": facts})
        self.assertTrue(got[-2]["until"])
        text = got[-1]["eval"]
        self.assertIn("could not check", text)
        self.assertIn("gh auth login", text)                       # no sign-in: how to sign in
        self.assertIn("ssh key", text)                            # the modules: the key, not the invitation
        self.assertNotIn("accept the invitation", text)
        # an unrecognised cause: git's words, no invented advice
        self.ev("update.modules", None, ok=False, access=False, missing=["stats"], modules={"stats": "missing"}, ref="pm-v1.0.0",
                why="fatal: disk quota exceeded", channel="cli", owner=True)
        got = self.page({"local": {"hub.settingsTab": "about"}}, {"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": f"(() => {{ const t = {facts}; return t.includes('disk quota exceeded'); }})()"}, {"eval": facts})
        self.assertTrue(got[-2]["until"])
        self.assertIn("Git said", got[-1]["eval"])
        self.assertNotIn("ssh key", got[-1]["eval"])
        # no words from git at all: no empty quotes either
        self.ev("update.modules", None, ok=False, access=False, missing=["stats"], modules={"stats": "missing"}, ref="pm-v1.0.0",
                why="", channel="cli", owner=True)
        got = self.page({"local": {"hub.settingsTab": "about"}}, {"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": f"(() => {{ const t = {facts}; return t.includes('no access to the modules repository') && !t.includes('disk quota'); }})()"},
                        {"eval": facts})
        self.assertTrue(got[-2]["until"])
        self.assertNotIn("Git said", got[-1]["eval"])

    def test_about_shows_which_claude_versions_fit(self):
        # show in the hub what is compatible and what is not — the Claude Code version of sessions against the
        # required one
        from unittest import mock
        from core import version
        for n, v in (("a", "2.1.291"), ("b", "2.1.291"), ("old", "2.1.218")):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True)
            self.ev("session.started", n, session_id=f"s-{n}")
            self.ev("session.info", n, version=v, model="m")
        # a sleeping session keeps the version from its last run, but will wake on the current claude — do not count it
        # (several shown although they are asleep)
        self.ev("session.requested", "nap", session_id="s-nap", cwd="/w", channel="cli", owner=True, executor=True)
        self.ev("session.started", "nap", session_id="s-nap")
        self.ev("session.info", "nap", version="2.1.100", model="m")
        self.ev("session.stop_requested", "nap", channel="cli", owner=True)    # the executor is asleep
        with mock.patch.object(version, "MIN_CLAUDE", "2.1.290"):
            got = self.page({"local": {"hub.settingsTab": "about"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                            {"wait": "Older than needed"}, {"eval": "document.querySelector('.claude-compat').innerText"})
        text = [g["eval"] for g in got if "eval" in g][-1]
        self.assertIn("2.1.290", text)          # required: not older than
        self.assertIn("2.1.291", text)          # of the sessions
        self.assertIn("old", text)              # who is older — by name
        self.assertIn("2.1.218", text)
        self.assertNotIn("2.1.100", text)       # a sleeping one does not count
        self.assertNotIn("nap", text)

