    def test_about_counts_all_unpublished_changes_not_the_cut_list(self):
        # owner report: "Unpublished changes: 40" is always 40: the server returns 40 list rows, the number is the full count
        code = self.web.code
        rows = [f"a{i:06d} change {i}" for i in range(40)]
        about = {"local": {"hub.settingsTab": "about"}}
        self.web.code = lambda: {**code(), "upstream": False, "unpublished": rows, "unpublished_count": 57}
        got = self.page(about, {"go": f"http://127.0.0.1:{self.port}/#/settings"}, {"wait": "Unpublished changes: 57"},
                        {"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/updates"},
                        {"wait": "Unpublished: 57"}, {"wait": "change 39"}, {"eval": "document.querySelector('.feed-inner').innerText"},
                        {"eval": "[...document.querySelectorAll('.feed-inner .hint')].filter(p => p.innerText.startsWith('and ')).map(p => p.innerText).join()"})
        self.assertEqual(got[-1]["eval"], "and 17 more")      # 57 minus the 40 shown
        self.assertEqual(len(re.findall(r"\bchange \d+\b", got[-2]["eval"])), 40)   # the page's own "what's new" may say "change"
        # an old server sends no number — as before, by list length, without "and N more"
        self.web.code = lambda: {**code(), "upstream": False, "unpublished": rows}
        got = self.page(about, {"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/settings"}, {"wait": "Unpublished changes: 40"},
                        {"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/updates"},
                        {"wait": "Unpublished: 40"}, {"wait": "change 39"}, {"eval": "[...document.querySelectorAll('.feed-inner .hint')].filter(p => p.innerText.startsWith('and ')).map(p => p.innerText).join()"})
        self.assertEqual(got[-1]["eval"], "")

