    def quiet_feed(self):
        """The feed for the PR #99 modes: a hub message (real name — hub-core), a finished turn with a step, a `hub wait` check
        and an ordinary scheduled job, a running turn."""
        self.ev("session.requested", "hub-core", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("session.started", "hub-core", session_id="s-h")
        first = self.j.append("message.received", None, {
            "to": "a", "text": "Look at the set and do it", "channel": "session", "owner": False, "sender": "hub-core"})
        self.ev("turn.started", "a", marker=f"m{first['seq']}", prompt_head="Look")
        self.tool("a", "t0", "ls-done")
        self.ev("turn.tool_result", "a", id="t0", text="ok", error=False)
        self.ev("session.said", "a", text="accepted")
        self.ev("turn.result", "a", text="accepted")
        self.ev("turn.stopped", "a")
        import time as _t
        prompt = ("[waiting for reply] a colleague's reply in the releases chat. Check now; a reaction is a reply too. If there is a reply, run "
                  "`hub wait done` and go on with the task. If there is none, end the turn with the single character \"—\".")
        self.ev("schedule.set", "a-wait-7738-1", session="a", at=_t.time() - 5, channel="cli", owner=False, prompt=prompt)
        due = self.j.append("schedule.due", "a-wait-7738-1", {"slot": _t.time(), "channel": "core"})
        self.ev("turn.started", "a", marker=f"m{due['seq']}", prompt_head="[⏰")
        self.ev("turn.result", "a", text="—")
        self.ev("turn.stopped", "a")
        self.ev("schedule.set", "a-daily", session="a", every="1d", channel="cli", owner=True, prompt="daily digest of chats")
        due = self.j.append("schedule.due", "a-daily", {"slot": _t.time(), "channel": "core"})
        self.ev("turn.started", "a", marker=f"m{due['seq']}", prompt_head="[⏰")
        self.ev("turn.result", "a", text="—")
        self.ev("turn.stopped", "a")
        e = self.j.append("message.received", None, {"to": "a", "text": "go ahead", "channel": "cli", "owner": True})
        self.ev("turn.started", "a", marker=f"m{e['seq']}", prompt_head="go ahead")
        self.tool("a", "t1", "ls-quiet")

    LOOK = ("(() => ({names: [...document.querySelectorAll('.chat-names')].map(n => n.textContent).join('|'), "
            "count: document.querySelectorAll('.chat-count').length, "
            "preview: [...document.querySelectorAll('.chat-preview')].map(n => n.textContent).join('|'), "
            "steps: [...document.querySelectorAll('.steps')].map(n => n.textContent)}))()")

    def test_silent_result_and_developer_lines_are_not_on_the_page(self):
        # the quiet result "—" is not drawn on the page: a check turn that ended with "—", in "Brief" with no reply — its
        # remarks during the turn ("No changes…", "Nothing new…") do not stand as a reply; a turn with a real reply — as
        # before. "session created" and the wake-up after parking — only in hub show
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        e = self.j.append("message.received", None, {"to": "a", "text": "check the rollout", "channel": "web", "owner": True})
        self.ev("turn.started", "a", marker=f"m{e['seq']}", prompt_head="check the rollout")
        self.tool("a", "t1", "curl -s stage/health")
        self.ev("session.said", "a", text="Rollout went fine, no errors.")
        self.ev("turn.result", "a", text="Rollout went fine, no errors.")
        self.ev("turn.stopped", "a")
        e = self.j.append("message.received", None, {"to": "a", "text": "check tick", "channel": "session",
                                                     "owner": False, "sender": "hub"})
        self.ev("turn.started", "a", marker=f"m{e['seq']}", prompt_head="check tick")
        self.tool("a", "t2", "curl -s stage/queue")
        self.ev("session.said", "a", text="No changes, the queue is empty.")
        self.ev("session.said", "a", text="—")
        self.ev("turn.result", "a", text="—")
        self.ev("turn.stopped", "a")
        self.ev("session.started", "a", session_id="s-a", source="resume")
        main = "document.querySelector('main').innerText"
        look = (f"(() => ({{dash: /^—$/m.test({main}), born: {main}.includes('session created'), "
                f"resumed: {main}.includes('brought up again'), "
                "answers: [...document.querySelectorAll('.row.out .b')].map(n => n.textContent).join('|')}))()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "compact"}, {"wait": "Rollout went fine"},
                        {"eval": look})
        seen = got[-1]["eval"]
        self.assertFalse(seen["dash"] or seen["born"] or seen["resumed"], seen)
        self.assertIn("Rollout went fine, no errors.", seen["answers"])
        self.assertNotIn("No changes", seen["answers"])        # a quiet turn's remark is not a reply
        got = self.page({"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"},
                        {"wait": "No changes"}, {"eval": look})
        seen = got[-1]["eval"]
        self.assertFalse(seen["dash"] or seen["born"] or seen["resumed"], seen)

    def test_brief_folds_core_and_session_mail_into_one_line(self):
        # in "Brief" the core's exchange with a session (the "hub restart cut off your turn" text, the hub restart cut off
        # your turn; the executor's REPLIED) showed one row per message — back to back, although nothing visible is between
        # them (the turn replied "—"). Adjacent collapsed groups with nothing visible between them are one row; a visible
        # reply breaks it. "Detailed" — as it was
        self.ev("session.requested", "hub-core", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "hub-core", session_id="s-h")
        self.ev("session.started", "a", session_id="s-a")

        def turn(marker, answer, head="x"):
            self.ev("turn.started", "a", marker=marker, prompt_head=head)
            self.tool("a", f"t{marker}", "ls")
            self.ev("turn.tool_result", "a", id=f"t{marker}", text="ok", error=False)
            if answer == "failure":   # a turn error is visible in "Brief" — it separates too
                self.ev("turn.result", "a", text="API Error: overloaded", is_error=True)
            else:
                self.ev("session.said", "a", text=answer)
                self.ev("turn.result", "a", text=answer)
            self.ev("turn.stopped", "a")

        e = self.j.append("message.received", None, {"to": "a", "text": "check the rollout", "channel": "web", "owner": True})
        turn(f"m{e['seq']}", "Rollout done.")
        self.ev("turn.started", "a", marker=None)          # the turn was cut off by a restart — the core writes "continue" to the session
        self.ev("session.exited", "a", code=0)
        cut = self.j.append("session.started", "a", {"session_id": "s-a"})
        turn(f"m{cut['seq']}x3", "—")
        for text, answer in (("REPLIED: executor replied first", "—"), ("REPLIED: executor replied second", "Result for the owner."),
                             ("REPLIED: executor replied third", "—"), ("REPLIED: executor replied fourth", "failure"),
                             ("REPLIED: executor replied fifth", "—"), ("owner message between", "—"),
                             ("REPLIED: executor replied sixth", "—")):
            mine = text.startswith("owner message")   # the owner's words in view — also separate
            e = self.j.append("message.received", None, {"to": "a", "text": text, **(
                {"channel": "web", "owner": True} if mine else {"channel": "session", "owner": False, "sender": "hub-core"})})
            turn(f"m{e['seq']}", answer)
        look = ("(() => [...document.querySelectorAll('.chat-group')].map(g => ({names: g.querySelector('.chat-names').textContent, "
                "preview: g.querySelector('.chat-preview').textContent, open: g.querySelector('.chat-head').getAttribute('aria-expanded'), "
                "inside: [...g.querySelectorAll('.chat-body .row')].length})))()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "compact"}, {"wait": "Result for the owner"},
                        {"eval": look}, {"eval": "document.querySelector('main').innerText"})
        groups, text = got[-2]["eval"], got[-1]["eval"]
        # core, first, second — one row; third and fourth — after the reply; fifth — after the error; sixth — after the
        # owner
        self.assertEqual(len(groups), 4, groups)
        self.assertIn("Core", groups[0]["names"])
        self.assertIn("Hub", groups[0]["names"])
        # the group row is the start of the last message (owner decision)
        self.assertEqual([("second" in groups[0]["preview"]), ("fourth" in groups[1]["preview"])], [True, True], groups)
        self.assertIn("fifth", groups[2]["preview"])
        self.assertIn("sixth", groups[3]["preview"])
        self.assertLess(text.index("fifth"), text.index("owner message between"))
        self.assertLess(text.index("owner message between"), text.index("sixth"))
        self.assertIn("overloaded", text)
        self.assertLess(text.index("overloaded"), text.index("fifth"))
        self.assertLess(text.index("Rollout done"), text.index("executor replied second"))
        self.assertLess(text.index("executor replied second"), text.index("Result for the owner"))
        self.assertLess(text.index("Result for the owner"), text.index("fourth"))
        self.assertNotIn("first", text)                        # collapsed
        got = self.page({"eval": "document.querySelector('.chat-head').click(); 1"}, {"wait": "executor replied first"}, {"eval": look})
        self.assertEqual(got[-1]["eval"][0]["inside"], 3, got[-1]["eval"])   # expanded with one click: all three
        got = self.page({"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "compact", "brief": {"last": False}},
                        {"wait": "Result for the owner"}, {"eval": look})
        groups = got[-1]["eval"]                               # the "by the last one" checkbox cleared — as it was
        self.assertIn(i18n.t("core.msg.cut_turn")[:23], groups[0]["preview"])   # the core's words in the hub's language
        self.assertIn("third", groups[1]["preview"])
        got = self.page({"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "Result for the owner"},
                        {"eval": "document.querySelectorAll('.chat-group').length"},
                        {"eval": "document.querySelector('main').innerText"})
        self.assertEqual(got[-2]["eval"], 0)                     # "Detailed" — every message in view
        for word in (i18n.t("core.msg.cut_turn")[:23], "first", "second", "third", "fourth", "fifth"):
            self.assertIn(word, got[-1]["eval"])

    def cut_turn_feed(self, want):
        """A turn of session a cut by a hub restart: the core's "continue" — in the strip while it is being typed, then
        in the feed, "Brief" and "Detailed"; want — the start of the text the page should show."""
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None)
        self.ev("session.exited", "a", code=0)
        cut = self.j.append("session.started", "a", {"session_id": "s-a"})
        strip = "((document.querySelector('.strip') || {}).innerText || '')"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "compact"},
                        {"until": f"{strip}.includes({json.dumps(want)})", "ms": 8000}, {"eval": strip})
        self.assertTrue(got[1]["until"], got)
        texts = [got[2]["eval"]]
        self.ev("turn.started", "a", marker=f"m{cut['seq']}x3", prompt_head="x")   # delivered: a row of the feed
        self.ev("session.said", "a", text="Continuing.")
        self.ev("turn.result", "a", text="Continuing.")
        feed = "((document.querySelector('.feed') || {}).innerText || '')"
        for mode in ("compact", "full"):
            got = self.page({"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": mode},
                            {"until": f"{feed}.includes({json.dumps(want)}) && {feed}.includes('Continuing')", "ms": 8000},
                            {"eval": feed})
            self.assertTrue(got[2]["until"], got)
            texts.append(got[3]["eval"])
        return texts

    def test_the_cores_words_to_a_session_read_in_russian_on_a_russian_hub(self):
        # 06.11, the owner: "this needs translating" — a Russian hub showed "A hub restart cut off your turn…" in the
        # feed; the session still reads the English, the row shows the same in the hub's language
        cfg = os.path.join(self.state, "hub-ru.json")   # the Russian hub: the tests' default is English
        with open(cfg, "w") as f:
            json.dump({"update": {"enabled": False}, "language": "ru"}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        i18n.use("ru")   # the server's texts: the hub's language (core/i18n.py current)
        self.addCleanup(i18n.use, "en")
        want = i18n.tr("ru", "core.msg.cut_turn")[:40]
        for text in self.cut_turn_feed(want):
            self.assertIn(want, text)
            self.assertNotIn("A hub restart cut off", text)
            self.assertNotIn("{nothing}", text)
        with self.web.tail.reading:   # the message itself, as the session gets it: English
            (msg,) = [m for m in self.web.tail.reader.state["messages"].values() if m["session"] == "a"]
        self.assertTrue(msg["text"].startswith("A hub restart cut off your turn"))

    def test_the_cores_words_to_a_session_read_in_english_on_an_english_hub(self):
        cfg = os.path.join(self.state, "hub-en.json")
        with open(cfg, "w") as f:
            json.dump({"update": {"enabled": False}, "language": "en"}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        i18n.use("en")   # the server's texts: the hub's language (core/i18n.py current)
        self.addCleanup(i18n.use, "en")
        for text in self.cut_turn_feed("A hub restart cut off your turn"):
            self.assertNotIn(i18n.tr("ru", "core.msg.cut_turn")[:20], text)

    def test_brief_hides_idle_schedule_turns_and_answer_retelling(self):
        # in "Brief" do not show a schedule turn that replied "—" (about 190 a day), nor the retelling
        # "the owner's answer to question qN" beside the "↳" row; checkboxes — as before.
        # "Detailed" — everything in view
        import time as _t
        self.ev("session.requested", "hub-core", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "hub-core", session_id="s-h")
        self.ev("session.started", "a", session_id="s-a")

        def due(job, prompt, answer, tool=False, command=False, before=False):
            self.ev("schedule.set", job, session="a", every="1d", channel="cli", owner=True, prompt=prompt)
            e = self.j.append("schedule.due", job, {"slot": _t.time(), "channel": "core"})
            if before:    # the owner's command between the tick and its turn — same tick, same turn
                self.ev("session.reload_requested", "a", channel="web", owner=True)
            self.ev("turn.started", "a", marker=f"m{e['seq']}", prompt_head="[⏰")
            if tool:
                self.tool("a", f"t{job}", "ls")
                self.ev("turn.tool_result", "a", id=f"t{job}", text="ok", error=False)
            if command:   # the owner's command mid-turn — a row after the group; an empty group does not break the feed
                self.ev("session.compact_requested", "a", channel="web", owner=True)
            self.ev("session.said", "a", text=answer)
            self.ev("turn.result", "a", text=answer)
            self.ev("turn.stopped", "a")

        e = self.j.append("message.received", None, {"to": "a", "text": "watch the queue", "channel": "web", "owner": True})
        self.ev("turn.started", "a", marker=f"m{e['seq']}", prompt_head="watch")
        self.ev("session.said", "a", text="Watching.")
        self.ev("turn.result", "a", text="Watching.")
        self.ev("turn.stopped", "a")
        due("a-tick", "queue tick empty", "—", tool=True)
        due("a-tick2", "queue tick second", "—")
        due("a-found", "queue tick with a finding", "A task is stuck in the queue.")
        due("a-tick4", "queue tick with a command", "—", command=True)  # one in the group: an emptied one is not in the feed
        e = self.j.append("message.received", None, {"to": "a", "text": "REPLIED: executor replied", "channel": "session",
                                                     "owner": False, "sender": "hub-core"})
        self.ev("turn.started", "a", marker=f"m{e['seq']}", prompt_head="REPLIED")
        self.ev("turn.result", "a", text="—")
        self.ev("turn.stopped", "a")
        due("a-tick3", "queue tick after", "—")
        due("a-tick5", "queue tick before the command", "—", before=True)
        # hub question as a card → owner's answer: a "↳" row and a core message to the hub with the retelling the answer
        # arrived while the question's turn is still running: the retelling is delivered after — that turn's reply is not
        # hidden under the steps
        self.ev("turn.started", "hub-core", marker=None, prompt_head="x")
        self.ev("permission.requested", "hub-core", request_id="r1", tool="AskUserQuestion", interactive=True,
                input={"questions": [{"question": "Release the build?", "options": [{"label": "Yes"}, {"label": "No"}]}]})
        e = self.j.append("permission.answered", "hub-core", {"request_id": "r1", "behavior": "allow",
                          "answers": {"Release the build?": "Yes"}, "channel": "web", "owner": True})
        self.tool("hub-core", "th", "ls")
        self.ev("turn.tool_result", "hub-core", id="th", text="ok", error=False)
        self.ev("session.said", "hub-core", text="Question asked, waiting for the answer.")
        self.ev("turn.result", "hub-core", text="Question asked, waiting for the answer.")
        self.ev("turn.stopped", "hub-core")
        _t.sleep(0.01)   # journal to the ms: the retelling is delivered later than the question's turn, as with a live hub
        self.ev("turn.started", "hub-core", marker=f"m{e['seq']}", prompt_head="The user's answer")
        self.ev("session.said", "hub-core", text="Releasing.")
        self.ev("turn.result", "hub-core", text="Releasing.")
        self.ev("turn.stopped", "hub-core")
        main = "document.querySelector('main').innerText"
        groups = "[...document.querySelectorAll('.chat-group .chat-preview')].map(n => n.textContent)"
        a = f"http://127.0.0.1:{self.port}/#/s/a"
        to_hub = {"eval": "location.hash = '#/s/hub-core'; 1"}   # without a new load: the test stand holds at most five per test
        got = self.page({"go": a, "feed": "compact"}, {"wait": "stuck"}, {"eval": main}, {"eval": groups},
                        to_hub, {"wait": "Releasing"}, {"eval": main})
        text, prev, hub = got[2]["eval"], got[3]["eval"], got[-1]["eval"]
        self.assertNotIn("queue tick empty", text)                   # "—" with nothing visible — no schedule message
        self.assertNotIn("queue tick second", text)
        self.assertNotIn("queue tick after", text)
        self.assertNotIn("queue tick with a command", text)
        self.assertNotIn("queue tick before the command", text)
        self.assertIn("/reload", text)
        self.assertIn("/compact", text)
        self.assertIn("queue tick with a finding", " ".join(prev))   # a turn with a reply — in view
        self.assertIn("Watching.", text)                                  # neighbouring turns' replies — in place
        self.assertEqual(sum("REPLIED" in p for p in prev), 1, prev)  # a non-schedule exchange — as a row, as it was
        self.assertEqual(len(prev), 2, prev)
        self.assertIn("Release the build?", hub)
        self.assertIn("Yes", hub)                                  # the "↳" row in view
        self.assertNotIn("The user's answer to question", hub)             # no retelling
        self.assertIn("Question asked, waiting for the answer.", hub)              # the turn's reply before the retelling — in view
        on = {"idle": False, "relay": False, "groups": True}
        got = self.page({"go": "about:blank"}, {"go": a, "feed": "compact", "brief": on}, {"wait": "stuck"},
                        {"eval": main}, to_hub, {"wait": "Releasing"}, {"eval": main})
        text, hub = got[3]["eval"], got[-1]["eval"]
        for word in ("queue tick empty", "queue tick second", "queue tick after", "queue tick with a command",
                     "queue tick before the command"):   # checkboxes — as before
            self.assertIn(word, text)
        self.assertIn("The user's answer to question", hub)
        got = self.page({"go": "about:blank"}, {"go": a, "feed": "full"}, {"wait": "stuck"}, {"eval": main},
                        to_hub, {"wait": "Releasing"}, {"eval": main})
        for word in ("queue tick empty", "queue tick second", "queue tick after"):   # "Detailed" — unchanged
            self.assertIn(word, got[3]["eval"])
        self.assertIn("The user's answer to question", got[-1]["eval"])

    def test_brief_options_from_settings_hide_steps_and_counter(self):
        # PR #99: choose with checkboxes in the hub settings what to show in Brief; two views; "by default as in the
        # minimum". By default steps appear only for a running turn, no "N messages"; the checkboxes bring them back; the
        # choice is remembered
        self.quiet_feed()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "compact", "brief": {"idle": False, "last": False}}, {"wait": "go ahead"},
                        {"wait": "waiting for a reply"}, {"eval": self.LOOK},
                        {"eval": "document.querySelectorAll('main .head .seg button').length"})
        run, buttons = got[-2]["eval"], got[-1]["eval"]
        self.assertEqual(len(run["steps"]), 1, run)                  # by default — only the running turn
        self.assertIn("Working", run["steps"][0])
        self.assertEqual(run["count"], 0)
        self.assertIn("Hub", run["names"])
        self.assertNotIn("hub-core", run["names"])
        self.assertEqual(buttons, 2)                                 # "Brief" and "Detailed"
        pick = ("[...document.querySelectorAll('.feed-opts label')].filter(l => /^(Steps of a finished turn|Count of collapsed)/.test(l.textContent))"
                ".forEach(l => l.querySelector('input').click()); 1")
        got = self.page({"eval": "localStorage.setItem('hub.settingsTab', 'theme'); location.hash = '#/settings'; 1"},
                        {"until": "document.querySelectorAll('.feed-opts input').length > 5"}, {"eval": pick},
                        {"eval": "location.hash = '#/s/a'; 1"}, {"wait": "go ahead"}, {"wait": "waiting for a reply"}, {"eval": self.LOOK},
                        {"eval": "JSON.parse(localStorage.getItem('hub.brief'))"})
        run, saved = got[-2]["eval"], got[-1]["eval"]
        self.assertEqual(len(run["steps"]), 2, run)                  # and a finished turn with a steps row
        self.assertGreater(run["count"], 0)
        self.assertEqual((saved["steps"], saved["count"], saved["big"]), (True, True, False))

    def test_plugin_options_live_on_the_view_tab(self):
        # API 1.12 (plugins and modules add their own settings there): a plugin's checkbox group is on the "Look"
        # tab under the feed (everything stored in the browser is there now); hub.option returns the choice, default is on
        # from addOptions
        from unittest import mock
        path = os.path.join(self.state, "plug-opts")
        os.makedirs(path)
        with open(os.path.join(path, "hub-plugin.json"), "w") as f:
            json.dump({"name": "opts", "description": "options", "why": "w", "web": "main.js", "hub": "^1.12"}, f)
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"extensions": {"opts": {"path": path, "web": "main.js"}}}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        with open(os.path.join(path, "main.js"), "w") as f:
            f.write("export default function register(hub) {\n"
                    "  hub.addOptions({ title: 'Plugin options', options: [{ key: 'loud', label: 'Loud', on: true },"
                    " { key: 'quiet', label: 'Quiet' }] });\n"
                    "  hub.addSlot('sidebar.footer', { id: 'probe', render(root) { root.textContent = "
                    "'opt:' + hub.option('loud') + ',' + hub.option('quiet'); } });\n}\n")
        flip = ("[...document.querySelectorAll('.feed-opts label')].filter(l => /^(Loud|Quiet)/.test(l.textContent))"
                ".forEach(l => l.querySelector('input').click()); 1")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"eval": "localStorage.removeItem('hub.opt.opts'); localStorage.setItem('hub.settingsTab', 'theme'); 1"},
                        {"errors": 1500}, {"wait": "Plugin options"},
                        {"eval": "document.querySelector('main .settings-groups').innerText.indexOf('Plugin options') > "
                                 "document.querySelector('main .settings-groups').innerText.indexOf('Feed')"},
                        {"until": "document.body.innerText.includes('opt:true,false')", "ms": 5000}, {"eval": flip},
                        {"until": "document.body.innerText.includes('opt:false,true')", "ms": 5000})
        self.assertTrue(got[4]["eval"])                               # the plugin's group — under the feed settings
        self.assertTrue(got[5]["until"], got[5])                      # by default — on from addOptions
        self.assertTrue(got[-1]["until"], got[-1])                    # changed — the plugin sees the new choice

    def test_a_plugin_theme_carries_its_own_options_under_its_row(self):
        # API 1.37: addOptions({ themes }) — a group of a theme of the plugin, shown under that theme's row in "Look" and only
        # while it is chosen; a theme is named by its file from the plugin's manifest (another plugin's theme cannot be
        # named); a group declared later comes in by itself; a group declared again on every render, its hint changing, does
        # not loop the page with "Look" open
        from unittest import mock
        path = os.path.join(self.state, "plug-dusk")
        os.makedirs(path)
        for n in ("a", "b"):
            with open(os.path.join(path, f"{n}.json"), "w") as f:
                json.dump({"name": f"Dusk {n.upper()}", "dark": True, "colors": {"background": "#101820", "foreground": "#e0e6ee",
                                                                               "primary": "#5fb0ff"}}, f)
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"extensions": {"dusk": {"path": path, "web": "main.js", "themes": ["a.json", "b.json"]}}}, f)
        with open(os.path.join(path, "hub-plugin.json"), "w") as f:
            json.dump({"name": "dusk", "description": "themes", "why": "w", "web": "main.js", "themes": ["a.json", "b.json"],
                       "hub": "^1.37"}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        with open(os.path.join(path, "main.js"), "w") as f:
            f.write("export default function register(hub) {\n"
                    "  window.__caps = hub.capabilities.themeOptions;\n"
                    "  let n = 0;\n"
                    "  const a = () => hub.addOptions({ themes: ['a.json'], title: 'Dusk options', hint: 'round ' + (n++ % 2),"
                    " options: [{ key: 'glow', label: 'Glow of A', on: true }] });\n"
                    "  a();\n"
                    "  hub.addOptions({ themes: ['other:x.json'], title: 'Foreign', options: [{ key: 'f', label: 'Foreign tick' }] });\n"
                    "  hub.addOptions({ themes: [], title: 'Empty', options: [{ key: 'e', label: 'Empty tick' }] });\n"
                    "  setTimeout(() => hub.addOptions({ themes: ['b.json'], options: [{ key: 'late', label: 'Late of B' }] }), 1500);\n"
                    "  hub.addSlot('sidebar.footer', { id: 'probe', render(root) { a(); root.textContent = 'glow:' + hub.option('glow'); } });\n}\n")
        row = "[...document.querySelectorAll('.theme-row')].find((r) => r.textContent.includes('Dusk %s'))"
        under = f"({row})?.nextElementSibling?.matches('.theme-opts') && ({row}).nextElementSibling.innerText"
        text = "document.querySelector('main .settings-groups').innerText"
        got = self.page({"local": {"hub.theme": '{"id":"core:classic"}', "hub.settingsTab": "theme"}},
                        {"go": f"http://127.0.0.1:{self.port}/#/settings"}, {"wait": "Dusk B"}, {"sleep": 2000},
                        {"eval": f"[{text}.includes('Glow of A'), {text}.includes('Late of B'), {text}.includes('Foreign tick'),"
                                 f" {text}.includes('Empty tick'), window.__caps]"},
                        {"click": "Dusk A"}, {"until": f"String({under % ('A', 'A')}).includes('Glow of A')"},
                        {"eval": f"[({row % 'A'}).nextElementSibling.querySelector('input').checked, {text}.includes('Foreign tick'),"
                                 " document.querySelectorAll('.theme-opts').length]"},
                        {"eval": f"(({row % 'A'}).nextElementSibling.querySelector('input').click(), 1)"},
                        {"until": "document.body.innerText.includes('glow:false')", "ms": 5000},
                        {"click": "Dusk B"}, {"until": f"String({under % ('B', 'B')}).includes('Late of B')"},
                        {"eval": f"[{text}.includes('Glow of A'), document.querySelectorAll('.theme-opts').length]"},
                        {"click": "Plugins"}, {"wait": "dusk"}, {"eval": "document.body.innerText.includes('addOptions')"})
        self.assertEqual(got[4]["eval"], [False, False, False, False, 1], got[4])   # Classic: none of them anywhere
        self.assertTrue(got[6]["until"], got[6])                                     # under its row
        self.assertEqual(got[7]["eval"], [True, False, 1])                           # on by default; the foreign one nowhere
        self.assertTrue(got[9]["until"], got[9])                                     # the plugin sees the tick
        self.assertTrue(got[11]["until"], got[11])                                   # the late group of B, under B
        self.assertEqual(got[12]["eval"], [False, 1])
        self.assertTrue(got[-1]["eval"], got[-1])                                    # an empty themes list is a plugin error

