    def test_settings_changed_outside_the_page_are_not_on_the_page(self):
        # dev-guard spec §5.2: the core watches the settings quietly (config.changed_outside), the owner put the block "changed
        # outside this page" on hold (06.11): the red band of own edits stays alone, and no row or snapshot key comes of it
        cfg = os.path.join(self.state, "hub-en.json")
