    def test_take_off_on_the_red_band_asks_first_and_leaves_the_task_to_the_update_process(self):
        # dev-guard spec §5.7: "Take off" next to "Fix" — a confirmation (the hub restarts after it), then the flag the
        # update process takes under the machine lock; the result comes to the hub's feed
        self.english()
        self.edits(count=2)
        band = "((document.querySelector('.local-edits') || {}).innerText || '')"
        got = self.page({"local": {"hub.settingsTab": "about"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": "!!document.querySelector('.local-edits button[data-act=off]')", "ms": 8000},
                        {"eval": "JSON.stringify([...document.querySelectorAll('.local-edits button')].map((b) => [b.dataset.act, b.innerText.trim()]))"},
                        {"eval": "(() => { document.querySelector('.local-edits button[data-act=off]').click(); return 1; })()"},
                        {"until": "document.getElementById('confirm-dlg').open", "ms": 3000},
                        {"eval": "document.getElementById('confirm-title').innerText"})
        self.assertTrue(got[2]["until"])
        self.assertEqual(json.loads(got[3]["eval"]), [["fix", "Fix"], ["off", "Take the edits off"]])   # no backup: no "Put back"
        self.assertTrue(got[5]["until"])
        self.assertIn("Take the own edits of the core off", got[6]["eval"])
        self.assertIsNone(self.edits_flag())                            # nothing before the confirmation
        got = self.page({"eval": "document.getElementById('confirm-ok').click(), 1"},
                        {"until": f"{band}.includes('The result comes to the hub')", "ms": 8000},
                        {"eval": "document.querySelector('.local-edits button[data-act=off]').disabled"})
        self.assertTrue(got[1]["until"])
        self.assertEqual(self.edits_flag(), "off")
        self.assertIs(got[2]["eval"], True)                             # until the check after it

