    def test_feed_stays_at_the_bottom_when_the_page_grows_after_a_redraw(self):
        # the bottom row ("Command in the background: …") is visible only after scrolling — the input field or feed
        # grew after the redraw, the feed stayed at its old height
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None)
        for i in range(30):
            self.tool("a", f"x{i}", f"cmd-{i}")
            self.ev("turn.tool_result", "a", id=f"x{i}", text="ok " * 50, error=False)
        self.j.append("session.background", "a", {"id": "b1", "kind": "bash", "output": "/tmp/x",
                                                  "title": "Wait for the prod index build to progress"})
        gap = ("(() => { const f = document.querySelector('main .feed'); "
               "return Math.round(f.scrollHeight - f.scrollTop - f.clientHeight); })()")
        grow = ("(() => { const d = document.createElement('div'); d.style.height = '300px'; "
                "document.querySelector('main .dock-inner').append(d); "
                "document.querySelector('main .feed-inner').append(d.cloneNode()); })()")
        up = "(() => { const f = document.querySelector('main .feed'); f.scrollTop = 0; })()"
        # a pinned feed catches up with the growth by itself — wait for it (under the load of a full run 500 ms was not
        # enough)
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Command in the background"}, {"sleep": 500},
                        {"eval": grow}, {"until": f"{gap} === 0"}, {"eval": gap}, {"eval": up}, {"sleep": 300},
                        {"eval": grow}, {"sleep": 500}, {"eval": gap})
        self.assertEqual(got[5]["eval"], 0)    # pinned to the bottom: it grew — stayed at the bottom
        self.assertGreater(got[-1]["eval"], 300)  # reading history: not dragged down

    def test_back_to_a_session_lands_at_the_bottom_when_the_dock_grows_after_the_redraw(self):
        # owner report: coming back to a session means scrolling down to the last message by hand. The page scrolled to
        # the bottom, then the input dock grew by a line before the next frame; the scroll event saw a gap above NEAR
        # and unpinned the feed, so it stayed one line short of the end
        for n in ("a", "b"):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True)
            self.ev("session.started", n, session_id=f"s-{n}")
            for i in range(12):
                self.ev("session.said", n, text=f"Reply {n}{i}\n\n" + "- item\n" * 6)
        gap =("(() => { const f = document.querySelector('main .feed'); "
               "return Math.round(f.scrollHeight - f.scrollTop - f.clientHeight); })()")
        grow = ("(() => { new MutationObserver((ms, mo) => { const d = document.querySelector('main .dock-inner'); "
                "if (!d || document.querySelector('main').dataset.for !== 'a') return; mo.disconnect(); "
                "queueMicrotask(() => { const x = document.createElement('div'); x.style.height = '36px'; d.append(x); }); })"
                ".observe(document.querySelector('main'), {childList: true}); location.hash = '#/s/a'; return 1; })()")
        # a's feed is already loaded (visited before): the return redraws it at once, in one task
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Reply a11"},
                        {"eval": "location.hash = '#/s/b'"}, {"wait": "Reply b11"}, {"eval": grow},
                        {"wait": "Reply a11"}, {"sleep": 500}, {"eval": gap})
        self.ev("session.said", "a", text="New reply")
        got += self.page({"wait": "New reply"}, {"sleep": 500}, {"eval": gap})
        self.assertEqual((got[-4]["eval"], got[-1]["eval"]), (0, 0))

    def _long_feed(self, name="a"):
        self.ev("session.requested", name, session_id=f"s-{name}", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", name, session_id=f"s-{name}")
        for i in range(12):
            self.ev("session.said", name, text=f"Reply {name}{i}\n\n" + "- item\n" * 6)

    GAP = ("(() => { const f = document.querySelector('main .feed'); "
           "return Math.round(f.scrollHeight - f.scrollTop - f.clientHeight); })()")

    def test_redraw_right_after_a_jump_up_does_not_pull_the_feed_down(self):
        # the feed is pinned to the bottom; the owner jumps up (PageUp, Home, a scrollbar drag) and a redraw runs in the
        # same browser task, before the scroll event arrives: the stale pin must not win over a scroll that already
        # happened
        self._long_feed()
        jump = ("(() => { const f = document.querySelector('main .feed'); f.scrollTop = 0; "
                "window.dispatchEvent(new Event('hashchange')); return 1; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Reply a11"}, {"sleep": 500},
                        {"eval": self.GAP}, {"eval": jump}, {"sleep": 500}, {"eval": self.GAP})
        self.assertEqual(got[3]["eval"], 0)           # was pinned
        self.assertGreater(got[-1]["eval"], 300)      # stays where the owner scrolled

    def test_creeping_up_one_pixel_at_a_time_unpins_the_feed(self):
        # a scrollbar drag or arrow keys move the feed up by a pixel or two per frame: each step alone is within the
        # tolerance, together they leave the bottom, and the next growth of the page must not drag the feed back down
        self._long_feed()
        creep = ("(() => { const f = document.querySelector('main .feed'); let n = 0; "
                 "const step = () => { f.scrollTop -= 1; if (++n < 60) requestAnimationFrame(step); else window.__crept = 1; }; "
                 "window.__crept = 0; requestAnimationFrame(step); return 1; })()")
        grow = ("(() => { const d = document.createElement('div'); d.style.height = '300px'; "
                "document.querySelector('main .dock-inner').append(d); "
                "document.querySelector('main .feed-inner').append(d.cloneNode()); })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Reply a11"}, {"sleep": 500},
                        {"eval": creep}, {"until": "window.__crept === 1", "ms": 8000}, {"eval": self.GAP},
                        {"eval": grow}, {"sleep": 500}, {"eval": self.GAP})
        self.assertGreaterEqual(got[5]["eval"], 50)   # left the bottom
        self.assertGreater(got[-1]["eval"], 300)      # growth did not carry it down

    def test_the_feed_that_got_shorter_at_the_bottom_still_follows(self):
        # the pinned feed grows and then gets shorter (the timeline trims old rows, a tall block goes away): the browser
        # clamps the position down. The point the feed counts "scrolled up" from must come down with it — otherwise the
        # next move down that lands short of the bottom (the dock grew before the scroll event) looks like a scroll up
        # and the feed stops following new messages
        self._long_feed()
        tall = ("(() => { const d = document.createElement('div'); d.id = 'tall'; d.style.height = '2000px'; "
                "document.querySelector('main .feed-inner').append(d); return 1; })()")
        drop = "(() => { document.getElementById('tall').remove(); return 1; })()"
        short = ("(() => { const f = document.querySelector('main .feed'); const d = document.createElement('div'); "
                 "d.style.height = '300px'; document.querySelector('main .feed-inner').append(d); "
                 "f.scrollTop = f.scrollHeight - f.clientHeight - 30; return 1; })()")
        grow = ("(() => { const d = document.createElement('div'); d.style.height = '300px'; "
                "document.querySelector('main .feed-inner').append(d); return 1; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "Reply a11"}, {"sleep": 500},
                        {"eval": tall}, {"sleep": 400}, {"eval": self.GAP}, {"eval": drop}, {"sleep": 400},
                        {"eval": short}, {"sleep": 400}, {"eval": grow}, {"sleep": 500}, {"eval": self.GAP})
        self.assertEqual(got[5]["eval"], 0)       # followed the tall block
        self.assertEqual(got[-1]["eval"], 0)      # and still follows after it went away

    def test_ended_schedule_jobs_newest_first(self):
        # owner (personal edit): in the schedule history, completed tasks go from newest to oldest
        import time as _t
        self.ev("session.requested", "alpha", session_id="s-alpha", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "alpha", session_id="s-alpha")
        for i, name in enumerate(("old-one", "mid-one", "new-one")):
            self.j.append("schedule.set", name, {"session": "alpha", "every": "1d", "prompt": f"Task {name}",
                                                "channel": "cli", "owner": True}, ts=_t.time() - 3600 + i)
        for i, name in enumerate(("mid-one", "old-one", "new-one")):   # removed out of creation order
            ts = {"old-one": 600, "mid-one": 300, "new-one": 60}[name]
            self.j.append("schedule.remove_requested", name, {"channel": "cli", "owner": True}, ts=_t.time() - ts)
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/schedule"}, {"wait": "Finished this week"},
                        {"eval": "[...document.querySelectorAll('details.ended .job .prompt')].map(p => p.textContent)"})
        self.assertEqual(got[-1]["eval"], ["Task new-one", "Task mid-one", "Task old-one"])

    def test_an_expired_job_waits_for_a_decision_with_its_end(self):
        # 30.10: a watcher whose term ran out lay folded among "finished" with "term over" and no date — days unnoticed
        import time as _t
        self.ev("session.requested", "alpha", session_id="s-alpha", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "alpha", session_id="s-alpha")
        self.j.append("schedule.set", "alpha-watch", {"session": "alpha", "every": "1h", "prompt": "Watch for news",
                                                     "until": _t.time() + 120, "channel": "cli", "owner": True},
                      ts=_t.time() - 3600)
        self.j.append("schedule.ended", "alpha-watch", {}, ts=_t.time() + 180)
        row = "document.querySelector('.jobs .job[data-s=\"expired\"]')"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/schedule"}, {"wait": "Watch for news"},
                        {"eval": f"!!{row}.closest('details.ended')"},
                        {"eval": f"{row}.querySelector('.why').textContent"},
                        {"eval": f"!!{row}.querySelector('button.remove')"},
                        {"eval": "document.querySelector('h3.day.warn').textContent"},
                        {"eval": f"{row}.querySelector('details').open"})
        self.assertFalse(got[2]["eval"])                       # not folded among the finished
        self.assertIn("Ended", got[3]["eval"])
        self.assertIn("ask the hub to renew it", got[3]["eval"])
        self.assertTrue(got[4]["eval"])                        # "Remove" = not needed
        self.assertEqual(got[5]["eval"], "Waiting for a decision")
        self.assertTrue(got[6]["eval"])                         # a decision is waiting — the row is open
        # "Remove" goes through: the page sends the removal of an expired job, not "the job is gone"
        self.page({"go": f"http://127.0.0.1:{self.port}/#/schedule"}, {"wait": "Watch for news"},
                  {"eval": f"({row}.querySelector('button.remove').click(), 1)"},
                  {"until": "document.getElementById('confirm-dlg').open && document.getElementById('confirm-title').textContent"},
                  {"eval": "document.getElementById('confirm-ok').click()"}, {"sleep": 500})
        sent = [(e["type"], e.get("entity")) for e in self.spooled() if e["type"].startswith("schedule.")]
        self.assertEqual(sent, [("schedule.remove_requested", "alpha-watch")])

