    def test_tab_from_the_session_field_reaches_the_list(self):
        # the list closed on blur, so Tab dropped focus to the body and the session buttons were unreachable
        self._two_sessions_page()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/schedule/gamma"},
                        {"until": "document.readyState === 'complete' && document.querySelector('.sched-pick-in')?.value === 'gamma'", "ms": 15000},
                        {"sleep": 700}, {"mclick": ".sched-pick-in"}, {"sleep": 200},
                        {"eval": "(document.querySelector('.sched-pick-list button').focus(), 1)"}, {"sleep": 200},
                        {"eval": "[document.activeElement.closest('.sched-pick-list') ? 'in-list' : document.activeElement.tagName, document.querySelector('.sched-pick-list').hidden]"},
                        {"eval": "(document.body.focus(), document.activeElement.blur(), 1)"}, {"sleep": 200},
                        {"eval": "document.querySelector('.sched-pick-list').hidden"})
        self.assertEqual(got[-4]["eval"], ["in-list", False])
        self.assertTrue(got[-1]["eval"])        # focus really leaving the control still closes the list

