                        {"sleep": 400}, {"eval": "location.hash"},
                        {"eval": "(i => (i.value = 'alp', i.dispatchEvent(new Event('input', {bubbles: true})), i.dispatchEvent(new KeyboardEvent('keydown', {key: 'Enter', bubbles: true})), 1))(document.querySelector('.sched-pick-in'))"},
