    def test_escape_in_the_session_list_closes_it_at_once(self):
        # Escape on a session moved focus back to the field, whose focus handler opened the list again; the cross did the same
        self._two_sessions_page()
        st = "(i => [document.activeElement === i, document.querySelector('.sched-pick-list').hidden])(document.querySelector('.sched-pick-in'))"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/schedule"},
                        {"until": "document.readyState === 'complete' && !!document.querySelector('.sched-pick-in')", "ms": 15000},
                        {"wait": "Check A"}, {"sleep": 700}, {"mclick": ".sched-pick-in"}, {"sleep": 200},
                        {"key": "ArrowDown"}, {"sleep": 200}, {"eval": "document.activeElement.textContent"},
                        {"key": "Escape"}, {"sleep": 300}, {"eval": st})
        self.assertEqual(got[-4]["eval"], "alpha")
        self.assertEqual(got[-1]["eval"], [True, True])
        # a snapshot while the field keeps focus does not open it again
        self.j.append("schedule.set", "alpha-job2", {"session": "alpha", "every": "3h", "prompt": "Check B", "channel": "cli", "owner": True})
        got = self.page({"wait": "Check B"}, {"sleep": 300}, {"eval": st},
                        {"eval": "(i => (i.value = 'al', i.dispatchEvent(new Event('input', {bubbles: true})), 1))(document.querySelector('.sched-pick-in'))"},
                        {"mclick": ".sched-pick-x"}, {"sleep": 300}, {"eval": st})
        self.assertEqual(got[2]["eval"], [True, True])
        self.assertEqual(got[-1]["eval"], [True, True])      # the cross empties the field and leaves the list closed

