    def test_a_paused_row_folds_once_the_job_is_handed_over(self):
        # a paused row opens by default; that default was stored as if the owner had opened it, so after retarget the
        # active row stayed open among the folded ones, and a removed one stayed open among the finished
        import time as _t
        now = _t.time()
        for n in ("maps", "beta"):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True)
            self.ev("session.started", n, session_id=f"s-{n}")
        self.j.append("schedule.set", "maps-hourly", {"session": "maps", "every": "1h", "prompt": "Report the queue",
                                                      "channel": "cli", "owner": True}, ts=now - 7200)
        self.j.append("schedule.set", "maps-logs", {"session": "maps", "every": "1h", "prompt": "Collect the logs",
                                                    "channel": "cli", "owner": True}, ts=now - 7200)
        self.j.append("session.ended", "maps", {"reason": "prompt_input_exit"}, ts=now - 7000)
        self.j.append("session.remove_requested", "maps", {"channel": "cli", "owner": True}, ts=now - 6990)
        for jid in ("maps-hourly", "maps-logs"):
            self.j.append("schedule.due", jid, {"slot": now - 3700}, ts=now - 3650)
        row = "[...document.querySelectorAll('.jobs .job')].find(li => li.textContent.includes('%s'))"
        q, logs = row % "Report the queue", row % "Collect the logs"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/schedule"}, {"wait": "Collect the logs"}, {"sleep": 700},
                        {"eval": f"[{q}.dataset.s, {q}.querySelector('details').open, {logs}.dataset.s, {logs}.querySelector('details').open]"})
        self.assertEqual(got[-1]["eval"], ["paused", True, "paused", True])
        self.ev("schedule.retarget", "maps-hourly", session="beta", channel="cli", owner=True)
        self.ev("schedule.remove_requested", "maps-logs", channel="cli", owner=True)
        got = self.page({"until": f"{q}?.dataset.s === 'active' && {logs}?.dataset.s === 'removed'", "ms": 15000}, {"sleep": 300},
                        {"eval": f"[{q}.querySelector('details').open, {logs}.querySelector('details').open]"})
        self.assertTrue(got[0]["until"])
        self.assertEqual(got[-1]["eval"], [False, False])

