    def test_a_sessions_command_job_is_in_its_schedule(self):
        # a command job set by a session (session empty, by — it) was not visible on the session itself
        for n in ("alpha", "beta"):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True)
            self.ev("session.started", n, session_id=f"s-{n}")
        self.j.append("schedule.set", "alpha-sync", {"every": "1h", "command": "echo sync", "channel": "session",
                                                     "owner": False, "sender": "alpha"})
        self.j.append("schedule.set", "own-cmd", {"every": "2h", "command": "echo mine", "channel": "cli",
                                                  "owner": True})
        self.j.append("schedule.set", "core-cmd", {"every": "3h", "command": "echo core", "channel": "core",
                                                   "owner": False})
        self.j.append("schedule.set", "gone-cmd", {"every": "3h", "command": "echo gone", "channel": "session",
                                                   "owner": False, "sender": "gone"})
        # a command given to beta (retarget writes session) — belongs to beta, even though a departed session set it
        self.j.append("schedule.set", "gone-to-beta", {"every": "4h", "command": "echo handed", "channel": "session",
                                                       "owner": False, "sender": "gone"})
        self.j.append("schedule.retarget", "gone-to-beta", {"session": "beta", "channel": "cli", "owner": True})
        # a prompt job that alpha set for beta — belongs to beta, not alpha
        self.j.append("schedule.set", "beta-ci", {"session": "beta", "every": "2h", "prompt": "Check CI",
                                                  "channel": "session", "owner": False, "sender": "alpha"})
        who = ("Object.fromEntries([...document.querySelectorAll('.job')].map(r => "
               "[r.querySelector('.prompt').textContent, r.querySelector('.who')?.getAttribute('href') || '']))")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/schedule"},
                        {"until": "document.body.innerText.includes('own-cmd') && "
                                  "document.querySelector('.sched-pick-in')", "ms": 15000},
                        {"sleep": 700}, {"mclick": ".sched-pick-in"}, {"sleep": 200},
                        {"eval": "[...document.querySelectorAll('.sched-pick-list button')].map(b => b.textContent)"},
                        {"eval": "document.querySelector('.sched-pick-list').getBoundingClientRect().top >= "
                                 "document.querySelector('.sched-pick-in').getBoundingClientRect().bottom"},
                        {"eval": who},
                        {"hash": "#/schedule/alpha"}, {"wait": "alpha-sync"}, {"count": "own-cmd"},
                        {"count": "Check CI"}, {"count": "gone-cmd"},
                        {"hash": "#/s/alpha"}, {"wait": "on the schedule"},
                        {"eval": "document.querySelector('a.chip.sched').getAttribute('href')"},
                        {"hash": "#/s/beta"},
                        {"until": "document.querySelector('a.chip.sched')?.getAttribute('href') === '#/schedule/beta'"},
                        {"eval": "document.querySelector('a.chip.sched').title"})
        # the overview is one "Session" field (no numbers) listing the sessions; commands of the owner, the core and a
        # departed session — nobody's
        self.assertEqual(got[5]["eval"], ["alpha", "beta"])
        self.assertTrue(got[6]["eval"])      # the list opens under the field, not over it
        self.assertEqual(got[7]["eval"], {"alpha-sync": "#/schedule/alpha", "own-cmd": "", "core-cmd": "",
                                          "gone-cmd": "", "gone-to-beta": "#/schedule/beta", "Check CI": "#/schedule/beta"})
        self.assertEqual([got[i]["n"] for i in (10, 11, 12)], [0, 0, 0])
        self.assertEqual(got[15]["eval"], "#/schedule/alpha")
        self.assertIn("Check CI", got[-1]["eval"])
        self.assertIn("echo handed", got[-1]["eval"])
        self.assertNotIn("echo sync", got[-1]["eval"])
        # a chosen session stays in the field; one press on the cross shows all sessions again
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/schedule/alpha"},
                        {"until": "document.querySelector('.sched-pick-in')?.value === 'alpha'", "ms": 15000},
                        {"eval": "document.querySelector('.sched-pick-x').click()"},
                        {"until": "location.hash === '#/schedule'", "ms": 5000},
                        {"eval": "document.querySelector('.sched-pick-in').value"})
        self.assertEqual(got[-1]["eval"], "")

    def test_directions_in_the_list_count_tasks_and_recap_inside(self):
        # owner decision: just a task counter instead of a noisy list, and inside it a dedicated recap for
        # directions
        from unittest import mock
        root = os.path.join(self.state, "directions")
        for slug, tasks in (("maps", [("In Progress", "Slice 2: import")]), ("done-one", [("Done", "a")]),
                            ("silent", [("To Do", "x"), ("To Do", "y")])):
            d = os.path.join(root, slug, "backlog", "tasks")
            os.makedirs(d)
            for i, (st, title) in enumerate(tasks):
                with open(os.path.join(d, f"task-{i}.md"), "w") as f:
                    f.write(f"---\nid: task-{i}\ntitle: '{title}'\nstatus: {st}\n---\n")
        env = mock.patch.dict(os.environ, {"HUB_DIRECTIONS": root})
        env.start()
        self.addCleanup(env.stop)
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.started", "hub", session_id="s-h")
        for n in ("maps", "done-one", "silent", "w", "old"):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True)
            self.ev("session.started", n, session_id=f"s-{n}")
        self.ev("session.waiting", "maps", text="support reply on request 42", channel="session", owner=False,
                sender="maps")
        self.ev("session.waiting", "w", text="MR review", channel="cli", owner=True)
        # after the mark she took the owner's word and did not repeat it: "waited: … · until" (issue #118)
        self.ev("session.waiting", "old", text="customer reply", channel="cli", owner=True)
        self.ev("message.received", None, to="old", text="how is it going?", channel="web", owner=True)
        self.ev("turn.started", "old", marker=f"m{self.j.seq}")
        self.ev("turn.result", "old", text="done", turns=2)
        rows_js = ("Object.fromEntries([...document.querySelectorAll('.srow')].map(r => "
                   "[r.querySelector('.nm')?.textContent.trim().split(' ').pop(), "
                   "[r.querySelector('.lb')?.textContent, r.querySelector('.count')?.textContent || '']]))")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/"}, {"sleep": 2500}, {"eval": rows_js},
                        {"eval": "document.querySelectorAll('.srow .lb.warn').length"},
                        {"hash": "#/s/silent"}, {"wait": "Board: 2 open"}, {"wait": "has not said what it waits for"},
                        {"click": "Ask what it waits for"}, {"wait": "Asked"},
                        {"hash": "#/s/maps"}, {"wait": "in progress: Slice 2: import"}, {"wait": "waiting for: support reply"},
                        {"hash": "#/s/done-one"}, {"wait": "Board: no open tasks"}, {"wait": "finishing the direction is up to you"})
        rows = got[2]["eval"]
        # the board is shown in words in the caption; the number on the right counts executors only (owner decision:
        # a task count there conflicts with the executor count on specialists)
        self.assertEqual(rows["maps"], ["1 task · waiting: support reply on request 42", ""])
        self.assertTrue(rows["silent"][0].startswith("2 tasks · "))
        self.assertNotIn("no turn going", rows["silent"][0])
        self.assertFalse(rows["done-one"][0][:1].isdigit())   # no open ones — nothing is written
        self.assertEqual(rows["w"], ["waiting: MR review", ""])
        self.assertRegex(rows["old"][0], r"^waited: customer reply · until \d\d:\d\d( [AP]M)?$")
        self.assertEqual(got[3]["eval"], 0)                # nothing is flagged yellow
        sent = [m for m in self.spooled() if m["type"] == "message.received"]
        self.assertEqual([m["data"]["to"] for m in sent], ["silent"])
        self.assertIn("hub waiting", sent[0]["data"]["text"])

