    def test_a_plugin_reorders_a_group_of_the_session_list(self):
        # API 1.10 (PR #52): hub.addOrder — a plugin reorders the rows of a list group (pinned directions on top);
        # it cannot lose, duplicate or add a row — otherwise the order stays as it was
        from unittest import mock
        path = os.path.join(self.state, "plug-order")
        os.makedirs(path)
        with open(os.path.join(path, "hub-plugin.json"), "w") as f:
            json.dump({"name": "order", "description": "order","why": "w", "web": "main.js", "hub": "^1.10"}, f)
        with open(os.path.join(path, "main.js"), "w") as f:
            f.write("export default function (hub) {\n"
                    "  hub.addOrder((g, rows) => g !== 'directions' ? rows : window.__mode === 'dup' ? [rows[0], rows[0], rows[1]]"
                    " : window.__mode === 'pin' ? [rows[2], rows[0], rows[1]] : rows);\n"
                    "  window.__redraw = () => hub.redraw();\n}\n")
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"extensions": {"order": {"path": path, "web": "main.js"}}}, f)
        root = os.path.join(self.state, "directions")
        for slug in ("alpha", "beta", "gamma"):
            os.makedirs(os.path.join(root, slug, "backlog", "tasks"))
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg, "HUB_DIRECTIONS": root})
        env.start()
        self.addCleanup(env.stop)
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.started", "hub", session_id="s-h")
        for n in ("alpha", "beta", "gamma"):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True)
            self.ev("session.started", n, session_id=f"s-{n}")
        rows = ("[...[...document.querySelectorAll('.sgroup')].find(g => g.textContent.includes('Directions'))"
                ".querySelectorAll(':scope > ul > li .nm')].map(n => n.textContent.trim().split(' ').pop())")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/"}, {"until": "window.__redraw", "ms": 8000},
                        {"until": f"{rows}.length === 3", "ms": 8000}, {"eval": rows},
                        {"eval": "window.__mode = 'pin'; window.__redraw(); 1"}, {"sleep": 300}, {"eval": rows},
                        {"eval": "window.__mode = 'dup'; window.__redraw(); 1"}, {"sleep": 300}, {"eval": rows})
        evals = [g["eval"] for g in got if "eval" in g]
        self.assertEqual(evals[0], ["alpha", "beta", "gamma"])
        self.assertEqual(evals[2], ["gamma", "alpha", "beta"])   # the plugin reordered, redraw repainted
        self.assertEqual(evals[4], ["alpha", "beta", "gamma"])   # it duplicated a row — its order is not taken

    def test_a_plugin_decides_unread_and_the_core_still_learns_it_was_read(self):
        # API 1.25 (PR #139): hub.addUnread clears a row's "new" mark; each pass starts from the core's value (not
        # from
        # the plugin's previous answer), hub.redraw from inside addUnread causes no recursion, and an opened session
        # still goes to the core as read (/api/seen), even if the plugin cleared its "new"
        from unittest import mock
        path = os.path.join(self.state, "plug-unread")
        os.makedirs(path)
        with open(os.path.join(path, "hub-plugin.json"), "w") as f:
            json.dump({"name": "quiet", "description": "quieter","why": "w", "web": "main.js", "hub": "^1.25"}, f)
        with open(os.path.join(path, "main.js"), "w") as f:
            f.write("export default function (hub) {\n"
                    "  hub.addUnread((s) => { if (window.__mode !== 'quiet') return null; hub.redraw(); return false; });\n"
                    "  window.__redraw = () => hub.redraw();\n}\n")
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"extensions": {"quiet": {"path": path, "web": "main.js"}}}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.started", "hub", session_id="s-h")
        self.ev("session.requested", "maps", session_id="s-m", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "maps", session_id="s-m")
        e = self.j.append("message.received", None, {"to": "maps", "text": "do it", "channel": "web", "owner": True})
        self.ev("turn.started", "maps", marker=f"m{e['seq']}", prompt_head="x")
        self.ev("turn.result", "maps", text="done")
        self.ev("turn.stopped", "maps")
        row = "window.__st.snap.sessions.find((s) => s.name === 'maps')"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"until": "window.__redraw", "ms": 8000},
                        {"eval": self.STATE}, {"until": f"!!window.__st && {row}.unread === true", "ms": 8000},
                        {"eval": "window.__mode = 'quiet'; window.__redraw(); 1"}, {"eval": f"{row}.unread"},
                        {"eval": "window.__mode = null; window.__redraw(); 1"}, {"eval": f"{row}.unread"},
                        {"eval": "window.__mode = 'quiet'; window.__redraw(); 1"}, {"eval": f"{row}.unread"},
                        {"hash": "#/s/maps"}, {"until": f"{row}.core_unread === false", "ms": 8000},
                        {"eval": f"{row}.unread"})
        evals = [g["eval"] for g in got if "eval" in g]
        self.assertEqual(evals[2], False)   # the plugin cleared it
        self.assertEqual(evals[4], True)    # the plugin is silent — back to the core's value, not its previous answer
        self.assertEqual(evals[6], False)
        self.assertEqual(evals[7], False)   # opened — the core learned it was read

    # records from the first script on: every layout shift (not after input) with the nodes that moved, and, on each frame
    # where the Flow view is in the page, where its title, controls and canvas stand
    FLOW_TRACE = ("window.__shifts = []; window.__frames = []; "
                  "new PerformanceObserver((l) => { for (const e of l.getEntries()) if (!e.hadRecentInput) "
                  "window.__shifts.push([Math.round(e.value * 1000) / 1000, (e.sources || []).map((x) => "
                  "x.node ? (x.node.className || x.node.nodeName || '') + '' : '?').join(' ')]); })"
                  ".observe({type: 'layout-shift', buffered: true}); "
                  "const at = (q) => { const n = document.querySelector(q); if (!n) return null; const b = n.getBoundingClientRect(); "
                  "return b.width && b.height ? [Math.round(b.left), Math.round(b.top), Math.round(b.width), Math.round(b.height)] : null; }; "
                  "const tick = () => { if (document.querySelector('.flow')) window.__frames.push(['.flow-bar h2', '.flow-controls', "
                  "'.flow canvas'].map(at)); if (window.__frames.length < 400) requestAnimationFrame(tick); }; "
                  "requestAnimationFrame(tick);")

    def test_flow_opens_without_layout_shifts_and_shows_its_controls_from_the_first_frame(self):
        # owner's requirement for the Flow screen: no layout shifts while it loads, the controls that can be shown are
        # shown from the start; a phone and a desktop, Classic and Clean, a hub with a few working sessions
        import time as _t
        for i in range(4):
            self.ev("session.requested", f"w{i}", session_id=f"s-w{i}", cwd="/w")
            self.ev("session.started", f"w{i}")
            self.j.append("message.received", None, {"to": f"w{i}", "text": f"go {i}", "channel": "cli", "owner": True},
                          ts=_t.time() - 600 + i * 60)
        base = f"http://127.0.0.1:{self.port}"
        for theme in ("core:classic", "core:clean"):
            for width, height in ((390, 844), (1440, 900)):
                got = self.page({"go": "about:blank", "look": None}, {"local": {"hub.theme": json.dumps({"id": theme})}},
                                {"shot": os.path.join(self.state, "flow-cls.png"), "width": width, "height": height},
                                {"go": f"{base}/#/flow", "look": None, "init": self.FLOW_TRACE},
                                {"until": "!!document.querySelector('.flow canvas')", "ms": 10000}, {"sleep": 2000},
                                {"eval": "[window.__shifts, window.__frames]"})
                what = (theme, width)
                self.assertTrue(got[4]["until"], what)
                shifts, frames = got[-1]["eval"]
                # Google's "good" limit for the whole load (the page around the view moves a little as the list fills)
                self.assertLessEqual(round(sum(v for v, _ in shifts), 3), 0.1, (what, shifts))
                self.assertTrue(frames, what)
                first, last = frames[0], frames[-1]
                # the title and the period list (pause and speed belong to a replay only); then they stay in place
                self.assertTrue(all(first[:2]), (what, "controls missing on the first frame", first))
                self.assertEqual(first[:2], last[:2], (what, "the title or controls moved", first, last))

    def test_flow_replay_speed_pause_and_seek(self):
        # owner decision: the stream over a day — at different speeds, pause, rewind with the slider
        import time as _t
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a")
        for k in range(6):   # six messages over the last hour, exactly 10 min apart
            self.j.append("message.received", None, {"to": "a", "text": f"m{k}", "channel": "cli", "owner": True},
                          ts=_t.time() - 3600 + 300 + k * 600)
        R = "window.__flowRec"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/flow"}, {"until": "!!document.querySelector('.flow canvas')"},
                        {"until": f"{R}.running()"},   # show — in the frame after the output: begin() before it left the stream without colors
                        {"eval": f"{R}.begin()"}, {"eval": f"{R}.mode('h1')"}, {"sleep": 800},
                        {"eval": "[...document.querySelectorAll('.flow-rate option')].map(b => b.textContent)"},
                        {"eval": f"(() => {{ const speed = document.querySelector('.flow-rate'); speed.value = '2'; speed.dispatchEvent(new Event('change')); {R}.step(15000); return Math.round({R}.pos() * 100); }})()"},
                        {"eval": f"(() => {{ document.querySelector('.flow-speed .pause').click(); {R}.step(20000); return Math.round({R}.pos() * 100); }})()"},
                        {"eval": f"(() => {{ const r = document.querySelector('.flow-seek'); r.value = 900; r.dispatchEvent(new Event('input')); {R}.step(16); return [Math.round({R}.pos() * 100), {R}.signals()]; }})()"},
                        {"eval": f"(() => {{ const r = document.querySelector('.flow-seek'); r.value = 50; r.dispatchEvent(new Event('input')); {R}.step(16); return {R}.signals(); }})()"})
        self.assertEqual(got[6]["eval"], ["×¼", "×½", "×1", "×2", "×4"])
        self.assertEqual(got[7]["eval"], 50)                 # ×2: 15 s of a minute is half an hour
        self.assertEqual(got[8]["eval"], 50)                 # pause: time stands still
        self.assertEqual(got[9]["eval"], [90, 5])          # rewind forward: 5 messages have already passed, no flight
        self.assertEqual(got[10]["eval"], 0)                # back — to the first message
        # after a replay ends, the chosen speed stays marked; after a rewind, interactions are visible —
        # the last signals before the point fly, not just thin traces
        got = self.page({"eval": f"(() => {{ {R}.step(5000); return document.querySelector('.flow-seek') && 1; }})()"},
                        {"eval": f"(() => {{ const r = document.querySelector('.flow-seek'); r.value = 900; r.dispatchEvent(new Event('input')); {R}.step(16); return {R}.pulses(); }})()"},
                        {"eval": f"{R}.mode('live')"}, {"eval": f"{R}.mode('h1')"}, {"sleep": 800},
                        {"eval": "[...document.querySelector('.flow-rate').selectedOptions].map(b => b.textContent)"})
        self.assertGreater(got[1]["eval"], 0)
        self.assertEqual(got[-1]["eval"], ["×2"])
        # played to the end — it stays at the end rather than going back to "Now"; leave "Flow" and return — "Now"
        # again
        got = self.page({"eval": f"(() => {{ {R}.step(120000); {R}.step(5000); return [{R}.done(), Math.round({R}.pos() * 100), "
                                 "document.querySelector('.flow-speed .pause').classList.contains('is-paused')]; })()"},
                        {"hash": "#/s/a"}, {"sleep": 300}, {"hash": "#/flow"}, {"sleep": 500},
                        {"eval": f"[{R}.done(), document.querySelector('.flow-period').selectedOptions[0].textContent]"})
        self.assertEqual(got[0]["eval"], [False, 100, True])
        self.assertEqual(got[-1]["eval"], [True, "Now"])

    def test_flow_cold_open_puts_nodes_in_place_even_when_layout_is_slow(self):
        # analysis of large-hub frames (~330 sessions): "You" and "Hub" were born at the center and flew apart — a
        # node
        # was put in place only if it was younger than 50 ms, while the layout itself took 130–270 ms on a large
        # hub.
        # A slow layout here is a slow name comparison (sorting the rings)
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.started", "hub", session_id="s-h")
        for i in range(14):
            self.ev("session.requested", f"w{i}", session_id=f"s-{i}", cwd="/w")
            self.ev("session.started", f"w{i}", session_id=f"s-{i}")
        self.ev("message.received", None, to="w3", text="m", channel="cli", owner=True)   # "Now" draws who has a line
        R = "window.__flowRec"
        slow = ("(() => { const lc = String.prototype.localeCompare; window.__lc = lc; String.prototype.localeCompare = "
                "function (...a) { const e = performance.now() + 4; while (performance.now() < e); return lc.apply(this, a); }; "
                "location.hash = '#/flow'; window.dispatchEvent(new Event('hashchange')); return 1; })()")
        off = "(() => { const d = (id) => { const n = %s.at(id); return n && Math.round(Math.hypot(n.x - n.tx, n.y - n.ty)); }; " \
              "return [d('owner'), d('hub'), d('w3')]; })()" % R
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/hub"}, {"sleep": 2000},
                        {"eval": slow}, {"until": f"{R}.running()", "ms": 8000},
                        {"eval": f"({R}.begin(), 1)"},   # frames are still: a node can move only because of the layout
                        {"sleep": 1500}, {"eval": off},
                        {"eval": "(String.prototype.localeCompare = window.__lc, 1)"})
        self.assertTrue(got[3]["until"])
        self.assertEqual(got[6]["eval"], [0, 0, 0])

    def big_flow_hub(self, active=12, idle=60, executors=6, extra_active=0, lead_by_hub=False):
        """A large hub: the hub, a lead session `lead` with executors, `active` sessions that were written to
        recently, and
        `idle` sleeping ones without events. Messages are from the last few minutes (for "Now" and the
        one-hour replay)."""
        self.ev("session.requested", "hub", session_id="s-h", cwd="/h", kind="hub", channel="cli", owner=True)
        self.ev("session.started", "hub", session_id="s-h")
        self.ev("session.requested", "lead", session_id="s-l", cwd="/l",
                **({"executor": True, "raised_by": "hub"} if lead_by_hub else {}))
        self.ev("session.started", "lead", session_id="s-l")
        for i in range(executors):
            self.ev("session.requested", f"lead-x{i}", session_id=f"s-x{i}", cwd="/l", executor=True, raised_by="lead")
            self.ev("session.started", f"lead-x{i}", session_id=f"s-x{i}")
        for i in range(active + extra_active):
            self.ev("session.requested", f"act{i}", session_id=f"s-a{i}", cwd="/w")
            self.ev("session.started", f"act{i}", session_id=f"s-a{i}")
        for i in range(idle):
            self.ev("session.requested", f"idle{i}", session_id=f"s-i{i}", cwd="/w")
            self.ev("session.started", f"idle{i}", session_id=f"s-i{i}")
        import time as _t
        t = _t.time()
        for i in range(active + extra_active):
            self.j.append("message.received", None, {"to": f"act{i}", "text": f"m{i}", "channel": "cli", "owner": True},
                          ts=t - 600 + i)
        for i in range(executors):   # lead gave a task to an executor, and the executor answered her
            self.j.append("message.received", None, {"to": f"lead-x{i}", "text": "do", "channel": "session",
                                                     "sender": "lead"}, ts=t - 300 + i)

    def flow_open(self, *steps):
        R = "window.__flowRec"
        return self.page({"go": f"http://127.0.0.1:{self.port}/#/flow"}, {"until": "!!document.querySelector('.flow canvas')"},
                         {"until": f"{R}.running()", "ms": 8000}, {"sleep": 1800}, {"eval": f"({R}.begin(), 1)"}, *steps)

    def test_flow_big_hub_draws_only_active_sessions_and_folds_executors(self):
        # analysis (hub of ~380 sessions): the canvas drew everyone — sleeping ones and executors, labels merged
        # into a mess.
        # On a large hub (more than 30 sessions) — only those with events in the window, plus "You", "Hub", "core",
        # "schedule"; a lead session's executors — as a counter on it; how many are not shown — as a number
        self.big_flow_hub(active=12, idle=60, executors=6)
        R = "window.__flowRec"
        got = self.flow_open({"eval": f"{R}.nodes()"}, {"eval": f"{R}.summary()"})
        nodes, summary = got[-2]["eval"], got[-1]["eval"]
        self.assertTrue({"owner", "hub", "core", "schedule"} <= set(nodes), nodes)
        self.assertEqual(sorted(n for n in nodes if n.startswith("act")), sorted(f"act{i}" for i in range(12)))
        self.assertFalse([n for n in nodes if n.startswith("idle")], nodes)   # sleeping with no events — not drawn
        self.assertFalse([n for n in nodes if n.startswith("lead-x")], nodes)  # executors are collapsed into `lead`
        self.assertIn("lead", nodes)
        self.assertEqual(summary["big"], True)
        self.assertEqual(summary["folded"], {"lead": 6})
        self.assertEqual(summary["hidden"], 0)
        self.assertLessEqual(len(nodes), 4 + 1 + 1 + 12 + 2)

    def test_flow_big_hub_folds_the_whole_chain_under_a_lead_the_hub_raised(self):
        # review: a lead raised by the hub (raised_by = hub) — its executors and the executor's executor still
        # collapse
        # into it, rather than standing as separate dots; the "N of M" count includes the hub too
        import time as _t
        self.big_flow_hub(active=3, idle=40, executors=3, lead_by_hub=True)
        self.ev("session.requested", "deep", session_id="s-d", cwd="/l", executor=True, raised_by="lead-x0")
        self.ev("session.started", "deep", session_id="s-d")
        self.j.append("message.received", None, {"to": "deep", "text": "do", "channel": "session", "sender": "lead-x0"},
                      ts=_t.time() - 100)
        R = "window.__flowRec"
        got = self.flow_open({"eval": f"{R}.nodes()"}, {"eval": f"{R}.summary()"})
        nodes, summary = got[-2]["eval"], got[-1]["eval"]
        self.assertIn("lead", nodes)
        self.assertFalse([n for n in nodes if n.startswith("lead-x") or n == "deep"], nodes)
        self.assertEqual(summary["folded"], {"lead": 4})
        self.assertEqual(summary["shown"], 1 + 3 + 1 + 4)   # hub, act0..2, lead and her four

    def test_flow_big_hub_expands_executors_on_click_and_collapses_again(self):
        self.big_flow_hub(active=4, idle=40, executors=5)
        R = "window.__flowRec"
        click = (f"(() => {{ const b = {R}.badge('lead'); const c = document.querySelector('.flow canvas'); const r = c.getBoundingClientRect(); "
                 "const o = {clientX: r.left + b.x, clientY: r.top + b.y, bubbles: true}; "
                 "c.dispatchEvent(new MouseEvent('mousemove', o)); c.dispatchEvent(new MouseEvent('click', o)); return 1; })()")
        away = ("(() => { const c = document.querySelector('.flow canvas'); const r = c.getBoundingClientRect(); "
                "c.dispatchEvent(new MouseEvent('click', {clientX: r.left + 3, clientY: r.top + 3, bubbles: true})); return 1; })()")
        at = (f"(() => {{ const n = {R}.at('lead'); const c = document.querySelector('.flow canvas'); const r = c.getBoundingClientRect(); "
              "c.dispatchEvent(new MouseEvent('click', {clientX: r.left + n.x, clientY: r.top + n.y, bubbles: true})); return 1; })()")
        got = self.flow_open({"eval": click}, {"sleep": 200}, {"eval": f"{R}.nodes().filter(n => n.startsWith('lead-x')).length"},
                             {"eval": f"{R}.summary().folded"}, {"eval": "location.hash"},
                             {"eval": away}, {"sleep": 200}, {"eval": f"{R}.nodes().filter(n => n.startsWith('lead-x')).length"},
                             {"eval": "location.hash"},
                             {"eval": click}, {"sleep": 200}, {"eval": at}, {"sleep": 200}, {"eval": "location.hash"})
        ev = [g["eval"] for g in got if "eval" in g][-9:]
        self.assertEqual(ev[0], 5)          # a click on the lead's dot — all five executors as dots
        self.assertEqual(ev[1], {})         # expanded ones are not "collapsed"
        self.assertEqual(ev[2], "#/flow")   # that click shows the executors, it does not open the session
        self.assertEqual(ev[4], 0)          # a click past the dots — collapsed again
        self.assertEqual(ev[5], "#/flow")
        self.assertEqual(ev[8], "#/s/lead")  # the lead with its executors shown: a click on it opens the session

    def test_flow_shows_no_counters_no_legend_and_names_the_lines(self):
        # the bar is the title and the period: no "signals: N", no "Active in the window…" line, no second "now" beside
        # the period list; a lead's executors are a ring on its dot, not "+N"; what a line carries is written on the line
        self.big_flow_hub(active=4, idle=40, executors=5)
        R = "window.__flowRec"
        got = self.flow_open(
            {"eval": "['.flow-n', '.flow-count', '.flow-note', '.flow-legend'].filter((q) => document.querySelector(q)?.offsetWidth)"},
            {"eval": "(() => { const c = document.querySelector('.flow-clock'); return !c || c.hidden || !c.offsetWidth; })()"},
            {"eval": "document.querySelector('.flow-bar').innerText.trim().split(/\\s*\\n\\s*/)"},
            {"eval": f"({R}.mode('h1'), 1)"}, {"sleep": 800},
            {"eval": f"(() => {{ const r = document.querySelector('.flow-seek'); r.value = 840; r.dispatchEvent(new Event('input')); "
                     f"{R}.step(16); return {R}.kinds().map((k) => k.kind); }})()"},
            {"eval": f"(() => {{ const k = {R}.kinds(), l = {R}.labels(); return k.every((a) => l.every((b) => "
                     "!(a.x0 < b.x1 && b.x0 < a.x1 && a.y0 < b.y1 && b.y0 < a.y1))); })()"},
            {"eval": f"(() => {{ const b = {R}.badge('lead'), n = {R}.at('lead'); return [b.x === n.x, b.y === n.y]; }})()"})
        ev = [g["eval"] for g in got if "eval" in g][-7:]
        del ev[3]                                    # the switch to the replay
        self.assertEqual(ev[0], [])
        self.assertTrue(ev[1])                       # live: the period list says "Now", the clock is the replay's
        self.assertEqual(ev[2][0], "Flow")
        self.assertNotIn("now", [x.lower() for x in ev[2][1:] if x != "Now"])
        self.assertEqual(ev[3], ["message"])         # one label per kind on the canvas — here only messages fly
        self.assertTrue(ev[4])                       # and it does not cover a dot's label
        self.assertEqual(ev[5], [True, True])        # the place to click for the executors is the lead's own dot

    def test_flow_says_how_many_sessions_the_canvas_left_out_and_only_then(self):
        # the canvas draws at most 48 sessions: past that, one line says how many are left out; a hub that fits has no
        # such line (and no "0 more")
        note = ("(() => { const n = document.querySelector('.flow-note'); "
                "return [n && n.offsetWidth ? n.textContent : null, window.__flowRec.summary().hidden]; })()")
        self.big_flow_hub(active=20, extra_active=50, idle=0, executors=0)
        text, hidden = self.flow_open({"eval": note})[-1]["eval"]
        self.assertGreater(hidden, 0)
        self.assertEqual(text, f"{hidden} more not shown")

