    def test_flow_on_a_narrow_canvas_every_name_is_under_its_dot(self):
        # on a phone the names of a big hub sat now above a dot, now under it or beside it, and it was not clear whose
        # dot a name was: on a narrow canvas a name is always under its dot. A wide canvas places names as before
        self.big_flow_hub(active=40, idle=10, executors=0)
        R = "window.__flowRec"
        probe = (f"({R}.step(16), {R}.labels().map((b) => {{ const n = {R}.at(b.id); "
                 "return [b.id, b.y0 >= n.y, Math.round(Math.abs((b.x0 + b.x1) / 2 - n.x))]; }))")
        got = self.flow_open({"shot": os.path.join(self.state, "n.png"), "width": 390, "height": 844}, {"sleep": 600}, {"eval": probe})
        rows = got[-1]["eval"]
