    def test_flow_fills_the_canvas_with_a_margin(self):
        # the dots used to sit in the middle 40% of a wide canvas: the drawing is fitted to the canvas, a margin of
        # about 48px (plus room for the names at the sides and under the lowest dot)
        self.big_flow_hub(active=8, idle=40, executors=0)
        R = "window.__flowRec"
        box = (f"(() => {{ const r = document.querySelector('.flow canvas').getBoundingClientRect(), "
               f"p = {R}.nodes().map((id) => {R}.at(id)), xs = p.map((q) => q.tx), ys = p.map((q) => q.ty); "
               "return [Math.min(...xs), r.width - Math.max(...xs), Math.min(...ys), r.height - Math.max(...ys), r.width]; })()")
        for width, height in ((1440, 900), (390, 844)):
            with self.subTest(width=width):
                left, right, top, bottom, w = self.page(
                    {"go": f"http://127.0.0.1:{self.port}/#/flow"},
                    {"until": "!!document.querySelector('.flow canvas')"}, {"until": f"{R}.running()", "ms": 8000},
                    {"shot": os.path.join(self.state, f"flow-fit-{width}.png"), "width": width, "height": height},   # sets the window size
                    {"sleep": 1800}, {"eval": f"({R}.begin(), 1)"}, {"eval": box})[-1]["eval"]
                for side in (left, right, top, bottom):
                    self.assertGreaterEqual(side, 47, (left, right, top, bottom))
                self.assertLessEqual(max(left, right), 48 + min(96, w * 0.14), (left, right))
                self.assertLessEqual(top, 60)
                self.assertLessEqual(bottom, 84)

    def test_flow_line_label_lies_along_its_line_and_never_on_a_short_one(self):
        # "message" used to hang in the air and between "You" and "Hub": the word is drawn along its own line, at its
        # middle, and a line shorter than the word carries none
        self.big_flow_hub(active=4, idle=40, executors=0)
        R = "window.__flowRec"
        got = self.flow_open(
            {"eval": f"({R}.mode('h1'), 1)"}, {"sleep": 800},
            {"eval": f"(() => {{ const r = document.querySelector('.flow-seek'); r.value = 840; r.dispatchEvent(new Event('input')); "
                     f"{R}.step(16); return {R}.kinds().map((k) => {{ const a = {R}.at(k.from), b = {R}.at(k.to); "
                     "return { kind: k.kind, pair: [k.from, k.to].sort().join('-'), off: Math.hypot(k.cx - (a.x + b.x) / 2, k.cy - (a.y + b.y) / 2), "
                     "len: Math.hypot(b.x - a.x, b.y - a.y), w: k.w, "
                     "turn: Math.abs(Math.sin(k.angle - Math.atan2(b.y - a.y, b.x - a.x))) }; }); })()"})
        kinds = got[-1]["eval"]
        self.assertEqual([k["kind"] for k in kinds], ["message"])
        for k in kinds:
            self.assertLess(k["turn"], 0.05, k)             # along the line
            self.assertLess(k["off"], k["len"] * 0.13, k)   # at its middle (the line is a shallow arc)
            self.assertGreater(k["len"], k["w"] + 24, k)    # and the line is longer than the word

