    def test_flow_small_hub_now_keeps_quiet_sessions_as_empty_rings_and_a_replay_draws_everyone(self):
        # "Now" on a small hub: a session with no line in the window stays on the canvas as a quiet dot — an empty ring,
        # not named until pointed at; whoever talks has a name and a line. A replay of a period has no quiet dots
        self.big_flow_hub(active=3, idle=5, executors=2)   # 12 sessions is a "small" hub
        R = "window.__flowRec"
        got = self.flow_open({"eval": f"({R}.step(16), {R}.lines())"},
                             {"eval": f"[{R}.nodes(), {R}.summary().big, {R}.labels().map((b) => b.id), {R}.quiet()]"},
                             {"eval": f"({R}.mode('h1'), 1)"}, {"sleep": 800},
                             {"eval": f"({R}.step(16), [{R}.nodes(), {R}.quiet()])"})
        nodes, big, labels, quiet = got[-4]["eval"]
        self.assertFalse(big)
        self.assertEqual(sorted(quiet), [f"idle{i}" for i in range(5)])   # a quiet hub is not an empty canvas
        self.assertTrue({"owner", "hub", "act0", "act2", "lead", "lead-x0"} <= set(nodes), nodes)
        self.assertEqual(sorted(labels), sorted(n for n in nodes if n not in quiet))
        lines = got[-5]["eval"]   # every named dot of "Now" has its line on the canvas, and it is not faded away
        ends = {x for line in lines if line["alpha"] >= 0.1 for x in (line["from"], line["to"])}
        self.assertFalse([n for n in labels if n not in ends and n not in ("hub", "owner", "core", "schedule")],
                         (labels, lines))   # the center pair and the special dots stay
        nodes, quiet = got[-1]["eval"]
        self.assertIn("idle0", nodes)
        self.assertEqual(quiet, [])

    def test_flow_a_quiet_dot_is_named_when_pointed_at(self):
        self.big_flow_hub(active=3, idle=2, executors=0)
        R = "window.__flowRec"
        move = ("((p, c) => (c.dispatchEvent(new MouseEvent('mousemove', {clientX: c.getBoundingClientRect().left + p.x,"
                " clientY: c.getBoundingClientRect().top + p.y, bubbles: true})), 1))"
                f"({R}.at('idle1'), document.querySelector('.flow canvas'))")
        got = self.flow_open({"eval": f"({R}.step(16), {R}.labels().map((b) => b.id))"}, {"eval": move},
                             {"eval": f"({R}.step(16), [{R}.labels().map((b) => b.id), {R}.tip()])"})
        self.assertNotIn("idle1", got[-3]["eval"])
        labels, tip = got[-1]["eval"]
        self.assertIn("idle1", labels)
        self.assertEqual((tip or [None])[0], "idle1")

    def test_flow_a_shown_tip_is_put_in_place_each_frame_without_measuring_it_again(self):
        # the tip follows its dot every frame; reading its size there forced a layout per frame
        self.big_flow_hub(active=3, idle=2, executors=0)
        R = "window.__flowRec"
        move = ("((p, c) => (c.dispatchEvent(new MouseEvent('mousemove', {clientX: c.getBoundingClientRect().left + p.x,"
                " clientY: c.getBoundingClientRect().top + p.y, bubbles: true})), 1))"
                f"({R}.at('act1'), document.querySelector('.flow canvas'))")
        count = ("(() => { const t = document.querySelector('.flow-tip'); let n = 0;"
                 " for (const k of ['offsetWidth', 'offsetHeight']) Object.defineProperty(t, k, { get() { n++; return 100; },"
                 f" configurable: true }}); for (let i = 0; i < 5; i++) {R}.step(16);"
                 " for (const k of ['offsetWidth', 'offsetHeight']) delete t[k];"
                 f" return [n, {R}.tip(), !!{R}.tipBox()]; }})()")
        got = self.flow_open({"eval": f"({R}.step(16), 1)"}, {"eval": move}, {"eval": count})
        reads, tip, box = got[-1]["eval"]
        self.assertEqual((tip or [None])[0], "act1")
        self.assertTrue(box)
        self.assertEqual(reads, 0)

    def test_flow_a_quiet_dot_is_an_empty_ring_the_size_of_a_dot_and_a_touch_names_it(self):
        # a quiet session is a session, not dust: the size of any other dot, an empty ring in the full dot colour (a
        # graphic of 3:1 to the page), and on a phone a touch near it shows its name before anything opens
        self.big_flow_hub(active=3, idle=2, executors=0)
        R = "window.__flowRec"
        ink = ("((c, d) => (id, dx) => { const p = " + R + ".at(id); "
               "return c.getContext('2d').getImageData(Math.round((p.x + dx) * d), Math.round(p.y * d), 1, 1).data[3]; })"
               "(document.querySelector('.flow canvas'), window.devicePixelRatio || 1)")
        tap = (f"(() => {{ const p = {R}.at('idle1'), c = document.querySelector('.flow canvas'), r = c.getBoundingClientRect(); "
               "const o = {clientX: r.left + p.x + 15, clientY: r.top + p.y + 15, bubbles: true, pointerType: 'touch'}; "
               "c.dispatchEvent(new PointerEvent('pointerdown', o)); c.dispatchEvent(new MouseEvent('click', o)); "
               f"{R}.step(16); return [location.hash, {R}.tip()?.[0], {R}.labels().some((b) => b.id === 'idle1')]; }})()")
        got = self.flow_open({"eval": f"({R}.step(16), [({ink})('idle1', 0), ({ink})('idle1', 3), ({ink})('act1', 0), ({ink})('act1', 3)])"},
                             {"eval": tap})
        hole, rim, full, edge = got[-2]["eval"]
        self.assertEqual(hole, 0, got[-2]["eval"])        # nothing inside the ring
        self.assertGreater(rim, 200, got[-2]["eval"])     # the ring is where the edge of a dot is, and it is not pale
        self.assertGreater(min(full, edge), 200, got[-2]["eval"])
        self.assertEqual(got[-1]["eval"], ["#/flow", "idle1", True])

    def test_flow_expanded_executors_names_stand_apart_and_the_tip_covers_none_of_them(self):
        # a phone: the names of a lead's executors stood wall to wall around its ring and the lead's tip lay over them
        self.big_flow_hub(active=6, idle=40, executors=5)
        R = "window.__flowRec"
        click = ("((p, c) => (c.dispatchEvent(new MouseEvent('click', {clientX: c.getBoundingClientRect().left + p.x,"
                 " clientY: c.getBoundingClientRect().top + p.y, bubbles: true})), 1))"
                 f"({R}.badge('lead'), document.querySelector('.flow canvas'))")
        settle = f"(() => {{ for (let i = 0; i < 240; i++) {R}.step(16); return 1; }})()"
        got = self.flow_open({"shot": os.path.join(self.state, "n.png"), "width": 390, "height": 844}, {"sleep": 600},
                             {"eval": f"({R}.step(16), 1)"}, {"eval": click}, {"eval": settle}, {"eval": click.replace("'click'", "'mousemove'").replace(f"{R}.badge('lead')", f"{R}.at('lead')")},
                             {"eval": f"({R}.step(16), [{R}.labels(), {R}.tipBox()])"})
        labels, tip = got[-1]["eval"]
        mine = [b for b in labels if b["id"] == "lead" or b["id"].startswith("lead-x")]
        self.assertEqual(len(mine), 6, [b["id"] for b in labels])
        near = lambda a, b, g: a["x0"] - g < b["x1"] and b["x0"] - g < a["x1"] and a["y0"] - g < b["y1"] and b["y0"] - g < a["y1"]
        self.assertFalse([(a["id"], b["id"]) for a in mine for b in labels if a["id"] < b["id"] and near(a, b, 3.5)])
        self.assertTrue(tip)
        self.assertFalse([b["id"] for b in labels if near(tip, b, 0)], (tip, labels))

