    def test_flow_line_words_are_in_the_canvas_language_like_the_dot_names(self):
        # the dot names followed hubFlow.setLang, the words on the lines stayed in the page language
        self.big_flow_hub(active=3, idle=2, executors=0)
        R, F = "window.__flowRec", "window.hubFlow"
        # what the canvas wrote: fillText calls of one frame
        spy = ("(() => { const c = document.querySelector('.flow canvas').getContext('2d'), said = [], f = c.fillText;"
               f" c.fillText = function (t, ...a) {{ said.push(String(t)); return f.call(this, t, ...a); }}; {R}.step(16);"
               " c.fillText = f; return said; })()")
        got = self.flow_open({"eval": spy}, {"eval": f"({F}.setLang('de'), 1)"}, {"sleep": 1500}, {"eval": spy})
        root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        en = json.load(open(os.path.join(root, "i18n", "en.json"), encoding="utf-8"))
        de = json.load(open(os.path.join(root, "i18n", "de.json"), encoding="utf-8"))
        self.assertIn(en["web.flow.kind_message"], got[-4]["eval"])
        self.assertIn(de["web.flow.you"], got[-1]["eval"])
        self.assertIn(de["web.flow.kind_message"], got[-1]["eval"])
        self.assertNotIn(en["web.flow.kind_message"], got[-1]["eval"])

