    def test_flow_small_hub_now_a_working_session_with_no_line_is_not_a_quiet_ring(self):
        # a session at work with no signal in the last 15 minutes was drawn as the sleeping ones: an empty ring, no
        # breathing, no name. So was one that waits for an answer to its question
        self.big_flow_hub(active=3, idle=5, executors=2)   # 12 sessions is a "small" hub
        self.ev("turn.started", "idle1", marker=None)
