        at = dict(dots)
        execs = [i for i in at if i.startswith("lead-executor")]
        self.assertEqual(len(execs), 40, sorted(at))
        self.assertFalse([(a, b) for a in execs for b in at
                          if a != b and abs(at[a]["x"] - at[b]["x"]) < 14 and abs(at[a]["y"] - at[b]["y"]) < 14], dots)
