        on = lambda b, p: b["x0"] - 3 < p["x"] < b["x1"] + 3 and b["y0"] - 3 < p["y"] < b["y1"] + 3
        self.assertFalse([(b["id"], i) for b in labels for i in at if i != b["id"] and on(b, at[i])
                          and (i in execs or b["id"] in execs)], labels)
        cross = lambda a, b: a["x0"] < b["x1"] and b["x0"] < a["x1"] and a["y0"] < b["y1"] and b["y0"] < a["y1"]
        # the canvas is full: the lead's tip may lie on the lead's own name (the tip says it too), on nothing else
        self.assertFalse([b.get("id") or b.get("text") for b in labels + kinds if tip and cross(tip, b) and b.get("id") != "lead"],
                         (tip, labels, kinds))
        self.assertEqual(len(got[-1]["eval"]), 1, got[-1]["eval"])   # and it stands still from frame to frame

