    def test_public_views_are_detached_navigation_metadata(self):
        self.views_plugin()
        self.assertEqual(self.page({"eval": "typeof window.__viewsHub.views"})[-1]["eval"], "function")
        got = self.page({"eval": "window.__viewsHub.views()"})[-1]["eval"]
        self.assertEqual(got[:2], [
            {"id": "settings", "title": "Settings", "icon": "account", "order": 0, "owner": None},
            {"id": "schedule", "title": "Schedule", "icon": "clock", "order": 1, "owner": None},
        ])
        row = next(v for v in got if v["id"] == "registry")
        self.assertEqual(row, {"id": "registry", "title": "Registry", "icon": "/ext/registry/mark.svg",
                               "order": got.index(row), "owner": "registry"})
        self.assertTrue(any(v["id"] == "flow" for v in got))
        self.assertTrue(all(set(v) == {"id", "title", "icon", "order", "owner"} for v in got))
        changed = self.page({"eval": "(() => {const a = window.__viewsHub.views(); a[0].title = 'changed'; a.pop();"
                                     "return window.__viewsHub.views();})()"})[-1]["eval"]
        self.assertEqual(changed, got)
        got = self.page({"eval": """(() => {
          const hub = window.__viewsHub;
          window.__pastViews = 0;
          hub.addView({id:'passive', title:'Passive', render() {}});
          const off = hub.on('views', () => window.__pastViews++);
          Promise.resolve().then(() => {off(); window.__pastChecked = true;});
          return true;
        })()"""}, {"until": "window.__pastChecked === true"}, {"eval": "window.__pastViews"})
        self.assertEqual(got[-1]["eval"], 0, "subscribing must not replay registrations made before the subscription")
        self.page({"eval": """import('/static/js/state.js').then(async ({S}) => {
          S.snap.extensions.push({name:'mod:sample', base:'/ext/registry/', main:'module.js'});
          await (await import('/static/js/ext.js')).loadExtensions();
          window.__moduleLoaded = true;
        }); true"""}, {"until": "window.__moduleLoaded === true"})
        row = self.page({"eval": "window.__viewsHub.views().find(v => v.id === 'module-view')"})[-1]["eval"]
        self.assertEqual(row["owner"], "mod:sample")
        self.assertEqual(row["icon"], "/ext/registry/mark.svg")

    def test_view_badge_is_a_plain_number_in_the_menu_item(self):
        self.views_plugin()
        read = ("(() => { const b = [...document.querySelectorAll('.srow.nav')].find(x => x.textContent.includes('Registry'));"
                "const c = b.querySelector('.nav-count'); const cs = getComputedStyle(c);"
                "return {text: c.textContent, shown: cs.display !== 'none', label: b.getAttribute('aria-label'),"
                "name: b.querySelector('.nm').textContent, sub: b.querySelector('.lb').textContent, bg: cs.backgroundColor}; })()")
        def show(badge):
            js = "window.__viewsHub.addView({id:'registry', title:'Registry', render() {}, badge: %s})" % badge
            return self.page({"eval": js}, {"sleep": 300}, {"eval": read})[-1]["eval"]
        got = show("3")
        self.assertEqual((got["text"], got["shown"]), ("3", True))
        self.assertEqual(got["label"], "%s %s, 3" % (got["name"], got["sub"]))   # the subtitle stays in the spoken name
        self.assertEqual(got["bg"], "rgba(0, 0, 0, 0)")
        got = show("12")   # a repeated registration updates the same item
        self.assertEqual((got["text"], got["label"]), ("12", "%s %s, 12" % (got["name"], got["sub"])))
        for bad in ("0", "'5'", "-2", "1.5", "NaN", "1e21", "[]", "{}", "null", "undefined"):
            got = show(bad)
            self.assertEqual((got["text"], got["shown"], got["label"]), ("", False, None), bad)
        self.assertEqual(self.page({"eval": "window.__viewsHub.capabilities.viewBadge"})[-1]["eval"], 1)

    def test_extension_reentry_keeps_registration_order_and_one_fresh_result(self):
        self.views_plugin()
        path = pathlib.Path(self.state, "plug-registry")
        (path / "held.js").write_text("""
          await new Promise(resolve => { window.__releaseReentry = resolve; });
          window.__reentryOrder.push('first evaluated');
          export default () => window.__reentryOrder.push('first registered');
        """)
        for name in ("second", "arrived"):
            (path / f"{name}.js").write_text(
                f"window.__reentryOrder.push('{name} evaluated');"
                f"export default () => window.__reentryOrder.push('{name} registered');")
        got = self.page({"eval": """import('/static/js/state.js').then(async ({S}) => {
          const ext = await import('/static/js/ext.js');
          const saved = S.snap.extensions;
          const additions = [
            {name:'reentry-first', base:'/ext/registry/', main:'held.js'},
            {name:'reentry-missing', base:'/ext/registry/', main:'absent.js'},
            {name:'reentry-second', base:'/ext/registry/', main:'second.js'}
          ];
          const load = entries => {
            S.snap.extensions = entries;
            const pending = ext.loadExtensions();
            S.snap.extensions = saved;
            return pending;
          };
          window.__reentryOrder = [];
          const first = load(additions);
          const updated = [...additions, {name:'reentry-arrived', base:'/ext/registry/', main:'arrived.js'}];
          // renders while the first module still waits: they settle before it is released
          window.__reentryRepeated = await Promise.all(Array.from({length:5}, () => load(updated)));
          window.__reentryFirst = await first;
          window.__reentryFollowup = await load(updated);
          window.__reentryRetry = await load(updated);
          window.__reentryDone = true;
        }); true"""}, {"until": "typeof window.__releaseReentry === 'function'"},
            {"until": "Array.isArray(window.__reentryRepeated)"},
            {"eval": "({order:window.__reentryOrder, repeated:window.__reentryRepeated})"},
            {"eval": "window.__releaseReentry(); true"},
            {"until": "window.__reentryDone === true"},
            {"eval": "({order:window.__reentryOrder, first:window.__reentryFirst, "
                     "followup:window.__reentryFollowup, retry:window.__reentryRetry})"})
        self.assertTrue(got[1]["until"] and got[2]["until"], "repeated renders must settle while the first import waits")
        self.assertEqual(got[3]["eval"], {"order": [], "repeated": [False] * 5},
                         "repeated renders must not register a later extension early")
        self.assertTrue(got[-2]["until"], "a failed import must not strand the loader")
        self.assertEqual(got[-1]["eval"], {
            "order": ["first evaluated", "first registered", "second evaluated", "second registered",
                      "arrived evaluated", "arrived registered"],
            "first": True, "followup": True, "retry": False,
        })

    def test_public_views_notify_late_registration_replacement_and_unsubscribe(self):
        self.views_plugin()
        self.assertEqual(self.page({"eval": "typeof window.__viewsHub.on"})[-1]["eval"], "function")
        self.page({"eval": """(() => {
          const hub = window.__viewsHub;
          window.__viewEvents = [];
          window.__offBroken = hub.on('views', () => {throw new Error('listener test');});
          window.__offViews = hub.on('views', rows => {window.__viewEvents.push(rows); rows[0].title = 'changed';});
          window.__offOther = hub.on('views', rows => {window.__otherViews = rows;});
          hub.addView({id: 'late', title: 'Interim', render() {}});
          hub.addView({id: 'late', title: 'Late', render() {}});
          return true;
        })()"""}, {"until": "window.__viewEvents.length === 1"})
        got = self.page({"eval": "[window.__viewsHub.views(), window.__otherViews]"})[-1]["eval"]
        self.assertEqual(got[0], got[1])
        self.assertEqual(got[0][-1]["id"], "late")
        self.assertEqual(got[0][-1]["icon"], "board")
        self.page({"eval": "window.__offBroken(); window.__viewsHub.addView({id:'late', title:'Updated', render() {}}); true"},
                  {"until": "window.__viewEvents.length === 2"})
        self.page({"eval": "window.__viewsHub.addView({id:'late', title:'Updated', render() {}}); true"}, {"sleep": 100})
        got = self.page({"eval": "window.__viewEvents.length"})[-1]["eval"]
        self.assertEqual(got, 2, "unchanged metadata must not emit again")
        self.page({"eval": "window.__offViews(); window.__offViews(); window.__offOther();"
                            "window.__viewsHub.addView({id:'late', title:'Final', render() {}}); true"}, {"sleep": 100})
        got = self.page({"eval": "[window.__viewEvents.length, window.__viewsHub.views().filter(v => v.id === 'late')]"})[-1]["eval"]
        self.assertEqual(got[0], 2)
        self.assertEqual(len(got[1]), 1)
        self.assertEqual(got[1][0]["title"], "Final")

    def test_settings_show_new_choices_and_plugin_options_changed_elsewhere(self):
        # PR #218: a choice option added by the hub (a value not in the list) and a plugin checkbox changed in
        # another
        # window — "Settings" showed the old value until the page was reloaded
        from unittest import mock
        path = os.path.join(self.state, "plug-opts")
        os.makedirs(path)
        with open(os.path.join(path, "hub-plugin.json"), "w") as f:
            json.dump({"name": "opts", "description": "opts", "why": "test", "web": "main.js", "hub": "^1.0"}, f)
        with open(os.path.join(path, "main.js"), "w") as f:
            f.write("export default hub => { window.__optsHub = hub; hub.addOptions({title: 'Opts', "
                    "options: [{key: 'flag', label: 'Plugin flag'}]}); };")
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"extensions": {"opts": {"path": path, "web": "main.js"}}}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        # a snapshot with a new option on the first choice field of "General"
        # (as the server returns it: the value is in choices)
        grow = """import('/static/js/state.js').then(({S, render}) => {
          const row = S.snap.settings.find((r) => r.kind === 'enum' && Array.isArray(r.choices)
            && !r.place?.startsWith('module:') && r.place !== 'hidden'), label = row.label;
          S.snap = {...S.snap, settings: S.snap.settings.map((r) => r === row
            ? {...r, choices: [...r.choices, 'zz-new'], value: 'zz-new'} : r)};
          render();
          window.__grown = label;
        }); 1"""
        seen = """(() => { const sel = document.querySelector(`main .settings-groups select[aria-label="${window.__grown}"]`);
          return [[...sel.options].some((o) => o.value === 'zz-new'), sel.value]; })()"""
        got = self.page({"local": {"hub.settingsTab": "general"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": "!!document.querySelector('main .settings-groups select')", "ms": 8000},
                        {"eval": grow}, {"until": "!!window.__grown"}, {"eval": seen})
        self.assertEqual(got[-1]["eval"], [True, "zz-new"])
        box = ("(() => { const l = [...document.querySelectorAll('main label')].find((x) => x.textContent.includes("
               "'Plugin flag')); return l.querySelector('input').checked; })()")
        other = ("import('/static/js/state.js').then(({render}) => { localStorage.setItem('hub.opt.opts', "
                 "JSON.stringify({flag: true})); render(); window.__other = true; }); 1")
        look = "[...document.querySelectorAll('[role=tab]')].find((b) => b.textContent.startsWith('Look')).click(), 1"
        got = self.page({"eval": look},
                        {"until": "document.body.innerText.includes('Plugin flag')", "ms": 8000}, {"eval": box},
                        {"eval": other}, {"until": "window.__other === true"}, {"eval": box})
        self.assertEqual([g["eval"] for g in got if "eval" in g], [1, False, 1, True])

