    def test_picked_cards_stay_after_leaving_the_mode_and_a_reload_and_a_card_that_left_the_board_drops_out(self):
        self.picking_board()
        got = self.page({"go": self.BOARD % self.port}, {"until": "!!document.querySelector('.board .board-card')", "ms": 8000},
                        {"eval": self.fn(self.CIRCLE, "TASK-2", False)}, {"eval": self.fn(self.CIRCLE, "TASK-6", False)},
                        {"sleep": 150}, {"eval": self.fn(self.BTN_CLICK, "Ask about 2 in the chat")}, {"sleep": 150}, {"eval": self.PICKED},
                        {"go": "about:blank"}, {"go": self.BOARD % self.port},
                        {"until": "!!document.querySelector('.board .board-card')", "ms": 8000}, {"sleep": 300}, {"eval": self.PICKED})
        self.assertEqual(got[7]["eval"]["chips"], ["TASK-2", "TASK-6"])          # the chips wait over the field, the mode is off
        self.assertEqual((got[7]["eval"]["foot"], got[7]["eval"]["mode"]), (None, False))
        self.assertEqual(got[-1]["eval"]["chips"], ["TASK-2", "TASK-6"])         # and over a reload
        # TASK-6 is archived: the next read of the board drops it from the picks; TASK-2 changes column and stays
        board = os.path.join(self.state, "directions", "maps", "backlog")
        os.remove(os.path.join(board, "tasks", "task-6.md"))
        path = os.path.join(board, "tasks", "task-2.md")
        with open(path) as f:
            text = f.read()
        with open(path, "w") as f:
            f.write(text.replace("status: To Do", "status: Done"))
        got = self.page({"go": "about:blank"}, {"go": self.BOARD % self.port},
                        {"until": "document.querySelectorAll('form.composer .mention-bar .mchip').length === 1", "ms": 8000},
                        {"eval": self.PICKED})
        self.assertEqual(got[-1]["eval"]["chips"], ["TASK-2"])

    def test_asking_in_the_chat_sends_the_cards_as_a_field_and_the_chips_go(self):
        self.picking_board()
        got = self.page({"go": self.BOARD % self.port}, {"until": "!!document.querySelector('.board .board-card')", "ms": 8000},
                        {"eval": self.fn(self.CIRCLE, "TASK-2", False)}, {"eval": self.fn(self.CIRCLE, "TASK-5", False)},
                        {"sleep": 150}, {"eval": self.fn(self.BTN_CLICK, "Ask about 2 in the chat")}, {"sleep": 250},
                        {"eval": "[document.activeElement.id, document.querySelector('form.composer .mention-lead')?.textContent]"},
                        {"eval": self.PICKED},
                        {"eval": self.fn(self.TYPE, "#msg", "what blocks this?")}, {"eval": self.fn(self.KEY, "#msg", False)},
                        {"until": "document.querySelectorAll('form.composer .mention-bar .mchip').length === 0", "ms": 8000},
                        {"eval": self.PICKED})
        self.assertEqual(got[7]["eval"], ["msg", "About tasks:"])
        self.assertEqual((got[8]["eval"]["foot"], got[8]["eval"]["chips"]), (None, ["TASK-2", "TASK-5"]))
