    def test_handing_cards_to_executors_always_asks_first_with_the_places_from_the_snapshot(self):
        self.picking_board(parallel=3)   # parallelism 3, one executor of `maps` is alive: two places are free
        bar = ("(() => ({msg: document.querySelector('.sel-msg')?.textContent, hint: [...document.querySelectorAll('.sel-confirm .hint')]"
               ".map((h) => h.textContent), send: document.querySelector('.sel-send')?.textContent, "
               "sendOff: document.querySelector('.sel-send')?.disabled, buttons: [...document.querySelectorAll('.select-foot .btn')]"
               ".map((b) => b.textContent.trim())}))()")
        got = self.page({"go": self.BOARD % self.port}, {"until": "!!document.querySelector('.board .board-card')", "ms": 8000},
                        {"eval": self.fn(self.CIRCLE, "TASK-1", False)}, {"eval": self.fn(self.CIRCLE, "TASK-2", False)},
                        {"eval": self.fn(self.CIRCLE, "TASK-3", False)}, {"sleep": 150},
                        {"eval": self.fn(self.BTN_CLICK, "Hand to executors")}, {"sleep": 150}, {"eval": bar},
                        {"eval": self.fn(self.CIRCLE, "TASK-4", False)}, {"sleep": 150}, {"eval": bar})
        self.assertEqual(self.sent(), [])   # the page raises nothing and writes nothing until "Send"
        first = got[8]["eval"]
        self.assertEqual(first["buttons"][:5], ["Clear", "Cancel", "Ask about 3 in the chat", "Hand to executors", "Copy list"])
        # the words name the picked cards themselves: a lead reading "these cards" raised executors for the whole board
        self.assertIn("for each selected card: TASK-1, TASK-2, TASK-3 — one per `hub task run … --board <number>`", first["msg"])
        self.assertIn("Do not touch other cards on the board.", first["msg"])
        self.assertEqual(first["hint"][0], "Parallelism 3, busy 1: 2 start at once, 1 wait in the queue")
        self.assertIn("a separate session with its own cost", first["hint"][1])
        self.assertEqual((first["send"], first["sendOff"]), ("Send to “maps”", False))
        self.assertEqual(got[11]["eval"]["hint"][0], "Parallelism 3, busy 1: 2 start at once, 2 wait in the queue")   # four cards
        # no core in this test: the message waits in the hub's mailbox, which is not "sent" yet — the mode stays with its caption
        # (the core's decision, and "sent" with the mode off, is in test_a_hand_over_the_core_has_not_decided_yet…)
        got = self.page({"eval": self.fn(self.BTN_CLICK, "Send to “maps”")}, {"sleep": 400}, {"eval": self.PICKED},
                        {"eval": "!!document.querySelector('.sel-wait')"})
        (sent,) = self.sent()
        self.assertEqual((sent["to"], sent["text"]), ("maps", first["msg"].replace("TASK-3 —", "TASK-3, TASK-4 —")))   # four cards by then
        self.assertEqual([x["id"] for x in sent["tasks"]], ["TASK-1", "TASK-2", "TASK-3", "TASK-4"])
        self.assertEqual((got[-2]["eval"]["picked"], got[-2]["eval"]["mode"], got[-1]["eval"]),
                         (["TASK-1", "TASK-2", "TASK-3", "TASK-4"], True, True))

    def test_handing_one_card_of_several_open_ones_names_it_and_forbids_the_rest(self):
        # 30.10: one card picked, the words said "each of these cards" — the lead raised executors for all open ones
        self.picking_board(parallel=3)
        msg = "document.querySelector('.sel-msg')?.textContent"
        got = self.page({"go": self.BOARD % self.port}, {"until": "!!document.querySelector('.board .board-card')", "ms": 8000},
                        {"eval": self.fn(self.CIRCLE, "TASK-3", False)},
                        {"sleep": 150}, {"eval": self.fn(self.BTN_CLICK, "Hand to executors")}, {"sleep": 150}, {"eval": msg})
        text = got[-1]["eval"]
        self.assertIn("TASK-3", text)
        self.assertIn("for the card TASK-3", text)
        self.assertIn("Do not touch other cards on the board", text)
        self.assertNotIn("for each", text)
        for other in ("TASK-1", "TASK-2", "TASK-4"):
            self.assertNotIn(other, text)
        self.page({"eval": self.fn(self.BTN_CLICK, "Send to “maps”")}, {"sleep": 400})
        (sent,) = self.sent()
        self.assertEqual(sent["text"], text)
        self.assertEqual([x["id"] for x in sent["tasks"]], ["TASK-3"])

    def test_handing_over_can_be_edited_in_the_field_or_cancelled_and_is_refused_for_a_lead_without_executors(self):
        self.picking_board(parallel=3)
        got = self.page({"go": self.BOARD % self.port}, {"until": "!!document.querySelector('.board .board-card')", "ms": 8000},
                        {"eval": self.fn(self.CIRCLE, "TASK-1", False)},
                        {"sleep": 150}, {"eval": self.fn(self.BTN_CLICK, "Hand to executors")}, {"sleep": 150},
                        {"eval": "document.querySelector('.sel-cancel').click(), 1"}, {"sleep": 150}, {"eval": self.PICKED},
                        {"eval": self.fn(self.BTN_CLICK, "Hand to executors")}, {"sleep": 150},
                        {"eval": self.fn(self.BTN_CLICK, "Edit the text in the input field")}, {"sleep": 250},
                        {"eval": "[document.querySelector('#msg').value, document.activeElement.id]"}, {"eval": self.PICKED})
        self.assertEqual(self.sent(), [])
        self.assertEqual((got[8]["eval"]["foot"], got[8]["eval"]["picked"]), ("Picked: 1", ["TASK-1"]))   # cancelled: still picked
        text, focus = got[13]["eval"]
        self.assertIn("Start an executor for the card TASK-1", text)
        self.assertEqual(focus, "msg")
        self.assertEqual((got[14]["eval"]["foot"], got[14]["eval"]["chips"]), (None, ["TASK-1"]))   # the field is free, the card is a chip
        # no executors for this lead: nothing to hand to — "Send" is off and says why
        self.ev("session.solo_set", "maps", on=True, channel="web", owner=True)
        self.settle()
        got = self.page({"eval": self.fn(self.CIRCLE, "TASK-2", False)}, {"sleep": 150},   # TASK-1 is a chip already: its circle would take it off
                        {"eval": self.fn(self.BTN_CLICK, "Hand to executors")}, {"sleep": 150},
                        {"eval": "[document.querySelector('.sel-send').disabled, document.querySelector('.sel-confirm .hint').textContent]"})
        self.assertTrue(got[-1]["eval"][0])
        self.assertIn("are off (parallelism 0)", got[-1]["eval"][1])

