    def test_the_hand_over_pressed_again_after_a_lost_answer_is_one_message(self):
        # the answer to "Send" is lost: the owner presses it again — the same client_id, so the core takes one message
        # (two would raise the executors twice); another set of cards is a new message
        self.picking_board(parallel=3)
        spy = ("(() => { window.__ids = []; window.__drop = true; const of = window.fetch; window.fetch = (u, o) => { "
               "if (u === '/api/send') { __ids.push(JSON.parse(o.body).client_id); if (__drop) { __drop = false; "
               "return Promise.reject(new TypeError('offline')); } } return of(u, o); }; return 1; })()")
        got = self.page({"go": self.BOARD % self.port}, {"until": "!!document.querySelector('.board .board-card')", "ms": 8000},
                        {"eval": spy}, {"eval": self.fn(self.CIRCLE, "TASK-1", False)},
                        {"eval": self.fn(self.CIRCLE, "TASK-2", False)},
                        {"sleep": 150}, {"eval": self.fn(self.BTN_CLICK, "Hand to executors")}, {"sleep": 150},
                        {"eval": self.fn(self.BTN_CLICK, "Send to “maps”")}, {"sleep": 300},
                        {"eval": "[document.querySelector('.sel-error')?.textContent || null, document.querySelectorAll('.board-card.picked').length]"},
                        {"eval": self.fn(self.BTN_CLICK, "Send to “maps”")}, {"sleep": 400}, {"eval": "__ids"})
        self.assertIsNotNone(got[10]["eval"][0])        # the first try failed: the cards are still picked, the reason is shown
        self.assertEqual(got[10]["eval"][1], 2)
        ids = got[-1]["eval"]
        self.assertEqual(len(ids), 2)
        self.assertEqual(ids[0], ids[1])
        self.assertEqual(len(self.sent()), 1)

    def test_a_hand_over_the_core_has_not_decided_yet_is_not_sent_and_a_late_refusal_keeps_the_cards(self):
        # "queued" (the hub's mailbox, the core did not answer in time) is not delivery: the bar stays with the waiting
        # caption and no "Sent"; the core refuses later — the cards stay picked with the reason, the owner can send again;
        # the core accepts the second try — only then the mode closes with "Sent to"
        self.picking_board(parallel=3)
        self.web.decide_wait = 0
        send, banner = self.fn(self.BTN_CLICK, "Send to “maps”"), "document.getElementById('banner').textContent"
        got = self.page({"go": self.BOARD % self.port}, {"until": "!!document.querySelector('.board .board-card')", "ms": 8000},
                        {"eval": self.fn(self.CIRCLE, "TASK-1", False)}, {"sleep": 150},
                        {"eval": self.fn(self.BTN_CLICK, "Hand to executors")}, {"sleep": 150}, {"eval": send},
                        {"until": "!!document.querySelector('.sel-wait')", "ms": 8000}, {"sleep": 1500},
                        {"eval": f"[{banner}, document.querySelector('.sel-wait')?.textContent, "
                                 "document.querySelector('.sel-send').disabled, document.querySelector('.sel-error')?.textContent || null]"},
                        {"eval": self.PICKED})
        self.assertTrue(got[7]["until"], got)
        shown, wait, off, error = got[9]["eval"]
        self.assertNotIn("Sent to", shown)
        self.assertIn("in its spool", wait)
        self.assertEqual((off, error), (True, None))   # waiting: no second press, no error yet
        self.assertEqual(got[10]["eval"]["picked"], ["TASK-1"])
        self.core_refuses("session maps is busy with something important")
        got = self.page({"until": "document.querySelector('.sel-error')?.textContent", "ms": 15000}, {"eval": self.PICKED},
                        {"eval": f"[{banner}, !!document.querySelector('.sel-wait'), document.querySelector('.sel-send').disabled]"})
        self.assertIn("Not sent to “maps”: session maps is busy with something important.", got[0]["until"])
        self.assertEqual(got[1]["eval"]["picked"], ["TASK-1"])   # the cards are still picked
        self.assertEqual(got[2]["eval"], [got[2]["eval"][0], False, False])
        self.assertNotIn("Sent to", got[2]["eval"][0])
        self.core_stop()
        self.core_stop = None
        self.web.decide_wait = 0
        self.page({"eval": send}, {"until": "!!document.querySelector('.sel-wait')", "ms": 8000})
        self.core_decides()
        got = self.page({"until": "!document.querySelector('.select-foot')", "ms": 15000}, {"eval": self.PICKED}, {"eval": banner})
        self.assertTrue(got[0]["until"], got)
        self.assertEqual(got[1]["eval"]["picked"], [])
        self.assertIn("Sent to “maps”", got[2]["eval"])
        refused, sent = [e["data"] for e in journal.read(self.j.path) if e["type"] == "message.received" and e["data"].get("tasks")]
        self.assertEqual([x["id"] for x in sent["tasks"]], ["TASK-1"])
        self.assertNotEqual(refused["client_id"], sent["client_id"])   # the core said no: the second try is a new message

    def queued_hand_over(self, ids=("TASK-1",)):
        """The board with `ids` picked and the hand-over sent while no core decides: the page waits (queued)."""
        self.picking_board(parallel=3)
        self.web.decide_wait = 0
        steps = [{"go": self.BOARD % self.port}, {"until": "!!document.querySelector('.board .board-card')", "ms": 8000}]
        steps += [{"eval": self.fn(self.CIRCLE, i, False)} for i in ids]
        steps += [{"sleep": 150}, {"eval": self.fn(self.BTN_CLICK, "Hand to executors")}, {"sleep": 150},
                  {"eval": self.fn(self.BTN_CLICK, "Send to “maps”")}, {"until": "!!document.querySelector('.sel-wait')", "ms": 8000}]
        self.assertTrue(self.page(*steps)[-1]["until"])

    def test_a_late_refusal_shows_its_reason_even_when_the_confirm_box_was_closed_while_waiting(self):
        self.queued_hand_over()
        got = self.page({"eval": "document.querySelector('.sel-cancel').click(), 1"}, {"sleep": 150},
                        {"eval": "!!document.querySelector('.sel-confirm')"})
        self.assertFalse(got[-1]["eval"])   # the box is closed, the hand-over is still waiting
        self.core_refuses("session maps is busy with something important")
        got = self.page({"until": "document.querySelector('.sel-error')?.textContent", "ms": 15000}, {"eval": self.PICKED})
        self.assertIn("Not sent to “maps”: session maps is busy with something important.", got[0]["until"])
        self.assertEqual(got[1]["eval"]["picked"], ["TASK-1"])

    def test_cards_picked_while_a_hand_over_waits_stay_picked_when_it_is_accepted(self):
        self.queued_hand_over()
        got = self.page({"eval": self.fn(self.CIRCLE, "TASK-2", False)}, {"sleep": 150}, {"eval": self.PICKED})
        self.assertEqual(got[-1]["eval"]["picked"], ["TASK-1", "TASK-2"])
