    def test_the_same_hand_over_cannot_be_pressed_again_after_a_reset_while_it_waits(self):
        # the bar is rebuilt by "Reset": the same cards may not be sent again while the first hand-over waits (the core would
        # take both and raise the executors twice); the waiting line is in the bar, not only in the confirm box
        self.queued_hand_over()
        got = self.page({"eval": self.fn(self.BTN_CLICK, "Clear")}, {"sleep": 150}, {"eval": self.PICKED},
                        {"eval": self.fn(self.CIRCLE, "TASK-1", False)}, {"sleep": 150},
                        {"eval": "!!document.querySelector('.sel-wait')"},   # the box is closed: the line is still there
                        {"eval": self.fn(self.BTN_CLICK, "Hand to executors")}, {"sleep": 150},
                        {"eval": "document.querySelector('.sel-send').disabled"})
        self.assertEqual(got[2]["eval"]["picked"], [])   # the reset did work
        self.assertEqual((got[5]["eval"], got[-1]["eval"]), (True, True))
        self.assertEqual(len(self.sent()), 1)

