    def test_a_long_finger_press_on_a_card_turns_the_mode_on_and_the_phone_bar_covers_the_field(self):
        self.picking_board()
        cover = ("(() => { const f = document.querySelector('.select-foot'), c = document.querySelector('form.composer'); "
                 "return {foot: getComputedStyle(f).position, field: getComputedStyle(c).visibility, "
                 "bottom: Math.round(f.getBoundingClientRect().bottom) === innerHeight}; })()")
