    def test_direction_board_says_it_lags(self):
        # boards-sync A: after the last card edit the lead got the owner's word and nobody touched the cards — a line
        # above the columns (core/board.py lag); the old page server does not send it and the page draws nothing
        import time
        from unittest import mock
        root = os.path.join(self.state, "directions")
        d = os.path.join(root, "maps", "backlog", "tasks")
        os.makedirs(d)
        path = os.path.join(d, "task-1.md")
        with open(path, "w") as f:
            f.write("---\nid: TASK-1\ntitle: 'Slice 2: import'\nstatus: In Progress\n---\n\nDetails\n")
        os.utime(path, (time.time() - 3600, time.time() - 3600))
        env = mock.patch.dict(os.environ, {"HUB_DIRECTIONS": root})
        env.start()
        self.addCleanup(env.stop)
        self.ev("session.requested", "maps", session_id="s-m", cwd="/m", channel="cli", owner=True)
        self.ev("session.started", "maps", session_id="s-m")
        self.j.append("task.backlog", None, {"slug": "maps", "channel": "session", "owner": False, "sender": "maps"})
        e = self.j.append("message.received", None, {"to": "maps", "text": "code first, then the switch",
                                                     "channel": "web", "owner": True}, ts=time.time() - 20 * 60)
        self.j.append("turn.started", "maps", {"marker": f"m{e['seq']}"}, ts=time.time() - 20 * 60 + 1)   # delivered
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/board/maps"},
                        {"until": "!!document.querySelector('.boards-body .board-lag')", "ms": 8000},
                        {"eval": "document.querySelector('.board-lag').textContent"})
        self.assertTrue(got[1]["until"], got)
        self.assertEqual(got[2]["eval"], "The board is behind: since the last card edit, the owner's word, 20 min")

    def test_direction_board_names_the_lead_working_on_a_card_itself(self):
        # a card In Progress with no executor behind it: while the lead is in a turn in which it edited the card, the
        # fact is "the lead works" (not "no executor"); after the turn it is "no executor" again (core/board.py editing_now)
        import time
        from unittest import mock
        root = os.path.join(self.state, "directions")
        d = os.path.join(root, "maps", "backlog", "tasks")
        os.makedirs(d)
        with open(os.path.join(d, "task-1.md"), "w") as f:
            f.write("---\nid: TASK-1\ntitle: 'Slice 2: import'\nstatus: In Progress\n---\n\nDetails\n")
        env = mock.patch.dict(os.environ, {"HUB_DIRECTIONS": root})
        env.start()
        self.addCleanup(env.stop)
        self.ev("session.requested", "maps", session_id="s-m", cwd="/m", channel="cli", owner=True)
        self.ev("session.started", "maps", session_id="s-m")
        self.j.append("task.backlog", None, {"slug": "maps", "channel": "session", "owner": False, "sender": "maps"})
        self.j.append("turn.started", "maps", {"marker": None, "prompt_head": "go"}, ts=time.time() - 30)
        self.j.append("direction.card", None, {"slug": "maps", "card": "TASK-1", "fields": ["append-notes"],
                                               "channel": "session", "owner": False, "sender": "maps"}, ts=time.time() - 20)
        fact = "(document.querySelector('.board-fact')?.innerText || '')"
        self.settle()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/board/maps"},
                        {"until": f"{fact}.includes('maps')", "ms": 8000}, {"eval": fact})
        self.assertEqual(got[2]["eval"], "⚙ maps working")
        self.j.append("turn.result", "maps", {"text": "ok"}, ts=time.time() - 5)
