    def test_grips_sit_in_the_gaps_and_drag_over_a_frame(self):
        # owner complaint (the resize handle sits crooked and does not work): the right handle stood inside the
        # panel window
        # (4 px from its edge, the left one inside the list), and dragging toward a panel with a file (iframe) was
        # impossible: the frame captured the mouse movement
        from unittest import mock
        path = os.path.join(self.state, "plug-frame")
        os.makedirs(path)
        with open(os.path.join(path, "hub-plugin.json"), "w") as f:
            json.dump({"name": "frame", "description": "frame", "why": "w", "web": "main.js", "hub": "^1.6"}, f)
        with open(os.path.join(path, "main.js"), "w") as f:
            f.write("export default function register(hub) {\n"
                    "  hub.addSlot('session.aside', { id: 'f', title: 'File', render(root) {"
                    " if (!root.firstChild) root.append(hub.el('iframe', 'probe-frame')); } });\n}\n")
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"extensions": {"frame": {"path": path, "web": "main.js"}}}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        self.quiet_feed()
        geo = ("(() => { const r = (s) => document.querySelector(s).getBoundingClientRect(), mid = (s) => (r(s).left + r(s).right) / 2;"
               " return [mid('.grip.left') - (r('aside').right + r('main').left) / 2,"
               " mid('.grip.right') - (r('main').right + r('.side').left) / 2]; })()")
        hold = ("(() => { const g = document.querySelector('.grip.right'), b = g.getBoundingClientRect();"
                " g.dispatchEvent(new PointerEvent('pointerdown', {bubbles: true, pointerId: 1, button: 0, clientX: b.left + 4, clientY: 300}));"
                " const pe = getComputedStyle(document.querySelector('.probe-frame')).pointerEvents;"
                " document.dispatchEvent(new PointerEvent('pointerup', {bubbles: true, pointerId: 1, button: 0, clientX: b.left + 4, clientY: 300}));"
                " return pe; })()")
        got = self.page({"width": 1400, "height": 800}, {"go": f"http://127.0.0.1:{self.port}/#/s/a"},
                        {"eval": "localStorage.setItem('hub.side', 'open'); 1"}, {"go": f"http://127.0.0.1:{self.port}/#/s/a"},
                        {"until": "document.querySelector('.side .probe-frame') && !document.querySelector('.side').hidden",
                         "ms": 5000}, {"eval": geo}, {"eval": hold})
        self.assertTrue(got[3]["until"], got[3])
        left, right = got[4]["eval"]
        self.assertLessEqual(abs(left), 1, got[4])                    # left — in the middle of the gap
        self.assertLessEqual(abs(right), 1, got[4])                   # right — in the middle of the gap
        self.assertEqual(got[5]["eval"], "none")                      # while dragging, the frame does not capture the mouse

