    # --- free groups and a custom icon (docs/spec-session-groups.md) -----------------------------------------------
    def fleet(self):
        """An invented fleet: a hub, two specialists (one has an executor), two working sessions; the core
        decides for real."""
        self.ev("session.requested", "hub", session_id="s-hub", cwd="/h", kind="hub", channel="cli", owner=True)
        for n, extra in (("devops", {"role": "agent", "about": "DevOps", "icon": "🛠"}),
                         ("seo", {"role": "agent", "about": "SEO", "icon": "🔎"}), ("maps", {}), ("notes", {})):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True, **extra)
        self.ev("session.requested", "devops-fix", session_id="s-x", cwd="/w", executor=True, raised_by="devops",
                channel="cli", owner=True)
        for n in ("hub", "devops", "seo", "maps", "notes", "devops-fix"):
            self.ev("session.started", n, session_id=f"s-{n}")
        self.core_decides()

    ROW = "#list li[data-s=\"{}\"] > .srow"
    # the list has settled: its top did not move for 300 ms (page plugins load by themselves and add items
    # above the
    # list — dragging and clicking right after load would miss the row)
    STEADY = {"until": "(() => { const t = Math.round(document.getElementById('list').getBoundingClientRect().top), now = Date.now(); "
                       "if (window.__lt !== t) { window.__lt = t; window.__ltAt = now; } return now - window.__ltAt > 300; })()"}
    IN = "!!document.querySelector('#list .sgroup[data-g=\"{}\"] li[data-s=\"{}\"]')"
    # autoscroll steps per frame (groups.js, up to 22 px), and chrome-headless-shell under load draws 10-15
    # frames
    # per second: 30 groups (~2300 px) scroll in 8-15 s
    AUTOSCROLL_MS = 30000

    def snap(self, ok=lambda st: True, ms=5000):
        """Core state from the test journal (decisions — core_decides); waits until ok(state) — the page sends
        the edit and
        shows it at once, the core records it a bit later."""
        from core import journal, reducer
        end = time.time() + ms / 1000
        while True:
            st = reducer.fold(reducer.empty(), journal.read(self.j.path))
            try:
                if ok(st) or time.time() > end:
                    return st
            except (KeyError, TypeError, IndexError):
                if time.time() > end:
                    return st
            time.sleep(0.05)

    # --- the session icon search: any emoji by a word (modules/web/static/js/groups.js, static/emoji/<lang>.json) ---------
    PAL = "#list li[data-s=\"devops\"] .avatar"
    FOUND = "[...document.querySelectorAll('.palette .pal-grid .pal-e')].map(b => b.textContent || b.querySelector('.kit-img')?.getAttribute('aria-label'))"
    # the grid without a word: the page's 32; in Clean its 24 characters first, then those of the 32 that have none
    PAL_GRID = {"classic": 32, "clean": 44}
    ICON = staticmethod(lambda q: f"((e) => e?.textContent || e?.getAttribute('aria-label'))(document.querySelector('{q}'))")

    def palette_search(self, look, word, *steps):
        """The palette of devops opened in the look, `word` typed into the search by key presses; steps — after the typing."""
        go = {"go": f"http://127.0.0.1:{self.port}/#/", **({"look": None} if look == "clean" else {})}
        typing = [{"typed": word}, {"until": f"({self.FOUND}).length !== {self.PAL_GRID[look]}", "ms": 8000}] if word else []
        return self.page({"go": "about:blank", "look": None}, go, {"until": f"!!document.querySelector('{self.PAL}')"},
                         {"eval": f"document.querySelector('{self.PAL}').click(), 1"},
                         {"until": "!!document.querySelector('.palette .pal-find input')"}, *typing, *steps)

    def test_palette_search_finds_any_emoji_by_a_word_and_a_click_sets_it(self):
        # owner, 17.11: "add a search by emoji here": a word (the hub's language and English) finds any emoji, not only the 32
        self.fleet()
        loaded = "performance.getEntriesByType('resource').filter(r => r.name.includes('/emoji/')).map(r => r.name.split('/').pop())"
        for look in ("clean", "classic"):
            with self.subTest(look=look):
                # nothing is loaded before the first letter; the field has the focus on a desktop; the grid is the 32 as before
                got = self.palette_search(look, "", {"eval": "document.activeElement === document.querySelector('.palette .pal-find input')"},
                                          {"eval": loaded}, {"eval": f"({self.FOUND}).length"},
                                          {"eval": "[...document.querySelectorAll('.palette .pal-grid .pal-e')].filter((b) => b.offsetParent !== null).length"},
                                          {"eval": "(i => !!i && i.offsetParent !== null)(document.querySelector('.palette .pal-own input'))"})
                self.assertEqual([g["eval"] for g in got[-5:]], [True, [], self.PAL_GRID[look], self.PAL_GRID[look], True], (look, got))   # none hidden, the own field in view
                got = self.palette_search(look, "rocket", {"eval": self.FOUND}, {"eval": loaded},
                                          {"eval": "document.querySelector('.palette .pal-own input') !== null"})
                self.assertEqual(got[-3]["eval"][0], "🚀", (look, got[-3]))
                self.assertEqual(got[-2]["eval"], ["en.json"], (look, got[-2]))   # the hub speaks English: one file
                self.assertTrue(got[-1]["eval"])   # the own field and "Done" stay
                # a click sets it as the icon
                got = self.page({"eval": "[...document.querySelectorAll('.palette .pal-grid .pal-e')][0].click(), 1"},
                                {"until": f"{self.ICON(self.PAL)} === '🚀'"},
                                {"eval": "document.querySelector('.palette') === null"})
                self.assertTrue(got[1]["until"], (look, got))
                self.assertTrue(got[2]["eval"], (look, got))
                self.assertEqual(self.snap(lambda st: st["sessions"]["devops"].get("own_icon") == "🚀")["sessions"]["devops"]["own_icon"], "🚀")
                # two words of a name, Enter sets the first found
                got = self.palette_search(look, "hot bev", {"eval": self.FOUND}, {"key": "Enter"},
                                          {"until": f"{self.ICON(self.PAL)} === '☕'"})
                self.assertIn("☕", got[-3]["eval"], (look, got[-3]))
                self.assertTrue(got[-1]["until"], (look, got))
                # nothing found: the message, Enter does nothing, Esc clears the field (the grid is back), the next Esc closes
                got = self.palette_search(look, "qqzzqq", {"eval": "document.querySelector('.palette .pal-none')?.textContent"},
                                          {"eval": f"({self.FOUND}).length"}, {"key": "Enter"},
                                          {"eval": "document.querySelector('.palette') !== null"},
                                          {"key": "Escape"}, {"eval": f"[document.querySelector('.palette .pal-find input').value, ({self.FOUND}).length]"},
                                          {"key": "Escape"}, {"eval": "document.querySelector('.palette') === null"})
                self.assertEqual([g["eval"] for g in got if "eval" in g][1:], ["Nothing found", 0, True, ["", self.PAL_GRID[look]], True], (look, got))

    def test_clean_palette_has_room_for_a_classic_scrollbar(self):
        # Windows, Linux and a Mac set to "always show scrollbars": the bar of the grid (44 cells scroll) takes 15 px of its width, and
        # it used to push the last column out under a horizontal scrollbar. Chrome here draws an overlay bar, so the 15 px are taken
        # by padding (a bar of its own, if there is one, counts)
        self.fleet()
        bar = ("(() => { const g = document.querySelector('.palette .pal-grid'), have = g.offsetWidth - g.clientWidth; "
               "if (have < 15) g.style.paddingInlineEnd = `${15 - have}px`; return g.scrollHeight > g.clientHeight; })()")
        measure = ("(() => { const g = document.querySelector('.palette .pal-grid'), c = [...g.querySelectorAll('.pal-e')], "
                   "edge = g.getBoundingClientRect().left + g.clientWidth - parseFloat(getComputedStyle(g).paddingInlineEnd); "
                   "return [g.scrollWidth > g.clientWidth, c.slice(0, 4).every((b) => b.getBoundingClientRect().right <= edge + 0.5), "
                   "Math.round(c[0].getBoundingClientRect().width)]; })()")
        got = self.page({"go": "about:blank", "look": None}, {"go": f"http://127.0.0.1:{self.port}/#/", "look": None},
                        {"until": f"!!document.querySelector('{self.PAL}')"},
                        {"eval": f"document.querySelector('{self.PAL}').click(), 1"},
                        {"until": "document.querySelectorAll('.palette .pal-grid .pal-e').length > 40"}, {"eval": bar}, {"eval": measure})
        self.assertTrue(got[-2]["eval"], got)   # the grid scrolls, the bar is the case
        scrolls, inside, cell = got[-1]["eval"]
        self.assertFalse(scrolls, got)
        self.assertTrue(inside, got)
        self.assertGreaterEqual(cell, 48, got)

