    def test_a_session_rows_menu_has_the_sessions_own_actions(self):
        # owner's requirement: a right click or a long press gives every action that fits where it is expected — on a
        # session's row, besides "Move to…" and "Icon…", what its header's "More" has: stop the turn, put to sleep, dismiss
        self.fleet()
        self.ev("turn.started", "maps", marker=None, prompt_head="long work")
        labels = "[...document.querySelectorAll('.gpop .gi-l')].map((x) => x.textContent)"
        pick = "[...document.querySelectorAll('.gpop .gpop-i')].find((b) => b.textContent.startsWith(%r)).click(), 1"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/hub"}, {"until": "!!document.querySelector('%s')" % self.ROW.format("maps")},
                        self.STEADY, {"rclick": self.ROW.format("maps")}, {"until": "!!document.querySelector('.gpop')", "ms": 3000},
                        {"eval": labels}, {"eval": "document.querySelectorAll('.gpop hr').length"},
                        {"eval": pick % "Stop"}, {"sleep": 400}, {"eval": "!!document.querySelector('.gpop')"},
                        {"rclick": self.ROW.format("devops")}, {"until": "!!document.querySelector('.gpop')", "ms": 3000}, {"eval": labels},
                        {"key": "Escape"}, {"rclick": self.ROW.format("notes")}, {"until": "!!document.querySelector('.gpop')", "ms": 3000},
                        {"eval": labels}, {"eval": pick % "Put to sleep"},
                        {"until": "document.getElementById('confirm-dlg').open && document.getElementById('confirm-title').textContent"})
        self.assertEqual(got[5]["eval"], ["Move to…", "Icon…", "Stop", "Put to sleep"])
        self.assertEqual(got[6]["eval"], 1)   # the session's own actions are set apart from the list's
        self.assertFalse(got[9]["eval"])      # a chosen item closes the menu
        # the core takes the request from the mailbox into the journal (core_decides) and accepts it
        asked = [e for e in journal.read(self.j.path) if e["type"] in ("session.interrupt_requested", "core.rejected")]
        self.assertEqual([(e["type"], e["entity"]) for e in asked], [("session.interrupt_requested", "maps")])
        self.assertEqual(got[12]["eval"], ["Move to…", "Icon…", "Dismiss"])   # an agent is dismissed, not put to sleep
        self.assertEqual(got[16]["eval"], ["Move to…", "Icon…", "Put to sleep"])
        self.assertEqual(got[18]["until"], "Put notes to sleep?")   # the same confirmation as in the header

    def test_group_menu_button_sits_on_the_header_row(self):
        # the "…" of a group header is at the right end of the header row inside the sidebar, centered on the header's
        # line (it was ~9 px low: the header's top margin collapsed out of the wrapper the button is placed in), and its dots
        # are centered inside it (the "⋯" glyph sat low)
        self.fleet()
        geo = ("(() => { const r = (e) => { const b = e.getBoundingClientRect(); return [b.left, b.top, b.right, b.bottom]; };"
               " const g = document.querySelector('#list .sgroup[data-g=\"agents\"]');"
               " return {side: r(document.getElementById('list')), head: r(g.querySelector('.sgroup-h')), more: r(g.querySelector('.gmore')),"
               " dots: r(g.querySelector('.gmore .gdots'))}; })()")
        setup = ("(() => { document.documentElement.style.setProperty('--ui-scale', '%s');"
                 " document.getElementById('app').style.setProperty('--left-w', '%dpx'); return 1; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"until": "document.querySelector('#list .sgroup[data-g=\"agents\"] .gmore')"},
                        {"eval": geo},
                        {"eval": setup % ("1.3333", 272)}, {"eval": geo},   # "Text size": the largest
                        {"eval": setup % ("1.3333", 200)}, {"eval": geo})   # the narrowest sidebar
        for case in (got[2], got[4], got[6]):
            side, head, more = case["eval"]["side"], case["eval"]["head"], case["eval"]["more"]
            self.assertAlmostEqual((more[1] + more[3]) / 2, (head[1] + head[3]) / 2, delta=1.5, msg=case["eval"])
            self.assertTrue(side[0] <= more[0] and more[2] <= side[2] and more[2] <= head[2], case["eval"])   # inside
            self.assertLessEqual(head[2] - more[2], 8, case["eval"])   # at the right end of the row
            dots = case["eval"]["dots"]   # the three dots are centered inside the button, both ways
            self.assertAlmostEqual((dots[0] + dots[2]) / 2, (more[0] + more[2]) / 2, delta=.5, msg=case["eval"])
            self.assertAlmostEqual((dots[1] + dots[3]) / 2, (more[1] + more[3]) / 2, delta=.5, msg=case["eval"])

    def test_groups_drag_menu_palette_reset(self):
        self.fleet()
        url = f"http://127.0.0.1:{self.port}/#/"
        got = self.page({"go": url}, {"until": "document.querySelector('#list .sgroup[data-g=\"agents\"]')"},
                        {"eval": "[...document.querySelectorAll('#list .sgroup:not(.bare)')].map(g => g.dataset.g)"},
                        {"eval": "!!document.querySelector('.add-group') && ![...document.querySelectorAll('#list .g-tools .btn')].some(b => b.innerText === 'Reset')"},
                        {"eval": self.IN.format("agents", "devops-fix")})
        self.assertEqual(got[2]["eval"], ["agents", "workers"])   # untouched — the view is as before, "+ Group" at the bottom
        self.assertTrue(got[3]["eval"])
        self.assertFalse(got[4]["eval"])                           # an executor — under its raiser, not in a group
        # 1. drag a working session's row with the mouse to the specialists, above seo
        got = self.page({"drag": self.ROW.format("maps"), "to": self.ROW.format("seo"), "at": 0.2},
                        {"until": self.IN.format("agents", "maps")},
                        {"eval": "[...document.querySelectorAll('#list .sgroup[data-g=\"agents\"] > ul > li[data-s]')].map(l => l.dataset.s)"},
                        {"until": "[...document.querySelectorAll('#list .g-tools .btn')].some(b => b.innerText === 'Reset')"})
        self.assertTrue(got[1]["until"])
        self.assertEqual(got[2]["eval"], ["devops", "maps", "seo"])
        lay = self.snap(lambda st: st["layout"]["order"]["agents"])["layout"]
        self.assertEqual((lay["place"], lay["order"]["agents"]), ({"maps": "agents"}, ["devops", "maps", "seo"]))
        # 2. right click → "Move to…" → "New group…" → the name in place
        got = self.page({"rclick": self.ROW.format("notes")}, {"click": "Move to…"}, {"click": "New group…"},
                        {"until": "document.activeElement && document.activeElement.classList.contains('gt-edit')"},
                        {"eval": "document.activeElement.value = 'Clients'"}, {"key": "Enter"},
                        {"until": "[...document.querySelectorAll('#list .sgroup .gt')].some(t => t.innerText === 'Clients')"})
        self.assertTrue(got[-1]["until"])
        lay = self.snap(lambda st: any(g["title"] == "Clients" for g in st["layout"]["groups"]))["layout"]
        new = [g for g in lay["groups"] if g["title"] == "Clients"]
        self.assertEqual(len(new), 1)
        self.assertEqual(lay["place"]["notes"], new[0]["id"])
        # 3. palette: click the icon — 32 emoji and "custom"; the chosen one is on the row and in the snapshot
        got = self.page({"eval": "document.querySelector('#list li[data-s=\"devops\"] .avatar').click(), document.querySelectorAll('.palette .pal-e').length"},
                        {"eval": "!!document.querySelector('.palette .pal-own input')"},
                        {"eval": "[...document.querySelectorAll('.palette .pal-e')].find(b => b.getAttribute('aria-label') === '🚀').click()"},
                        {"until": "document.querySelector('#list li[data-s=\"devops\"] .avatar')?.textContent === '🚀'"})
        self.assertEqual((got[0]["eval"], got[1]["eval"], got[-1]["until"]), (32, True, True))
        self.assertEqual(self.snap(lambda st: st["sessions"]["devops"]["own_icon"])["sessions"]["devops"]["own_icon"], "🚀")
        # a custom emoji from the field: the first grapheme is taken, text will not become an icon
        got = self.page({"rclick": self.ROW.format("notes")}, {"click": "Icon…"},
                        {"eval": "document.querySelector('.palette .pal-own input').value = '🦊🐻'"}, {"click": "Done"},
                        {"until": "document.querySelector('#list li[data-s=\"notes\"] .avatar')?.textContent === '🦊'"})
        self.assertTrue(got[-1]["until"])
        # 4. group menu: "Ungroup" — its sessions go outside groups, as a row at the top
        gid = new[0]["id"]
        got = self.page({"eval": f"document.querySelector('#list .sgroup[data-g=\"{gid}\"] .gmore').click()"},
                        {"click": "Ungroup"}, {"until": self.IN.format("none", "notes")})
        self.assertTrue(got[-1]["until"])
        # 5. drag a group by its header: "Executors" above "Specialists"
        # the list from the start: earlier steps scrolled it, and the "Specialists" header could go off the top
        # (the window is lower in the sandbox)
        got = self.page({"eval": "document.getElementById('list').scrollTop = 0"},
                        {"drag": "#list .sgroup[data-g=\"workers\"] .sgroup-h", "to": "#list .sgroup[data-g=\"agents\"] .sgroup-h", "at": 0.1},
                        {"until": "[...document.querySelectorAll('#list .sgroup:not(.bare)')].map(g => g.dataset.g).join() === 'workers,agents,directions'"})
        self.assertTrue(got[-1]["until"])
        lay = self.snap(lambda st: st["layout"]["groups"][0]["id"] == "workers")["layout"]
        self.assertEqual([g["id"] for g in lay["groups"]][:2], ["workers", "agents"])
        # 6. "Reset" — standard groups, icons stay
        got = self.page({"click": "Reset"},
                        {"until": "[...document.querySelectorAll('#list .sgroup:not(.bare)')].map(g => g.dataset.g).join() === 'agents,workers'"},
                        {"eval": self.IN.format("workers", "maps")},
                        {"eval": "document.querySelector('#list li[data-s=\"devops\"] .avatar')?.textContent"})
        self.assertEqual((got[1]["until"], got[2]["eval"], got[3]["eval"]), (True, True, "🚀"))
        # the edit is sent once the snapshot shows the previous one as recorded — the reload (the errors step)
        # only after it
        self.assertNotIn("groups", self.snap(lambda st: "groups" not in st["layout"])["layout"])
        self.assertEqual(self.page({"errors": 1500})[-1]["errors"], [])

    def test_groups_stale_tab_gets_a_reason_not_a_silent_overwrite(self):
        """Two tabs: an edit based on an old layout — the core refuses, in words under the list; the view is
        from the snapshot."""
        self.fleet()
        url = f"http://127.0.0.1:{self.port}/#/"
        self.page({"go": url}, {"until": "document.querySelector('#list .sgroup[data-g=\"agents\"]')"})
        # "another tab" changed the layout, and this one still counts from the previous one (its snapshot is from
        # before the edit)
        self.page({"eval": "import('/static/js/state.js').then(m => { window.__S = m.S; }), 1"}, {"until": "window.__S"})
        self.ev("layout.set", None, layout={"groups": [{"id": "agents", "title": "Specialists"}]}, base=0,
                channel="web", owner=True)
        got = self.page({"until": "window.__S.snap.layout"}, {"eval": "window.__S.snap.layout = null, 1"},
                        {"drag": self.ROW.format("maps"), "to": self.ROW.format("seo"), "at": 0.2},
                        {"until": "document.body.innerText.includes('the layout was changed already')"})
        self.assertTrue(got[-1]["until"])
        self.assertEqual(self.snap()["layout"]["groups"], [{"id": "agents", "title": "Specialists"}])

    def test_groups_rename_survives_snapshots(self):
        """A new group's name is being typed while snapshots arrive (once a second): the field is the same,
        what was typed is
        not lost and is not saved halfway."""
        self.fleet()
        url = f"http://127.0.0.1:{self.port}/#/"
        self.page({"go": url}, {"until": "document.querySelector('#list .sgroup[data-g=\"agents\"]')"},
                  {"eval": "import('/static/js/state.js').then(m => { window.__S = m.S; }), 1"}, {"until": "window.__S"},
                  {"click": "+ Group"},
                  {"until": "document.activeElement && document.activeElement.classList.contains('gt-edit')"},
                  {"eval": "document.activeElement.value = 'Cli', 1"})
        self.ev("session.iconed", "maps", icon="🗺", channel="web", owner=True)   # a snapshot with a new one — in the middle of typing
        got = self.page({"until": "window.__S.snap.sessions.find(s => s.name === 'maps').own_icon === '🗺'"},
                        {"sleep": 400},
                        {"eval": "[document.activeElement.classList.contains('gt-edit'), document.activeElement.value]"},
                        {"eval": "document.activeElement.value += 'ents', 1"}, {"key": "Enter"},
                        {"until": "[...document.querySelectorAll('#list .sgroup .gt')].some(t => t.innerText === 'Clients')"})
        self.assertEqual(got[2]["eval"], [True, "Cli"])
        titles = lambda st: [g["title"] for g in (st.get("layout") or {}).get("groups") or []]
        self.assertIn("Clients", titles(self.snap(lambda st: "Clients" in titles(st))))
        self.assertNotIn("Cli", titles(self.snap()))

    def test_groups_tools_reset_and_auto_always_shown(self):
        """"Reset" (was "As it was") — only for one's own layout; "Auto" — always: after confirmation it sends
        the hub an
        ordinary message from the owner (via the same /api/send as the hub form) with a task to
        arrange the list from the journal."""
        self.fleet()
        url = f"http://127.0.0.1:{self.port}/#/"
        tools = "[...document.querySelectorAll('#list .g-tools .btn')].map(b => b.innerText)"
        spy = ("(() => { window.__sent = []; const f = window.fetch; window.fetch = (u, o) => { if (String(u).includes('/api/send')) "
               "{ window.__sent.push(JSON.parse(o.body)); return Promise.resolve(new Response('{}', {status: 202})); } return f(u, o); }; return 1; })()")
        got = self.page({"go": url}, {"until": "document.querySelector('#list .sgroup[data-g=\"agents\"]')"},
                        {"eval": tools}, {"eval": "document.querySelector('#list .g-tools .btn.auto').title"},
                        {"eval": spy},
                        {"click": "Auto"}, {"until": "document.getElementById('confirm-dlg').open"},
                        {"eval": "window.__sent.length"},   # without confirmation nothing was sent
                        {"eval": "document.getElementById('confirm-text').textContent"},
                        {"eval": "document.getElementById('confirm-ok').className"},
                        {"eval": "document.getElementById('confirm-ok').click(), 1"},
                        {"until": "window.__sent.length === 1"},
                        {"eval": "window.__sent[0]"})
        self.assertEqual(got[2]["eval"], ["+ Group", "Auto"])   # layout untouched — no "Reset", "Auto" is present
        self.assertIn("a task for the hub", got[3]["eval"])
        self.assertEqual(got[7]["eval"], 0)
        self.assertIn("will be replaced", got[8]["eval"])
        self.assertEqual(got[9]["eval"], "btn primary")   # not a dangerous action: the theme's color, not red
        sent = got[-1]["eval"]
        self.assertEqual((sent["session"], sent["action"]), ("hub", True))
        for word in ("7 days", "hub layout move", "hub layout ungroup", "outside the groups", "4–7"):
            self.assertIn(word, sent["text"])
        # layout touched — "Reset" appeared next to "Auto"
        got = self.page({"drag": self.ROW.format("maps"), "to": self.ROW.format("seo"), "at": 0.2},
                        {"until": "[...document.querySelectorAll('#list .g-tools .btn')].some(b => b.innerText === 'Reset')"},
                        {"eval": tools}, {"eval": "document.querySelector('#list .g-tools .btn:not(.add-group):not(.auto)').title"})
        self.assertEqual(got[2]["eval"], ["+ Group", "Reset", "Auto"])
        self.assertIn("the standard groups", got[3]["eval"])
        # "Cancel" in the confirmation — nothing is sent
        got = self.page({"click": "Auto"}, {"until": "document.getElementById('confirm-dlg').open"},
                        {"eval": "document.getElementById('confirm-dlg').close('cancel'), 1"}, {"sleep": 300},
                        {"eval": "window.__sent.length"})
        self.assertEqual(got[-1]["eval"], 1)

    def test_auto_groups_answer_shows_under_the_button(self):
        # what "Auto" got — the task sent or the reason it was not — shows as a line right under the buttons, gone after 10 s,
        # on a phone's session list (#/sessions: main and the banner in it are hidden) and on a desktop alike, never as the
        # banner; the buttons stay the same node (the focus on "Auto" is not lost)
        self.fleet()
        note = "#list .g-tools .g-auto-note"
        spy = ("(() => { window.__sent = []; const f = window.fetch; window.fetch = (u, o) => { if (String(u).includes('/api/send')) "
               "{ window.__sent.push(JSON.parse(o.body)); return Promise.resolve(window.__fail ? new Response(JSON.stringify({error: 'Hub busy'}), {status: 503})"
               " : new Response('{}', {status: 202})); } return f(u, o); }; return 1; })()")
        seen = f"(() => {{ const n = document.querySelector('{note}'); return n && n.textContent && n.getClientRects().length ? n.textContent : null; }})()"
        auto = [{"eval": "document.querySelector('#list .g-tools .btn.auto').click(), 1"}, {"until": "document.getElementById('confirm-dlg').open"},
                {"eval": "document.getElementById('confirm-ok').click(), 1"}]
        got = self.page({"go": "about:blank"}, {"touch": True}, {"shot": os.path.join(tempfile.gettempdir(), "e2e-auto-phone.png"), "width": 390, "height": 844},
                        {"go": f"http://127.0.0.1:{self.port}/#/sessions"}, {"until": "!!document.querySelector('#list .g-tools .btn.auto')?.offsetWidth"},
                        {"eval": spy}, {"eval": "window.__tools = document.querySelector('#list .g-tools'), 1"}, {"eval": "import('/static/js/i18n.js').then((m) => { window.__t = m.t('web.groups.auto_sent'); }), 1"},
                        {"until": "!!window.__t"}, *auto, {"until": "window.__sent.length === 1"},
                        {"until": f"{seen} !== null", "ms": 3000}, {"eval": seen}, {"eval": "window.__t"},
                        {"eval": "window.__fail = 1"}, *auto, {"until": "window.__sent.length === 2"},
                        {"until": f"({seen} || '').includes('Hub busy')", "ms": 3000}, {"eval": seen},
                        {"until": f"{seen} === null", "ms": 12000},
                        {"eval": "document.querySelector('#list .g-tools') === window.__tools"})
        self.assertEqual(got[14]["eval"], got[15]["eval"], got)        # "Task sent to the hub — …", in the page's language
        self.assertIn("Hub busy", got[-3]["eval"] or "", got)          # the reason it was not
        self.assertTrue(got[-2]["until"], got)                         # gone after 10 s
        self.assertTrue(got[-1]["eval"], got)                          # the same buttons all along
        # a desktop: the same line under the button, the banner over the feed stays off
        got = self.page({"go": "about:blank"}, {"touch": False}, {"shot": os.path.join(tempfile.gettempdir(), "e2e-auto-desk.png"), "width": 1300, "height": 900},
                        {"go": f"http://127.0.0.1:{self.port}/#/"}, {"until": "!!document.querySelector('#list .g-tools .btn.auto')?.offsetWidth"},
                        {"eval": spy}, *auto, {"until": "window.__sent.length === 1"},
                        {"until": f"{seen} !== null", "ms": 3000}, {"sleep": 300},
                        {"eval": "document.getElementById('banner').classList.contains('on')"})
        self.assertTrue(got[-3]["until"], got)
        self.assertFalse(got[-1]["eval"], got)

    def test_groups_drag_group_from_the_bottom_of_a_long_list_to_the_top(self):
        """A long list: a group is grabbed by its header at the bottom and brought to the top edge — the list
        scrolls up by
        itself, the insertion target is recomputed while scrolling; released at the top — the group is first."""
        self.fleet()
        groups = [{"id": f"g{i:02d}", "title": f"Group {i}"} for i in range(30)]
        self.ev("layout.set", None, layout={"groups": groups, "place": {}, "order": {}}, base=0, channel="web", owner=True)
        url = f"http://127.0.0.1:{self.port}/#/"
        last = '#list .sgroup[data-g="g29"] .sgroup-h'
        got = self.page({"go": url}, {"until": "document.querySelector('#list .sgroup[data-g=\"g29\"]')"}, self.STEADY,
                        {"eval": "(() => { const l = document.getElementById('list'); l.scrollTop = l.scrollHeight; return [l.scrollHeight > l.clientHeight * 2, l.scrollTop > 0]; })()"},
                        {"drag": last, "to": "#list", "at": 0.01, "keep": True},
                        {"until": "document.getElementById('list').scrollTop === 0", "ms": self.AUTOSCROLL_MS},
                        {"eval": "!!document.querySelector('#list .drop-line')"},
                        {"drop": 1},
                        {"until": "document.querySelector('#list .sgroup:not(.bare)')?.dataset.g === 'g29'"})
        self.assertEqual(got[3]["eval"], [True, True])
        self.assertTrue(got[5]["until"])    # scrolled all the way to the top
        self.assertTrue(got[6]["eval"])     # the insertion line is in place
        self.assertTrue(got[-1]["until"])
        lay = self.snap(lambda st: st["layout"]["groups"][0]["id"] == "g29")["layout"]
        self.assertEqual([g["id"] for g in lay["groups"]][:3], ["g29", "g00", "g01"])

    def test_groups_drag_autoscrolls_down_and_wheel_keeps_the_target_fresh(self):
        """Down — with the same edge; the wheel during dragging also scrolls, the insertion line follows the
        scroll."""
        self.fleet()
        groups = [{"id": f"g{i:02d}", "title": f"Group {i}"} for i in range(30)]
        self.ev("layout.set", None, layout={"groups": groups, "place": {}, "order": {}}, base=0, channel="web", owner=True)
        url = f"http://127.0.0.1:{self.port}/#/"
        got = self.page({"go": url}, {"until": "document.querySelector('#list .sgroup[data-g=\"g29\"]')"}, self.STEADY,
                        {"eval": "document.getElementById('list').scrollTop = 0, 1"},
                        {"drag": '#list .sgroup[data-g="g00"] .sgroup-h', "to": "#list", "at": 0.99, "keep": True},
                        {"until": "(() => { const l = document.getElementById('list'); return l.scrollTop + l.clientHeight >= l.scrollHeight - 2; })()", "ms": self.AUTOSCROLL_MS},
                        {"eval": "document.querySelector('#list .drop-line') ? document.querySelector('#list .drop-line').style.top : null"},
                        {"drop": 1},
                        {"until": "[...document.querySelectorAll('#list .sgroup[data-g]')].pop().dataset.g === 'g00'"})
        self.assertTrue(got[5]["until"], got)
        self.assertTrue(got[8]["until"], got)
        lay = self.snap(lambda st: st["layout"]["groups"][-1]["id"] == "g00")["layout"]
        self.assertEqual(lay["groups"][-1]["id"], "g00")
        # wheel in the middle of dragging: the pointer is mid-list, the list is scrolled by the wheel — the
        # insertion landed
        # before the group that is now under the pointer (recomputed, not by the position before scrolling)
        under = ("(() => { const l = document.getElementById('list').getBoundingClientRect(), y = l.top + l.height / 2; "
                 "const b = [...document.querySelectorAll('#list .sgroup[data-g]')].filter(x => x.dataset.g !== 'g29')"
                 ".find(x => y < x.getBoundingClientRect().top + x.getBoundingClientRect().height / 2); return b ? b.dataset.g : null; })()")
        got = self.page({"eval": "document.getElementById('list').scrollTop = 0, 1"},
                        {"drag": '#list .sgroup[data-g="g29"] .sgroup-h', "to": "#list", "at": 0.5, "keep": True},
                        {"eval": "window.__t0 = document.getElementById('list').scrollTop"},
                        {"wheel": -120, "over": "held", "times": 3},
                        {"until": "document.getElementById('list').scrollTop < window.__t0 - 100"},
                        {"sleep": 200}, {"eval": under},
                        {"drop": 1}, {"sleep": 300})
        before = got[6]["eval"]
        self.assertTrue(got[4]["until"])
        self.assertTrue(before and before != "g00")
        lay = self.snap(lambda st: [g["id"] for g in st["layout"]["groups"]].index("g29") + 1 == [g["id"] for g in st["layout"]["groups"]].index(before) if before in [g["id"] for g in st["layout"]["groups"]] else False)["layout"]
        ids = [g["id"] for g in lay["groups"]]
        self.assertEqual(ids.index("g29") + 1, ids.index(before))

