    # --- "All | Now" above the list ----------------------------------------------------------------------------------
    def busy_fleet(self):
        """The hub; devops — free, but its executor ask asks the owner, run is working, done is free; seo and
        notes
        are free; maps is working. "Now" on top: the hub, devops (because of executors), maps."""
        self.fleet()
        for n in ("ask", "run", "done"):
            self.ev("session.requested", f"devops-{n}", session_id=f"s-{n}", cwd="/w", executor=True, raised_by="devops",
                    channel="cli", owner=True)
            self.ev("session.started", f"devops-{n}", session_id=f"s-{n}")
        for n in ("devops-ask", "devops-run", "maps"):
            self.ev("turn.started", n, marker=None, prompt_head="x")
        self.ev("permission.requested", "devops-ask", request_id="r1", tool="AskUserQuestion", interactive=True,
                input={"questions": [{"question": "Deploy?", "options": [{"label": "Yes"}, {"label": "No"}]}]})

    TOP = ("JSON.stringify([...document.querySelectorAll('#list .srow')].filter(b => !b.closest('li.forks'))"
           ".map(b => b.querySelector('.nm').textContent.trim().split(/\\s+/).pop()))")
    UNDER = ("JSON.stringify([...document.querySelectorAll('#list li:is([data-s=\"devops\"], [data-m=\"devops\"]) + li.forks .srow .nm')]"
             ".map(n => n.textContent.trim().split(/\\s+/).pop()))")
    BAR = "JSON.stringify([...document.querySelectorAll('#active-bar button')].map(b => [b.textContent, b.getAttribute('aria-pressed')]))"

    def test_active_only_switch_hides_the_quiet_and_keeps_what_needs_you(self):
        self.busy_fleet()
        url = f"http://127.0.0.1:{self.port}/#/"
        toggle = "document.querySelector('#list li:is([data-s=\"devops\"], [data-m=\"devops\"]) .fork-toggle .n').textContent"
        got = self.page({"go": url}, {"until": "document.querySelector('#list li:is([data-s=\"maps\"], [data-m=\"maps\"])')"}, self.STEADY,
                        {"eval": self.BAR}, {"eval": self.TOP},
                        {"click": "Now"}, {"until": "!document.querySelector('#list li:is([data-s=\"seo\"], [data-m=\"seo\"])')"},
                        {"eval": self.BAR}, {"eval": self.TOP}, {"eval": self.UNDER}, {"eval": toggle},
                        {"eval": "localStorage.getItem('hub.sidebar')"},
                        {"eval": "[document.querySelector('#list .more-all, #list .g-tools'), document.querySelector('#list .add-group')]"},
                        {"eval": "[...document.querySelectorAll('#active-bar button')].map(b => [b.getAttribute('aria-label'), b.title])"})
        self.assertEqual(json.loads(got[3]["eval"]), [["All", "true"], ["Now", "false"]])   # by default — all
        self.assertEqual(set(json.loads(got[4]["eval"])), {"Hub", "devops", "seo", "maps", "notes"})
        self.assertEqual(json.loads(got[7]["eval"]), [["All", "false"], ["Now", "true"]])
        self.assertEqual(set(json.loads(got[8]["eval"])), {"Hub", "devops", "maps"})   # devops — because of executors
        self.assertEqual(sorted(json.loads(got[9]["eval"])), ["ask", "run"])   # all that have work are expanded — without a click
        self.assertEqual(got[10]["eval"], "2")                    # the counter — working and waiting ones (no free ones)
        self.assertEqual(got[11]["eval"], "active")
        # neither "N more" nor group buttons — the rest is in "All" (owner decision)
        self.assertEqual(got[12]["eval"], [None, None])
        # the tab shows the word alone; its number is in the tooltip and in the name a screen reader reads
        self.assertEqual(got[13]["eval"], [["All · 5", "All sessions by group · 5"],
                                           ["Now · 3", "Only those working, waiting for you or with something new; the hub and "
                                                       "the open one — always · 3"]])
        # the choice survives a reload; search looks through all
        got = self.page({"go": "about:blank"}, {"go": url}, {"until": "document.querySelector('#list li:is([data-s=\"maps\"], [data-m=\"maps\"])')"},
                        {"eval": self.TOP},
                        {"eval": "(() => { const f = document.getElementById('filter'); f.value = 'seo'; f.dispatchEvent(new Event('input')); return 1; })()"},
                        {"until": "!!document.querySelector('#list li:is([data-s=\"seo\"], [data-m=\"seo\"])')"})
        self.assertEqual(set(json.loads(got[3]["eval"])), {"Hub", "devops", "maps"})
        self.assertTrue(got[-1]["until"])
        # an open one is always visible, and a free executor under a free parent too
        got = self.page({"eval": "(() => { const f = document.getElementById('filter'); f.value = ''; f.dispatchEvent(new Event('input')); return 1; })()"},
                        {"hash": "#/s/devops-done"}, {"until": "!!document.querySelector('#list li.forks li .srow[aria-current=\"true\"]')"},
                        {"eval": self.UNDER})
        self.assertTrue(got[2]["until"])
        self.assertEqual(sorted(json.loads(got[3]["eval"])), ["ask", "done", "run"])
        # a click on the counter collapses (no partial expansion any more)
        got = self.page({"eval": "(document.querySelector('#list li:is([data-s=\"devops\"], [data-m=\"devops\"]) .fork-toggle').click(), 1)"},
                        {"until": "!document.querySelector('#list li:is([data-s=\"devops\"], [data-m=\"devops\"]) + li.forks')"})
        self.assertTrue(got[-1]["until"])
        # "All" — the previous list, the choice cleared; dragging works as before
        got = self.page({"click": "All"}, {"until": "!!document.querySelector('#list li:is([data-s=\"seo\"], [data-m=\"seo\"])')"},
                        {"eval": "localStorage.getItem('hub.sidebar')"}, self.STEADY,
                        {"drag": self.ROW.format("maps"), "to": self.ROW.format("seo"), "at": 0.2},
                        {"until": self.IN.format("agents", "maps")})
        self.assertIsNone(got[2]["eval"])
        self.assertTrue(got[-1]["until"])

