    # whether a session is read, per the page snapshot (the result arrived, the owner opened it — /api/seen
    # reached the core)
    STATE = "import('/static/js/state.js').then((m) => { window.__st = m.S; })"
    READ = "!!window.__st && !window.__st.snap.sessions.find((s) => s.name === 'NAME').unread"

    def test_active_keeps_a_session_you_just_read(self):
        # owner report: active ones vanish on a click into them — he opened an unread one, moved to the next, and
        # the
        # read one disappeared from under his hand. It stays until 15 minutes pass after leaving it
        self.busy_fleet()
        for n in ("notes", "seo"):
            e = self.j.append("message.received", None, {"to": n, "text": "do it", "channel": "web", "owner": True})
            self.ev("turn.started", n, marker=f"m{e['seq']}", prompt_head="x")
            self.ev("turn.result", n, text="done " + n)
            self.ev("turn.stopped", n)
        click = "(document.querySelector('#list li:is([data-s=\"NAME\"], [data-m=\"NAME\"]) > .srow').click(), 1)"
        got = self.page({"local": {"hub.sidebar": "active"}}, {"go": f"http://127.0.0.1:{self.port}/#/"},
                        {"until": "document.querySelector('#list li:is([data-s=\"notes\"], [data-m=\"notes\"])')"}, self.STEADY,
                        {"eval": self.TOP},
                        {"eval": click.replace("NAME", "notes")}, {"until": "location.hash === '#/s/notes'"},
                        {"eval": self.STATE}, {"until": self.READ.replace("NAME", "notes")},
                        {"eval": click.replace("NAME", "seo")}, {"until": "location.hash === '#/s/seo'"},
                        {"eval": self.STATE}, {"until": self.READ.replace("NAME", "seo")},
                        {"eval": self.TOP}, {"eval": self.BAR})
        self.assertEqual(set(json.loads(got[4]["eval"])), {"Hub", "devops", "maps", "notes", "seo"})
        self.assertEqual(set(json.loads(got[13]["eval"])), {"Hub", "devops", "maps", "notes", "seo"})   # notes in place
        self.assertEqual(json.loads(got[14]["eval"])[1], ["Now", "true"])
        # an executor too: opened a free devops-done, left — it stays under its parent until 15 minutes pass
        got = self.page({"hash": "#/s/devops-done"}, {"until": "!!document.querySelector('#list li.forks li .srow[aria-current=\"true\"]')"},
                        {"hash": "#/s/maps"}, {"until": "location.hash === '#/s/maps'"}, {"sleep": 300},
                        {"eval": self.UNDER})
        self.assertEqual(json.loads(got[-1]["eval"]), ["ask", "run", "done"])   # the one waiting for you — first
        # 16 minutes passed — read ones left on their own, the open maps and the working ones are in place
        got = self.page({"eval": "(() => { const t = Date.now() + 16 * 60e3; Date.now = () => t; "
                                  "window.dispatchEvent(new Event('hub-redraw')); return 1; })()"},
                        {"until": "!document.querySelector('#list li:is([data-s=\"notes\"], [data-m=\"notes\"])')"},
                        {"eval": self.TOP}, {"eval": self.UNDER})
        self.assertEqual(set(json.loads(got[2]["eval"])), {"Hub", "devops", "maps"})
        self.assertEqual(json.loads(got[3]["eval"]), ["ask", "run"])

    def test_active_count_survives_a_reload(self):
        # owner report: "Now" shows 18, after a reload — 16. The stream and the snapshot agree; what diverged was
        # the tab's
        # memory: just-viewed ones are kept for 15 minutes, read ones stay in "New", and a reload lost both — the
        # number
        # and the sections jumped. After a reload — the same sections and the same number
        self.busy_fleet()
        e = self.j.append("message.received", None, {"to": "seo", "text": "do it", "channel": "web", "owner": True})
        self.ev("turn.started", "seo", marker=f"m{e['seq']}", prompt_head="x")
        self.ev("turn.result", "seo", text="done")
        self.ev("turn.stopped", "seo")
        url = f"http://127.0.0.1:{self.port}/#/"
        got = self.page({"local": {"hub.sidebar": "active"}}, {"go": url}, {"until": "document.querySelector('#list .sgroup.asec')"},
                        self.STEADY, {"hash": "#/s/seo"}, {"eval": self.STATE}, {"until": self.READ.replace("NAME", "seo")},
                        {"hash": "#/s/notes"}, {"until": "location.hash === '#/s/notes'"}, {"hash": "#/"},
                        {"until": "!document.querySelector('#list .srow[aria-current=\"true\"]')"},
                        {"eval": self.BAR}, {"eval": self.SECTIONS})
        live = [json.loads(got[-2]["eval"]), json.loads(got[-1]["eval"])]
        self.assertEqual(live, [[["All", "false"], ["Now", "true"]],
                                [["Waiting for you", 1, ["devops"]], ["Answered you", 1, ["seo"]], ["Working", 1, ["maps"]],
                                 ["Just viewed", 1, ["notes"]]]])
        got = self.page({"go": "about:blank"}, {"go": url}, {"until": "document.querySelector('#list .sgroup.asec')"}, self.STEADY,
                        {"eval": self.BAR}, {"eval": self.SECTIONS})
        self.assertEqual([json.loads(got[-2]["eval"]), json.loads(got[-1]["eval"])], live)
        # on load the expiry is re-checked: left notes 16 minutes ago — it is gone; a timestamp from the future
        # (the clock
        # was set back) does not hold a row either
        got = self.page({"eval": "sessionStorage.setItem('hub.left', JSON.stringify({notes: Date.now() - 16 * 60e3, "
                                 "seo: Date.now() + 60 * 60e3})), sessionStorage.setItem('hub.wasNew', '[\"seo\", {}]'), 1"},
                        {"go": "about:blank"}, {"go": url}, {"until": "document.querySelector('#list .sgroup.asec')"}, self.STEADY,
                        {"eval": self.BAR}, {"eval": self.SECTIONS})
        self.assertEqual(json.loads(got[-2]["eval"])[1], ["Now", "true"])
        self.assertEqual(json.loads(got[-1]["eval"]), [["Waiting for you", 1, ["devops"]], ["Working", 1, ["maps"]]])

    # "Now" sections by state (owner decision, option A): [name, number, [names of top rows]]
    SECTIONS = ("JSON.stringify([...document.querySelectorAll('#list .sgroup.asec')].map(g => [g.querySelector('.gt').textContent, "
                "+g.querySelector('.gcount').textContent, [...g.querySelectorAll(':scope > ul > li[data-m] > .srow .nm')]"
                ".map(n => n.textContent.trim().split(/\\s+/).pop())]))")
    LINE = "document.querySelector('#list li[data-m=\"NAME\"] > .srow .lb')?.textContent"

    def test_active_sections_by_state(self):
        # "Waiting for you" — by the core's status (an executor with a question raises its parent), the row is the
        # question itself;
        # "Answered you" — an unread answer to the owner's words, the row is its beginning; "Working"; "Waiting" — its
        # whole "waiting…" phrase;
        # an idle hub — on top
        self.busy_fleet()
        e = self.j.append("message.received", None, {"to": "seo", "text": "do it", "channel": "web", "owner": True})
        self.ev("turn.started", "seo", marker=f"m{e['seq']}", prompt_head="x")
        self.ev("turn.result", "seo", text="## Done\n\n**Map** fixed, `tests` green.")
        self.ev("turn.stopped", "seo")
        self.ev("session.waiting", "notes", text="reviewer answer on the branch", channel="session", sender="notes")
        child = "document.querySelector('#list li[data-m=\"devops\"] + li.forks .srow .lb')?.textContent"
        got = self.page({"local": {"hub.sidebar": "active"}}, {"go": f"http://127.0.0.1:{self.port}/#/"},
                        {"until": "document.querySelector('#list .sgroup.asec')"}, self.STEADY,
                        {"eval": self.SECTIONS}, {"eval": self.LINE.replace("NAME", "seo")}, {"eval": child},
                        {"eval": self.LINE.replace("NAME", "notes")}, {"eval": self.TOP}, {"eval": self.BAR},
                        {"eval": "!!document.querySelector('#list .sgroup.asec .srow.two')"},
                        {"eval": "!!document.querySelector('#list .sgroup.asec[data-sec=\"wait\"] .sgroup-h.alarm')"})
        self.assertEqual(json.loads(got[4]["eval"]), [["Waiting for you", 1, ["devops"]], ["Answered you", 1, ["seo"]],
                                                      ["Working", 1, ["maps"]], ["Waiting", 1, ["notes"]]])
        self.assertEqual(got[5]["eval"], "Done. Map fixed, tests green.")   # no markup
        self.assertEqual(got[6]["eval"], "Deploy?")
        self.assertEqual(got[7]["eval"], "waiting: reviewer answer on the branch")
        self.assertEqual(json.loads(got[8]["eval"])[0], "Hub")                         # an idle hub goes on top, outside the sections
        self.assertEqual(json.loads(got[9]["eval"])[1], ["Now", "true"])
        self.assertTrue(got[10]["eval"])
        self.assertTrue(got[11]["eval"])
        # opened something new and left: it stays in "Answered you" (does not jump under the cursor), not moved to "Just viewed";
        # opened with nothing pending (notes without a word) goes to "Just viewed"
        self.ev("session.waiting", "notes", clear=True, channel="session", sender="notes")
        want = [["Waiting for you", 1, ["devops"]], ["Answered you", 1, ["seo"]], ["Working", 1, ["maps"]], ["Just viewed", 1, ["notes"]]]
        got = self.page({"hash": "#/s/seo"}, {"eval": self.STATE}, {"until": self.READ.replace("NAME", "seo")},
                        {"hash": "#/s/notes"}, {"until": f"{self.SECTIONS} === {json.dumps(json.dumps(want, ensure_ascii=False, separators=(",", ":")))}"})
        self.assertTrue(got[-1]["until"])
        # "Just viewed" is above "Waiting" (owner decision): seo said "waiting…"
        self.ev("session.waiting", "seo", text="reviewer answer", channel="session", sender="seo")
        want = [["Waiting for you", 1, ["devops"]], ["Working", 1, ["maps"]], ["Just viewed", 1, ["notes"]], ["Waiting", 1, ["seo"]]]
        got = self.page({"until": f"{self.SECTIONS} === {json.dumps(json.dumps(want, ensure_ascii=False, separators=(",", ":")))}"})
        self.assertTrue(got[-1]["until"])
        # a section collapses and remembers it; "All" keeps the owner's former groups
        got = self.page({"eval": "(document.querySelector('#list .sgroup.asec[data-sec=\"work\"] .sgroup-h').click(), 1)"},
                        {"until": "!document.querySelector('#list li[data-m=\"maps\"]')"},
                        {"eval": "localStorage.getItem('hub.closedGroups')"},
                        {"click": "All"}, {"until": "!!document.querySelector('#list .sgroup[data-g=\"agents\"]')"},
                        {"eval": "!!document.querySelector('#list .sgroup.asec')"})
        self.assertIn("a:work", got[2]["eval"])
        self.assertFalse(got[-1]["eval"])

    def test_active_keeps_the_hub_pinned_on_top_in_any_state(self):
        # owner decision: the hub must always be shown, in the active view too: first row on top, as in "All"; the section by
        # state does not repeat it (working, asking you)
        self.busy_fleet()
