        self.assertEqual(json.loads(got[4]["eval"])[0], "Hub")
        self.assertEqual(json.loads(got[5]["eval"]), [["Waiting for you", 1, ["devops"]], ["Working", 1, ["maps"]]])
        self.assertTrue(got[6]["eval"])
        # the hub's result goes in the second row while unread; read and left, it is not "New" (the hub has none), and its
        # row is then what it did last — the start of that result (gist without a gist line of its own, PR #435)
        e = self.j.append("message.received", None, {"to": "hub", "text": "do it", "channel": "web", "owner": True})
        self.ev("turn.started", "hub", marker=f"m{e['seq']}", prompt_head="x")
