    def test_active_unfolds_every_executor_at_work(self):
        # owner decision (snapshot): under a mini-hub a "3 ▾" counter and only a recently opened executor with background work
        # as a row; two working, just-raised ones are in the counter but not visible. In "Now" under a parent everyone busy is
        # shown: working, idle with background work, waiting for you; the counter and the rows agree
        self.fleet()
        for n in ("new", "two", "bg"):
            self.ev("session.requested", f"devops-{n}", session_id=f"s-{n}", cwd="/w", executor=True, raised_by="devops",
                    channel="cli", owner=True)
            self.ev("session.started", f"devops-{n}", session_id=f"s-{n}")
        for n in ("devops-new", "devops-two"):
            self.ev("turn.started", n, marker=None, prompt_head="x")
        self.ev("session.background", "devops-bg", id="b1", kind="bash", title="tools/test.py")
        toggle = "#list li:is([data-s=\"devops\"], [data-m=\"devops\"]) .fork-toggle"
        got = self.page({"local": {"hub.sidebar": "active"}}, {"go": f"http://127.0.0.1:{self.port}/#/"},
                        {"until": "document.querySelector('#list li[data-m=\"devops\"] + li.forks')"}, self.STEADY,
                        {"eval": f"document.querySelector('{toggle} .n').textContent"}, {"eval": self.UNDER},
                        {"eval": "document.querySelector('#list li[data-m=\"devops\"]').closest('section').dataset.sec"})
        self.assertEqual(got[4]["eval"], "3")
        self.assertEqual(sorted(json.loads(got[5]["eval"])), ["bg", "new", "two"])
        self.assertEqual(got[6]["eval"], "work")                             # the parent is in "Working"
        # the one raised last asked you: it goes first under the parent, working ones do not push it down
        self.ev("permission.requested", "devops-bg", request_id="r1", tool="AskUserQuestion", interactive=True,
                input={"questions": [{"question": "Deploy?", "options": [{"label": "Yes"}, {"label": "No"}]}]})
        got = self.page({"until": f"JSON.parse({self.UNDER})[0] === 'bg'"}, {"eval": self.UNDER})
        under = json.loads(got[1]["eval"])
        self.assertEqual((under[0], sorted(under[1:])), ("bg", ["new", "two"]))

    AWAY = ("Finishing the report export: Europe is already assembled and checked, Africa waits for a spot in the queue. Next I will check "
            "the final tables against last month, fix the discrepancies in currencies and send a summary with charts once "
            "both executors hand in their part of the work, then I will close the task and clean up temp folders.")
    def test_active_line_starts_with_the_point_not_the_crew_label(self):
        # owner decision (snapshot): how to fit everything most important into these three lines. The mini-hub row began with
        # the service text "executors: 1 working, 1 queued ·" and the point
        # was cut off. In "Now" it shows right away where it stopped and what is next (the Claude Code recap); that executors
        # are working is shown by a spinning icon and a counter. "All" is unchanged
        self.minihub_with_queue()
        self.ev("session.recap", "maps", text=self.AWAY, by="claude")
        self.ev("turn.started", "maps-europe", marker=None)
        line = "document.querySelector('#list li:is([data-m=\"maps\"], [data-s=\"maps\"]) > .srow .lb').textContent"
        got = self.page({"local": {"hub.sidebar": "active"}}, {"go": f"http://127.0.0.1:{self.port}/#/"},
                        {"until": "document.querySelector('#list li[data-m=\"maps\"] > .srow .glyph.spin')"}, self.STEADY,
                        {"eval": line})
        self.assertEqual(got[-1]["eval"], self.AWAY)
        got = self.page({"click": "All"}, {"until": "!!document.querySelector('#list li[data-s=\"maps\"]')"}, {"eval": line})
        self.assertTrue(got[-1]["eval"].startswith("executors: 1 working, 1 queued · Finishing"), got[-1]["eval"])
        # its own "waiting…" outranks the recap even while executors work (review finding)
        self.ev("session.waiting", "maps", text="reviewer answer", channel="session", sender="maps")
        got = self.page({"click": "Now"}, {"until": f"{line} === 'waiting: reviewer answer'"})
        self.assertTrue(got[-1]["until"])
        # free after a big turn: without "free ·" in front
        self.ev("session.waiting", "maps", clear=True, channel="session", sender="maps")
        self.ev("turn.result", "maps-europe", text="done")
        self.ev("turn.stopped", "maps-europe")
        got = self.page({"until": f"{line} === {json.dumps(self.AWAY, ensure_ascii=False)}"})
        self.assertTrue(got[-1]["until"])

    def test_active_line_of_a_minihub_without_recap_is_its_last_result(self):
        # no recap yet: not "executors: 1 working, 1 queued" but the start of
        # its last result to you (what it assigned and to whom); a read one too: that is the gist while executors work
        self.minihub_with_queue()
