    def test_sections_live_behind_the_menu_button(self):
        # owner decision: schedule, flow and summary must be folded into a burger, they take half of the useful sidebar.
        # The sections sit behind a button in the hub row; the session list is right under the switcher
        self.fleet()
        rect = "(() => { const r = document.querySelector('SEL').getBoundingClientRect(); return [Math.round(r.top), Math.round(r.height)]; })()"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"until": "document.querySelector('#list li[data-s=\"maps\"]')"},
                        self.STEADY,
                        {"eval": "[document.getElementById('nav-extra').hidden, [...document.querySelectorAll('#nav-extra .nm')].map(n => n.textContent)]"},
                        {"eval": rect.replace("SEL", "#list")}, {"eval": rect.replace("SEL", "#active-bar")},
                        {"eval": "document.getElementById('navmenu').getAttribute('aria-expanded')"},
                        {"eval": "(document.getElementById('navmenu').click(), 1)"},
                        {"until": "!document.getElementById('nav-extra').hidden"},
                        {"eval": "document.getElementById('navmenu').getAttribute('aria-expanded')"},
                        {"eval": rect.replace("SEL", "#list")},
                        {"eval": "(() => { const r = document.querySelector('#nav-extra .srow.nav').getBoundingClientRect(); return document.elementFromPoint(r.left + 20, r.top + 10)?.closest('#nav-extra') !== null; })()"},
                        {"click": "Schedule"}, {"until": "location.hash === '#/schedule'"},
                        {"until": "document.getElementById('nav-extra').hidden"},
                        {"until": "document.getElementById('navmenu').getAttribute('aria-current') === 'true'"},
                        {"eval": "(document.getElementById('navmenu').click(), 1)"},
                        {"until": "!document.getElementById('nav-extra').hidden"},
                        {"eval": "(document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape', bubbles: true})), 1)"},
                        {"until": "document.getElementById('nav-extra').hidden"},
                        {"eval": "document.activeElement?.id"},
                        {"eval": "(document.getElementById('navmenu').click(), 1)"},
                        {"until": "!document.getElementById('nav-extra').hidden"},
                        {"eval": "(document.querySelector('#list .srow').dispatchEvent(new PointerEvent('pointerdown', {bubbles: true})), 1)"},
                        {"until": "document.getElementById('nav-extra').hidden"},
                        # opened from the keyboard: redrawing the snapshot does not drop focus, focus leaving outside closes the menu
                        {"eval": "(document.getElementById('navmenu').click(), 1)"},
                        {"until": "document.getElementById('nav-extra').contains(document.activeElement)"},
                        {"eval": "(window.dispatchEvent(new Event('hub-redraw')), document.getElementById('nav-extra').contains(document.activeElement))"},
                        {"eval": "(document.getElementById('filter').focus(), 1)"},
                        {"until": "document.getElementById('nav-extra').hidden"}, {"errors": 300})
        self.assertTrue(got[3]["eval"][0])                       # closed by default
        self.assertIn("Schedule", got[3]["eval"][1])           # the items are in the menu
        top, bar = got[4]["eval"], got[5]["eval"]
        self.assertLess(top[0] - (bar[0] + bar[1]), 24)          # the list is right under the switcher
        self.assertEqual(got[6]["eval"], "false")
        self.assertEqual(got[9]["eval"], "true")
        self.assertEqual(got[10]["eval"], top)                   # an open menu does not move the list: it floats over it
        self.assertTrue(got[11]["eval"])
        self.assertTrue(got[15]["until"])                        # a section from the menu is open: the button is marked
        self.assertEqual(got[20]["eval"], "navmenu")             # Esc returns focus to the button
        self.assertTrue(got[-4]["eval"])
        self.assertEqual(got[-1]["errors"], [])

    def test_a_menu_item_under_the_mouse_survives_new_snapshots(self):
        # the ☰ menu items were recreated on every snapshot: the item under the mouse became a new node, and the plugin's
        # hover animation (the kind icon) restarted with a jerk. Now the items are the same nodes, only what changed is
        # updated
        from unittest import mock
        path = os.path.join(self.state, "plug-view")
        os.makedirs(path, exist_ok=True)
        with open(os.path.join(path, "hub-plugin.json"), "w") as f:
            json.dump({"name": "board", "description": "view", "why": "w", "web": "main.js", "hub": "^1.6"}, f)
        with open(os.path.join(path, "main.js"), "w") as f:
            f.write("export default hub => hub.addView({id: 'board', title: 'Board', render() {}});\n")
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"extensions": {"board": {"path": path, "web": "main.js"}}}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        self.fleet()
        item = "[...document.querySelectorAll('#nav-extra .srow.nav')].find((b) => b.textContent.includes('Board'))"
        sched = item.replace("Board", "Schedule")
        keep = ("(() => { const b = " + item + "; window.__nav = [b, b.querySelector('.glyph > *'), "
                + sched + "]; return b.matches(':hover'); })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"until": "document.querySelector('#list li[data-s=\"maps\"]')"},
                        self.STEADY, {"until": item + " !== undefined"},
                        {"eval": "(document.getElementById('navmenu').click(), 1)"},
                        {"until": "!document.getElementById('nav-extra').hidden"},
                        {"eval": "(" + item + ".id = 'probe-nav', 1)"}, {"hover": "#probe-nav"}, {"eval": keep})
        self.assertTrue(got[-1]["eval"], got)                    # mouse is over a kind item
        for i in range(3):                                       # three new snapshots with the menu open
            self.ev("session.requested", f"w{i}", session_id=f"s-w{i}", cwd="/w", channel="cli", owner=True)
            self.page({"until": f"document.querySelector('#list li[data-s=\"w{i}\"]')"})
        got = self.page({"eval": "(() => { const b = " + item + "; return [b === window.__nav[0], "
                                 "b.querySelector('.glyph > *') === window.__nav[1], "
                                 + sched + " === window.__nav[2], b.matches(':hover'), "
                                 "[...document.querySelectorAll('#nav-extra .srow.nav .nm')].map((n) => n.textContent)]; })()"},
                        {"eval": "(" + item + ".click(), 1)"}, {"until": "location.hash === '#/x/board'"},
                        {"until": "(" + item + ")?.getAttribute('aria-current') === 'true'"})
        same, glyph, sched, hover, names = got[0]["eval"]
        self.assertEqual([same, glyph, sched, hover], [True, True, True, True], got)
        self.assertEqual(names, ["Settings", "Schedule", "Flow", "Usage", "Board"])   # same order
        self.assertTrue(got[-1]["until"], got)                   # the chosen kind is marked, on the same item

    def test_menu_items_follow_the_theme_icons(self):
        # the ☰ menu items stay the same nodes between snapshots, but the "Schedule" icon and a plugin kind's icon are not
        # permanent: themes can have their own (mario, cyberpunk: clock, board); changing the theme swaps them without a
        # reload, "Classic" brings the defaults back
        from unittest import mock
        cfgdir = os.path.join(self.state, "cfg")
        own = os.path.join(cfgdir, "themes")
        os.makedirs(own)
        png = bytes.fromhex("89504e470d0a1a0a0000000d4948445200000001000000010806000000"
                            "1f15c4890000000d49444154789c6360f8cf00000003010100c9fe92ef0000000049454e44ae426082")
        for f in ("clock.png", "board.png"):
            with open(os.path.join(own, f), "wb") as fh:
                fh.write(png)
        with open(os.path.join(own, "kit.json"), "w") as f:
            json.dump({"name": "Bricks", "colors": {"background": "#5c94fc", "foreground": "#000000", "primary": "#e52521"},
                       "icons": {"clock": "clock.png", "board": "board.png"}}, f)
        path = os.path.join(self.state, "plug-view")
        os.makedirs(path)
        with open(os.path.join(path, "hub-plugin.json"), "w") as f:
            json.dump({"name": "board", "description": "view", "why": "w", "web": "main.js", "hub": "^1.6"}, f)
        with open(os.path.join(path, "main.js"), "w") as f:
            f.write("export default hub => hub.addView({id: 'board', title: 'Board', render() {}});\n")
        with open(os.path.join(cfgdir, "hub.json"), "w") as f:
            json.dump({"extensions": {"board": {"path": path, "web": "main.js"}}}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": os.path.join(cfgdir, "hub.json")})
        env.start()
        self.addCleanup(env.stop)
        self.fleet()
        # how many items (schedule, kind) carry the theme's icon
        kits = "document.querySelectorAll('#nav-extra .srow.nav .glyph .kit-img').length"
        items = "[...document.querySelectorAll('#nav-extra .srow.nav')]"
        same = "(() => { const n = " + items + "; return n.length === 5 && n.every((b, i) => b === window.__nav[i]); })()"
        got = self.page({"local": {"hub.settingsTab": "theme"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"wait": "Bricks"}, {"until": items + ".length === 5"},   # the plugin view, "Flow" and "Usage" arrive later
                        {"eval": kits}, {"eval": "(window.__nav = " + items + ", 1)"},
                        {"click": "Bricks"}, {"until": kits + " === 2"}, {"eval": kits}, {"eval": same},
                        {"click": "Classic"}, {"until": kits + " === 0"}, {"eval": kits}, {"eval": same})
        self.assertTrue(got[3]["until"], got)
        self.assertEqual([got[4]["eval"], got[8]["eval"], got[-2]["eval"]], [0, 2, 0], got)
        self.assertEqual([got[9]["eval"], got[-1]["eval"]], [True, True], got)   # the icon changes inside the same items

