    def test_a_version_that_needs_a_new_app_offers_it_with_the_update_button(self):
        # app spec §4.4 (slice A4): the new app is on the distribution server — "Update" puts it in place (Mac,
        # Windows) or downloads the .deb (Linux); checked and waiting for the restart: no button; no app on the
        # server, or a shell from before A4 — the download link of the shell's PACKAGED, as before
        shots = os.environ.get("HUB_TEST_SHOTS")
        cases = (({"auto": True}, "needs a new version of the app (environment 2, yours 1) — Update installs it", True),
                 ({"auto": True, "deb": True}, "Update downloads it; the system then installs it", True),
                 ({"auto": False}, "download the new app", False))
        for shell, text, button in cases:
            self.ev("update.checked", None, result="needs-runtime", app=True, layer=True, version="1.9.10",
                    need_runtime=2, have_runtime=1, download="https://example.test/app",
                    shell={"runtime": 2, "size": 5, **shell}, notes=["- what 1.9.10 brings"])
            got = self.page({"local": {"hub.settingsTab": "about"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                            {"until": "((document.querySelector('.upd-check > p') || {}).textContent || '').includes("
                                      + json.dumps(text) + ")"},
                            {"eval": "String(!!document.querySelector('.upd-check .upd-actions button.btn.primary'))"},
                            *([{"shot": os.path.join(shots, f"a4-{'deb' if shell.get('deb') else 'auto'}.png"),
                                "width": 900, "height": 700}] if shots and button else []))
            self.assertTrue(got[2]["until"], (shell, got))
            self.assertEqual(got[3]["eval"], str(button).lower(), shell)
        self.ev("update.checked", None, result="shell-ready", app=True, layer=True, version="1.9.10",
                shell={"runtime": 2, "auto": True})
        got = self.page({"local": {"hub.settingsTab": "about"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": "((document.querySelector('.upd-check > p') || {}).textContent || '').includes("
                                  + json.dumps("is downloaded and checked") + ")"},
                        {"eval": "String(!!document.querySelector('.upd-check .upd-actions .btn.primary'))"})
        self.assertTrue(got[2]["until"], got)
        self.assertEqual(got[3]["eval"], "false")

