    def test_about_the_hub_on_a_build_of_edits_names_the_release_the_edits_and_returns_the_released(self):
        # `hub app apply` (core/ownsrc.py): "1.2.3 + your edits (2)", and "Return" names the release, not a version
        self.web._code = {"version": "1.2.3+local.abcdef123", "head": "abcdef123", "running": "abcdef123",
                          "layer": "1.2.3+local.abcdef123-team", "own": {"release": "1.2.3", "edits": 2}, "changes": []}
        self.web._code_at = time.time() + 3600
        self.ev("update.checked", None, result="current", app=True, layer=True, have_version="1.2.3", previous="1.2.3",
                own={"release": "1.2.3", "edits": 2})
        # the last word of a git-era modules step stays in the core state of a moved hub
        self.ev("update.modules", None, ok=False, access=False, missing=["stats"], modules={"stats": "missing"}, ref="pm-v1.0.0",
                why="fatal: nope", channel="cli", owner=True)
        got = self.page({"local": {"hub.settingsTab": "about"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": "[...document.querySelectorAll('button')].some((b) => b.textContent.includes('1.2.3'))"},
                        {"eval": "document.querySelector('.about').textContent"},
                        {"eval": "[...document.querySelectorAll('button')].map((b) => b.textContent).filter((t) => t.includes('1.2.3'))"},
                        {"eval": "[...document.querySelectorAll('.about-facts dt')].map((d) => d.textContent)"})
        self.assertTrue(got[2]["until"], got)
        self.assertIn("1.2.3 + your edits (2) · abcdef123", got[3]["eval"])
        self.assertNotIn("local.abcdef123 ·", got[3]["eval"])
        self.assertEqual(got[4]["eval"], ["Return the released 1.2.3"])
        # a hub on a code layer takes updates from the distribution server and has no modules repository: neither
        # "this is the shared hub itself" nor the private modules line is true there
        self.assertIn("Version", got[5]["eval"])
        self.assertNotIn("Updates", got[5]["eval"])
        self.assertNotIn("Private modules", got[5]["eval"])
        self.assertNotIn("shared hub", got[3]["eval"])

