    def test_third_party_modules_are_marked_and_switch_on_the_modules_tab(self):
        # owner decision: third-party modules should be shown, just all marked as third-party: a module from a folder
        # (examples/module-hello) sits in its own section of the "Modules" tab, with a label and a source; enable, disable,
        # lift the pause
        from unittest import mock
        example = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "examples", "module-hello")
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"modules": {"paths": [example]}}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        card = "document.querySelector('.module-card.third-party[data-name=hello]')"
        look = (f"(() => {{ const c = {card}; return [c.querySelector('.third-badge').textContent, "
                "c.querySelector('.module-state').textContent, c.querySelector('.module-from').textContent, "
                "c.querySelector('.module-toggle').textContent, c.closest('.third-party-list').querySelector('h3').textContent, "
                "!!c.closest('.set-more')]; })()")
        click = lambda what: f"({card}.querySelector('[data-act={what}]').click(), 1)"  # noqa: E731
        got = self.page({"local": {"hub.settingsTab": "modules"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": card, "ms": 8000}, {"eval": look}, {"eval": click("enable")},
                        {"until": f"{card}.querySelector('.module-toggle').textContent === 'Disable'", "ms": 8000})
        badge, state, src, button, title, hidden = got[3]["eval"]
        self.assertEqual((badge, state, button, title, hidden), ("third-party", "off", "Enable", "Third-party modules", False))
        self.assertIn(f"Installed from the folder {example}", src)
        self.assertIn("Module API ^2.3", src)
        with open(cfg) as f:
            self.assertEqual(json.load(f)["modules"]["enabled"], ["hello"])
        got = self.page({"eval": click("enable")},
                        {"until": f"{card}.querySelector('.module-toggle').textContent === 'Enable'", "ms": 8000})
        with open(cfg) as f:
            self.assertEqual(json.load(f)["modules"]["enabled"], [])
        # three failures in five minutes pause it; "Lift the pause" is module.reset from the owner, the core lifts it
        with open(cfg, "w") as f:
            json.dump({"modules": {"paths": [example], "enabled": ["hello"]}}, f)
        self.core_decides()
        for _ in range(3):
            self.ev("module.error", "hello", module="hello", hook="call", kind="error", error="boom", channel="core",
                    owner=False)
        got = self.page({"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": f"{card} && {card}.querySelector('[data-act=reset]')", "ms": 8000},
                        {"eval": f"[{card}.querySelector('.module-state').textContent, {card}.querySelector('.module-why').textContent, "
                                 f"{card}.querySelector('[data-act=reset]').textContent]"},
                        {"eval": click("reset")},
                        {"until": f"!{card}.querySelector('[data-act=reset]')", "ms": 8000}, {"errors": 300})
        state, why, reset = got[3]["eval"]
        self.assertEqual((state, reset), ("paused", "Lift the pause"))
        self.assertIn("call: boom", why)
        from core import journal
        self.assertIn("module.reset", [e["type"] for e in journal.read(self.j.path)])
        self.assertEqual(got[-1]["errors"], [])

    def test_an_embeds_module_shows_and_switches_on_the_modules_tab(self):
        # an embed's module (embed/<name>/modules/<module>/module.json, the build's code) has the row with the switch, as
        # one from hub module add had; default_off — off until Enable; a clash with the core's module name — the reason
        from unittest import mock
        from core import modules
        top = os.path.join(self.state, "tree")

        def put(rel, data):
            os.makedirs(os.path.join(top, *rel.split("/")[:-1]), exist_ok=True)
            with open(os.path.join(top, *rel.split("/")), "w") as f:
                json.dump(data, f)
        man = {"version": "1.0.0", "api": "^2.0", "run": ["python3", "main.py"]}
        put("embed/acme/embed.json", {"embed": 1, "api": "1.1"})
        put("embed/acme/modules/quiet/module.json", {"name": "quiet", "default_off": True, "description": "Quiet", **man})
        put("embed/acme/modules/greeter/module.json", {"name": "core-one", **man})
        put("modules/core-one/module.json", {"name": "core-one", **man})
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({}, f)
        for p in (mock.patch.dict(os.environ, {"HUB_CONFIG": cfg}), mock.patch.object(modules, "REPO", top)):
            p.start()
            self.addCleanup(p.stop)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        card = "document.querySelector('.module-card.third-party[data-name=quiet]')"
        clash = "document.querySelector('.module-card.third-party[data-name=core-one]')"
        got = self.page({"local": {"hub.settingsTab": "modules"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": f"!!({card} && {clash})", "ms": 8000},
                        {"eval": f"[{card}.querySelector('.module-toggle').textContent, {card}.dataset.state, "
                                 f"{card}.querySelector('.module-from').textContent, "
                                 f"{clash}.querySelector('.module-state').textContent, "
                                 f"{clash}.querySelector('.module-why').textContent, "
                                 "document.querySelectorAll('.module-card.third-party').length]"},
                        {"eval": f"({card}.querySelector('[data-act=enable]').click(), 1)"},
                        {"until": f"{card}.querySelector('.module-toggle').textContent === 'Disable'", "ms": 8000},
                        {"errors": 300})
        self.assertTrue(got[2]["until"] and got[5]["until"], got)
        button, state, src, clash_state, why, count = got[3]["eval"]
        self.assertEqual((button, state, count), ("Enable", "off", 2))   # the core's own core-one has no row
        self.assertIn("Comes with this build (embed acme), from " + os.path.join(top, "embed", "acme", "modules", "quiet"), src)
        self.assertEqual(clash_state, "error")
        self.assertIn(os.path.join(top, "embed", "acme", "modules", "greeter"), why)
        with open(cfg) as f:
            self.assertEqual(json.load(f)["modules"], {"enabled": ["quiet"], "off": []})
        self.assertEqual(got[-1]["errors"], [])
        shots = os.environ.get("HUB_TEST_SHOTS")   # a folder: the embed's rows as a picture
        if shots:
            self.page({"eval": "(document.querySelector('.third-party-list').scrollIntoView(), 1)"},
                      {"shot": os.path.join(shots, "embed-modules.png"), "width": 1100, "height": 900})

