    def test_page_strings_wait_for_the_server_and_never_show_keys(self):
        # live hub: the page was opened when the new page code was already served from disk, but the old server did not yet
        # know /i18n.json (or was restarting): 404, and until a manual reload the whole page showed keys (web.sidebar.…)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        self.ev("message.received", None, to="a", text="line to check", channel="web", owner=True)
        handler = self.server.RequestHandlerClass
        get, old = handler.do_GET, {"on": True, "asked": 0}

        def do_get(h):   # old server: does not know the page strings
            if h.path == "/i18n.json" and old["on"]:
                old["asked"] += 1
                return h.send_error(404)
            return get(h)
        handler.do_GET = do_get
        keys = r"/\bweb\.[a-z_]+\.[a-z_]/.test(document.body.innerText + document.title)"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"sleep": 2500}, {"eval": keys},
                        {"eval": "document.querySelector('#banner').textContent"})
        self.assertFalse(got[2]["eval"])
        self.assertIn("Connecting to the hub", got[3]["eval"])   # it waits rather than stays silent: the text comes from the page the server served in its language
        self.assertGreater(old["asked"], 1)   # it retries rather than giving up on the first refusal
        # server restart in the middle: for a while nobody answers, then the new server knows the strings
        self.server.shutdown()
        self.server.server_close()
        time.sleep(1)
        from modules.tailnet import access
        for _ in range(50):   # the port may not be free yet (Chrome connections)
            try:
                self.server = access.Server(("127.0.0.1", self.port), self.web.handler())
                break
            except OSError:
                time.sleep(0.1)
        threading.Thread(target=self.server.serve_forever, daemon=True).start()
        got = self.page({"wait": "line to check", "ms": 15000}, {"eval": keys},
                        {"eval": "document.querySelector('#banner').textContent"})
        self.assertFalse(got[1]["eval"])
        self.assertNotIn("Connecting to the hub", got[2]["eval"])

    def test_a_saved_theme_from_an_uninstalled_plugin_is_dropped(self):
        # the theme was chosen while its plugin was still in the catalog; the plugin was removed, the browser remembers the
        # theme and on every load asks for theme files from a nonexistent plugin (hundreds of 404s). Checking against a fresh
        # catalog drops such a theme and brings back the system one.
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        theme = json.dumps({"id": "ghost:gone", "theme": {"name": "Ghost", "colors": {
            "background": "#111111", "foreground": "#eeeeee", "primary": "#ff0000"}}})
        got = self.page({"local": {"hub.theme": theme}},
                        {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": "localStorage.getItem('hub.theme') === null", "ms": 3000},
                        {"eval": "[localStorage.getItem('hub.theme'), "
                                 "getComputedStyle(document.documentElement).getPropertyValue('--background').trim()]"})
        self.assertEqual(got[-1]["eval"], [None, "#ffffff"])   # the plugin that provided it is no longer in the catalog: theme dropped (system background)

    def test_a_saved_theme_survives_a_failed_catalog_answer(self):
        # /api/themes answered with something other than a catalog (a JSON error): that is not "no such theme", the choice
        # stays
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        theme = json.dumps({"id": "own:night.json", "theme": {"name": "Night", "colors": {
            "background": "#111111", "foreground": "#eeeeee", "primary": "#ff0000"}}})
        with mock.patch.object(type(self.web), "themes", return_value={"error": "failure"}):
            got = self.page({"local": {"hub.theme": theme}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                            {"sleep": 800}, {"eval": "localStorage.getItem('hub.theme') === " + json.dumps(theme)})
        self.assertEqual(got[-1]["eval"], True)

    def test_a_saved_theme_whose_file_is_broken_is_kept(self):
        # a theme file is being edited and became invalid JSON for a minute: the server returns it in errors, not in themes.
        # The choice is dropped neither on load nor on opening "Look"; when the file is fixed the theme is back in the list
        # and applied.
        from unittest import mock
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        own = os.path.join(self.state, "themes")
        os.makedirs(own)
        night = os.path.join(own, "night.json")
        with open(night, "w") as f:
            f.write('{"name": "Night", "colors": {')
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        theme = json.dumps({"id": "own:night.json", "theme": {"name": "Night", "colors": {
            "background": "#111111", "foreground": "#eeeeee", "primary": "#ff0000"}}})
        got = self.page({"local": {"hub.theme": theme, "hub.settingsTab": "theme"}},
                        {"go": f"http://127.0.0.1:{self.port}/#/settings"}, {"wait": "night.json"},
                        {"sleep": 500}, {"eval": "localStorage.getItem('hub.theme') === " + json.dumps(theme)})
        self.assertEqual(got[-1]["eval"], True)   # the choice stays: the id is in errors
        with open(night, "w") as f:
            json.dump({"name": "Night", "colors": {"background": "#222222", "foreground": "#eeeeee",
                                                   "primary": "#00ff00"}}, f)
        got = self.page({"errors": 300},   # page reload
                        {"until": "getComputedStyle(document.documentElement).getPropertyValue('--background').trim() === '#222222'",
                         "ms": 3000},
                        {"eval": "JSON.parse(localStorage.getItem('hub.theme')).theme.colors.primary"})
        self.assertEqual(got[-1]["eval"], "#00ff00")   # file fixed: the fresh one is applied

    def route_plugin(self):
        """Navigating to a plugin kind item (API 1.28): hub.go(id, params) puts the params in the address #/x/<id>?k=v, and the kind
        gets them in open(root, params, ctx) on entry, on a new address and on a repeated go to the same one; a kind
        registered after the go gets them at registration; ctx.close() returns to where we came from."""
        path = os.path.join(self.state, "plug-route")
        os.makedirs(path)
        with open(os.path.join(path, "hub-plugin.json"), "w") as f:
            json.dump({"name": "route", "description": "navigation", "why": "w", "web": "main.js", "hub": "^1.28"}, f)
        with open(os.path.join(path, "main.js"), "w") as f:
            f.write("export default function register(hub) {\n"
                    "  window.__opens = []; window.__hub = hub;\n"
                    "  const open = (id) => (root, params, ctx) => { window.__opens.push(id + ' ' + JSON.stringify(params)"
                    " + ' from ' + ctx.from + ' in ' + document.contains(root)); window.__ctx = ctx; };\n"
                    "  hub.addView({ id: 'pick', title: 'Item', render(root) { if (!root.firstChild) root.append("
                    "hub.el('div', 'probe-pick', 'item view')); }, open: open('pick') });\n"
                    "  window.__late = () => hub.addView({ id: 'late', title: 'Late', render(root) {"
                    " if (!root.firstChild) root.append(hub.el('div', 'probe-late', 'late view')); }, open: open('late') });\n"
                    "}\n")
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"extensions": {"route": {"path": path, "web": "main.js"}}}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)

    @staticmethod
    def opens(n):
        return {"until": f"(window.__opens || []).length >= {n}", "ms": 5000}

    def test_go_with_params_reaches_the_view_and_close_returns(self):
        self.route_plugin()
        base = f"http://127.0.0.1:{self.port}/"
        last = "window.__opens.at(-1)"
        got = self.page({"go": base + "#/schedule"}, {"until": "!!window.__hub", "ms": 10000},
                        {"eval": "__hub.go('pick', {plugin: 'teams', id: 'p7'}); 1"}, self.opens(1),
                        {"eval": f"[location.hash, {last}]"},
                        # the same address again: no hashchange, yet the kind gets the item again (to come back to it)
                        {"eval": "__hub.go('pick', {plugin: 'teams', id: 'p7'}); 1"}, self.opens(2), {"eval": last},
                        # another item of the same kind: new params, the original kind stays
                        {"eval": "__hub.go('pick', {id: 'p8', n: 5}); 1"}, self.opens(3), {"eval": last},
                        # two gos in a row: the kind gets only the last
                        {"eval": "__hub.go('pick', {id: 'a'}); __hub.go('pick', {id: 'b'}); 1"}, self.opens(4),
                        {"sleep": 400},
                        {"eval": "window.__opens.slice(3)"},
                        # not a plain object: no navigation
                        {"eval": "__hub.go('pick', {deep: {x: 1}}); location.hash"},
                        {"eval": "__ctx.close(); 1"}, {"until": "location.hash === '#/schedule'", "ms": 5000},
                        # old call without params: as before, the kind gets empty params
                        {"eval": "__hub.go('pick'); 1"}, self.opens(5), {"eval": f"[location.hash, {last}]"})
        self.assertEqual(got[4]["eval"], ["#/x/pick?plugin=teams&id=p7",
                                          'pick {"plugin":"teams","id":"p7"} from #/schedule in true'])
        self.assertEqual(got[7]["eval"], 'pick {"plugin":"teams","id":"p7"} from #/schedule in true')
        self.assertEqual(got[10]["eval"], 'pick {"id":"p8","n":"5"} from #/schedule in true')
        self.assertEqual(got[14]["eval"], ['pick {"id":"b"} from #/schedule in true'])
        self.assertEqual(got[15]["eval"], "#/x/pick?id=b")
        self.assertTrue(got[17]["until"], got[17])
        self.assertEqual(got[20]["eval"], ["#/x/pick", "pick {} from #/schedule in true"])

    def test_params_wait_for_a_view_registered_later(self):
        self.route_plugin()
        base = f"http://127.0.0.1:{self.port}/"
        got = self.page({"go": base + "#/settings"}, {"until": "!!window.__hub", "ms": 10000},
                        {"eval": "__hub.go('late', {id: 'p9'}); 1"}, {"until": "location.hash.startsWith('#/x/late')", "ms": 5000},
                        {"eval": "window.__opens.length"}, {"eval": "__late(); 1"}, self.opens(1),
                        {"eval": "[window.__opens[0], !!document.querySelector('main .probe-late')]"},
                        {"eval": "__ctx.close(); 1"}, {"until": "location.hash === '#/settings'", "ms": 5000})
        self.assertEqual(got[4]["eval"], 0)
        self.assertEqual(got[7]["eval"], ['late {"id":"p9"} from #/settings in true', True])
        self.assertTrue(got[9]["until"], got[9])

    def test_close_of_a_nested_view_keeps_where_the_parent_came_from(self):
        # kind -> nested kind -> close() -> close(): returning to the previous kind does not make the nested one its original
        # address (otherwise two kinds would point to each other)
        self.route_plugin()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/schedule"}, {"until": "!!window.__hub", "ms": 10000},
                        {"eval": "__late(); __hub.go('pick', {id: 'p1'}); 1"}, self.opens(1),
                        {"eval": "__hub.go('late'); 1"}, self.opens(2),
                        {"eval": "__ctx.close(); 1"}, self.opens(3), {"eval": "[location.hash, window.__opens[2]]"},
                        {"eval": "__ctx.close(); 1"}, {"until": "location.hash === '#/schedule'", "ms": 5000})
        self.assertEqual(got[8]["eval"], ["#/x/pick?id=p1", 'pick {"id":"p1"} from #/schedule in true'])
        self.assertTrue(got[10]["until"], got[10])

    def test_opened_by_address_without_origin_closes_to_the_list(self):
        self.route_plugin()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/x/pick?id=p3"}, self.opens(1),
                        {"eval": "window.__opens[0]"}, {"eval": "__ctx.close(); 1"},
                        {"until": "location.hash === '#/sessions'", "ms": 5000})
        self.assertEqual(got[2]["eval"], 'pick {"id":"p3"} from null in true')
        self.assertTrue(got[4]["until"], got[4])

    # ---- feed search (owner decision, option A: a row under the header, ⌘F; "very performant") ----
    # search row state: whether it is open, the count, the current highlight in the feed window, number of highlights,
    # status line
    FS_STATE = ("(() => { const b = document.querySelector('main > .fsearch'); if (!b) return null; "
                "const f = document.querySelector('main .feed').getBoundingClientRect(), c = document.querySelector('main .feed mark.fs-cur'); "
                "const r = c && c.getBoundingClientRect(); "
                "return { focus: document.activeElement === b.querySelector('input'), n: b.querySelector('.fs-n').textContent, "
                "status: b.querySelector('.fs-status').innerText, cur: c ? c.closest('[data-key]').innerText.slice(0, 120) : null, "
                "inside: !!r && r.top >= f.top - 1 && r.bottom <= f.bottom + 1, marks: document.querySelectorAll('main .feed mark.fs-hit').length, "
                "under: Math.round(document.querySelector('main .feed').getBoundingClientRect().top - b.getBoundingClientRect().bottom) }; })()")

    def search_feed(self, busy=False):
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.turn("a", "Where is Ωμέγα?", said="Ωμέγα is on the cape.")
        m = self.j.append("message.received", None, {"to": "a", "text": "check", "channel": "web", "owner": True})
        self.ev("turn.started", "a", marker=f"m{m['seq']}")
        self.ev("turn.tool", "a", id="t-find", name="Bash", input={"command": "grep -r omega"})
        self.ev("turn.tool_result", "a", id="t-find", text="docs/a.md: old ΩΜΈΓΑ stands\nanother line")
        self.ev("session.said", "a", text="Found it.")
        self.ev("turn.result", "a", is_error=False)
        for i in range(12):
            self.turn("a", f"question {i}", said=f"answer {i}", done=not busy or i < 11)   # busy: the last turn is running

    def test_search_in_the_loaded_feed(self):
        self.search_feed(busy=True)   # working: Esc without search would stop the turn
        self.settle()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "compact"}, {"wait": "question 11"},
                        {"eval": "window.__row = document.querySelector('main .feed-inner > [data-key]'), 1"},
                        {"eval": "document.querySelector('main .feed').focus(), 1"},
                        {"key": "f", "mods": ["ctrl"]}, {"typed": "ΩΜΈΓΑ"}, {"sleep": 400}, {"eval": self.FS_STATE},
                        {"eval": "document.contains(window.__row)"},
                        {"key": "Enter"}, {"sleep": 300}, {"eval": self.FS_STATE},
                        {"key": "Enter"}, {"sleep": 300}, {"eval": self.FS_STATE},
                        {"key": "Enter"}, {"sleep": 300}, {"eval": self.FS_STATE},
                        {"key": "Enter", "mods": ["shift"]}, {"sleep": 300}, {"eval": self.FS_STATE},
                        {"key": "Escape"}, {"sleep": 300}, {"eval": self.FS_STATE},
                        {"eval": "document.querySelectorAll('main .feed mark').length"},
                        {"eval": "[...document.querySelectorAll('.feed .row.tool')].filter((r) => r.getAttribute('aria-expanded') === 'true').length"})
        first = got[7]["eval"]
        self.assertTrue(first["focus"])                        # ⌘F puts the cursor in the search row
        self.assertEqual(first["n"], "1 of 3")                  # three rows: question, answer, step output (collapsed in "Brief")
        self.assertGreaterEqual(first["under"], -1)             # the feed is below the row, not hidden under it
        self.assertTrue(got[8]["eval"])                         # typing did not rebuild the feed
        newest = got[11]["eval"]                                # the newest is the step output: the first Enter expands it
        self.assertEqual(newest["n"], "1 of 3")
        self.assertIn("old ΩΜΈΓΑ", newest["cur"])
        self.assertTrue(newest["inside"])
        self.assertLessEqual(newest["marks"], 3)                # only what is in the feed window and nearby is highlighted
        self.assertEqual(got[14]["eval"]["n"], "2 of 3")
        self.assertIn("Ωμέγα is on the cape", got[14]["eval"]["cur"])
        self.assertEqual(got[17]["eval"]["n"], "3 of 3")
        self.assertIn("Where is Ωμέγα", got[17]["eval"]["cur"])
        self.assertEqual(got[20]["eval"]["n"], "2 of 3")        # Shift+Enter goes later
        self.assertIsNone(got[23]["eval"])                      # Esc closed the search
        self.assertEqual(got[24]["eval"], 0)                    # and the highlight
        self.assertEqual(got[25]["eval"], 0)                    # the step output expanded by the jump is collapsed again
        self.assertEqual([e for e in self.spooled() if e["type"] == "session.interrupt_requested"], [])   # the turn was not stopped

    def test_search_goes_on_into_the_archive_in_portions(self):
        from core import history, journal, reducer
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        for k in range(3):   # three archives, each with the phrase for "distant omega"
            self.turn("a", f"old question {k}", said=f"distant ωμέγα {k}")
            for i in range(4):
                self.turn("a", f"noise {k}-{i}", said="nothing")
            st = reducer.fold(reducer.empty(), journal.read(self.j.path))
            journal.rotate(self.state, st, keep=2, per_session=2)
            self.j = journal.Journal(self.j.path)
        for i in range(160):   # the page's first window has only fresh content
            self.turn("a", f"fresh question {i}", said=f"fresh answer {i}")
        history.History(self.state).build_all()
        self.settle()
        with mock.patch.object(history, "SEARCH_BUDGET", 0):   # one archive per chunk
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full"}, {"wait": "fresh answer 159", "ms": 15000},
                            {"eval": self.HIST},
                            {"eval": "document.querySelector('.fs-lupa').click(), 1"}, {"typed": "distant ωμέγα"}, {"sleep": 400},
                            {"eval": self.FS_STATE},
                            {"key": "Enter"}, {"until": "!!document.querySelector('.excerpt-head')", "ms": 20000},
                            {"until": "!!document.querySelector('main .feed mark.fs-cur')", "ms": 5000},
                            {"eval": self.FS_STATE},
                            {"until": "/\\d+ of 3$/.test(document.querySelector('.fs-n').textContent) && /History searched/.test(document.querySelector('.fs-status').innerText)", "ms": 20000},
                            {"eval": self.FS_STATE}, {"eval": "window.__hist"},
                            {"eval": "document.querySelector('.excerpt-head').innerText"},
                            {"key": "Enter"}, {"key": "Enter"}, {"until": "/distant ωμέγα 0/.test(document.querySelector('main .feed mark.fs-cur')?.closest('[data-key]')?.innerText || '')", "ms": 10000},
                            {"eval": self.FS_STATE},
                            {"eval": "[...document.querySelectorAll('.excerpt-head button')].find((b) => b.textContent === 'Back to the feed').click(), 1"},
                            {"sleep": 300}, {"eval": "[!!document.querySelector('.excerpt-head'), document.querySelector('main .feed').innerText.includes('fresh answer 159')]"})
        before = got[6]["eval"]
        self.assertEqual(before["n"], "none")                    # not in what is loaded
        self.assertIn("Search earlier", before["status"])
        landed = got[10]["eval"]
        self.assertIn("distant ωμέγα 2", landed["cur"])           # the nearest one before the loaded part is in the excerpt, in the window
        self.assertTrue(landed["inside"])
        self.assertTrue(got[11]["until"])                       # the chunks reached the end, all three found
        self.assertGreaterEqual(got[13]["eval"], 5)             # three search chunks and the excerpt window, via /api/history… requests
        self.assertIn("Excerpt from", got[14]["eval"])
        self.assertIn("distant ωμέγα 0", got[18]["eval"]["cur"])
        self.assertTrue(got[18]["eval"]["inside"])
        self.assertEqual(got[21]["eval"], [False, True])         # "Back to the feed": the live feed again

    def test_search_with_an_old_server_searches_only_the_loaded_part(self):
        # the page is newer than the server (JS from disk before the hub page restarted): no search path, 404
        self.search_feed()
        self.settle()
        old = ("const of = window.fetch; window.fetch = (u, o) => String(u).startsWith('/api/history/search') "
               "? Promise.resolve(new Response('{\"error\":\"not found\"}', { status: 404 })) : of(u, o);")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "full", "init": old}, {"wait": "answer 11"},
                        {"eval": "document.querySelector('.fs-lupa').click(), 1"}, {"typed": "ωμέγα"}, {"sleep": 400},
                        {"eval": self.FS_STATE}, {"key": "Enter"}, {"key": "Enter"}, {"key": "Enter"}, {"key": "Enter"},
                        {"sleep": 500}, {"eval": self.FS_STATE}, {"errors": 300})
        self.assertEqual(got[5]["eval"]["n"], "1 of 3")
        self.assertIn("after the hub page restarts", got[11]["eval"]["status"])   # beyond what is loaded: no search
        self.assertEqual(got[11]["eval"]["n"], "3 of 3")
        self.assertEqual(got[12].get("errors", []), [])

    def test_search_on_a_phone(self):
        self.search_feed()
        self.settle()
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a", "feed": "compact"}, {"wait": "answer 11"},
                        {"shot": os.path.join(self.state, "p.png"), "width": 390, "height": 844},
                        {"eval": "document.querySelector('.fs-lupa').getClientRects().length > 0"},
                        {"eval": "document.querySelector('.fs-lupa').click(), 1"}, {"typed": "ωμέγα"}, {"sleep": 400},
                        {"eval": "(() => { const b = document.querySelector('main > .fsearch').getBoundingClientRect(), "
                                 "i = document.querySelector('.fsearch input').getBoundingClientRect(), "
                                 "n = document.querySelector('.fs-n').getBoundingClientRect(), "
                                 "x = [...document.querySelectorAll('.fs-btn')].map((e) => e.getBoundingClientRect().right); "
                                 "return [Math.round(b.width), Math.round(i.width), n.width > 0, Math.max(...x) <= innerWidth + 0.5, innerWidth]; })()"},
                        {"eval": self.FS_STATE},
                        # a long query put in at once (pasted, dictated) that finds nothing: the count changes width, the
                        # field with it; the end and the caret stay in view (they slid under the microphone)
                        {"eval": "(() => { const i = document.querySelector('.fsearch input'); i.focus(); i.select(); "
                                 "document.execCommand('insertText', false, 'ωμέγα and a long tail of the query'); return 1; })()"},
                        {"sleep": 400},
                        {"eval": "(() => { const i = document.querySelector('.fsearch input'); "
                                 "return [i.scrollWidth > i.clientWidth, i.scrollWidth - i.clientWidth - i.scrollLeft]; })()"})
        self.assertTrue(got[3]["eval"])                          # a narrow phone screen does not hide the magnifier
        overflows, hidden = got[11]["eval"]
        self.assertTrue(overflows)
        self.assertLessEqual(hidden, 1)                          # the end of the query is in view
        bw, iw, counted, fits, vw = got[7]["eval"]
        self.assertEqual(vw, 390)
        self.assertGreaterEqual(iw, 110)                        # the field is not squeezed to a dot
        self.assertGreaterEqual(iw, bw - 245)                   # the count takes its text, not a reserved 11ch: the field gets the line ("Cancel" is a word here, not a cross)
        self.assertTrue(counted and fits)                       # the count and buttons are on screen
        self.assertEqual(got[8]["eval"]["n"], "1 of 3")

    def test_bottom_line_follows_the_budget_gate(self):
        # budget gate (core/budget.gate): on, executors at the threshold of the whole pool wait for your word; off, at the
        # window reset; in saving mode without the gate nobody waits
        import time as _t
        self.ev("owner.settings", None, timezone="UTC", parallel=3, channel="core")
        self.ev("session.requested", "a", session_id="s-a", cwd="/home/x/work/apps/proj", role="agent", channel="cli",
                owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("session.folder", "a", git="ok", dirty=0, channel="core")
