    def test_account_window_past_its_reset_says_so_instead_of_zero(self):
        """"Settings → Accounts": a window whose reset has passed holds a measurement of the previous window — not "0%" with an
        empty bar (and no aria-label "0%"), but the same words as `hub accounts` and "Spending": "limit reset, no fresh
        reading"; a live window keeps its bar and percent."""
        from modules.accounts import accounts
        accounts.save({"accounts": [{"name": "work", "token": "sk-ant-oat01-x"}], "switch_at": 0.95})
        self.addCleanup(os.remove, accounts.path())
        self.ev("account.switched", None, to="work", restart=False, why="test", channel="core")
        self.ev("account.limits", None, account="work",
                windows={"five_hour": {"used": 0.84, "resets": time.time() - 3600},
                         "seven_day": {"used": 0.43, "resets": time.time() + 3 * 86400}})
        # the page asks /api/usage once on load and keeps the answer for a minute: the tail (every 0.3 s) must already have
        # these events, or a request that comes first gets "no limits yet" and the Spending tab waits for it in vain
        self.settle()
        rows = ("[...document.querySelectorAll('.ac-card .ac-lim')].map((r) => [r.querySelector('.ac-lim-name').textContent, "
                "r.querySelector('.ac-pct')?.textContent || null, !!r.querySelector('.ac-bar'), "
                "[...r.querySelectorAll('[aria-label]')].map((x) => x.getAttribute('aria-label')).join('|'), "
                "r.querySelector('.ac-muted')?.textContent || null])")
        got = self.page({"local": {"hub.settingsTab": "accounts"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": "document.querySelectorAll('.ac-card .ac-lim').length === 2 && "
                                  "!!document.querySelector('.ac-card .ac-pct')"},
                        {"eval": rows})
        (five, week) = got[-1]["eval"]
        self.assertEqual(five, ["5 hours", None, False, "", "limit reset, no fresh reading"], got)
        self.assertEqual(week[:3], ["Week", "43%", True], got)
        self.assertIn("43%", week[3])
        # "Spending" (a preinstalled plugin): the same window — "—" in the head, the words under it, no empty bar "0% used"
        wins = ("[...document.querySelectorAll('.us-win')].map((c) => [c.querySelector('.us-win-pct').textContent, "
                "!!c.querySelector('.us-bar'), c.querySelector('.us-win-lines').textContent])")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/x/usage"},
                        {"until": "document.querySelectorAll('.us-win').length === 2"}, {"eval": wins})
        (five, week) = got[-1]["eval"]
        self.assertEqual(five[:2], ["—", False], got)
        self.assertIn("limit reset, no fresh reading", five[2])
        self.assertNotIn("$0", five[2])   # the spend of a window past its reset is unknown, not $0
        self.assertEqual(week[:2], ["43%", True], got)
        # the limits line under the input field: "—" with the same words in the tooltip
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        segs = ("[...document.querySelectorAll('.status .limseg:not(.limacc)')].map((x) => "
                "[x.querySelector('.limpct').textContent, x.title])")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"},
                        {"until": "document.querySelectorAll('.status .limpct').length === 2"}, {"eval": segs})
        (five, week) = got[-1]["eval"]
        self.assertEqual(five, ["—", "5 hours: limit reset, no fresh reading"], got)
        self.assertEqual(week[0], "43%", got)

    @cut.needs("profile")
    def test_usage_is_a_menu_view_next_to_flow_not_a_settings_tab(self):
        """"Usage" sits in the ☰ menu right after "Flow" (the same kind of item, its own address #/x/usage) and is no tab of
        Settings; the old tab address — hub.openSettings("x:usage") — opens the view; the view is not narrower than "Flow"'s."""
        names = "[...document.querySelectorAll('#nav-extra .srow.nav .nm')].map((n) => n.textContent)"
        tabs = "[...document.querySelectorAll('[data-settings-tab]')].map((b) => b.dataset.settingsTab)"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"until": f"{names}.includes('Usage')"}, {"eval": names},
                        {"eval": "(document.getElementById('navmenu').click(), 1)"},
                        {"until": "!document.getElementById('nav-extra').hidden"},
                        {"eval": "(() => { const b = [...document.querySelectorAll('#nav-extra .srow.nav')].find((x) => x.querySelector('.nm').textContent === 'Usage'); b.click(); return 1; })()"},
                        {"until": "location.hash === '#/x/usage'"},
                        {"until": "!!document.querySelector('.ext-view .us')"},
                        {"eval": "[document.querySelector('.ext-view .us-title').textContent, document.querySelector('#nav-extra .srow.nav[aria-current=\"true\"] .nm')?.textContent]"},
                        {"eval": "(() => { const a = document.querySelector('.ext-view .us').getBoundingClientRect().width, v = document.querySelector('.ext-view').clientWidth; return [a, v]; })()"},
                        {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": "!!document.querySelector('[data-settings-tab]')"}, {"eval": tabs},
                        {"eval": "(() => { const open = (tab) => !dispatchEvent(new CustomEvent('hub-open-settings', {detail: tab, cancelable: true})); return open('x:usage'); })()"},
                        {"until": "location.hash === '#/x/usage'"},
                        {"until": "!!document.querySelector('.ext-view .us-lead')"},
                        {"eval": "(() => { const t = document.querySelector('.us-title').getBoundingClientRect(), l = document.querySelector('.us-lead').getBoundingClientRect(); return [l.top - t.bottom, l.top >= t.bottom]; })()"},
                        {"errors": 300})
        order = got[2]["eval"]
        self.assertEqual(order[order.index("Flow") + 1], "Usage", got)          # right after "Flow"
        self.assertEqual(got[8]["eval"], ["Usage", "Usage"], got)               # the open view is marked in the menu
        width, room = got[9]["eval"]
        self.assertGreater(width, room * 0.9, got)                              # takes the width of the view, no 880 px column
        self.assertFalse([x for x in got[12]["eval"] if x.endswith(":usage")], got)   # no tab in Settings
        self.assertTrue(got[13]["eval"], got)                                   # the old address was taken by the view
        gap, below = got[-2]["eval"]
        self.assertTrue(below and gap < 10, got)                                # the lead sits right under the title: no overlap, no drift
        self.assertEqual(got[-1]["errors"], [])

