    def account_cards_fit(self):
        """The pool of four accounts (a busy one, a current one, emails of a usual length, a week reset on another day): at the
        width of a tablet, a wide window and a phone, in Classic and Clean, nothing of a card is cut by its edge or hangs out
        of it — not the limit rows with their "resets …", not the email, not the "measured …" line beside "Refresh" — and
        the tab has no sideways scroll. Returns the first things out of place, per look and width."""
        from modules.accounts import accounts
        mails = ["owner.one@example.com", "owner.two@example.com", "team.member@example.org", "second.owner@example.net"]
        accounts.save({"accounts": [{"name": n, "token": f"sk-ant-oat01-{n}", "email": m}
                                    for n, m in zip(("alpha", "beta", "gamma", "delta"), mails)], "switch_at": 0.95})
        self.addCleanup(os.remove, accounts.path())
        now = time.time()
        self.ev("account.switched", None, to="gamma", restart=False, why="test", channel="core",
                blocked={"alpha": now + 86400})
        for name, five, week in (("alpha", None, 0.99), ("beta", None, 0.02), ("gamma", 0.74, 0.26), ("delta", None, 0.0)):
            self.ev("account.limits", None, account=name, windows={
                **({"five_hour": {"used": five, "resets": now + 3 * 3600}} if five is not None else {}),
                "seven_day": {"used": week, "resets": now + 2 * 86400 + 7200}})
        self.settle()
        probe = ("(() => { const out = []; const tab = document.querySelector('.ac'); "
                 "for (let n = tab; n; n = n.parentElement) if (n.scrollWidth > n.clientWidth + 1) out.push('scroll:' + (n.className || n.tagName)); "
                 "for (const c of document.querySelectorAll('.ac-card')) { const cr = c.getBoundingClientRect(); "
                 "for (const x of c.querySelectorAll('*')) { if (!x.textContent.trim() || x.children.length && !x.matches('.ac-lim, .ac-head, .ac-title, .ac-note-row')) continue; "
                 "const r = x.getBoundingClientRect(); "
                 "if (x.scrollWidth > x.clientWidth + 1 || r.right > cr.right + 1 || r.left < cr.left - 1) out.push(x.className + ':' + x.textContent.trim().slice(0, 30)); } } "
                 "return out.slice(0, 8); })()")
        url = f"http://127.0.0.1:{self.port}/#/settings"
        steps, keys = [{"local": {"hub.settingsTab": "accounts"}}], []
        for look in ("clean", "classic"):   # a fresh browser is Clean; Classic is stored in it
            for width, scale in ((830, 1), (390, 1), (1100, 1), (1300, 1), (1300, 1.3333)):   # the last one — a larger text step
                init = f"localStorage.setItem('hub.textScale', '{scale}')" if scale != 1 else "localStorage.removeItem('hub.textScale')"
                steps += [{"go": "about:blank", "look": None},
                          {"go": url, "init": init, **({"look": None} if look == "clean" else {})},
                          {"until": "document.querySelectorAll('.ac-card .ac-pct').length >= 3"},
                          {"shot": os.path.join(self.state, f"cards-{look}-{width}-{scale}.png"), "width": width, "height": 900, "full": True},
                          {"eval": probe}]
                keys.append((look, width, scale))
        got = self.page(*steps)
        return {k: got[1 + 5 * i + 4]["eval"] for i, k in enumerate(keys)}

    @cut.needs("profile")
    def test_account_cards_fit_their_width(self):
        got = self.account_cards_fit()
        self.assertEqual(got, {k: [] for k in got}, got)

    @cut.needs("profile")
    def test_account_refresh_button_takes_a_fresh_reading_into_the_card(self):
        """"Settings → Accounts": an account with its own token has "Refresh" (its tooltip warns that on an account that is not
        current the reading opens the 5-hour window), a token by command has none; the click measures that account only
        (a fake API), the button says "Measuring…" meanwhile, and the card shows the new reading from the core; a reading
        that fails says why under the card."""
        from modules.accounts import accounts
        from modules.gateway import gateway
        accounts.save({"accounts": [{"name": "work", "token": "sk-ant-oat01-x"}, {"name": "spare", "token": "sk-ant-oat01-y"},
                                    {"name": "corp", "command": ["get-token"]}], "switch_at": 0.95})
        self.addCleanup(os.remove, accounts.path())
        self.ev("account.switched", None, to="work", restart=False, why="test", channel="core")
        self.ev("account.limits", None, account="work", windows={"five_hour": {"used": 0.4, "resets": time.time() + 3600}})
        self.core_decides()
        self.settle()
        tokens, release = [], threading.Event()

        def measure(token, **kw):
            tokens.append(token)
            release.wait(30)   # the reading runs until the page has shown "Measuring…" (the test lets it go)
            return 200, {"status": "allowed", "type": "five_hour", "overage": False,
                         "windows": {"five_hour": {"used": 0.37, "resets": time.time() + 5 * 3600},
                                     "seven_day": {"used": 0.12, "resets": time.time() + 4 * 86400}}}
        card = "[...document.querySelectorAll('.ac-card')].find((c) => c.querySelector('.ac-name').textContent === '{}')"
        btn = f"({card.format('spare')}.querySelector('.ac-probe') || {{}})"
        with mock.patch.object(gateway, "measure", measure):
            got = self.page({"local": {"hub.settingsTab": "accounts"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                            {"until": "document.querySelectorAll('.ac-card').length === 3"},
                            {"eval": "[...document.querySelectorAll('.ac-card')].map((c) => [c.querySelector('.ac-name').textContent, "
                                     "c.querySelector('.ac-probe')?.textContent || null])"},
                            {"eval": f"[{btn}.title, document.querySelector('.ac-tools .ac-probe')?.textContent || null]"},
                            {"eval": f"{btn}.click()"},
                            {"until": f"{btn}.textContent === 'Measuring…' && {btn}.disabled === true"})
            release.set()
            done = self.page({"until": f"(({card.format('spare')}.querySelector('.ac-pct') || {{}}).textContent || '') === '37%'"},
                             {"until": f"{btn}.textContent === 'Refresh' && {btn}.disabled === false"})
        self.assertEqual(got[3]["eval"], [["work", "Refresh"], ["spare", "Refresh"], ["corp", None]], got)
        self.assertIn("5-hour window", got[4]["eval"][0])
        self.assertEqual(got[4]["eval"][1], "Refresh all")
        self.assertTrue(got[6]["until"], got)
        self.assertTrue(all(s["until"] for s in done), done)
        self.assertEqual(tokens, ["sk-ant-oat01-y"])                     # only the clicked account, never the command one
        seen = self.web.tail.reader.state["account"]["seen"]
        self.assertEqual(seen["spare"]["windows"]["five_hour"]["used"], 0.37)
        self.assertEqual(seen["work"]["windows"]["five_hour"]["used"], 0.4)   # the others untouched

        def broken(token, **kw):
            raise ConnectionRefusedError("x")
        with mock.patch.object(gateway, "measure", broken):
            got = self.page({"eval": "document.querySelector('.ac-tools .ac-probe').click()"},
                            {"until": "document.querySelectorAll('.ac-probe-err').length === 2"},
                            {"eval": "[...document.querySelectorAll('.ac-probe-err')].map((x) => x.textContent)"})
        self.assertTrue(got[1]["until"], got)
        self.assertEqual(len(got[2]["eval"]), 2)
        self.assertTrue(all("no connection to Claude" in x for x in got[2]["eval"]), got)

    def test_slash_commands_of_a_sleeping_session_are_decided_by_the_core(self):
        # automata audit, finding 20: the page refused by itself ("asleep, nothing to compact"), but
        # the core accepts compacting a sleeping session (it compacts on wake-up, PR #131); a core refusal (/stop without a
        # turn) keeps the page's old words
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        self.ev("session.ended", "a", reason="prompt_input_exit")
        self.core_decides()
        box = "#msg"
        hint, err = (f"(document.querySelector('.composer {c}')?.textContent || '')" for c in (".hint", ".error-text"))
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": "!!document.querySelector('#msg')"},
                        {"eval": self.fn(self.TYPE, box, "/compact")}, {"eval": self.fn(self.KEY, box, False)},
                        {"until": f"{hint}.includes('The core took /compact')", "ms": 6000},
                        {"eval": self.fn(self.TYPE, box, "/stop")}, {"eval": self.fn(self.KEY, box, False)},
                        {"until": f"{err}.includes('The session is not doing anything right now')", "ms": 6000})
        self.assertTrue(got[4]["until"], got)
        self.assertTrue(got[-1]["until"], got)
        st = reducer.fold(reducer.empty(), journal.read(self.j.path))
        self.assertEqual((st["sessions"]["a"]["state"], st["sessions"]["a"].get("compact_wake")), ("asleep", True))

    def test_parked_session_can_be_removed_from_its_menu(self):
        # owner decision: a parked session (on the page "idle", no process) had no "Remove" in the menu: first "Put to sleep",
        # then "Remove"; the core accepts removing a parked one. The confirmation is the same dialog as for a sleeping one
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
