        items = "[...document.querySelectorAll('.menu-item')].filter((b) => b.getClientRects().length).map((b) => b.innerText.trim())"   # the shown ones: the head's switches are in it hidden
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"wait": "More"},
                        {"eval": "(document.querySelector('main .menu-btn').click(), 1)"},
                        {"until": "!!document.querySelector('.menu-item')"}, {"eval": items},
                        {"click": "Remove from the list"},
                        {"until": "document.getElementById('confirm-dlg').open && document.getElementById('confirm-title').textContent"},
                        {"eval": "document.getElementById('confirm-ok').click(), 1"},
                        {"until": "location.hash === '#/'", "ms": 6000})
