        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"extensions": {"field2": {"path": path, "web": "main.js"}}}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        with open(os.path.join(path, "main.js"), "w") as f:
            f.write("export default function register(hub) {\n"
                    "  for (const slot of ['topbar', 'session.header', 'session.composer']) {\n"
                    "    const inp = document.createElement('input'); inp.dataset.probe = slot;\n"
                    "    hub.addSlot(slot, { id: 'f', render(root) { if (!root.firstChild) root.append(inp); } });\n"
                    "  }\n  window.__ready = true;\n}\n")
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        slots = ("topbar", "session.header", "session.composer")
        q = lambda slot: f"document.querySelector('input[data-probe=\"{slot}\"]')"
        type_in = lambda slot, text: (f"(() => {{ const i = {q(slot)}; i.focus(); i.value = '{text}'; "
                                      "return document.activeElement === i; })()")
        kept = lambda slot: f"[document.activeElement === {q(slot)}, {q(slot)}.value]"
        live = ("import('/static/js/state.js').then(({render}) => { render(); render(); "
                "requestAnimationFrame(() => requestAnimationFrame(() => { window.__live = true; })); }); 1")
