    def test_plugin_shows_hub_words_in_the_page_banner(self):
        # API 1.30 (module kind request: a hub refusal of its own request looks like the page's, without its markup):
        # hub.banner(text) is a row in the page banner, text only, fades after 10 s, a click closes it; the page banner is not
        # covered
        from unittest import mock
        path = os.path.join(self.state, "plug-banner")
        os.makedirs(path)
        with open(os.path.join(path, "hub-plugin.json"), "w") as f:
            json.dump({"name": "said", "description": "words", "why": "w", "web": "main.js", "hub": "^1.30"}, f)
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"extensions": {"said": {"path": path, "web": "main.js"}}}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        with open(os.path.join(path, "main.js"), "w") as f:
            f.write("export default function register(hub) { window.__hub = hub; }\n")
        on = "document.getElementById('banner').classList.contains('on')"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"errors": 1500},
                        {"until": "!!window.__hub", "ms": 8000},
                        {"eval": "window.__hub.capabilities.banner"},
                        {"eval": "window.__hub.banner('  <b>Hub</b>\\n refused:  ' + 'x'.repeat(400))"},
                        {"eval": f"[{on}, document.getElementById('banner').textContent, "
                                 "document.getElementById('banner').children.length]"},
                        {"eval": "document.getElementById('banner').click(), 1"},
                        {"eval": on},
                        {"eval": "window.__hub.banner('   ')"},
                        {"eval": "import('/static/js/api.js').then((m) => { window.__api = m; }), 1"},
                        {"until": "!!window.__api"},
                        {"eval": "window.__api.banner('No connection.', true), "
                                 "[window.__hub.banner('Hub refusal.'), document.getElementById('banner').textContent]"},
                        {"eval": "window.__api.banner(''), window.__hub.banner('Hub refusal.')"},
                        {"eval": f"[{on}, document.getElementById('banner').textContent]"})
        self.assertEqual(got[3]["eval"], 1)
        self.assertIs(got[4]["eval"], True)
        shown, text, children = got[5]["eval"]
        self.assertTrue(shown)
        self.assertEqual(children, 0)                                   # HTML is not parsed, text only
        self.assertTrue(text.startswith("<b>Hub</b> refused: x"))     # in one line
        self.assertEqual(len(text), 300)
        self.assertFalse(got[7]["eval"])                                # a click closed it
        self.assertIs(got[8]["eval"], False)                            # empty: nothing
        self.assertEqual(got[11]["eval"], [False, "No connection."])         # the page banner holds
        self.assertIs(got[12]["eval"], True)
        self.assertEqual(got[13]["eval"], [True, "Hub refusal."])

    def test_plugin_banner_counts_symbols_and_says_false_where_main_is_hidden(self):
        # from the PR #292 review: truncation to 300 is by characters (a surrogate pair is not split), and on a narrow screen
        # in the session list (#/sessions) main is hidden together with the banner: hub.banner returns false, not "shown"
        from unittest import mock
        path = os.path.join(self.state, "plug-banner2")
