    def test_attachment_remove_has_a_44_target_without_moving_the_chip(self):
        # the attachment's cross: a 44×44 tap zone around ✕ (was ~18×20), only on a touch screen (pointer: coarse); with a
        # mouse there is no zone, and a click on the end of a file name does not remove the attachment. The chip's look and
        # layout are the same, a click on a neighbouring chip and on the field stays theirs
        for n in ("a", "b", "c", "d"):   # a separate session per case: each has its own attachments in the field
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w")
            self.ev("session.started", n, session_id=f"s-{n}")
        paste = ("(() => { const png = Uint8Array.from(atob('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8DwHwAFBQIAX8jx0gAAAABJRU5ErkJggg=='), "
                 "(c) => c.charCodeAt(0)); const dt = new DataTransfer(); "
                 "dt.items.add(new File([png], 'a.png', {type: 'image/png'})); "
                 "dt.items.add(new File([new Uint8Array([1, 2])], 'b.pdf', {type: 'application/pdf'})); "
                 "document.querySelector('#msg').dispatchEvent(new ClipboardEvent('paste', "
                 "{clipboardData: dt, bubbles: true, cancelable: true})); return 1; })()")
        rects = ("[...document.querySelectorAll('form.composer .pchip, form.composer .pchip .x')].map((e) => { "
                 "const r = e.getBoundingClientRect(); return [r.left, r.top, r.width, r.height].map((v) => Math.round(v * 100) / 100); })")
        probe = ("(() => { const chips = [...document.querySelectorAll('form.composer .pchip')], "
                 "at = (x, y) => document.elementFromPoint(x, y); "
                 "const zones = chips.map((c) => { const x = c.querySelector('.x'), r = x.getBoundingClientRect(), "
                 "cx = r.left + r.width / 2, cy = r.top + r.height / 2, z = getComputedStyle(x, '::after'); "
                 "return {w: parseFloat(z.width) || 0, h: parseFloat(z.height) || 0, "
                 "corners: [[-21, -21], [21, -21], [-21, 21], [21, 21]].every(([dx, dy]) => at(cx + dx, cy + dy)?.closest('.x') === x), "
                 "nameEnd: ((n) => at(getComputedStyle(c).direction === 'rtl' ? n.left + 1 : n.right - 1, n.top + n.height / 2)?.closest('.x') === x)"
                 "(c.querySelector('.nm').getBoundingClientRect()), "
                 "coarse: matchMedia('(pointer: coarse)').matches}; }); "
                 "const n = chips[1].getBoundingClientRect(), t = document.querySelector('#msg').getBoundingClientRect(), "
                 "s = getComputedStyle(chips[1]).direction === 'rtl' ? n.right - 1 : n.left + 1; "   # the chip's start, by the first one's zone
                 "return {zones, neighbour: at(s, n.top + n.height / 2)?.closest('.pchip') === chips[1] "
                 "&& !at(s, n.top + n.height / 2)?.closest('.x'), "
                 "field: at(t.left + t.width / 2, t.top + t.height / 2) === document.querySelector('#msg')}; })()")
        plain = ("(() => { const s = document.createElement('style'); s.id = 'pchip-plain'; s.textContent = "
                 "'.pchip .x::after { content: none !important }'; "
                 "document.head.append(s); return 1; })()")
        chips = "document.querySelectorAll('form.composer .pchip .nm')"
        seen = {}
        # first the frames of all cases, then the checks; mouse and touch, at both widths
        for width, height, n, touch in ((1300, 800, "a", True), (390, 844, "b", True), (1300, 800, "c", False), (390, 844, "d", False)):
            seen[(width, touch)] = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/{n}"}, {"until": "!!document.querySelector('#msg')"},
                            {"shot": os.path.join(self.state, "x.png"), "width": width, "height": height},
                            {"touch": touch}, {"eval": paste},
                            {"until": f"{chips}.length === 2 && ![...{chips}].some((n) => n.textContent.includes('uploading'))"},
                            {"until": "!document.querySelector('form.composer.flash')"}, {"sleep": 300},
                            {"eval": rects}, {"eval": probe},
                            {"shot": os.path.join(self.state, f"pchip-{width}.png"), "width": width, "height": height},
                            {"eval": plain}, {"sleep": 100}, {"eval": rects},
                            {"eval": "document.getElementById('pchip-plain').remove(), 1"}, {"touch": False})
        for (width, touch), got in seen.items():
            case = (width, "touch" if touch else "mouse")
            zones = got[9]["eval"]
            self.assertEqual(len(zones["zones"]), 2, case)
            for z in zones["zones"]:
                self.assertEqual(z["coarse"], touch, case)               # emulation works: pointer matches the case
                if touch:
                    self.assertGreaterEqual(min(z["w"], z["h"]), 44, (case, zones))
                    self.assertTrue(z["corners"], (case, zones))        # the zone's edges are the same cross
                else:
                    self.assertLess(max(z["w"], z["h"]), 44, (case, zones))   # with a mouse there is no zone
                    self.assertFalse(z["nameEnd"], (case, zones))        # the end of the file name is not the cross
            if touch:
                self.assertTrue(any(z["nameEnd"] for z in zones["zones"]), (case, zones))   # a finger at the end of the name is the cross
            self.assertTrue(zones["neighbour"], (case, zones))         # a neighbouring chip is its own
            self.assertTrue(zones["field"], (case, zones))             # the field is its own
            self.assertEqual(got[8]["eval"], got[13]["eval"])          # without the zone the chips and ✕ are in the same places

    def test_composer_long_paste_is_a_tile_the_quote_a_card_the_cross_a_round_button(self):
        # owner requests: a long paste (a log, an article) is attached as a text file with its start in a small tile, with
        # no length limit, not left as a wall of text in the field; the field does not repeat the session's name (it is in
        # the header); the attachment's ✕ is hit with a mouse the first time; the reply quote is a card in the field with
        # up to two lines of the quote and a ✕ in its corner, not a one-line "Reply to …" plate with "Cancel"
        self.ev("session.requested", "atlas", session_id="s-at", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "atlas", session_id="s-at")
        self.ev("session.said", "atlas", text="Noted: the map stays on the old server, we do not install a corporate proxy. " * 6)
        paste = ("((text) => { const dt = new DataTransfer(); dt.setData('text/plain', text); "
                 "return document.querySelector('#msg').dispatchEvent(new ClipboardEvent('paste', {clipboardData: dt, bubbles: true, "
                 "cancelable: true})); })")
        chip = "document.querySelector('form.composer .pchip')"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/atlas"}, {"wait": "Noted"},
                        {"shot": os.path.join(self.state, "x.png"), "width": 1300, "height": 800},
                        {"eval": "document.querySelector('#msg').placeholder"},
                        {"eval": f"{paste}('a short line')"},
                        {"eval": f"{paste}('line of a long log\\n'.repeat(1500))"},
                        {"until": f"!!{chip} && !{chip}.textContent.includes('uploading')", "ms": 5000},
                        {"eval": f"(() => {{ const x = {chip}.querySelector('.x').getBoundingClientRect(); return {{"
                                 f"name: {chip}.querySelector('.nm').textContent, tile: {chip}.querySelector('.ptile')?.textContent.slice(0, 18), "
                                 f"field: document.querySelector('#msg').value, x: [x.width, x.height]}}; }})()"},
                        {"eval": "[...document.querySelectorAll('.reply-btn')].pop().click(), 1"},
                        {"until": "!!document.querySelector('.reply-bar.quote .reply-quote')"},
                        {"eval": "(() => { const q = document.querySelector('.reply-quote'), lh = parseFloat(getComputedStyle(q).lineHeight); "
                                 "return {lines: Math.round(q.clientHeight / lh), cut: q.scrollHeight > q.clientHeight, "
                                 "words: q.textContent.startsWith('Noted: the map'), cross: !!document.querySelector('.reply-bar > .x .icon'), "
                                 "cancel: [...document.querySelectorAll('.reply-bar button')].some((b) => /Cancel/.test(b.textContent))}; })()"},
                        {"eval": "document.querySelector('.reply-bar > .x').click(), 1"},
                        {"until": "!document.querySelector('form.composer .reply-bar')"})
        self.assertNotIn("atlas", got[3]["eval"])                         # the field does not repeat the session's name
        self.assertIs(got[4]["eval"], True)                               # a short paste is the browser's own
        self.assertIs(got[5]["eval"], False)                              # a long one is taken
        self.assertTrue(got[6]["until"], got)
        tile = got[7]["eval"]
        self.assertTrue(tile["name"].startswith("pasted-1.txt"), tile)
        self.assertEqual(tile["tile"], "line of a long log")
        self.assertEqual(tile["field"], "")
        self.assertEqual(tile["x"], [20, 20], tile)                       # the ✕ is a disc in the corner (was an 18×20 glyph)
        self.assertTrue(got[9]["until"], got)
        self.assertEqual(got[10]["eval"], {"lines": 2, "cut": True, "words": True, "cross": True, "cancel": False})
        self.assertTrue(got[12]["until"], got)                            # the ✕ takes the reply off

    def test_the_quote_and_the_chips_are_above_the_text_and_their_crosses_are_discs_in_the_corner(self):
        # as in the phone and Mac apps (kit composer): the reply quote and the attachments are one strip of cards
        # above the text, the quote first; each card's cross is a visible disc in its corner (20 with a mouse, 22 on a touch
        # screen, inset radius - disc/2 but at least 4) with a 44 tap zone on touch; the quote is the message's words,
        # without its markdown (no ** or list dash)
        self.ev("session.requested", "atlas", session_id="s-at", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "atlas", session_id="s-at")
        self.ev("session.said", "atlas", text="- **Permission card:** the map stays on the old server, the cache holds a week.")
        paste = ("(() => { const png = Uint8Array.from(atob('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8DwHwAFBQIAX8jx0gAAAABJRU5ErkJggg=='), "
                 "(c) => c.charCodeAt(0)); const dt = new DataTransfer(); dt.items.add(new File([png], 'a.png', {type: 'image/png'})); "
                 "dt.items.add(new File(['notes'], 'notes.txt', {type: 'text/plain'})); "
                 "document.querySelector('#msg').dispatchEvent(new ClipboardEvent('paste', {clipboardData: dt, bubbles: true, cancelable: true})); return 1; })()")
        probe = ("(() => { const r = (e) => e.getBoundingClientRect(), bar = document.querySelector('form.composer .reply-bar'), "
                 "chip = bar.querySelector('.reply-chip'), filled = (e) => !/rgba\\(0, 0, 0, 0\\)|transparent/.test(getComputedStyle(e).backgroundColor), "
                 "q = r(bar), c = r(document.querySelector('form.composer .pending')), t = r(document.querySelector('#msg')); "
                 "const disc = (x, card) => { const a = r(x), b = r(card), rtl = getComputedStyle(card).direction === 'rtl', z = getComputedStyle(x, '::after'); "
                 "return {size: [Math.round(a.width), Math.round(a.height)], round: getComputedStyle(x).borderRadius === '50%', seen: filled(x), "
                 "top: Math.round(a.top - b.top), end: Math.round(rtl ? a.left - b.left : b.right - a.right), zone: Math.round(parseFloat(z.width) || 0)}; }; "
                 "return {order: q.bottom <= c.top + 1 && c.bottom <= t.top + 1, quote: document.querySelector('.reply-quote').textContent, "
                 "chips: document.querySelectorAll('form.composer .pchip').length, "
                 "fit: [...document.querySelectorAll('form.composer .pchip')].every((e) => r(e.querySelector('.x')).bottom <= r(e).bottom - 2), "
                 "file: disc(document.querySelector('form.composer .pchip .x'), document.querySelector('form.composer .pchip')), "
                 "reply: disc(bar.querySelector(':scope > .x'), filled(chip) ? chip : bar)}; })()")
        seen = {}
        for touch in (False, True):
            seen[touch] = self.page({"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/s/atlas"}, {"wait": "Permission card"},
                                    {"shot": os.path.join(self.state, "x.png"), "width": 390 if touch else 1300, "height": 844 if touch else 800},
                                    {"touch": touch}, {"eval": paste},
                                    {"until": "!!document.querySelector('form.composer .pchip img') && !document.querySelector('form.composer.flash')"},
                                    {"eval": "[...document.querySelectorAll('.reply-btn')].pop().click(), 1"},
                                    {"until": "!!document.querySelector('.reply-bar.quote .reply-quote')"}, {"sleep": 200},
                                    {"eval": probe}, {"touch": False})
        for touch, got in seen.items():
            self.assertTrue(got[6]["until"] and got[8]["until"], got)
            p = got[10]["eval"]
            self.assertTrue(p["order"], (touch, p))                                  # quote, then the chips, then the text
            self.assertEqual(p["chips"], 2, p)
            self.assertTrue(p["fit"], (touch, p))                 # a file chip without a preview is as tall as its disc needs
            self.assertEqual(p["quote"], "Permission card: the map stays on the old server, the cache holds a week.", p)
            side = 22 if touch else 20
            for x in (p["file"], p["reply"]):
                self.assertEqual(x["size"], [side, side], (touch, p))
                self.assertTrue(x["round"] and x["seen"], (touch, p))               # a disc one sees, not a bare glyph
                self.assertTrue(3 <= x["top"] <= 6 and 3 <= x["end"] <= 6, (touch, p))   # in the card's corner
                self.assertGreaterEqual(x["zone"], 44 if touch else 28, (touch, p))

    def test_attachment_remove_targets_do_not_take_the_paperclip(self):
        # PR #298: the ✕ zone (44×44) of a second-row chip reached the paperclip in the field's corner (window below 900 px:
        # no "to" row, chips are the first row): tapping the bottom of the clip removed the attachment. The clip is above the
        # chips and the zones: 44 on a touch screen, 28 with a mouse
        for n in ("a", "b"):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w")
            self.ev("session.started", n, session_id=f"s-{n}")
        files = ",".join(f"new File([new Uint8Array([1, 2])], 'r{i}-{'x' * (6 + 3 * i)}.pdf', {{type: 'application/pdf'}})"
                         for i in range(12))
        paste = ("(() => { const dt = new DataTransfer(); [" + files + "].forEach((f) => dt.items.add(f)); "
                 "document.querySelector('#msg').dispatchEvent(new ClipboardEvent('paste', "
                 "{clipboardData: dt, bubbles: true, cancelable: true})); return 1; })()")
        chips = "document.querySelectorAll('form.composer .pchip .nm')"
        # the layout depends on fonts (✕ 16 or 19 px, field height, chip wrapping): chips pushed right put each row's ✕ at the
        # right edge, under the clip, whichever row it falls in
        right = "(() => { document.querySelector('form.composer .pending').style.justifyContent = 'flex-end'; return 1; })()"
        # [the ✕ zone of some chip reaches the clip: how many points inside the clip's circle (it is round, the box corners
        # are not its) the chip takes]
        probe = ("(() => { const a = document.querySelector('form.composer > .attach'), r = a.getBoundingClientRect(), "
                 "zones = [...document.querySelectorAll('form.composer .pchip .x')].map((x) => { "
                 "const q = x.getBoundingClientRect(), cx = q.left + q.width / 2, cy = q.top + q.height / 2; "
                 "return [cx - 22, cy - 22, cx + 22, cy + 22]; }); "
                 "const under = zones.some(([x0, y0, x1, y1]) => x0 < r.right && r.left < x1 && y0 < r.bottom && r.top < y1); "
                 "const cx = (r.left + r.right) / 2, cy = (r.top + r.bottom) / 2, R = r.width / 2 - 1; let miss = 0; "
                 "for (let x = r.left + 1; x < r.right; x += 2) for (let y = r.top + 1; y < r.bottom; y += 2) "
                 "if (Math.hypot(x - cx, y - cy) < R && document.elementFromPoint(x, y)?.closest('.pchip')) miss += 1; "
                 "return [under, miss]; })()")
        for n, touch in (("a", True), ("b", False)):
            got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/{n}"}, {"until": "!!document.querySelector('#msg')"},
                            {"shot": os.path.join(self.state, "x.png"), "width": 1300, "height": 800}, {"touch": touch}, {"eval": paste},
                            {"until": f"{chips}.length === 12 && ![...{chips}].some((n) => n.textContent.includes('uploading'))"},
                            {"until": "!document.querySelector('form.composer.flash')"}, {"sleep": 300}, {"eval": right}, {"sleep": 100},
                            {"eval": probe}, {"touch": False})
            self.assertTrue(got[5]["until"])                # all 12 chips are loaded
            # touch: the ✕ zone reaches the clip, but a tap on the clip is the clip's; mouse: the clip is its own too
            under, miss = got[-2]["eval"]
            self.assertEqual(miss, 0, touch)
            if touch:
                self.assertTrue(under)

    def test_plugin_tiles_slot_comes_before_the_search_in_markup_and_tab_order(self):
        # the sidebar.tiles place (1.30): tiles above the search row. A plugin put them in sidebar.top and raised the CSS
        # order; Safari and Firefox move Tab by markup, so focus went to the search before the tiles that are visible above it
        from unittest import mock
        aside = ("(() => { const a = document.querySelector('aside'), r = document.querySelector('.search-row'), "
                 "t = document.getElementById('slot-sidebar-tiles'); "
                 "return [!!t, t && t.offsetHeight, Math.round(r.getBoundingClientRect().top - a.getBoundingClientRect().top)]; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"until": "!!document.querySelector('#conn .dot')", "ms": 8000},
                        {"eval": aside})
        self.assertEqual(got[-1]["eval"], [True, 0, 0])   # without a plugin the place is empty and has no margins: the search row is where it was
        path = os.path.join(self.state, "plug-tiles")
        os.makedirs(path)
        with open(os.path.join(path, "hub-plugin.json"), "w") as f:
            json.dump({"name": "tiles", "description": "tiles", "why": "w", "web": "main.js", "hub": "^1.30"}, f)
        with open(os.path.join(path, "main.js"), "w") as f:
            f.write("export default function register(hub) {\n"
                    "  const b = document.createElement('button'); b.type = 'button'; b.textContent = 'Tile'; b.id = 'probe-tile';\n"
                    "  hub.addSlot('sidebar.tiles', { id: 't', render(root) { if (!root.firstChild) root.append(b); } });\n"
                    "  window.__ready = true;\n}\n")
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"extensions": {"tiles": {"path": path, "web": "main.js"}}}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        # focus to the start of the panel, then a real Tab: the tile gets focus first, the second one is not it
        start = ("(() => { const a = document.querySelector('aside'); a.tabIndex = -1; a.focus(); "   # -1: focused but not in the Tab chain
                 "return document.activeElement === a; })()")
        order = ("(() => { const b = document.getElementById('probe-tile'), f = document.getElementById('filter'); "
                 "return !!(b.compareDocumentPosition(f) & Node.DOCUMENT_POSITION_FOLLOWING) "
                 "&& b.closest('#slot-sidebar-tiles') !== null; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/"}, {"errors": 1500},
                        {"until": "window.__ready === true && !!document.getElementById('probe-tile')", "ms": 8000},
                        {"eval": order}, {"eval": start}, {"key": "Tab"},
                        {"eval": "document.activeElement?.id || document.activeElement?.tagName"},
                        {"key": "Tab"}, {"eval": "document.activeElement?.id || document.activeElement?.tagName"})
        self.assertTrue(got[-6]["eval"])                    # the button is earlier in the markup than the search field
        self.assertTrue(got[-5]["eval"])
        self.assertEqual(got[-3]["eval"], "probe-tile")     # the first Tab goes to the tile
        self.assertEqual(got[-1]["eval"], "filter")         # the next one goes to search

    def test_plugin_reads_the_message_of_a_feed_row_and_reacts_by_it(self):
        # 1.36: hub.messageAt(node) — a plugin's own actions on a feed message (a menu on the right click) need to know
        # which message a row shows: the session, whether it is the owner's own, the text as written and the target that
        # POST /api/react takes. The target is the one the feed's own reactions use, so a reaction from a plugin lands
        said = self.reacted_turn()
        self.message_at_plugin()
        self.reactions_module(True)
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"errors": 1500},
                        {"until": "window.__ready === true && !!document.querySelector('.feed .row.out')", "ms": 8000},
                        {"eval": "window.__at('Report ready')"}, {"eval": "window.__at('make a report')"},
                        {"eval": "window.__outside"}, {"eval": "window.__react('Report ready', '👍')"}, {"sleep": 500})
        self.assertTrue(got[2]["until"], got)
        self.assertEqual(got[3]["eval"], {"session": "a", "kind": "out", "mine": False, "target": str(said["seq"]),
                                          "text": "Report ready."})
        self.assertEqual(got[4]["eval"], {"session": "a", "kind": "in", "mine": True, "target": self.asked,
                                          "text": "make a report"})
        self.assertEqual(got[5]["eval"], [None, None, 1])   # not a feed row — null; the page says it can
        (ev,) = [e for e in self.spooled() if e["type"] == "message.reacted"]
        self.assertEqual((ev["data"]["target"], ev["data"]["emoji"], ev["data"]["session"]), (str(said["seq"]), "👍", "a"))

    def test_plugin_message_of_a_feed_row_has_no_target_while_reactions_are_off(self):
        # the feed draws no reaction on a row while the module is off, so the target (what POST /api/react takes) is null
        # there too — a plugin menu built on `if (!m.target) return` does not offer a reaction the core would refuse
        self.reacted_turn()
        self.message_at_plugin()
        self.reactions_module(False)
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"errors": 1500},
                        {"until": "window.__ready === true && !!document.querySelector('.feed .row.out')", "ms": 8000},
                        {"eval": "window.__at('Report ready')"}, {"eval": "window.__at('make a report')"})
        self.assertTrue(got[2]["until"], got)
        self.assertEqual([(m["kind"], m["target"], m["text"]) for m in (got[3]["eval"], got[4]["eval"])],
                         [("out", None, "Report ready."), ("in", None, "make a report")])

    def message_at_plugin(self):
        """A test plugin on hub.messageAt: window.__at(text) is the message of the feed row that holds the text,
        window.__react(text, emoji) sets a reaction by its target."""
        from unittest import mock
        path = os.path.join(self.state, "plug-message-at")
        os.makedirs(path)
        with open(os.path.join(path, "hub-plugin.json"), "w") as f:
            json.dump({"name": "msgat", "description": "probe", "why": "w", "web": "main.js", "hub": "^1.36"}, f)
        with open(os.path.join(path, "main.js"), "w") as f:
            f.write("export default function register(hub) {\n"
                    "  const row = (t) => [...document.querySelectorAll('.feed .row')].find((r) => r.textContent.includes(t));\n"
                    "  window.__at = (t) => { const r = row(t); return r ? hub.messageAt(r.querySelector('.b') || r) : 'no row'; };\n"
                    "  window.__react = (t, emoji) => { const m = window.__at(t);\n"
                    "    hub.post('/api/react', { session: m.session, target: m.target, emoji, quote: m.text }); return m.target; };\n"
                    "  window.__outside = [hub.messageAt(document.body), hub.messageAt(null), hub.capabilities.messageAt];\n"
                    "  window.__ready = true;\n}\n")
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"extensions": {"msgat": {"path": path, "web": "main.js"}}}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)

    def test_plugin_header_start_slot_comes_before_the_session_name_in_markup_and_tab_order(self):
        # the session.header.start place (1.35): a plugin's node before the session name. In session.header it lands at
        # the end of the header and a plugin raising the CSS order sees it before the name, while Tab in Safari and
        # Firefox follows the markup and reaches it after the header's buttons
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        bare = ("(() => { const h = document.querySelector('main .head'); "
                "return [!!h.querySelector('.slot-session-header-start'), h.querySelector('h2')?.previousElementSibling?.className || ''] })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"until": "!!document.querySelector('main .head h2')", "ms": 8000},
                        {"eval": bare})
        self.assertTrue(got[-2]["until"], got)
        self.assertEqual(got[-1]["eval"], [False, "btn quiet back"])   # without a plugin the header is as before
        path = os.path.join(self.state, "plug-head-start")
        os.makedirs(path)
        with open(os.path.join(path, "hub-plugin.json"), "w") as f:
            json.dump({"name": "headstart", "description": "label", "why": "w", "web": "main.js", "hub": "^1.35"}, f)
        with open(os.path.join(path, "main.js"), "w") as f:
            f.write("export default function register(hub) {\n"
                    "  hub.addSlot('session.header.start', { id: 'm', render(root, snap, ctx) {\n"
                    "    if (!root.firstChild) { const b = document.createElement('button'); b.type = 'button'; b.id = 'probe-head';\n"
                    "      b.textContent = 'Label'; root.append(b); }\n"
                    "    root.firstChild.dataset.session = ctx.session.name; } });\n"
                    "  window.__ready = true;\n}\n")
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"extensions": {"headstart": {"path": path, "web": "main.js"}}}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        order = ("(() => { const b = document.getElementById('probe-head'), h = b.closest('main .head'), "
                 "back = h.querySelector('.btn.back'), name = h.querySelector('h2'); "
                 "const before = (x, y) => !!(x.compareDocumentPosition(y) & Node.DOCUMENT_POSITION_FOLLOWING); "
                 "return [before(back, b), before(b, name), b.dataset.session]; })()")
        start = ("(() => { const h = document.querySelector('main .head'); h.tabIndex = -1; h.focus(); "   # -1: focused, not in the Tab chain
                 "return document.activeElement === h; })()")
        # the root's class has every dot of the place name as a dash (a theme finds it by the class); a root the plugin left
        # empty for this session takes no gap before the name
        empty = ("(() => { const r = document.getElementById('probe-head').parentElement, cls = r.className; "
                 "r.replaceChildren(); return [cls, getComputedStyle(r).display]; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"errors": 1500},
                        {"until": "window.__ready === true && !!document.getElementById('probe-head')", "ms": 8000},
                        {"eval": order}, {"eval": start}, {"key": "Tab"},
                        {"eval": "document.activeElement?.id || document.activeElement?.tagName"}, {"eval": empty})
        self.assertEqual(got[1]["errors"], [])               # the plugin in the header draws without page errors
        self.assertTrue(got[-6]["until"], got)
        self.assertEqual(got[-5]["eval"], [True, True, "a"])   # after "back", before the name; ctx.session is the open session
        self.assertTrue(got[-4]["eval"])
        self.assertEqual(got[-2]["eval"], "probe-head")         # the first Tab in the header goes to the plugin's node
        self.assertEqual(got[-1]["eval"], ["slot slot-session-header-start", "none"])

    def test_flow_tip_of_a_dot_with_no_messages_shows_no_zero_counts(self):
        # "sent 0 · received 0" under a name says nothing: the counts line is there only when there is a number
        self.big_flow_hub(active=3, idle=5, executors=0)
        R = "window.__flowRec"
        hover = ("(() => { const n = %s.at('idle0'); const c = document.querySelector('.flow canvas'); const r = c.getBoundingClientRect(); "
                 "c.dispatchEvent(new MouseEvent('mousemove', {clientX: r.left + n.x, clientY: r.top + n.y, bubbles: true})); "
                 "return [...document.querySelectorAll('.flow-tip > *')].map((x) => x.textContent); })()") % R
        got = self.flow_open({"eval": f"({R}.mode('h1'), 1)"}, {"sleep": 800}, {"eval": f"({R}.step(16), 1)"}, {"eval": hover})
        tip = got[-1]["eval"]
        self.assertEqual(tip[0], "idle0")
        self.assertFalse([t for t in tip[1:] if "0" in t], tip)

    def test_flow_is_driven_through_window_hubflow_and_reports_hubflow_state(self):
        # "Flow" is embedded by others (a plugin, an app): commands are window.hubFlow, state is the hubflow:state event on
        # window. Review: a window load failure does not hold "loading" forever; on a window change the state does not keep
        # the old one's bounds; the slider does not jerk under the finger; a new retry does not report a false pause. Point
        # labels come from --flow-label / --flow-label-size (a theme or the embedder changes them with style)
        self.big_flow_hub(active=4, idle=40, executors=5)
        R = "window.__flowRec"
        F = "window.hubFlow"
        hover = ("(() => { const n = %s.at('%%s'); const c = document.querySelector('.flow canvas'); const r = c.getBoundingClientRect(); "
                 "c.dispatchEvent(new MouseEvent('mousemove', {clientX: r.left + n.x, clientY: r.top + n.y, bubbles: true})); "
                 "return %s.tip(); })()") % (R, R)
        leave = f"(document.querySelector('.flow canvas').dispatchEvent(new MouseEvent('mouseleave')), {R}.step(16), 1)"
        look = f"(() => {{ const l = {R}.labels().find((b) => b.id === 'lead'); return [l.font.match(/\\d+px/)[0], l.color]; }})()"
        listen = ("(window.__st = [], addEventListener('hubflow:state', (e) => window.__st.push(JSON.parse(JSON.stringify(e.detail)))), "
                  "window.__fetch = window.fetch, 1)")
        broken = ("(window.fetch = (u, o) => String(u).includes('/api/flow/history') ? Promise.reject(new TypeError('offline')) "
                  f": window.__fetch(u, o), {F}.setMode('h1'), 1)")
        got = self.flow_open(
            {"eval": listen}, {"eval": f"{F}.state()"},                                                       # 5, 6
            {"eval": broken}, {"until": f"!{F}.state().loading"},                                              # 7, 8
            {"eval": f"(() => {{ const s = {F}.state(); return [s.mode, s.loading, s.failed, s.replay, "
                     "document.querySelector('.flow-clock').textContent]; })()"},                              # 9
            {"eval": f"(window.fetch = window.__fetch, {F}.setMode('h6'), 1)"}, {"until": f"{F}.state().replay"},
            {"eval": f"(window.__st = [], {F}.setMode('h1'), 1)"},                                             # 12
            {"until": f"{F}.state().replay && {F}.state().to - {F}.state().from === 3600"},                    # 13
            {"eval": "window.__st.map((s) => [s.mode, s.loading, s.paused, s.replay, s.from === null ? null : s.to - s.from])"},
            {"eval": f"(() => {{ {F}.setSpeed(2); {F}.setSpeed(3); {F}.togglePause(); const s = {F}.state(), e = window.__st.at(-1); "
                     "return [s.speed, s.paused, e.speed, e.paused, s.speeds]; })()"},                         # 15
            {"eval": f"(() => {{ {F}.togglePause(); {F}.seek(0.3, true); {R}.step(3000); const a = {F}.state().pos; "
                     f"{F}.seek(0.3); {R}.step(3000); return [Math.round(a * 100), Math.round({F}.state().pos * 100)]; }})()"},
            {"eval": f"(() => {{ const r = document.querySelector('.flow-seek'); r.value = '500'; r.dispatchEvent(new Event('input')); "
                     f"{R}.step(3000); const held = [r.value, Math.round({F}.state().pos * 100)]; r.dispatchEvent(new Event('change')); "
                     f"{R}.step(3000); return [...held, Math.round({F}.state().pos * 100)]; }})()"},           # 17
            {"eval": leave}, {"eval": look},                                                                   # 18, 19
            {"eval": "(document.documentElement.style.setProperty('--flow-label-size', '15px'), "
                     "document.documentElement.style.setProperty('--flow-label', 'rgb(1, 2, 3)'), "
                     f"window.dispatchEvent(new Event('hub-theme')), {R}.step(16), 1)"},
            {"eval": look},                                                                                    # 21
            {"eval": hover % "lead"},
            {"eval": "document.querySelector('.flow-tip .flow-tip-counts')?.textContent || ''"},             # 23
            {"eval": f"({F}.setLang('en'), 1)"}, {"until": f"({hover % 'hub'})[0] === 'Hub'"})
        st = got[6]["eval"]
        self.assertEqual([st["mode"], st["loading"], st["failed"], st["replay"], st["speeds"], st["active"]],
                         ["live", False, False, False, [0.25, 0.5, 1, 2, 4], True])
        self.assertEqual(got[9]["eval"], ["h1", False, True, False, "couldn't load the log"])   # does not hang in "loading"
        seen = got[14]["eval"]
        self.assertEqual(seen[0][:4], ["h1", True, False, False])        # immediately: the new window is loading, no retry yet
        self.assertTrue(all(x[4] in (None, 3600) for x in seen if x[0] == "h1"), seen)   # the old 6 h bounds are gone
        self.assertFalse(any(x[2] for x in seen), seen)                   # no false pause
        self.assertEqual(seen[-1][1:], [False, False, True, 3600])
        self.assertEqual(got[15]["eval"], [2, True, 2, True, [0.25, 0.5, 1, 2, 4]])   # no x3: the speed stayed x2
        self.assertEqual(got[16]["eval"], [30, 40])        # while dragged, it stands; when released, it runs (x2: 3 s is 10%)
        self.assertEqual(got[17]["eval"], ["500", 50, 60])  # the page slider under the finger does not move the frame
        self.assertEqual(got[19]["eval"][0], "13px")       # the default: no small type on the canvas
        self.assertEqual(got[21]["eval"], ["15px", "#010203"])
        self.assertTrue(got[23]["eval"].startswith("sent") or not got[23]["eval"], got[23]["eval"])   # no counts — no line
        self.assertTrue(got[25]["until"])                   # canvas labels are in the named language

    def test_flow_hubflow_retry_after_failed_load_slider_reset_and_commands_only_while_shown(self):
        # PR #296 review: after a load failure the period choice is reset (otherwise the same period gives no change, so no
        # retry); on a window change the slider goes to the start; while "Flow" is not on screen, window.hubFlow commands do
        # nothing
        self.big_flow_hub(active=4, idle=40, executors=5)
        F = "window.hubFlow"
        sel = "document.querySelector('.flow select')"
        broken = ("(window.__fetch = window.fetch, window.fetch = (u, o) => String(u).includes('/api/flow/history') "
                  f"? Promise.reject(new TypeError('offline')) : window.__fetch(u, o), {F}.setMode('h1'), 1)")
        got = self.flow_open(
            {"eval": broken}, {"until": f"!{F}.state().loading"},                                              # 5, 6
            {"eval": f"[{sel}.selectedIndex, {sel}.value, {F}.state().failed]"},                               # 7
            {"eval": f"(window.fetch = window.__fetch, {F}.setMode('h6'), 1)"}, {"until": f"{F}.state().replay"},
            {"eval": f"({F}.seek(0.7), document.querySelector('.flow-seek').value)"},                          # 10
            {"eval": f"({F}.setMode('h1'), [document.querySelector('.flow-seek').value, {F}.state().replay])"},  # 11
            {"until": f"{F}.state().replay"},
            {"hash": "#/s/lead"}, {"until": f"!{F}.state().active"},
            {"eval": "(window.__hist = 0, window.__f2 = window.fetch, window.fetch = (u, o) => (String(u).includes('/api/flow/history') "
                     "&& window.__hist++, window.__f2(u, o)), 1)"},
            {"eval": f"({F}.setMode('h24'), {F}.setSpeed(4), {F}.togglePause(), {F}.seek(0.5), 1)"}, {"sleep": 500},   # 15, 16
            {"eval": f"(() => {{ const s = {F}.state(); return [s.active, s.mode, s.loading, s.speed, s.paused, window.__hist]; }})()"})
        self.assertEqual(got[7]["eval"], [-1, "", True])
        self.assertEqual(got[11]["eval"], ["0", False])                 # the new window is loading: the slider is at the start
        self.assertEqual(got[-1]["eval"], [False, "live", False, 1, False, 0])   # left "Flow": commands do not act, the journal is not loaded

    def test_updates_screen_gets_the_notes_from_about_not_from_the_snapshot(self):
        # stream-lean: the first frame has no notes of past updates; the "Updates" screen takes them from /api/about
        self.seed()
        self.ev("update.applied", None, **{"from": "a", "to": "b"}, notes=["Update note"], channel="cli", owner=True)
        self.settle()
        snap = json.loads(self.req("GET", "/api/snapshot")[1])
        self.assertTrue(snap["updates"] and "notes" not in snap["updates"][-1])
        # a past update is one line; its notes are inside it (textContent: a closed line's notes are not in innerText)
        self.page({"go": f"http://127.0.0.1:{self.port}/#/updates"},
                  {"until": "document.querySelector('main').textContent.includes('Update note')", "ms": 8000})
        # an update that lands while the screen is open shows with its notes at once, not after the half-minute refresh
        self.ev("update.applied", None, **{"from": "b", "to": "c"}, notes=["Second note"], channel="cli", owner=True)
        self.settle()
        got = self.page({"until": "document.querySelector('main').textContent.includes('Second note')", "ms": 8000})
        self.assertTrue(got[-1]["until"], got)

