    def test_updates_screen_is_short_releases_open_on_a_press(self):
        # the screen was paragraphs: how updates work, every note in full, ISO dates, "version v1 · <commit>". Now: the
        # version alone, the check with its button, a release is a line with a friendly date (the newest one open), a
        # note is shown whole; a past update is a line too
        self.seed()
        code = self.web.code
        self.web.code = lambda: {**code(), "upstream": True}   # also in a clone with no origin remote
        self.ev("update.applied", None, **{"from": "a", "to": "b"}, channel="cli", owner=True,
                notes=["2020-03-05", "Page: a note with `code` in it. The second sentence of the note. Needs `hub restart`."])
        self.settle()
        note = "[...document.querySelectorAll('.upd li')].find((d) => d.textContent.startsWith('Page: a note'))"
        got = self.page(
            {"go": f"http://127.0.0.1:{self.port}/#/updates"},
            {"until": "document.querySelector('main').textContent.includes('Page: a note')", "ms": 8000},
            {"eval": "[document.querySelector('.head .pill').textContent]"},
            {"eval": "[...document.querySelectorAll('.feed-inner > .hint')].map((p) => p.textContent)"},
            {"eval": "[...document.querySelectorAll('.upd-check button')].map((b) => b.textContent)"},
            {"eval": "[...document.querySelectorAll('details.upd')].map((d) => d.open)"},
            {"eval": "[...document.querySelectorAll('.upd-head, .upd-date')].map((d) => d.textContent)"
                     ".filter((x) => /\\d{4}-\\d{2}-\\d{2}/.test(x))"},
            {"eval": "[...document.querySelectorAll('.upd-date')].map((d) => d.textContent)"},
            {"eval": f"(() => {{ const d = {note}; d.closest('details.upd').querySelector('summary').click(); "
                     "return [d.textContent, d.querySelector('code').textContent]; })()"},
            {"eval": "window.dispatchEvent(new Event('hub-about'))"}, {"sleep": 400},   # a redraw keeps what was opened
            {"eval": f"{note}.closest('details.upd').open"})
        ev = [g["eval"] for g in got if "eval" in g]
        self.assertNotIn("·", ev[0][0])                   # the version, no commit beside it
        self.assertNotIn("version", ev[0][0])
        self.assertEqual(ev[1], [])                       # no paragraph about how updates work
        self.assertIn("Check for updates", ev[2])
        self.assertEqual(ev[3][-1], False)                # a past update is closed
        self.assertEqual([x for x in ev[3][:-1] if x], ev[3][:1])   # of the releases only the newest is open
        self.assertEqual(ev[4], [])                       # no ISO dates
        self.assertIn("2020", ev[5][0])                   # another year's date carries the year
        self.assertIn("March", ev[5][0])
        self.assertEqual(ev[6], ["Page: a note with code in it. The second sentence of the note. Needs hub restart.", "code"])
        self.assertEqual(ev[-1], True)

    def test_updates_screen_a_failure_the_hub_has_got_past_does_not_stand_out(self):
        # the last record of the history was a failure of days ago, in the warning colour and open, though the hub had
        # caught up since (the check after it said "latest version"): only a failure that still holds stands out
        self.seed()
        self.ev("update.failed", None, why="conflict", **{"from": "a", "to": "b"}, channel="cli", owner=True, notes=["The failure."])
        self.settle()
        probe = """(() => { const b = [...document.querySelectorAll('details.upd')].find((x) => x.querySelector('.upd-state'));
          const w = b.querySelector('.why'), hint = document.createElement('p'); hint.className = 'hint'; b.append(hint);
          const r = { open: b.open, now: w.classList.contains('now'), same: getComputedStyle(w).color === getComputedStyle(hint).color,
            state: b.querySelector('.upd-state').getAttribute('data-state') }; hint.remove(); return r; })()"""
        go = ({"go": "about:blank", "look": None}, {"go": f"http://127.0.0.1:{self.port}/#/updates", "look": None},
              {"until": "!!document.querySelector('details.upd .upd-state')", "ms": 8000}, {"sleep": 300}, {"eval": probe})
        self.assertEqual(self.page(*go)[-1]["eval"], {"open": True, "now": True, "same": False, "state": "fail"})
        self.ev("update.checked", None, result="current", behind=0)
        self.settle()
        self.assertEqual(self.page(*go)[-1]["eval"], {"open": False, "now": False, "same": True, "state": "fail"})

