    def test_updates_screen_keeps_the_restart_heading_when_the_check_line_no_longer_says_it(self):
        # after a background update the next scheduled check says "latest version" (HEAD is already the target) while
        # the hub still runs the old code: the check line does not say the restart, so the heading has to
        self.seed()
        code = self.web.code
        self.web.code = lambda: {**code(), "upstream": True, "head": "b" * 40, "running": "a" * 40}
        self.ev("update.checked", None, result="applied", behind=0, ask_restart=True)
        self.ev("update.checked", None, result="current", behind=0)
        self.settle()
        got = self.page({"go": "about:blank", "look": None}, {"go": f"http://127.0.0.1:{self.port}/#/updates", "look": None},
                        {"until": "!!document.querySelector('.upd-check .hint')", "ms": 8000}, {"sleep": 300},
                        {"eval": "[document.querySelector('.upd-check .hint').textContent.includes('restart'), "
                                 "[...document.querySelectorAll('.upd-list > h3.day')].map((h) => h.textContent)]"})
        self.assertEqual(got[-1]["eval"], [False, ["A new version is available — waiting for a hub restart"]])

    CHECK_ANSWERS = ("(() => {{ const f = window.fetch; window.fetch = (u, o) => String(u).includes('/api/update/check')"
                     " ? Promise.resolve(new Response(JSON.stringify({body}), {{status: {status},"
                     " headers: {{'Content-Type': 'application/json'}}}})) : f(u, o); return 1; }})()")
    PRESS_CHECK = ("(() => { const b = [...document.querySelectorAll('.upd-check button')]"
                   ".find((x) => x.textContent === 'Check for updates'); b.click(); return 1; })()")

    def test_updates_screen_a_past_update_with_nothing_inside_is_a_plain_line(self):
        # every past update was a fold with a sign, also one with no notes and no reason: a press opened an empty row
        self.seed()
