    def test_dictate_space_outside_the_field_records_a_session_voice_message(self):
        # review #293, item 1: a dictation field stayed current forever, Space outside fields recorded into the last dictation
        # field; Space starts dictation only while the caret is in that field, otherwise it is the session's voice message
        self.dictate_page("")
        out = ("(() => { const i = document.createElement('input'); i.id = 'dz-out'; document.body.append(i); "
               "const b = window.__hub.dictate(i, {}); b.id = 'dz-out-mic'; document.body.append(b); return 1; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"errors": 1500},
                        {"until": "!!window.__hub && !!document.querySelector('form.composer .btn.round.mic')", "ms": 8000},
                        {"eval": self.DICTATE_STUB}, {"eval": out},
                        {"until": "!document.querySelector('#dz-out-mic').hidden", "ms": 4000},
                        # dictation by the button in a field outside the feed inserted the text
                        {"eval": "(document.querySelector('#dz-out').focus(), 1)"}, {"eval": self.dz_click("#dz-out-mic")},
                        {"until": self.dz_rec("#dz-out-mic"), "ms": 4000}, {"eval": self.dz_click("#dz-out-mic")},
                        {"until": "document.querySelector('#dz-out').value === 'good world'", "ms": 5000},
                        # the field is cleared and the caret left the fields: holding Space is the session's voice message, not dictation
                        {"eval": "(() => { const i = document.querySelector('#dz-out'); i.value = ''; i.blur(); "
                                 "return document.activeElement === document.body; })()"},
                        {"eval": self.dz_space("keydown")},
                        {"until": "!!document.querySelector('form.composer.rec') || " + self.dz_rec("#dz-out-mic"), "ms": 4000},
                        {"eval": f"[!!document.querySelector('form.composer.rec'), {self.dz_rec('#dz-out-mic')}]"},
                        {"eval": self.dz_space("keyup")},
                        {"until": "JSON.stringify(window.__posts).includes('/api/send')", "ms": 5000}, {"sleep": 300},
                        {"eval": "document.querySelector('#dz-out').value"})
        self.assertEqual(got[10]["until"], True)
        self.assertEqual(got[11]["eval"], True)
        self.assertEqual(got[14]["eval"], [True, False])        # the recording is the session's voice message
        self.assertEqual(got[18]["eval"], "")                    # nothing in the dictation field
        self.assertEqual([d["text"] for d in self.sent()], [f"🎤 {i18n.t('web.voice.head')}: good world"])

    def test_dictate_throwing_on_error_does_not_break_the_next_recording(self):
        # review #293, item 2: onText/onError run in try like other Plugin API callbacks: a throw in onError (microphone refused)
        # left the press held, and the next recording did not start
        self.dictate_page("['dz-a', { onError: (t) => { window.__errs.push(t); throw new Error('boom'); } }]")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/x/dz"}, {"errors": 1500},
                        {"until": "!!document.querySelector('#dz-a-mic') && !document.querySelector('#dz-a-mic').hidden", "ms": 8000},
                        {"eval": self.DICTATE_STUB}, {"eval": "(window.__deny = 1, document.querySelector('#dz-a').focus(), 1)"},
                        {"eval": self.dz_click("#dz-a-mic")}, {"until": "window.__errs.length === 1", "ms": 4000},
                        {"eval": self.dz_click("#dz-a-mic")}, {"until": self.dz_rec("#dz-a-mic"), "ms": 4000},
                        {"eval": self.dz_click("#dz-a-mic")},
                        {"until": "document.querySelector('#dz-a').value === 'good world'", "ms": 5000},
                        {"eval": "JSON.stringify(window.__texts)"})
        self.assertEqual(got[6]["until"], True)
        self.assertEqual(got[8]["until"], True)                  # the second recording started
        self.assertEqual(got[10]["until"], True)
        self.assertEqual(json.loads(got[11]["eval"]), [["dz-a", "good world", True]])

    def test_dictate_retry_does_nothing_while_another_recording_goes(self):
        # review #293, item 3: "Retry" of an untranscribed dictation while another recording runs does nothing (recognition
        # used to take over the shared recording and insert the text in the middle of another one)
        self.dictate_page("['dz-a', { onError: (t, o) => { window.__errs.push(t); window.__retry = o.retry; } }], ['dz-b', {}]")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/x/dz"}, {"errors": 1500},
                        {"until": "!!document.querySelector('#dz-b-mic') && !document.querySelector('#dz-b-mic').hidden", "ms": 8000},
                        {"eval": self.DICTATE_STUB},
                        {"eval": "(window.__voice.push({status: 500, body: {error: 'not understood'}}), document.querySelector('#dz-a').focus(), 1)"},
                        {"eval": self.dz_click("#dz-a-mic")}, {"until": self.dz_rec("#dz-a-mic"), "ms": 4000},
                        {"eval": self.dz_click("#dz-a-mic")}, {"until": "!!window.__retry", "ms": 5000},
                        # record into another field and press "Retry" on the first
                        {"eval": "(document.querySelector('#dz-b').focus(), 1)"}, {"eval": self.dz_click("#dz-b-mic")},
                        {"until": self.dz_rec("#dz-b-mic"), "ms": 4000},
                        {"eval": "(window.__retry(), 1)"}, {"sleep": 500},
                        {"eval": f"[window.__posts.filter((u) => u === '/api/voice').length, document.querySelector('#dz-a').value, "
                                 f"{self.dz_rec('#dz-b-mic')}]"},
                        {"eval": self.dz_click("#dz-b-mic")},
                        {"until": "document.querySelector('#dz-b').value === 'good world'", "ms": 5000}, {"sleep": 300},
                        {"eval": "[window.__posts.filter((u) => u === '/api/voice').length, document.querySelector('#dz-a').value]"},
                        # no other recording: "Retry" transcribes
                        {"eval": "(window.__retry(), 1)"},
                        {"until": "document.querySelector('#dz-a').value === 'good world'", "ms": 5000})
        self.assertEqual(got[8]["until"], True)
        self.assertEqual(got[11]["until"], True)
        self.assertEqual(got[14]["eval"], [1, "", True])          # "Retry" did nothing, the recording goes on
        self.assertEqual(got[16]["until"], True)
        self.assertEqual(got[18]["eval"], [2, ""])
        self.assertEqual(got[20]["until"], True)

    def test_dictate_text_reaches_the_plugin_when_the_field_was_rebuilt(self):
        # review #293, item 4: the field was rebuilt during recognition: hand the text to the plugin in onText (inserted: false)
        # instead of losing it
        self.dictate_page("['dz-a', {}]")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/x/dz"}, {"errors": 1500},
                        {"until": "!!document.querySelector('#dz-a-mic') && !document.querySelector('#dz-a-mic').hidden", "ms": 8000},
                        {"eval": self.DICTATE_STUB},
                        {"eval": "(window.__hold = new Promise((ok) => { window.__release = ok; }), document.querySelector('#dz-a').focus(), 1)"},
                        {"eval": self.dz_click("#dz-a-mic")}, {"until": self.dz_rec("#dz-a-mic"), "ms": 4000},
                        {"eval": self.dz_click("#dz-a-mic")},
                        {"until": "window.__posts.includes('/api/voice')", "ms": 4000},
                        {"eval": "(document.querySelector('#dz-a').remove(), window.__release(), 1)"},
                        {"until": "window.__texts.length > 0", "ms": 5000},
                        {"eval": "JSON.stringify(window.__texts)"})
        self.assertEqual(got[8]["until"], True)
        self.assertEqual(got[10]["until"], True)
        self.assertEqual(json.loads(got[11]["eval"]), [["dz-a", "good world", False]])

    def test_dictate_into_a_hidden_field_does_not_type_into_the_focused_one(self):
        # review of the #293 merge: the text went in by execCommand, which writes into whatever has the focus; a field hidden
        # during recognition does not take the focus, and the dictation landed in the session's message field
        self.dictate_page("")
        out = ("(() => { const i = document.createElement('input'); i.id = 'dz-out'; document.body.append(i); "
               "const b = window.__hub.dictate(i, {}); b.id = 'dz-out-mic'; document.body.append(b); return 1; })()")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"errors": 1500},
                        {"until": "!!window.__hub && !!document.querySelector('#msg')", "ms": 8000},
                        {"eval": self.DICTATE_STUB}, {"eval": out},
                        {"until": "!document.querySelector('#dz-out-mic').hidden", "ms": 4000},
                        {"eval": "(window.__hold = new Promise((ok) => { window.__release = ok; }), document.querySelector('#dz-out').focus(), 1)"},
                        {"eval": self.dz_click("#dz-out-mic")}, {"until": self.dz_rec("#dz-out-mic"), "ms": 4000},
                        {"eval": self.dz_click("#dz-out-mic")}, {"until": "window.__posts.includes('/api/voice')", "ms": 4000},
                        {"eval": "(document.querySelector('#dz-out').style.display = 'none', document.querySelector('#msg').focus(), "
                                 "window.__release(), 1)"},
                        {"until": "!!document.querySelector('#dz-out').value", "ms": 5000}, {"sleep": 300},
                        {"eval": "[document.querySelector('#dz-out').value, document.querySelector('#msg').value]"})
        self.assertTrue(all(g["until"] for g in got if "until" in g), got)
        self.assertEqual(got[-1]["eval"], ["good world", ""])

    def test_dictate_no_speech_does_not_offer_an_earlier_recording(self):
        # merging #293: "no speech" (422) after an earlier failed transcription offered "Retry" of that earlier recording
        # under the message about the new one; the button's tooltip promised Space where it is off (space: false)
        self.dictate_page("['dz-a', { onError: (t, o) => window.__errs.push([t, !!o.retry, !!o.download]) }], ['dz-b', { space: false }]")
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/x/dz"}, {"errors": 1500},
                        {"until": "!!document.querySelector('#dz-b-mic') && !document.querySelector('#dz-b-mic').hidden", "ms": 8000},
                        {"eval": self.DICTATE_STUB},
                        {"eval": "(window.__voice.push({status: 502, body: {error: 'failure'}}, {status: 422, body: {error: 'no speech'}}), "
                                 "document.querySelector('#dz-a').focus(), 1)"},
                        {"eval": self.dz_click("#dz-a-mic")}, {"until": self.dz_rec("#dz-a-mic"), "ms": 4000},
                        {"eval": self.dz_click("#dz-a-mic")}, {"until": "window.__errs.length === 1", "ms": 5000},
                        {"eval": self.dz_click("#dz-a-mic")}, {"until": self.dz_rec("#dz-a-mic"), "ms": 4000},
                        {"eval": self.dz_click("#dz-a-mic")}, {"until": "window.__errs.length === 2", "ms": 5000},
                        {"eval": "[JSON.stringify(window.__errs), document.querySelector('#dz-b-mic').title]"})
        self.assertTrue(all(g["until"] for g in got if "until" in g), got)
        errs, title = got[-1]["eval"]
        self.assertEqual(json.loads(errs), [["failure", True, True], ["no speech", False, False]])
        self.assertNotIn("Space", title)
        self.assertIn("Dictate", title)

    def test_page_fields_have_a_dictation_mic(self):
        # "voice wherever there is input", owner decision 2026-10-26 (review #294): the hub.dictate microphone only in a
        # card's "own answer" and in the feed search; the dictated text goes into the field and nothing is sent (the own
        # answer stays in the field until "Reply"); in the search Space does not start recording, only the button does
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": "Which format?", "options": [{"label": "PDF"}, {"label": "Table"}]}]})
        env = mock.patch.dict(os.environ, {"VOICE_CMD": "true"})
        env.start()
        self.addCleanup(env.stop)
        other, mic, fs, fsmic = (".ask-card textarea.other", ".ask-card .other-row .dictate.mini", ".fs-row input",
                                 ".fs-row .dictate.mini")
        has = lambda sel: f"(() => {{ const b = document.querySelector('{sel}'); return !!b && !b.hidden; }})()"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"errors": 1500},
                        {"until": has(mic), "ms": 9000}, {"eval": self.DICTATE_STUB},
                        # the session search has no microphone
                        {"eval": "[document.querySelectorAll('.search .dictate').length, "
                                 "[...document.querySelectorAll('.dictate')].filter((b) => b.getClientRects().length).length]"},
                        # the card's own answer: a click records, another click puts the text into the field, no answer is sent
                        {"eval": f"(document.querySelector('{other}').focus(), 1)"}, {"eval": self.dz_click(mic)},
                        {"until": self.dz_rec(mic), "ms": 4000}, {"eval": self.dz_click(mic)},
                        {"until": f"document.querySelector('{other}').value === 'good world'", "ms": 5000}, {"sleep": 300},
                        {"eval": f"[!!document.querySelector('.ask-card'), document.activeElement === document.querySelector('{other}')]"},
                        # the feed search has a microphone; Space in the empty field does not record
                        {"eval": "(document.querySelector('.fs-lupa').click(), 1)"}, {"until": has(fsmic), "ms": 4000},
                        {"eval": f"(document.querySelector('{fs}').focus(), 1)"}, {"eval": self.dz_space("keydown")},
                        {"sleep": 700},
                        {"eval": f"[{self.dz_rec(fsmic)}, !!document.querySelector('form.composer.rec'), "
                                 "document.activeElement === document.querySelector('.fs-row input')]"},
                        {"eval": self.dz_space("keyup")},
                        # by the button it writes into the search
                        {"eval": self.dz_click(fsmic)}, {"until": self.dz_rec(fsmic), "ms": 4000}, {"eval": self.dz_click(fsmic)},
                        {"until": f"document.querySelector('{fs}').value === 'good world'", "ms": 5000},
                        # on a phone the microphone is inside the field, the field is not squeezed
                        {"shot": os.path.join(self.state, "fs-phone.png"), "width": 390, "height": 844},
                        {"eval": f"(() => {{ const i = document.querySelector('{fs}').getBoundingClientRect(), "
                                 f"m = document.querySelector('{fsmic}').getBoundingClientRect(); "
                                 "return [Math.round(i.width) >= 110, m.left >= i.left && m.right <= i.right + 0.5]; })()"},
                        # and the own answer: the field, the microphone and "Reply" are inside the card, not past its edge
                        {"eval": f"(() => {{ const c = document.querySelector('.ask-card').getBoundingClientRect(); "
                                 "return [...document.querySelectorAll('.ask-card .other-row > *')].every((e) => "
                                 "e.getBoundingClientRect().right <= c.right + 0.5); })()"},
                        # other page fields (settings, plugins) have no microphone
                        {"eval": "(location.hash = '#/settings', 1)"}, {"wait": "Settings"}, {"click": "Plugins"},
                        {"until": "!!document.querySelector('.plugin-filter')", "ms": 6000},
                        {"eval": "document.querySelectorAll('.dictate').length"},
                        {"eval": "JSON.stringify(window.__posts)"})
        self.assertEqual(got[4]["eval"], [0, 1])                   # one microphone, at the own answer
        self.assertEqual(got[11]["eval"], [True, True])            # the card is open, the caret is in the own answer
        self.assertEqual(got[13]["until"], True)
        self.assertEqual(got[17]["eval"], [False, False, True])    # Space in the search does not record
        self.assertEqual(got[22]["until"], True)
        self.assertEqual(got[24]["eval"], [True, True])            # phone: the field is ≥110 px, the microphone is inside it
        self.assertTrue(got[25]["eval"])
        self.assertEqual(got[30]["eval"], 0)
        posts = json.loads(got[-1]["eval"])
        self.assertEqual(posts.count("/api/voice"), 2)
        self.assertFalse({"/api/answer", "/api/send", "/api/permission"} & set(posts))   # nothing was sent
        self.assertEqual([e["type"] for e in self.spooled() if e["type"] in ("permission.answered", "message.received")], [])

    def test_a_frozen_card_does_not_revive_its_mic(self):
        # review #294: a frozen card (the question was closed elsewhere, the typed text is kept) has no microphone, also
        # while another recording runs (a button redraw used to show it again)
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        self.ev("session.started", "a", session_id="s-a")
        self.ev("turn.started", "a", marker=None, prompt_head="x")
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": "Which option?", "options": [{"label": "A"}, {"label": "B"}]}]})
        env = mock.patch.dict(os.environ, {"VOICE_CMD": "true"})
        env.start()
        self.addCleanup(env.stop)
        mic = ".ask-card .other-row .dictate.mini"
        shown = f"(() => {{ const b = document.querySelector('{mic}'); return !!b && !b.hidden; }})()"
        self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"errors": 1500}, {"until": shown, "ms": 9000},
                  {"eval": self.DICTATE_STUB},
                  {"eval": "(() => { const t = document.querySelector('.ask-card [name=other0]'); t.value = 'my own answer'; "
                           "t.dispatchEvent(new Event('input', {bubbles: true})); return 1; })()"})
        self.ev("permission.answered", "a", request_id="r1", behavior="allow", answers={"Which option?": "A"},
                channel="telegram", owner=True)
        got = self.page({"until": "!!document.querySelector('.ask-card.frozen')", "ms": 5000}, {"eval": shown},
                        # the session's voice message is recording: the frozen card's microphone does not come back
                        {"eval": self.dz_click("form.composer .btn.round.mic")},
                        {"until": "!!document.querySelector('form.composer.rec')", "ms": 4000}, {"sleep": 800},
                        {"eval": shown},
                        {"eval": "(document.querySelector('form.composer .btn.round.stop').click(), 1)"},
                        {"until": "JSON.stringify(window.__posts).includes('/api/send')", "ms": 5000}, {"sleep": 800},
                        {"eval": shown})
        self.assertEqual(got[0]["until"], True)
        self.assertEqual(got[1]["eval"], False)
        self.assertEqual(got[3]["until"], True)
        self.assertEqual(got[5]["eval"], False)
        self.assertEqual(got[9]["eval"], False)

    def test_a_failed_dictation_into_a_page_field_keeps_the_recording(self):
        # merging #294: a failed transcription at the card's own answer or in the feed search showed only a banner and the
        # recording was gone; now the reason is under the field with "Retry" and "Download", as for the voice message
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        self.ev("permission.requested", "a", request_id="r1", tool="AskUserQuestion", interactive=True, input={
            "questions": [{"question": "Which format?", "options": [{"label": "PDF"}, {"label": "Table"}]}]})
        env = mock.patch.dict(os.environ, {"VOICE_CMD": "true"})
        env.start()
        self.addCleanup(env.stop)
        other, mic, note = ".ask-card textarea.other", ".ask-card .other-row .dictate.mini", ".ask-card .dictate-note"
        fs, fsmic, fsnote = ".fs-row input", ".fs-row .dictate.mini", ".fsearch .dictate-note"
        has = lambda sel: f"(() => {{ const b = document.querySelector('{sel}'); return !!b && !b.hidden; }})()"
        links = lambda sel: f"[...document.querySelectorAll('{sel} .linkbtn')].map((b) => b.textContent)"
        fail = "(window.__voice.push({status: 502, body: {error: 'transcription failed'}}), 1)"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"errors": 1500},
                        {"until": has(mic), "ms": 9000}, {"eval": self.DICTATE_STUB}, {"eval": fail},
                        {"eval": f"(document.querySelector('{other}').focus(), 1)"}, {"eval": self.dz_click(mic)},
                        {"until": self.dz_rec(mic), "ms": 4000}, {"eval": self.dz_click(mic)},
                        {"until": f"!!document.querySelector('{note} .linkbtn')", "ms": 5000},
                        {"shot": os.path.join(self.state, "card-fail.png"), "width": 1280, "height": 800},
                        {"eval": f"[document.querySelector('{note}').firstChild.textContent, {links(note)}, "
                                 f"document.querySelector('{other}').value]"},
                        # "Retry": the same recording is transcribed into the field, the line goes away
                        {"eval": f"(document.querySelector('{note} .linkbtn').click(), 1)"},
                        {"until": f"document.querySelector('{other}').value === 'good world'", "ms": 5000},
                        {"eval": f"document.querySelector('{note}').textContent"},
                        # the feed search: the same under the search row
                        {"eval": fail}, {"eval": "(document.querySelector('.fs-lupa').click(), 1)"}, {"until": has(fsmic), "ms": 4000},
                        {"eval": self.dz_click(fsmic)}, {"until": self.dz_rec(fsmic), "ms": 4000}, {"eval": self.dz_click(fsmic)},
                        {"until": f"!!document.querySelector('{fsnote} .linkbtn')", "ms": 5000},
                        {"eval": f"[{links(fsnote)}, document.querySelector('{fs}').value]"},
                        {"eval": "JSON.stringify(window.__posts)"})
        self.assertTrue(all(g["until"] for g in got if "until" in g), got)
        self.assertEqual(got[11]["eval"], ["transcription failed", ["Retry transcription", "Download the recording"], ""])
        self.assertEqual(got[14]["eval"], "")
        self.assertEqual(got[22]["eval"], [["Retry transcription", "Download the recording"], ""])
        posts = json.loads(got[-1]["eval"])
        self.assertEqual(posts.count("/api/voice"), 3)
        self.assertFalse({"/api/answer", "/api/send", "/api/permission"} & set(posts))   # nothing was sent

