    def test_a_failed_dictation_into_a_closed_search_is_kept_in_the_banner(self):
        # review of the #294 merge: the feed search closed while its dictation was recognized and recognition failed — the
        # reason and "Retry"/"Download" are in the banner; a click on a link does not close the banner, the reopened search
        # has no stale line, and a successful retry takes the banner away
        from unittest import mock
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        self.ev("session.started", "a", session_id="s-a")
        env = mock.patch.dict(os.environ, {"VOICE_CMD": "true"})
        env.start()
        self.addCleanup(env.stop)
        fs, fsmic = ".fs-row input", ".fs-row .dictate.mini"
        has = lambda sel: f"(() => {{ const b = document.querySelector('{sel}'); return !!b && !b.hidden; }})()"
        links = "[...document.querySelectorAll('#banner .linkbtn')].map((b) => b.textContent)"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/a"}, {"errors": 1500},
                        {"until": "!!document.querySelector('.fs-lupa')", "ms": 9000}, {"eval": self.DICTATE_STUB},
                        {"eval": "(window.__voice.push({status: 502, body: {error: 'transcription failed'}}), "
                                 "window.__hold = new Promise((ok) => { window.__release = ok; }), "
                                 "URL.createObjectURL = () => 'blob:x', 1)"},
                        {"eval": "(document.querySelector('.fs-lupa').click(), 1)"}, {"until": has(fsmic), "ms": 4000},
                        {"eval": self.dz_click(fsmic)}, {"until": self.dz_rec(fsmic), "ms": 4000}, {"eval": self.dz_click(fsmic)},
                        {"until": "window.__posts.includes('/api/voice')", "ms": 4000},
                        {"eval": "([...document.querySelectorAll('.fs-row .fs-btn')].pop().click(), 1)"},
                        {"until": "!document.querySelector('.fsearch')", "ms": 3000},
                        {"eval": "(window.__hold = null, window.__release(), 1)"},
                        {"until": "!!document.querySelector('#banner .linkbtn')", "ms": 5000},
                        {"eval": f"[document.querySelector('#banner').firstChild.textContent, {links}]"},
                        # "Download" does not close the banner
                        {"eval": "([...document.querySelectorAll('#banner .linkbtn')][1].click(), 1)"},
                        {"eval": f"[document.querySelector('#banner').classList.contains('on'), {links}.length]"},
                        # the search opens again without a stale line; "Retry" puts the text into it and the banner goes away
                        {"eval": "(document.querySelector('.fs-lupa').click(), 1)"}, {"until": has(fsmic), "ms": 4000},
                        {"eval": "document.querySelector('.fsearch .dictate-note').textContent"},
                        {"eval": "(document.querySelector('#banner .linkbtn').click(), 1)"},
                        {"until": f"document.querySelector('{fs}').value === 'good world'", "ms": 5000},
                        {"eval": "[document.querySelector('#banner').classList.contains('on'), document.querySelector('#banner').textContent]"})
        self.assertTrue(all(g["until"] for g in got if "until" in g), got)
        self.assertEqual(got[15]["eval"], ["transcription failed", ["Retry transcription", "Download the recording"]])
        self.assertEqual(got[17]["eval"], [True, 2])
        self.assertEqual(got[20]["eval"], "")
        self.assertEqual(got[-1]["eval"], [False, ""])

    def test_the_hubs_tab_is_there_without_the_bus_and_with_an_older_server(self):
        # Settings -> Hubs is always there (spec hubbus/ux §3.2): the bus off — one phrase and the two ways in, no
        # «Hubs» group in the list; the page newer than its server (the update's self-check: the old server serves the
        # new files) — the tab says so, nothing breaks
        tab = [{"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/settings",
                                       "init": "localStorage.setItem('hub.settingsTab', 'hubs')"},
               {"until": "!!document.querySelector('.bus-tab')", "ms": 10000}]
        got = self.page(*tab, {"until": "!!document.querySelector('.bus-paste')", "ms": 10000},
                        {"eval": "document.querySelector('[data-settings-tab=hubs]').getAttribute('aria-selected')"},
                        {"eval": "document.querySelector('[data-part=link] .btn.primary').textContent"},
                        {"eval": "!!document.querySelector('#list [data-sec=hubs]')"})
        self.assertTrue(got[3]["until"], got)
        self.assertEqual(got[4:], [{"eval": "true"}, {"eval": "Make an invitation"}, {"eval": False}])
        real = self.web.with_clock

        def older(snap, records=None, lang=None):
            out = real(snap, records, lang)
            return {**{k: v for k, v in out.items() if k != "bus"}, "features": [f for f in out["features"] if f != "bus"]}
        self.web.with_clock = older
        self.web._view = None   # the stream's shared snapshot is built anew
        self.ev("owner.notify", None, title="x", text="y")
        got = self.page(*tab, {"errors": 1500}, {"until": "!!document.querySelector('.bus-tab')", "ms": 10000},
                        {"eval": "document.querySelector('.bus-tab').innerText"})
        self.assertEqual(got[3]["errors"], [])
        self.assertIn("hub restart web", got[-1]["eval"])
    def test_the_hubs_tab_names_the_public_relay_before_the_link(self):
        # spec public relay §3.1: a hub of the public install that is on no relay links through the relay its install
        # names; the tab says which, with the way to one's own, before «Make an invitation» is pressed
        fake = ("(() => { const of = window.fetch.bind(window); window.fetch = (u, o) => { const b = o && o.body && "
                "JSON.parse(o.body); if (u === '/api/bus/act' && b.op === 'view') return of(u, o).then((r) => r.json())"
                ".then((d) => new Response(JSON.stringify({...d, enabled: true, name: 'Mine', relay: null, "
                "public_relay: 'https://relay.example.test', public_relay_reading: false}), {status: 200})); "
                "return of(u, o); }; })()")
        shots = os.environ.get("HUB_TEST_SHOTS")
        got = self.page({"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/settings",
                                                "init": "localStorage.setItem('hub.settingsTab', 'hubs');" + fake},
                        {"until": "!!document.querySelector('[data-part=link] .hint')", "ms": 10000},
                        {"until": "[...document.querySelectorAll('[data-part=link] .hint')].some((h) => "
                                  "h.textContent.includes('relay.example.test'))", "ms": 8000},
                        {"eval": "[...document.querySelectorAll('[data-part=link] .hint')].map((h) => h.textContent)"
                                 ".find((x) => x.includes('relay.example.test'))"},
                        *([{"shot": os.path.join(shots, "public-relay-hint.png"), "width": 1100, "height": 760}]
                          if shots else []))
        self.assertTrue(got[3]["until"], got)
        self.assertIn("the public one this hub was installed with", got[4]["eval"])
        self.assertIn("Accept an invitation", got[4]["eval"])

    def test_a_linked_hub_page_asks_for_its_history_only_while_open_and_survives_a_refusal(self):
        # a contact of the hub bus straight in the journal (the page reads the core's facts): its page asks for the
        # history while it is open — and stops when the owner leaves; a 503 of the server is a line, not a broken page
        self.ev("core.bus_enabled", None, fp="hb1-" + "a" * 26, sign_pub="QQ==", enc_pub="QQ==", lib="50", label="Mine")
        self.ev("core.bus_contact_added", None, name="maps", fp="hb1-" + "b" * 26, label="Maps hub", sign_pub="QQ==",
                enc_pub="QQ==", relays=[], agents={}, bus_v=2, status="known", verified=False)
        self.ev("session.requested", "maps-dev", session_id="s-m", cwd="/w")
        self.ev("session.started", "maps-dev", session_id="s-m")
        asks = "window.__calls.filter((c) => c[0] === '/api/bus/act' && c[1].op === 'history').length"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/hub/maps"}, {"eval": self.PREP},
                        {"until": "!!document.querySelector('.bus-dock textarea')", "ms": 10000},
                        {"until": "!!document.querySelector('.bus-feed .bus-empty')", "ms": 10000},
                        {"eval": "document.querySelector('main .head h2').textContent"},
                        {"eval": "location.hash = '#/s/maps-dev', window.__calls.length = 0, 1"},
                        {"sleep": 4000}, {"eval": asks})
        self.assertTrue(got[3]["until"], got)
        self.assertEqual(got[4]["eval"], "↔ Maps hub")
        self.assertEqual(got[-1]["eval"], 0)   # it used to ask forever, every 1.5 s, for every contact page once seen
        refuse = ("(() => { const of = window.fetch; window.fetch = (u, o) => (u === '/api/bus/act' && "
                  "JSON.parse(o.body).op === 'history') ? Promise.resolve(new Response(JSON.stringify({error: 'busy'}), "
                  "{status: 503})) : of(u, o); return 1; })()")
        got = self.page({"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/hub/maps", "init": refuse},
                        {"until": "(document.querySelector('.bus-feed .bus-err') || {}).textContent", "ms": 10000},
                        {"eval": "!!document.querySelector('.bus-dock textarea')"})
        self.assertEqual(got[2]["until"], "busy")
        self.assertEqual(got[3]["eval"], True)

