    def feed_stand(self, verified=True, rows=None):
        self.ev("core.bus_enabled", None, fp="hb1-" + "a" * 26, sign_pub="QQ==", enc_pub="QQ==", lib="50", label="Mine")
        self.ev("core.bus_contact_added", None, name="maps", fp="hb1-" + "b" * 26, label="Maps hub", sign_pub="QQ==",
                enc_pub="QQ==", relays=[], agents={}, bus_v=2, status="known", verified=verified)
        # the page reads the feed from the server: here the server's answer is the rows above (the core's rows —
        # tests/test_hubbus_l3.py), the page's drawing of them is what is checked
        return ("(() => { const of = window.fetch; window.__sent = []; window.fetch = (u, o) => { if (u === '/api/bus/act') { "
                "const b = JSON.parse(o.body); if (b.op === 'history') return Promise.resolve(new Response(JSON.stringify("
                "{rows: %s}), {status: 200})); if (b.op === 'chat') { window.__sent.push(b); return Promise.resolve("
                "new Response(JSON.stringify(window.__reply || {ok: true}), {status: window.__reply ? 409 : 200})); } } "
                "return of(u, o); }; })()" % json.dumps(self.FEED if rows is None else rows))

    def test_a_linked_hub_feed_is_the_agents_correspondence_with_a_thread_folded_and_a_word_of_what_was_done(self):
        # owner 02.11: the page of a linked hub shows what the agents wrote to each other — what came from the other hub, to
        # whom the liaison passed it or why not, what our sessions sent — the field below is the session field's component
        init = self.feed_stand()
        got = self.page({"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/hub/maps", "init": init},
                        {"until": "document.querySelectorAll('.bus-ex').length === 3", "ms": 10000},
                        {"eval": "[...document.querySelectorAll('.bus-ex')].map((x) => [x.querySelectorAll('.bus-m').length, "
                                 "[...x.querySelectorAll('.bus-chip')].map((c) => c.textContent).join('|'), "
                                 "(x.querySelector('.bus-ex-head') || {}).textContent || ''])"},
                        {"eval": "document.querySelectorAll('.bus-bub').length"},
                        {"eval": "document.querySelector('.bus-ex.multi .bus-t').innerHTML"},
                        {"eval": "document.querySelector('.bus-ex-head').click(), document.querySelectorAll('.bus-ex.multi .bus-m').length"},
                        {"eval": "document.querySelector('.bus-ex-head').getAttribute('aria-expanded')"},
                        {"eval": "!!document.querySelector('.bus-dock form.composer textarea') && "
                                 "!document.querySelector('.bus-dock .composer .attach') && !document.querySelector('.bus-dock .bus-msg')"})
        self.assertTrue(got[2]["until"], got)
        threads = got[3]["eval"]
        self.assertEqual([x[0] for x in threads], [1, 1, 1])   # the thread of two is folded to its last message …
        self.assertIn("Thread, messages: 2", threads[0][2])
        self.assertIn("passed to maps-dev", threads[0][1])
        self.assertEqual(threads[1][1], "waits for your card")
        self.assertEqual(threads[2][1], "declined")
        self.assertEqual(got[4]["eval"], 2)                     # … and the owner's words and the hub's answer are bubbles
        self.assertEqual(got[5]["eval"], "The schema is in the wiki &lt;b&gt;not bold&lt;/b&gt;")   # a text of another hub is a text
        self.assertEqual(got[6]["eval"], 2)                     # … that opens on a press
        self.assertEqual(got[7]["eval"], "true")
        self.assertTrue(got[8]["eval"], got)

    def test_the_microphone_of_a_linked_hub_composer_stays_at_the_right_edge_under_a_long_hint(self):
        # owner 05.11: the hint nearly fills the row (here 20 px short), the microphone wrapped to a second line and stood at the left;
        # the spacer (flex 1 from 0) stayed on the first line, so it could not push the icon to the right
        from unittest import mock
        init = self.feed_stand(rows=[])
        mic = ".bus-dock .composer .btn.round.mic"
        with mock.patch.dict(os.environ, {"VOICE_CMD": "true"}):
            got = self.page({"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/hub/maps", "init": init},
                            {"until": "document.querySelector('%s')?.offsetWidth > 0" % mic, "ms": 10000},
                            {"eval": "(() => { const b = document.querySelector('.bus-dock .composer .bar'); "
                                   "b.querySelector('.hint').style.width = (b.clientWidth - 20) + 'px'; return 1; })()"},
                            {"eval": "(() => { const m = document.querySelector('%s').getBoundingClientRect(), "
                                   "f = document.querySelector('.bus-dock .composer').getBoundingClientRect(); "
                                   "return [Math.round(f.right - m.right), Math.round(m.left - f.left)]; })()" % mic})
            self.assertTrue(got[2]["until"], got)
            right, left = got[-1]["eval"]
            self.assertLess(right, 30, got[-1])   # the icon touches the right edge of the box, not the left
            self.assertGreater(left, 100, got[-1])

