    def test_the_hub_name_field_saves_and_the_invitation_carries_its_own_name_when_changed(self):
        init = self.feed_stand(rows=[])
        spy = ("(() => { const of = window.fetch; window.__calls = []; window.fetch = (u, o) => { const b = o && o.body && "
               "JSON.parse(o.body); if (u === '/api/bus/act' && b.op === 'name') { window.__calls.push(['name', b.text]); "
               "return Promise.resolve(new Response(JSON.stringify({ok: true}), {status: 200})); } "
               "if (u === '/api/bus/start') { window.__calls.push(['start', b.label || null]); "
               "return Promise.resolve(new Response(JSON.stringify({error: 'x'}), {status: 409})); } return of(u, o); }; })()")
        spy = spy.replace("const of = window.fetch;", "const of = window.fetch.bind(window);")
        fill = ("(() => { const f = document.querySelector('%s'); f.focus(); f.value = %s; "
                "f.dispatchEvent(new Event('input', {bubbles: true})); return 1; })()")
        got = self.rights_page(init, (
            {"eval": spy},
            {"eval": fill % (".bus-hubname-in", json.dumps("  Sales hub "))}, {"key": "Enter"},
            {"until": "window.__calls.length === 1", "ms": 5000}, {"eval": "window.__calls"}))
        self.assertTrue(got[-2]["until"], got)
        self.assertEqual(got[-1]["eval"], [["name", "Sales hub"]])   # the page sends it; the core trims and checks
        # the core took it (its fold is the page's state): the field of the invitation carries the name, a change goes with it
        self.ev("bus.name_requested", None, name="Sales hub", channel="web", owner=True)
        got = self.page({"until": "!!document.querySelector('.bus-invite-name')", "ms": 8000},
                        {"eval": "document.querySelector('.bus-invite-name').value"},
                        {"eval": "document.querySelector('[data-part=link] .btn.primary').disabled"},
                        {"eval": "document.querySelector('[data-part=link] .btn.primary').click(), 1"},
                        {"until": "window.__calls.length === 2", "ms": 5000},
                        {"eval": fill % (".bus-invite-name", json.dumps("Partner hub"))},
                        {"eval": "document.querySelector('[data-part=link] .btn.primary').click(), 1"},
                        {"until": "window.__calls.length === 3", "ms": 5000},
                        {"eval": "window.__calls.slice(1)"})
        self.assertTrue(got[0]["until"], got)
        self.assertEqual((got[1]["eval"], got[2]["eval"]), ("Sales hub", False))
        self.assertEqual(got[-1]["eval"], [["start", None], ["start", "Partner hub"]])   # as it is — no label at all

    def test_a_second_press_while_the_invitation_waits_for_the_reader_does_not_start_a_second_one(self):
        # review of PR #482: the press is repeated by itself on 503 «Loading…» with the button still there — a second
        # press started a second chain (both made an invitation once the reader was free); a press with a changed name
        # must not be lost either: the one chain goes on with what was pressed last
        init = self.feed_stand(rows=[])
        self.ev("bus.name_requested", None, name="Sales hub", channel="web", owner=True)
        spy = ("(() => { const of = window.fetch.bind(window); window.__starts = []; window.fetch = (u, o) => { "
               "if (u === '/api/bus/start') { window.__starts.push(JSON.parse(o.body).label || null); "
               "return Promise.resolve(new Response(JSON.stringify({error: 'busy'}), {status: 503})); } "
               "return of(u, o); }; })()")
        make = "document.querySelector('[data-part=link] .btn.primary')"
        rename = ("(() => { const f = document.querySelector('.bus-invite-name'); f.value = 'Partner hub'; "
                  "f.dispatchEvent(new Event('input', {bubbles: true})); %s.click(); return window.__starts.length; })()"
                  % make)
        got = self.rights_page(init, (
            {"eval": spy}, {"until": f"!!{make} && !{make}.disabled", "ms": 8000},
            {"eval": f"{make}.click(), 1"},
            {"until": "document.querySelector('.bus-tab').textContent.includes('Loading')", "ms": 3000},
            {"eval": rename},   # the fetch spy counts at once: a press that posted shows here, no race with the retry
            {"until": "window.__starts.length >= 2", "ms": 5000}, {"eval": "window.__starts"}))
        self.assertTrue(got[-6]["until"] and got[-4]["until"] and got[-2]["until"], got)
        self.assertEqual(got[-3]["eval"], 1)
        self.assertEqual(got[-1]["eval"][:2], [None, "Partner hub"])

