    def test_the_field_of_a_linked_hub_sends_as_a_word_to_the_hub_and_a_key_like_text_goes_on_the_second_enter(self):
        init = self.feed_stand(rows=[])
        type_ = ("(() => { const a = document.querySelector('.bus-dock textarea'); a.focus(); a.value = %s; "
                 "a.dispatchEvent(new Event('input', {bubbles: true})); return a.placeholder; })()")
        reply = "window.__reply = {error: 'looks like a key', code: 'secret', confirm: true}, 1"
        got = self.page({"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/hub/maps", "init": init},
                        # the field is there before the snapshot with the contact (the view «not linked»): wait for the linked one
                        {"until": "!!document.querySelector('.bus-dock textarea') && "
                                  "((document.querySelector('.bus-vhead h2') || {}).textContent || '').startsWith('↔')", "ms": 10000},
                        {"eval": type_ % json.dumps("Who owns the catalog?")}, {"key": "Enter"},
                        {"until": "window.__sent.length === 1", "ms": 5000},
                        {"eval": "window.__sent"},
                        {"eval": reply}, {"eval": type_ % json.dumps("key sk-test")}, {"key": "Enter"},
                        {"until": "!!(document.querySelector('.bus-dock .error-text') || {}).textContent", "ms": 5000},
                        {"eval": "document.querySelector('.bus-dock .error-text').textContent"},
                        {"eval": "delete window.__reply, document.querySelector('.bus-dock textarea').value"},
                        {"key": "Enter"}, {"until": "window.__sent.length === 3", "ms": 5000},
                        {"eval": "window.__sent.map((b) => [b.op, b.name, b.text, b.confirm === true])"})
        self.assertTrue(got[2]["until"], got)
        self.assertEqual(got[3]["eval"], "Message")   # the hub's name is in the page's header (K-36), as a session's
        self.assertEqual(got[6]["eval"], [{"op": "chat", "name": "maps", "text": "Who owns the catalog?"}])
        self.assertIn("Enter once more", got[11]["eval"])
        self.assertEqual(got[12]["eval"], "key sk-test")   # the text came back into the field
        self.assertEqual(got[-1]["eval"], [["chat", "maps", "Who owns the catalog?", False],
                                           ["chat", "maps", "key sk-test", False], ["chat", "maps", "key sk-test", True]])

    def test_a_hub_link_in_a_session_field_is_not_sent_without_a_word(self):
        # spec hubbus/ux §3.3 p. 5: a link is a secret, a session's transcript keeps what it gets — the page stops the
        # send and offers «Link this hub» (the paste field of Settings -> Hubs gets it) or «Send as text»
        self.ev("session.requested", "maps", session_id="s-maps", cwd="/w")
        self.ev("session.started", "maps", session_id="s-maps")
        link = "hub-link-1:" + "eyJ2IjoyfQ" * 8
        typed = ("(() => { const a = document.querySelector('#msg'); a.focus(); a.value = %s; "
                 "a.dispatchEvent(new Event('input', {bubbles: true})); return true; })()" % json.dumps("here " + link))
        sends = "window.__calls.filter((c) => c[0] === '/api/send').length"
        got = self.page({"go": f"http://127.0.0.1:{self.port}/#/s/maps"}, {"until": "!!document.querySelector('#msg')"},
                        {"eval": self.PREP}, {"sleep": 300}, {"eval": typed}, {"key": "Enter"}, {"sleep": 500},
                        {"eval": sends}, {"eval": "document.querySelector('#msg').value.includes('hub-link-1:')"},
                        {"eval": "[...document.querySelectorAll('main button')].filter((b) => b.textContent === "
                                 "'Accept the invitation').length"})
        self.assertEqual(got[7:], [{"eval": 0}, {"eval": True}, {"eval": 1}])
        got = self.page({"eval": "[...document.querySelectorAll('main button')].find((b) => b.textContent === "
                                 "'Accept the invitation').click(), 1"},
                        {"until": "!!document.querySelector('.bus-paste') && document.querySelector('.bus-paste').value",
                         "ms": 10000},
                        {"eval": "location.hash"}, {"eval": sends})
        self.assertIn(link, got[1]["until"])
        self.assertEqual(got[2:], [{"eval": "#/settings"}, {"eval": 0}])
        # «Send as text» — the owner's word: it goes
        got = self.page({"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/s/maps"},
                        {"until": "!!document.querySelector('#msg')"}, {"eval": self.PREP}, {"sleep": 300},
                        {"eval": typed}, {"key": "Enter"}, {"sleep": 300},
                        {"eval": "[...document.querySelectorAll('main button')].find((b) => b.textContent === "
                                 "'Send as text').click(), 1"}, {"sleep": 600}, {"eval": sends})
        self.assertEqual(got[-1], {"eval": 1})

    def settings_details(self, tab):
        """Open every <details> of a Settings tab, let the page redraw it from a new snapshot: [summary, open] of each."""
        mine = "[...document.querySelectorAll('main .feed-inner details')]"
        names = f"JSON.stringify({mine}.map((d) => [d.querySelector(':scope > summary')?.textContent, d.open]))"
        opening = f"(() => {{ for (const d of {mine}) d.open = true; return 1; }})()"
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        shown = "document.querySelector('[data-settings-tab][aria-selected=true]')?.dataset.settingsTab"
        # about:blank first: a second go to the same #/settings does not reload the page, the tab would stay the old one
        got = self.page({"go": "about:blank"}, {"local": {"hub.settingsTab": tab}},
                        {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": f"{mine}.length > 0", "ms": 10000}, {"sleep": 2500}, {"eval": shown}, {"eval": opening},
                        {"sleep": 300}, {"eval": names})
        self.assertEqual(got[-4]["eval"], tab)
        before = got[-1]["eval"]
        self.ev("owner.notify", None, title="x", text="y")   # a new snapshot: the tab is refreshed from it
        got = self.page({"sleep": 4500}, {"eval": names})   # longer than the page's pause between two reads of a tab
        return json.loads(before), json.loads(got[1]["eval"])

