    # the stats report takes seconds: the fake answer comes after SLOW ms and says which request it is
    STATS_SLOW = ("(() => { const of = window.fetch; window.__stats = []; window.fetch = (u, o) => { "
                  "if (!String(u).startsWith('/api/stats?')) return of(u, o); const n = window.__stats.push(u); "
                  "return new Promise((ok) => setTimeout(() => ok(new Response(JSON.stringify({text: 'report ' + n}))), 6000)); }; })()")
    STATS_BLOCKS = "[...document.querySelectorAll('main .stats-peek details')]"

    def stats_blocks(self, *steps):
        """The Modules tab with the statistics blocks; the steps run after the page has loaded."""
        self.ev("session.requested", "a", session_id="s-a", cwd="/w", channel="cli", owner=True)
        return self.page({"local": {"hub.settingsTab": "modules"}},
                         {"go": f"http://127.0.0.1:{self.port}/#/settings", "init": self.STATS_SLOW},
                         {"until": f"{self.STATS_BLOCKS}.length > 1", "ms": 10000}, {"sleep": 2500}, *steps)

    @cut.needs("stats")
    def test_a_stats_block_restored_open_joins_the_request_under_way(self):
        # the tab is rebuilt with every snapshot while the report is still coming: the rebuilt block must not ask again
        opening = f"(() => {{ for (const d of {self.STATS_BLOCKS}) d.open = true; return 1; }})()"
        shown = f"JSON.stringify([window.__stats.length, {self.STATS_BLOCKS}.map((d) => d.querySelector('pre').textContent)])"
        self.stats_blocks({"eval": opening}, {"sleep": 300})   # opened: one request per block
        self.ev("owner.notify", None, title="x", text="y")   # a new snapshot: the tab is drawn anew, the report is not here yet
        got = self.page({"sleep": 4500}, {"eval": shown}, {"sleep": 3000}, {"eval": shown})
        while_waiting, done = json.loads(got[1]["eval"]), json.loads(got[3]["eval"])
        self.assertEqual(while_waiting[0], 2, while_waiting)   # one per `what`, not one per rebuild
        self.assertEqual(done, [2, ["report 1", "report 2"]])

    @cut.needs("stats")
    def test_a_stats_block_reopened_during_a_redraw_shows_the_new_report(self):
        # closed and opened again → a new request; the tab is rebuilt while it runs and shows the new report, not the old one
        opening = f"(() => {{ for (const d of {self.STATS_BLOCKS}) d.open = true; return 1; }})()"
        again = f"(() => {{ const d = {self.STATS_BLOCKS}[0]; d.open = false; setTimeout(() => {{ d.open = true; }}, 100); return 1; }})()"
        first = f"{self.STATS_BLOCKS}[0].querySelector('pre').textContent"
        self.stats_blocks({"eval": opening}, {"until": f"{first} == 'report 1'", "ms": 10000}, {"eval": again}, {"sleep": 600})
        self.ev("owner.notify", None, title="x", text="y")   # the tab is rebuilt while the second report is on its way
        got = self.page({"sleep": 4500}, {"eval": f"window.__stats.length"}, {"until": f"{first} == 'report 3'", "ms": 10000},
                        {"eval": first})
        self.assertEqual(got[1]["eval"], 3, got)   # the second report was asked once: the rebuilt block did not ask again
        self.assertEqual(got[-1]["eval"], "report 3", got)

    def test_a_task_button_rebuilt_while_held_frees_itself(self):
        # PR #500: "Fix" stays held for a few seconds after a press (a double click sent the task twice); a redraw of the
        # tab in that time built the button anew, disabled, and nothing freed it — on a quiet hub it stayed grey for good
        from unittest import mock
        from core import i18n
        path = os.path.join(self.state, "plug-held")
        os.makedirs(path)
        with open(os.path.join(path, "hub-plugin.json"), "w") as f:
            json.dump({"name": "old", "description": "old", "web": "main.js", "hub": "^0.3"}, f)
        with open(os.path.join(path, "main.js"), "w") as f:
            f.write("export default function register(hub) {}\n")
        cfg = os.path.join(self.state, "hub.json")
        with open(cfg, "w") as f:
            json.dump({"extensions": {"bob:old": {"path": path, "web": "main.js", "source": "bob/z", "hub": "^0.3"}}}, f)
        env = mock.patch.dict(os.environ, {"HUB_CONFIG": cfg})
        env.start()
        self.addCleanup(env.stop)
        self.ev("session.requested", "a", session_id="s-a", cwd="/w")
        names = json.dumps([i18n.tr(lang, "web.plugins.fix_pr") for lang in ("ru", "en")], separators=(",", ":"))
        fix = f"[...document.querySelectorAll('button')].find((b) => {names}.includes(b.textContent))"
        got = self.page({"local": {"hub.settingsTab": "plugins"}},
                        {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": f"!!{fix}", "ms": 8000},
                        # the press and a redraw at once (synchronous): the new button is built while the first one holds
                        {"eval": f"const old = {fix}; old.click(); window.dispatchEvent(new Event('hub-plugins')); "
                                 f"const b = {fix}; [b !== old, !!b && b.disabled]"},
                        {"until": "[...document.querySelectorAll('.plugin-note')].some((n) => n.textContent.length > 0)", "ms": 6000},
                        {"until": f"!!{fix} && !{fix}.disabled", "ms": 14000})
        self.assertTrue(got[2]["until"], got[2])
        self.assertEqual(got[3]["eval"], [True, True])     # rebuilt, and held right after the press
        self.assertTrue(got[4]["until"], got[4])
        self.assertTrue(got[5]["until"], got[5])           # the hold is over: the new button takes a press again
        self.assertEqual(len([e for e in self.spooled() if e["type"] == "message.received"]), 1)

    def test_a_password_in_this_hub_s_row_keeps_this_tab_and_closes_the_others(self):
        # Settings -> Main -> Hubs on this computer: "Password" in this hub's row (core/pagepass.py); the same answer
        # signs this tab in; a browser without the cookie (another profile) gets 401; the neighbour without a password
        # is named, it opens the others
        from unittest import mock
        from core import instancecli, pagepass
        from modules.web import instancesweb
        from platforms import current
        cfg, other = tempfile.mkdtemp(prefix="hub-e2e-pass-"), tempfile.mkdtemp(prefix="hub-e2e-pass-other-")
        for d in (cfg, other):
            self.addCleanup(current.rmtree, d)
        rows = [{"name": "", "command": "hub", "title": "", "state": self.state, "config_dir": cfg,
                 "ports": {"web": self.port}, "running": True, "port_busy": False, "engine": "claude"},
                {"name": "personal", "command": "hub-personal", "title": "personal", "state": "/home/x/.hub-personal",
                 "config_dir": other, "ports": {"web": 8801}, "running": True, "port_busy": False, "engine": "claude",
                 "gone": False}]
        for target, name, value in ((os.environ, None, {"HUB_CONFIG_DIR": cfg}), (instancecli, "rows", lambda: rows),
                                    (instancesweb, "knows_password", lambda row: True)):
            p = mock.patch.dict(target, value) if name is None else mock.patch.object(target, name, value)
            p.start()
            self.addCleanup(p.stop)
        instancesweb._seen.clear()
        me = "document.querySelector('.inst-row[data-hub=\"\"]')"
        new = "document.querySelector('.inst-pass input[name=\"new-password\"]')"
        status = ("Promise.all([fetch('/api/snapshot').then((r) => r.status),"
                  " fetch('/api/snapshot', { credentials: 'omit' }).then((r) => r.status)])"
                  ".then((x) => { window.__pp = x; })")
        got = self.page({"local": {"hub.settingsTab": "general"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": "document.querySelectorAll('.instances .inst-row').length === 2", "ms": 8000},
                        {"eval": f"{me}.querySelector('.inst-pass-btn').click(); 1"},
                        {"until": f"!!{new}", "ms": 4000},
                        {"eval": f"{new}.focus(); 1"}, {"typed": "short"},
                        {"eval": "document.querySelector('.inst-pass .btn.primary').click(); 1"},
                        {"until": "!!document.querySelector('.inst-pass .hint.warn:not([hidden])')", "ms": 4000},
                        {"eval": f"{new}.select(); 1"}, {"typed": "correct horse battery"},
                        {"eval": "document.querySelector('.inst-pass .btn.primary').click(); 1"},
                        {"until": f"!document.querySelector('.inst-pass') && !!{me}.querySelector('.inst-lock')",
                         "ms": 6000},
                        {"eval": "[document.querySelector('.inst-open')?.textContent || '',"
                                 f" {me}.querySelector('.inst-lock').textContent]"},
                        {"eval": f"{status}, 1"}, {"until": "!!window.__pp", "ms": 6000}, {"eval": "window.__pp"},
                        {"errors": 1500},
                        {"until": "document.querySelectorAll('.instances .inst-row').length === 2", "ms": 8000})
        self.assertTrue(got[2]["until"], got)
        self.assertTrue(got[4]["until"], got)
        self.assertTrue(got[8]["until"], got)   # too short: said under the form, nothing set
        self.assertTrue(got[12]["until"], got)
        warn, chip = got[13]["eval"]
        self.assertIn("personal", warn)
        self.assertEqual(chip, "password")
        self.assertEqual(pagepass.state(cfg), "password")
        self.assertTrue(pagepass.matches("correct horse battery", cfg))
        self.assertEqual(got[16]["eval"], [200, 401])   # this tab works; without its cookie — refused
        self.assertTrue(got[-1]["until"], got)          # a reload: the cookie keeps the page open

    def test_hubs_on_this_computer_add_and_remove(self):
        # Settings -> Main -> Hubs on this computer (modules/web/instancesweb.py): the machine's hubs from the registry,
        # "Add a hub" in the block's "More" — the form checks like the terminal and the install runs apart; the end of
        # the job comes by itself, with "Open"; "Remove" asks for the name
        from unittest import mock
        from core import instancecli, instancejob
        from modules.web import instancesweb
        other = 8801
        rows = [{"name": "", "command": "hub", "title": "", "state": self.state, "config_dir": "", "ports": {"web": self.port},
                 "running": True, "port_busy": False, "engine": "claude"},
                {"name": "personal", "command": "hub-personal", "title": "personal", "state": "/home/x/.hub-personal",
                 "config_dir": "", "ports": {"web": other}, "running": True, "port_busy": False, "engine": "claude",
                 "gone": False}]
        dry, spawned = [], []
        for name, value in (("rows", lambda: rows),):
            p = mock.patch.object(instancecli, name, value)
            p.start()
            self.addCleanup(p.stop)
        for name, value in (("refusal", lambda: None), ("engines", lambda found=None: ["claude"]), ("check", lambda argv, lang: dry.append(argv) or ("taken" if argv[0] == "bad1" else None)),
                            ("spawn", lambda cmd, env: spawned.append(cmd)), ("knows_password", lambda row: True)):
            p = mock.patch.object(instancesweb, name, value)
            p.start()
            self.addCleanup(p.stop)
        reg = mock.patch.object(instancesweb.instance, "entries", lambda *a: [{"name": "personal", "gone": False}])
        reg.start()
        self.addCleanup(reg.stop)
        instancesweb._seen.clear()
        row = "document.querySelector('.inst-row[data-hub=\"personal\"]')"
        name = "document.querySelector('.inst-new-name')"
        got = self.page({"local": {"hub.settingsTab": "general"}}, {"go": f"http://127.0.0.1:{self.port}/#/settings"},
                        {"until": "document.querySelectorAll('.instances .inst-row').length === 2", "ms": 8000},
                        {"eval": "[...document.querySelectorAll('.inst-row')].map((r) => [r.dataset.hub,"
                                 " !!r.querySelector('a.btn'), !!r.querySelector('.inst-acts .inst-remove')])"},
                        {"eval": "document.querySelector('.inst-more').open"},
                        {"eval": "document.querySelector('.inst-more > summary').click(); 1"},
                        {"until": f"!!{name} && {name}.checkVisibility()", "ms": 3000},
                        {"eval": f"{name}.focus(); 1"}, {"typed": "bad1"},
                        {"eval": "document.querySelector('.inst-add .btn.primary').click(); 1"},
                        {"until": "!document.querySelector('.inst-add .hint.warn').hidden", "ms": 6000},
                        {"eval": "[document.querySelector('.inst-add .hint.warn').textContent, !!document.querySelector('.inst-job')]"},
                        {"eval": f"{name}.select(); 1"}, {"typed": "work"},
                        {"eval": "document.querySelector('.inst-add .seg button[data-v=\"own\"]').click();"
                                 " document.querySelector('.inst-add .btn.primary').click(); 1"},
                        {"until": "!!document.querySelector('.inst-job.running')", "ms": 6000})
        self.assertTrue(got[2]["until"], got)
        # the main one is this page's: no "Open", no "Remove"; the other one: both
        self.assertEqual(got[3]["eval"], [["", False, False], ["personal", True, True]])
        self.assertFalse(got[4]["eval"])   # "Add a hub" is in "More", closed
        self.assertTrue(got[6]["until"], got)
        self.assertTrue(got[10]["until"], got)
        self.assertEqual(got[11]["eval"], ["taken", False])   # the terminal's refusal, under the form; nothing started
        self.assertTrue(got[-1]["until"], got)
        self.assertEqual(dry, [["bad1", "--dry-run"], ["work", "--claude", "own", "--dry-run"]])
        self.assertEqual(len(spawned), 1)
        job = instancejob.read(self.state)
        self.assertEqual(instancejob.argv_of(job), ["new", "work", "--claude", "own", "--yes"])
        # the job ends (the runner writes it): the page sees it by itself and offers the new hub's page
        rows.append({"name": "work", "command": "hub-work", "title": "work", "state": "/home/x/.hub-work", "config_dir": "",
                     "ports": {"web": 8803}, "running": True, "port_busy": False, "engine": "claude", "gone": False})
        instancesweb._seen.clear()
        instancejob.write(self.state, {**job, "ended": int(time.time()), "code": 0})
        open_new = "document.querySelector('.inst-job.done a.btn')"
        got = self.page({"until": f"!!{open_new}", "ms": 8000}, {"eval": f"{open_new}.getAttribute('href')"},
                        {"eval": "document.querySelectorAll('.instances .inst-row').length"},
                        {"eval": f"{row}.querySelector('.inst-acts .inst-remove').click(); 1"},
                        {"until": "!!document.querySelector('.inst-confirm input')", "ms": 3000},
                        {"eval": "document.querySelector('.inst-confirm .btn.danger').disabled"},
                        {"eval": "document.querySelector('.inst-confirm input').focus(); 1"}, {"typed": "personal"},
                        {"eval": "document.querySelector('.inst-confirm .btn.danger').disabled"},
                        {"eval": "document.querySelector('.inst-confirm .btn.danger').click(); 1"},
                        {"until": "!!document.querySelector('.inst-job.running')", "ms": 6000})
        self.assertTrue(got[0]["until"], got)
        self.assertEqual(got[1]["eval"], "http://127.0.0.1:8803/")
        self.assertEqual(got[2]["eval"], 3)
        self.assertTrue(got[4]["until"], got)
        self.assertTrue(got[5]["eval"])     # not before the name is typed
        self.assertFalse(got[8]["eval"])
        self.assertTrue(got[-1]["until"], got)
        self.assertEqual(instancejob.argv_of(instancejob.read(self.state)), ["uninstall", "personal", "--yes"])
        self.assertEqual(len(spawned), 2)

    def spec_ready(self, text="# Export\n\nThree slices.\n"):
        """maps (specs on) raised maps-1 with --spec, its first result made the spec ready (core/specmode.py). -> task id."""
        self.ev("session.requested", "maps", session_id="s-maps", cwd="/w", role="agent", about="Maps", channel="cli",
                owner=True)
        self.ev("session.started", "maps", session_id="s-maps")
        self.ev("session.spec_set", "maps", on=True, channel="web", owner=True)
        self.ev("task.run_requested", "maps-1", task="design the export", spec=True, channel="session", owner=False,
                sender="maps")
        self.ev("session.requested", "maps-1", session_id="s1", executor=True, raised_by="maps", cwd="/w/x",
                about="design the export")
        seq = self.j.append("delegation.created", None, {"session": "maps-1", "for_session": "maps", "context": "design",
                                                         "channel": "session", "owner": False, "sender": "maps"})["seq"]
        self.ev("session.started", "maps-1", session_id="s1")
        self.ev("turn.started", "maps-1", marker=f"m{seq}")
        self.ev("turn.result", "maps-1", text="The spec is ready.")
        self.ev("turn.stopped", "maps-1")
        path = os.path.join(self.state, "specs", f"d{seq}", "spec.md")
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            f.write(text)
        self.settle()
        return f"d{seq}"

