    def test_an_executor_in_clean_keeps_stop_executor_and_a_message_goes(self):
        heads = ("[...document.querySelectorAll('main .head > .btn')].filter((b) => b.textContent.startsWith('Stop'))"
                 ".map((b) => [b.textContent.trim(), b.offsetParent !== null])")
        self.spooled()
        got = self.page(self.go("#/s/maps-x"), {"until": "main.dataset.for === 'maps-x'"}, {"wait": "Stop executor"},
                        {"eval": heads},
                        {"eval": "document.querySelector('.dock textarea').focus(), 1"}, {"typed": "hello from clean"},
                        {"key": "Enter"}, {"sleep": 500})
        # Esc stops the turn on a computer, so its button is hidden; Esc does not stop an executor — that button stays
        self.assertEqual(got[3]["eval"], [["Stop turn", False], ["Stop executor", True]])
        sent = [e["data"]["text"] for e in self.spooled() if e["type"] == "message.received"]
        self.assertEqual(sent, ["hello from clean"])

    def test_the_second_line_of_the_detailed_list_says_what_a_working_or_waiting_session_does(self):
        # owner decision (12.11): a session that works shows its gist of this turn (what it says it does), else the core's caption of
        # the row; one that waits — the caption (what it waits for and from whom); one that finished or sleeps, and a parent that is
        # free and spins only for its executors — the start of its last result, as before; an executor that never wrote to the chat
        # and is not working — its gist; with neither, the line is empty. The tooltip stays as it was
        for n in ("waiter", "done", "sleeper", "gisted", "stale"):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True, role="agent", about=n)
            self.ev("session.started", n, session_id=f"s-{n}")
        self.ev("session.requested", "maps-y", session_id="s-y", cwd="/w", channel="cli", owner=True, executor=True, raised_by="maps")
        self.ev("session.started", "maps-y", session_id="s-y")
        for n in ("maps", "waiter", "done", "sleeper"):
            e = self.j.append("message.received", None, {"to": n, "text": "go", "channel": "web", "owner": True})
            self.ev("turn.started", n, marker=f"m{e['seq']}", prompt_head="go")
            self.ev("session.said", n, text=f"Result of {n}: all is ready.")
            self.ev("turn.result", n, text=f"Result of {n}: all is ready.")
            self.ev("turn.stopped", n)
        self.ev("session.waiting", "waiter", text="the reviewer answer on the branch", channel="session", sender="waiter")
        self.ev("session.ended", "sleeper", reason="prompt_input_exit")
        self.ev("session.gist", "stale", text="Old gist of the previous turn", channel="session", owner=False, sender="stale")
        time.sleep(0.05)
        for n in ("gisted", "stale"):
            self.ev("turn.started", n, marker=None, prompt_head="work")
        time.sleep(0.05)
        self.ev("session.gist", "gisted", text="Checking the October invoices", channel="session", owner=False, sender="gisted")
        self.ev("turn.started", "maps-y", marker=None, prompt_head="job")
        self.ev("session.gist", "maps-y", text="Handed in: the feed fix", channel="session", owner=False, sender="maps-y")
        self.ev("turn.stopped", "maps-y")
        self.core_decides()
        rows = ("JSON.stringify(Object.fromEntries([...document.querySelectorAll('#list .srow:not(.nav)')].map((r) => [[...r.querySelector('.nm').childNodes]"
                ".filter((n) => n.nodeType === 3).map((n) => n.nodeValue.trim()).filter(Boolean).pop(), [r.querySelector(':scope > .txt').dataset.cleanPrev || '', r.querySelector('.lb').textContent.trim()]])))")
        got = self.page({"local": {"hub.opt.core:clean": '{"detail":true}'}}, self.go(),
                        {"until": "document.documentElement.classList.contains('th-clean-detail') && document.querySelectorAll('#list .srow').length > 5"},
                        {"until": "!!document.querySelector('#list .fork-toggle')"}, {"eval": "(document.querySelector('#list .fork-toggle').click(), 1)"},
                        {"until": "document.querySelectorAll('#list li.forks .srow').length === 2"}, {"sleep": 800}, {"eval": rows})
        shown = json.loads(got[-1]["eval"])
        self.assertEqual(shown["waiter"][0], "waiting: the reviewer answer on the branch", shown)
        self.assertEqual(shown["done"][0], "Result of done: all is ready.", shown)
        self.assertEqual(shown["sleeper"][0], "Result of sleeper: all is ready.", shown)
        self.assertEqual(shown["y"][0], "Handed in: the feed fix", shown)   # the executor under maps, no result, not working
        self.assertEqual(shown["gisted"][0], "Checking the October invoices", shown)   # working, said what it does in this turn
        self.assertEqual(shown["stale"][0], "working · stale", shown)   # working, its gist is from the previous turn: the core's caption
        self.assertEqual(shown["maps"][0], "Result of maps: all is ready.", shown)   # free, spins for its executor: its result
        self.assertEqual(shown["x"][0], "working", shown)   # working: the core caption, without the ticking time (".lb" has " · 5s" after it)
        self.assertTrue(shown["x"][1].startswith("working · "), shown)

