    def test_sorting_by_the_last_message_is_off_by_default_and_rows_drag(self):
        # owner decision (10.11): the theme's sorting comes unchecked — the hub's own order stays and rows drag; checked, a
        # drag of a row is not taken (the sorting owns the order)
        for n in ("devops", "seo"):
            self.ev("session.requested", n, session_id=f"s-{n}", cwd="/w", channel="cli", owner=True, role="agent", about=n)
            self.ev("session.started", n, session_id=f"s-{n}")
        self.core_decides()
        check = "[...document.querySelectorAll('label.opt')].find((l) => l.textContent.startsWith('Sort by last message'))?.querySelector('input')"
        got = self.page({"local": {"hub.settingsTab": "theme"}}, self.go("#/settings"), {"wait": "Sort by last message"},
                        {"eval": f"[({check})?.checked, document.documentElement.classList.contains('th-clean-recent')]"},
                        {"go": f"http://127.0.0.1:{self.port}/#/"}, {"until": "!!document.querySelector('#list .sgroup[data-g=\"agents\"]')"},
                        self.STEADY, {"drag": self.ROW.format("maps"), "to": self.ROW.format("seo"), "at": 0.2},
                        {"until": self.IN.format("agents", "maps")})
        self.assertEqual(got[3]["eval"], [False, False])
        self.assertTrue(got[-1]["until"], got)   # dropped above seo: the row moved to the specialists
        lay = self.snap(lambda st: st["layout"]["place"].get("maps") == "agents")["layout"]
        self.assertEqual(lay["order"]["agents"], ["devops", "maps", "seo"])
        # checked: the row is not lifted (the sorting owns the order in a group)
        got = self.page({"go": "about:blank", "look": None}, {"local": {"hub.opt.core:clean": '{"recent":true}'}}, self.go(),
                        {"until": "document.documentElement.classList.contains('th-clean-recent')"}, self.STEADY,
                        {"drag": self.ROW.format("maps"), "to": self.ROW.format("devops"), "at": 0.2}, {"sleep": 800})
        self.assertTrue(got[3]["until"], got)
        self.assertEqual(self.snap()["layout"]["order"]["agents"], ["devops", "maps", "seo"])   # the drag was not taken

    def test_the_counts_in_the_list_are_off_by_default_and_a_tick_brings_them_back(self):
        # the filter tabs ("All · N") and the group headers carry no number in Clean until "Counts in the list" is ticked
        check = ("[...document.querySelectorAll('label.opt')].find((l) => l.textContent.startsWith('Counts in the list'))"
                 "?.querySelector('input')")
        look = ("(() => { const tabs = [...document.querySelectorAll('#active-bar button')]; const g = document.querySelector('.sgroup-h .gcount');"
                " return [document.documentElement.classList.contains('th-clean-counts'), tabs.map((b) => b.textContent.trim()),"
                " tabs.filter((b) => b.querySelector('.c-n')).length, g ? getComputedStyle(g).display : null]; })()")
        ready = "document.querySelectorAll('#active-bar button').length > 1 && !!document.querySelector('.sgroup-h .gcount')"
        got = self.page({"local": {"hub.settingsTab": "theme"}}, self.go("#/settings"), {"wait": "Counts in the list"},
                        {"eval": f"({check})?.checked"},
                        self.go(), {"until": ready}, {"sleep": 400}, {"eval": look},
                        {"go": "about:blank", "look": None}, {"local": {"hub.opt.core:clean": '{"counts":true}'}}, self.go(),
                        {"until": ready + " && document.documentElement.classList.contains('th-clean-counts')"}, {"sleep": 400}, {"eval": look})
        self.assertIs(got[3]["eval"], False)   # the tick is in "Settings → Look", off
        off, on = got[7]["eval"], got[-1]["eval"]
        self.assertEqual((off[0], off[2], off[3]), (False, 0, "none"), off)
        self.assertTrue(all(not re.search(r"\d", t) for t in off[1]), off)   # "All", "Now" — the word alone
        self.assertEqual((on[0], on[3] != "none"), (True, True), on)
        self.assertGreater(on[2], 0, on)   # ticked: the number is a badge on the tab again, as before
        self.assertTrue(all(re.search(r"\d", t) for t in on[1]), on)
        # the tick works at once, no reload: the numbers come back and go away again
        digits = "[...document.querySelectorAll('#active-bar button')].every((b) => /\\d/.test(b.textContent))"
        got = self.page({"go": "about:blank", "look": None}, {"local": {"hub.settingsTab": "theme", "hub.opt.core:clean": "{}"}},
                        self.go("#/settings"), {"wait": "Counts in the list"}, {"sleep": 800}, {"eval": f"({check}).click(), 1"}, {"until": digits, "ms": 8000}, {"eval": look},
                        {"eval": f"({check}).click(), 1"}, {"until": "!" + digits.replace("every", "some"), "ms": 8000}, {"eval": look})
        self.assertTrue(got[6]["until"] and got[9]["until"], got)
        self.assertEqual((got[7]["eval"][0], got[7]["eval"][3] != "none"), (True, True), got[7])
        self.assertEqual((got[10]["eval"][0], got[10]["eval"][3]), (False, "none"), got[10])

    def test_the_state_counts_under_the_list_are_off_by_default_and_a_tick_shows_them_above_the_menu_button(self):
        # the "State counts under the list" option: off, the counts line of the footer stays hidden as before; on, it is a row of
        # its own above ☰ and the limits, the ☰ plate never meets it
        check = ("[...document.querySelectorAll('label.opt')].find((l) => l.textContent.startsWith('State counts under the list'))"
                 "?.querySelector('input')")
        look = ("(() => { const c = document.querySelector('.aside-foot .counts'), m = document.querySelector('#navmenu'), f = document.querySelector('.aside-foot');"
                " if (!c || !m) return null; const r = c.getBoundingClientRect(), mr = m.getBoundingClientRect(), fr = f.getBoundingClientRect();"
                " return [document.documentElement.classList.contains('th-clean-footcounts'), getComputedStyle(c).display, c.childElementCount,"
                " Math.round(r.height), r.bottom <= mr.top + 0.5, Math.round(r.left - fr.left), getComputedStyle(c).fontSize]; })()")
        ready = "!!document.querySelector('.aside-foot .counts') && !!document.querySelector('#navmenu')"
        got = self.page({"local": {"hub.settingsTab": "theme"}}, self.go("#/settings"), {"wait": "State counts under the list"},
                        {"eval": f"({check})?.checked"},
                        self.go(), {"until": ready}, {"sleep": 400}, {"eval": look},
                        {"go": "about:blank", "look": None}, {"local": {"hub.opt.core:clean": '{"footcounts":true}'}}, self.go(),
                        {"until": ready + " && document.documentElement.classList.contains('th-clean-footcounts')"}, {"sleep": 400}, {"eval": look})
        self.assertIs(got[3]["eval"], False)   # the tick is in "Settings → Look", off
        off, on = got[7]["eval"], got[-1]["eval"]
        self.assertEqual(off[:2], [False, "none"], off)
        self.assertEqual(off[3], 0, off)
        self.assertEqual((on[0], on[1]), (True, "flex"), on)
        self.assertGreater(on[2], 0, on)
        self.assertEqual((on[3] >= 16, on[4], on[6]), (True, True, "12px"), on)   # a row of its own, above ☰, 12/16
        # the tick works at once, no reload
        got = self.page({"go": "about:blank", "look": None}, {"local": {"hub.settingsTab": "theme", "hub.opt.core:clean": "{}"}},
                        self.go("#/settings"), {"wait": "State counts under the list"}, {"sleep": 800}, {"eval": f"({check}).click(), 1"},
                        {"until": "document.documentElement.classList.contains('th-clean-footcounts')", "ms": 8000},
                        {"eval": f"({check}).click(), 1"},
                        {"until": "!document.documentElement.classList.contains('th-clean-footcounts')", "ms": 8000})
        self.assertTrue(got[6]["until"] and got[8]["until"], got)

