    def test_the_waiting_square_is_off_by_default_and_a_tick_shows_it_beside_the_search_field(self):
        # the "Waiting for you square" option: off, Clean draws nothing of the core's pill (as before); on, it is a 36 plate beside the
        # field with the same count as Classic's pill, and a search or the "Now" filter does not hide it; a click goes where Classic's goes
        self.fleet()
        self.ask("seo", "r1")
        self.ask("maps", "r2")
        check = ("[...document.querySelectorAll('label.opt')].find((l) => l.textContent.startsWith('Waiting for you square'))"
                 "?.querySelector('input')")
        look = ("(() => { const p = document.getElementById('wpill'), r = p.getBoundingClientRect(), s = document.querySelector('.search').getBoundingClientRect(),"
                " n = p.querySelector('.wn'), f = document.querySelector('.clean-fold');"
                " return [document.documentElement.classList.contains('th-clean-waitbox'), getComputedStyle(p).display, Math.round(r.width), Math.round(r.height),"
                " n ? n.textContent : null, r.left >= s.right - 0.5, !f || f.getBoundingClientRect().left >= r.right - 0.5, p.getAttribute('aria-label')]; })()")
        ready = "!!document.querySelector('#list li[data-s=\"seo\"]') && !!document.querySelector('.clean-fold') && !document.getElementById('wpill').hidden"
        on = ready + " && document.documentElement.classList.contains('th-clean-waitbox')"
        got = self.page({"local": {"hub.settingsTab": "theme"}}, self.go("#/settings"), {"wait": "Waiting for you square"},
                        {"eval": f"({check})?.checked"},
                        self.go(), {"until": ready}, {"sleep": 400}, {"eval": look},
                        {"go": "about:blank", "look": None}, {"local": {"hub.opt.core:clean": '{"waitbox":true}'}}, self.go(),
                        {"until": on}, {"sleep": 400}, {"eval": look})
        self.assertIs(got[3]["eval"], False)   # the tick is in "Settings → Look", off
        off, now = got[7]["eval"], got[-1]["eval"]
        self.assertEqual((off[0], off[1]), (False, "none"), off)
        self.assertEqual(now[:7], [True, "flex", 36, 36, "2", True, True], now)   # beside the field, before the fold button, two sessions wait
        self.assertIn("2", now[7], now)
        # a search that finds nobody who waits, and the "Now" filter: the square stays, the count is the same
        got = self.page({"eval": "(() => { const f = document.getElementById('filter'); f.value = 'notes'; f.dispatchEvent(new Event('input', { bubbles: true })); return 1; })()"},
                        {"until": "!document.querySelector('#list li[data-s=\"seo\"]')"}, {"eval": look},
                        {"eval": "(() => { const f = document.getElementById('filter'); f.value = ''; f.dispatchEvent(new Event('input', { bubbles: true })); return 1; })()"},
                        {"until": "!!document.querySelector('#list li[data-s=\"seo\"]')"},
                        {"eval": "(([...document.querySelectorAll('#active-bar button')].at(-1).click(), 1))"}, {"sleep": 400}, {"eval": look})
        self.assertEqual(got[2]["eval"][:5], [True, "flex", 36, 36, "2"], got[2])
        self.assertEqual(got[-1]["eval"][:5], [True, "flex", 36, 36, "2"], got[-1])
        # the click is the core's: the same session as Classic's pill opens
        click = [{"eval": "(document.getElementById('wpill').click(), 1)"}, {"until": "location.hash.startsWith('#/s/')"},
                 {"eval": "location.hash"}]
        clean = self.page(*click)[-1]["eval"]
        classic = self.page({"go": "about:blank"}, {"go": f"http://127.0.0.1:{self.port}/#/"},
                            {"until": "!document.getElementById('wpill').hidden"}, *click)[-1]["eval"]
        self.assertEqual(clean, classic)

